const CORE_FILTER_AUTO_KEY='lcw.corePageFilters.auto.v1';
let coreFilterAutoReady=false, coreFilterSaveTimer=null;
function coreSerializeFilters(bucket){
  const out={};
  Object.entries(bucket||{}).forEach(([key,entry])=>{
    if(!entry)return;
    out[key]={
      granularity:entry.granularity||null,
      values:[...(entry.values||[])],
      numericRule:entry.numericRule||null,
      quickPriority:!!entry.quickPriority,
      quickExf:!!entry.quickExf,
    };
  });
  return out;
}
function coreDeserializeFilters(bucket){
  const out={};
  Object.entries(bucket||{}).forEach(([key,entry])=>{
    if(!entry)return;
    out[key]={
      granularity:entry.granularity||null,
      values:new Set(entry.values||[]),
      numericRule:entry.numericRule||null,
      quickPriority:!!entry.quickPriority,
      quickExf:!!entry.quickExf,
    };
  });
  return out;
}
function coreSetSelectValue(id,value){
  const el=document.getElementById(id);if(!el)return;
  const text=String(value||'');
  if(text&&![...el.options].some(o=>o.value===text)){
    const option=document.createElement('option');option.value=text;option.textContent=text;el.appendChild(option);
  }
  el.value=text;
}
function collectCoreAutoFilterState(){
  const value=id=>document.getElementById(id)?.value||'';
  return {
    cp:{
      search:value('cpSearch'),
      selects:{cpFCountry:value('cpFCountry'),cpFLicense:value('cpFLicense'),cpFPriority:value('cpFPriority'),cpFDelType:value('cpFDelType'),cpFStatus:value('cpFStatus'),cpFSeason:value('cpFSeason')},
      colFilters:coreSerializeFilters(state.colFilters.cp),
      checkFilter:normalizeCheckFilterMode(state.checkFilter.cp),
      quickExf:state.cpQuickExf||'',
    },
    orders:{
      search:value('ordersSearch'),
      selects:{ordersFCountry:value('ordersFCountry'),ordersFLicense:value('ordersFLicense'),ordersFPriority:value('ordersFPriority'),ordersFDelType:value('ordersFDelType'),ordersFStatus:value('ordersFStatus'),ordersFSeason:value('ordersFSeason')},
      colFilters:coreSerializeFilters(state.colFilters.orders),
      checkFilter:normalizeCheckFilterMode(state.checkFilter.orders),
      quickExf:state.ordersQuickExf||'',
      quickActive:[...(state.ordersQuickActive||[])],
    },
  };
}
function saveCoreAutoFilterState(){
  if(!coreFilterAutoReady)return;
  try{BLStorage.setItem(CORE_FILTER_AUTO_KEY,JSON.stringify(collectCoreAutoFilterState()));}catch(e){}
}
const scheduleCoreAutoFilterSave=window.BLPerf?.debounce
  ? window.BLPerf.debounce(saveCoreAutoFilterState,80)
  : function(){if(!coreFilterAutoReady)return;clearTimeout(coreFilterSaveTimer);coreFilterSaveTimer=setTimeout(saveCoreAutoFilterState,80);};
function applyCoreAutoFilterState(){
  if(coreFilterAutoReady)return;
  let saved=null;
  try{saved=JSON.parse(BLStorage.getItem(CORE_FILTER_AUTO_KEY)||'null');}catch(e){}
  if(saved&&saved.cp){
    const x=saved.cp;
    const search=document.getElementById('cpSearch');if(search)search.value=x.search||'';
    Object.entries(x.selects||{}).forEach(([id,value])=>coreSetSelectValue(id,value));
    state.colFilters.cp=coreDeserializeFilters(x.colFilters);
    state.checkFilter.cp=normalizeCheckFilterMode(x.checkFilter);
    state.cpQuickExf=x.quickExf||'';
  }
  if(saved&&saved.orders){
    const x=saved.orders;
    const search=document.getElementById('ordersSearch');if(search)search.value=x.search||'';
    Object.entries(x.selects||{}).forEach(([id,value])=>coreSetSelectValue(id,value));
    state.colFilters.orders=coreDeserializeFilters(x.colFilters);
    state.checkFilter.orders=normalizeCheckFilterMode(x.checkFilter);
    state.ordersQuickExf=x.quickExf||'';
    state.ordersQuickActive=new Set(Array.isArray(x.quickActive)?x.quickActive:[]);
  }
  coreFilterAutoReady=true;
}
window.addEventListener('beforeunload',saveCoreAutoFilterState);

const ORDER_URL = c => `https://troy.lcwaikiki.com/order-management/orders/${c}`;
const SHIP_URL  = c => `https://troy.lcwaikiki.com/cps-management/shipment-request/${c}`;
const PLM_STYLE_URL = 'https://corenectum.lcwaikiki.com/models-options/style-overview';
let plmStyleLinks = new Map();
let plmStyleLinksByModel = new Map();
let plmStyleLinksMeta = {count:0,updatedAt:null};

function normalizePlmLinkId(value){
  const text=String(value==null?'':value).trim().replace(/^_+/,'').replace(/\.(?=\d{3}(?:\D|$))/g,'');
  if(!/^\d+$/.test(text))return '';
  const number=Number(text);return Number.isSafeInteger(number)&&number>0?String(number):'';
}
function plmStyleLinkInfo(plmId){return plmStyleLinks.get(normalizePlmLinkId(plmId))||null;}
function normalizePlmModelName(value){return String(value==null?'':value).replace(/\s+/g,' ').trim().toLocaleUpperCase('tr-TR');}
/* v6.54 — YANLIŞ İSİM EŞLEŞMESİ ÖNLENDİ.
   PLM ID (plmId) yoksa link, model ADINA göre bulunuyordu (plmStyleLinksByModel).
   Bu, YENİ oluşturulan bir Koleksiyon modelinin adı PLM'de kayıtlı ESKİ/farklı
   bir modelin adıyla benzeşince, o ESKİ modelin PLM linkini YANLIŞLIKLA yeni
   modele bağlıyordu. allowNameMatch=false verildiğinde isim eşleşmesi HİÇ
   denenmez — yalnız gerçek PLM ID eşleşmesi kabul edilir. */
function plmModelLinkInfo(modelName,plmId='',{allowNameMatch=true}={}){
  const exact=plmStyleLinkInfo(plmId);
  if(exact||!allowNameMatch)return exact;
  return plmStyleLinksByModel.get(normalizePlmModelName(modelName))||null;
}
function plmModelLinkUrl(modelName,plmId='',opts={}){
  const item=plmModelLinkInfo(modelName,plmId,opts),styleId=normalizePlmLinkId(item&&item.styleId);
  return styleId?`${PLM_STYLE_URL}?styleId=${styleId}&m=2`:'';
}
function plmModelLinkHtml(modelName,{plmId='',iconOnly=false,allowNameMatch=true}={}){
  const display=norm(modelName),url=plmModelLinkUrl(display,plmId,{allowNameMatch}),item=plmModelLinkInfo(display,plmId,{allowNameMatch});
  if(!display)return '';
  const openTitle=appLang==='en'?'Open this model in CoreNectum PLM':'Bu modeli CoreNectum PLM’de aç';
  if(!url)return iconOnly?'':escapeHtml(display);
  const detail=[item&&item.plmId,item&&item.specialCode].filter(Boolean).join(' · '),title=detail?`${openTitle} · ${detail}`:openTitle;
  return `<a class="plmBridgeLink${iconOnly?' plmBridgeIcon':''}" title="${escapeHtml(title)}" target="_blank" rel="noopener noreferrer" href="${escapeHtml(url)}" aria-label="${escapeHtml(openTitle)}">${iconOnly?'↗':escapeHtml(display)}</a>`;
}
window.BLPlmModelLinks={info:plmModelLinkInfo,url:plmModelLinkUrl,html:plmModelLinkHtml};
function detailBridgeColumnRole(column){
  const key=turknorm(String(column||'')).replace(/[^A-Z0-9]+/g,'');
  if(['SIPARISKOD','SIPARISKODU','ORDER','ORDERCODE','ORDERNO','ORDERNUMBER'].includes(key))return 'order';
  if(['MODEL','MODELAD','MODELADI','MODELNAME','STYLENAME'].includes(key))return 'model';
  if(['PLM','PLMID','PLMCODE','PLMKOD','PLMKODU'].includes(key))return 'plm';
  return '';
}
function detailOrderLinkHtml(orderCode,displayValue=orderCode){
  const code=String(orderCode==null?'':orderCode).replace(/\D/g,'').replace(/^0+(?=\d)/,'');
  const display=String(displayValue==null?'':displayValue).trim();
  if(!code)return escapeHtml(display);
  const title=appLang==='en'?'Double-click to open this order in Troy':'Bu siparişi Troy’da açmak için çift tıklayın';
  return `<a class="lnk" title="${escapeHtml(title)}" target="_blank" rel="noopener noreferrer" href="${escapeHtml(ORDER_URL(code))}">${escapeHtml(display||fmtOC(code))}</a>`;
}
function detailReportLinkUrl(column,value,row={},plmId=''){
  const role=detailBridgeColumnRole(column);
  if(role==='order'){
    const code=String(value==null?'':value).replace(/\D/g,'').replace(/^0+(?=\d)/,'');
    return code?ORDER_URL(code):'';
  }
  if(role==='model')return plmModelLinkUrl(value,plmId||row.plmId||row['PLM ID']||row['PLM Code']||'');
  return '';
}
function detailReportCellHtml({column,label='',value,displayValue=value,row={},plmId=''}){
  const role=detailBridgeColumnRole(column)||detailBridgeColumnRole(label),display=displayValue==null?'':String(displayValue);
  if(role==='order')return detailOrderLinkHtml(value,display);
  if(role==='model')return plmModelLinkHtml(value,{plmId:plmId||row.plmId||row['PLM ID']||row['PLM Code']||''})||escapeHtml(display);
  if(role==='plm')return escapeHtml(display);
  return null;
}
window.BLDetailLinks={roleFor:detailBridgeColumnRole,urlFor:detailReportLinkUrl,cellHtml:detailReportCellHtml};
function applyPlmStyleLinksPayload(data){
  const next=new Map(),byModel=new Map(),ambiguousModels=new Set();
  (Array.isArray(data&&data.links)?data.links:[]).forEach(item=>{
    const plmId=normalizePlmLinkId(item&&item.plmId),styleId=normalizePlmLinkId(item&&item.styleId);
    if(plmId&&styleId){
      const normalized={...item,plmId,styleId};next.set(plmId,normalized);
      const modelKey=normalizePlmModelName(item&&item.styleName);
      if(modelKey){const current=byModel.get(modelKey);if(current&&current.styleId!==styleId)ambiguousModels.add(modelKey);else byModel.set(modelKey,normalized);}
    }
  });
  ambiguousModels.forEach(key=>byModel.delete(key));
  plmStyleLinks=next;plmStyleLinksByModel=byModel;plmStyleLinksMeta={count:next.size,updatedAt:data&&data.updatedAt||null};
  schedulePlmModelLinkEnhancement();
  try{window.BLOAB?.refreshPlmLinks?.();}catch(_){ }
}

let plmEnhanceScheduled=false;
function enhanceModelNameCells(root=document,onlyTables=null){
  const modelAliases=new Set(['MODEL NAME','MODEL ADI','STYLE NAME','MODEL']);
  const orderAliases=new Set(['ORDER CODE','ORDER','ORDER NO','ORDER NUMBER','SIPARIS KOD','SIPARIS KODU']);
  const plmAliases=new Set(['PLM ID','PLM CODE','PLM KOD','PLM KODU']);
  const tables=onlyTables?[...onlyTables].filter(table=>table&&table.isConnected!==false):(root.querySelectorAll?root.querySelectorAll('table'):[]);
  tables.forEach(table=>{
    // Backlog raporları salt veri tablosudur. Bu ekranlarda sipariş/model
    // hücrelerini sonradan köprüye dönüştürme.
    if(table.matches('.backlogDetailTable'))return;
    const headerRows=[...table.querySelectorAll('thead tr')];if(!headerRows.length)return;
    const header=headerRows[headerRows.length-1],headers=[...header.children];
    const labels=headers.map(th=>normalizePlmModelName(th.querySelector?.('.thLabel')?.textContent||th.textContent).replace(/[▲▼▾]+/g,'').trim());
    const modelIndexes=[],orderIndexes=[];let plmIndex=-1;
    labels.forEach((label,index)=>{if(modelAliases.has(label))modelIndexes.push(index);if(orderAliases.has(label))orderIndexes.push(index);if(plmAliases.has(label))plmIndex=index;});
    if(!modelIndexes.length&&!orderIndexes.length)return;
    table.querySelectorAll('tbody tr').forEach(row=>{
      const plmId=plmIndex>=0?norm(row.children[plmIndex]?.textContent):'';
      modelIndexes.forEach(index=>{
        const cell=row.children[index];if(!cell||cell.querySelector('.plmBridgeLink,input,textarea,select,button'))return;
        const modelName=norm(cell.textContent),html=plmModelLinkHtml(modelName,{plmId});if(!html||!html.includes('plmBridgeLink'))return;
        cell.innerHTML=html;cell.classList.add('plmModelLinkCell');
      });
      orderIndexes.forEach(index=>{
        const cell=row.children[index];if(!cell||cell.querySelector('a,input,textarea,select,button'))return;
        const orderCode=norm(cell.textContent),html=detailOrderLinkHtml(orderCode,orderCode);if(!html||!html.includes('class="lnk"'))return;
        cell.innerHTML=html;cell.classList.add('orderBridgeLinkCell');
      });
    });
  });
}
/* Eklenen düğümlerin ilgilendirdiği tablolar: düğüm tablonun içindeyse o
   tablo, düğüm tablo içeriyorsa içerdikleri. Bildirim/ipucu gibi tablo dışı
   eklemeler hiçbir tabloyu yeniden taratmaz. */
function tablesForMutations(mutations){
  const tables=new Set();
  for(const mutation of mutations||[]){
    for(const node of mutation.addedNodes||[]){
      if(!node||node.nodeType!==1)continue;
      if(node.tagName==='TABLE')tables.add(node);
      const owner=node.closest&&node.closest('table');if(owner)tables.add(owner);
      if(node.querySelectorAll)for(const inner of node.querySelectorAll('table'))tables.add(inner);
    }
  }
  return tables;
}
let plmEnhancePendingTables=new Set();
function schedulePlmModelLinkEnhancement(tables=null){
  if(tables){if(plmEnhancePendingTables)for(const table of tables)plmEnhancePendingTables.add(table);}
  else plmEnhancePendingTables=null; // tam tarama istendi
  if(plmEnhanceScheduled)return;plmEnhanceScheduled=true;
  requestAnimationFrame(()=>{
    plmEnhanceScheduled=false;
    const pending=plmEnhancePendingTables;plmEnhancePendingTables=new Set();
    enhanceModelNameCells(document,pending);
  });
}
new MutationObserver(mutations=>{const tables=tablesForMutations(mutations);if(tables.size)schedulePlmModelLinkEnhancement(tables);}).observe(document.documentElement,{subtree:true,childList:true});
async function loadPlmStyleLinks({rerender=true}={}){
  try{
    const res=await fetch('/api/plm-style-links',{cache:'no-store'}),data=await res.json().catch(()=>({}));
    if(!res.ok)throw new Error(data.error||res.statusText);
    applyPlmStyleLinksPayload(data);
    if(rerender){
      if(state.cp)renderCP();
      if(state.orders)renderOrders();
      if(typeof kolRows!=='undefined'&&document.body.dataset.activeTab==='koleksiyon')renderKol();
    }
    return data;
  }catch(err){console.warn('PLM bağlantıları yüklenemedi:',err);return null;}
}
const BRIDGE_LINK_SELECTOR = 'a.lnk[href]';

// Program içindeki Troy / CPS köprüleri yanlışlıkla tek tıkla açılmasın.
// Fareyle aktivasyon yalnız çift tıkta yapılır; klavye ile Enter erişilebilirliği
// tarayıcının sentetik (detail=0) click davranışı üzerinden korunur.
document.addEventListener('click',event=>{
  const link=event.target?.closest?.(BRIDGE_LINK_SELECTOR);
  if(!link || event.detail===0) return;
  event.preventDefault();
});
document.addEventListener('auxclick',event=>{
  const link=event.target?.closest?.(BRIDGE_LINK_SELECTOR);
  if(link) event.preventDefault();
});
document.addEventListener('dblclick',event=>{
  const link=event.target?.closest?.(BRIDGE_LINK_SELECTOR);
  if(!link || event.button!==0) return;
  event.preventDefault();
  event.stopPropagation();
  const opened=window.open(link.href,link.target||'_blank','noopener,noreferrer');
  if(opened) opened.opener=null;
});
