// Sunucudan gelen tarihler JSON'da metindir; burada gerçek Date'e çevrilir.
// _asas* alanları (revizyon öncesi ASAS orijinalleri) v4.16'da eklenmişti ama bu
// listeye girmemişti: canlı değer Date, temel metin kalıyordu. Karışık tip, hem
// karşılaştırmayı hem de hücre boşaltılınca geri konan değeri kırılgan yapıyor.
const CP_BASELINE_DATE_KEYS = ['_asasExFactory','_asasRetailDate','_asasInStore'];
const CP_DATE_KEYS = ['OPD','Ex-factory','HANDOVER Tarihi','Retail Date','Buying Son Onay Tarihi','In-Store (Model Budget)','Ant. Arrival', ...CP_BASELINE_DATE_KEYS];
function makeDateOnly(y,m,d){
  y=Number(y); m=Number(m); d=Number(d);
  if(!Number.isInteger(y)||!Number.isInteger(m)||!Number.isInteger(d)) return null;
  const dt=new Date(y,m-1,d);
  return dt.getFullYear()===y && dt.getMonth()===m-1 && dt.getDate()===d ? dt : null;
}
function dateOnlyFromDateObject(v){
  if(!(v instanceof Date)||isNaN(v)) return null;
  const localMidnight=v.getHours()===0&&v.getMinutes()===0&&v.getSeconds()===0&&v.getMilliseconds()===0;
  const utcMidnight=v.getUTCHours()===0&&v.getUTCMinutes()===0&&v.getUTCSeconds()===0&&v.getUTCMilliseconds()===0;
  if(utcMidnight&&!localMidnight) return makeDateOnly(v.getUTCFullYear(),v.getUTCMonth()+1,v.getUTCDate());
  return makeDateOnly(v.getFullYear(),v.getMonth()+1,v.getDate());
}
function excelSerialToDateOnly(v){
  const n=Number(v); if(!Number.isFinite(n)) return null;
  if(window.XLSX && XLSX.SSF && typeof XLSX.SSF.parse_date_code==='function'){
    const dc=XLSX.SSF.parse_date_code(n);
    if(dc) return makeDateOnly(dc.y,dc.m,dc.d);
  }
  const utc=new Date(Math.round((n-25569)*86400000));
  return makeDateOnly(utc.getUTCFullYear(),utc.getUTCMonth()+1,utc.getUTCDate());
}
// ISO tarih-saat → yerel gün başlangıcı belleği (bkz. coerceDateLoose hızlı yolu).
const ISO_DAY_CACHE_MAX = 20000;
const _isoDayCache = new Map();
function coerceDateLoose(v){
  if(v instanceof Date) return dateOnlyFromDateObject(v);
  if(v==null || v==='') return null;
  if(typeof v==='number' && Number.isFinite(v)){
    const whole=Math.trunc(v);
    if(whole>=10000101&&whole<=99991231) return makeDateOnly(Math.trunc(whole/10000),Math.trunc((whole%10000)/100),whole%100);
    if(v>0&&v<3000000) return excelSerialToDateOnly(v);
    return null;
  }
  const s=String(v).trim(); if(!s) return null;
  // HIZLI YOL: sunucu tarihleri JSON'da her zaman ISO tarih-saat olarak gelir
  // (JSON'un Date tipi yok). Açılışta ~140.000 alan bu fonksiyondan geçiyor;
  // en olası biçimi en sona koymak, alan başına üç boşa .match() maliyeti
  // demekti. Sıra değişti, davranış aynı — aşağıdaki üç kalıptan hiçbiri
  // "YYYY-M-DTsaat" biçimiyle eşleşemez (ilki 8 haneli, ikincisi ayraç
  // bekler, üçüncüsü gün sonrası satır sonu ister).
  //
  // Ayrıca sonuç belleklenir: aynı ex-factory/OPD tarihi yüzlerce siparişte
  // tekrar ettiği için ayrıştırma bir kez yapılır. Bellekte yalnız ZAMAN
  // DAMGASI tutulur ve her çağrıda YENİ bir Date döner — Date nesneleri
  // değiştirilebilir olduğundan paylaşılan örnek döndürmek satırlar arası
  // veri bozulmasına yol açardı.
  // Eşdeğerlik: tests/date-coercion-equivalence-v309.test.js
  if(s.length>10 && s.charCodeAt(4)===45 && /^\d{4}-\d{1,2}-\d{1,2}T/.test(s)){
    let ms=_isoDayCache.get(s);
    if(ms===undefined){
      const day=dateOnlyFromDateObject(new Date(s));
      ms=day?day.getTime():null;
      // Uzun oturumda sınırsız büyümesin: kapasite dolunca sıfırlanır.
      if(_isoDayCache.size>=ISO_DAY_CACHE_MAX) _isoDayCache.clear();
      _isoDayCache.set(s,ms);
    }
    return ms===null?null:new Date(ms);
  }
  let m=s.match(/^(\d{4})(\d{2})(\d{2})$/);
  if(m) return makeDateOnly(+m[1],+m[2],+m[3]);
  m=s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{2}|\d{4})(?:\s|$)/);
  if(m){ const y=+m[3]<100?2000+(+m[3]):+m[3]; return makeDateOnly(y,+m[2],+m[1]); }
  m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if(m) return makeDateOnly(+m[1],+m[2],+m[3]);
  // API'nin eski sürümlerinden gelen ISO tarih-saatler yerel takvim gününe çevrilir.
  // Örn. 19.10.2026 yerel gece yarısı JSON'da 18.10.2026T21:00:00Z olabilir.
  if(/^\d{4}-\d{1,2}-\d{1,2}T/.test(s)) return dateOnlyFromDateObject(new Date(s));
  const n=Number(s.replace(',','.')); return Number.isFinite(n)?coerceDateLoose(n):null;
}
function normalizeCPDates(rows){
  rows.forEach(r=>{
    CP_DATE_KEYS.forEach(k=>{ if(k in r) r[k] = coerceDateLoose(r[k]); });
    cpLogisticSegments(r).forEach(segment=>{ segment.arrival=coerceDateLoose(segment.arrival);segment.handover=coerceDateLoose(segment.handover); });
    if(cpLogisticHasDetails(r)) rebuildCpLogisticCaches(r);
  });
}
const dz = document.getElementById('dropzone');
let dragCounter=0;
// Yalnızca gerçek DOSYA sürüklemelerinde tetiklenir — sütun başlığı sürükle-bırakla
// yeniden sıralama gibi uygulama-içi sürüklemeler "text/plain" taşır, "Files" değil;
// bu ayrım yapılmadan önce her sürükleme "Dosyayı buraya bırak" katmanını açıp sütun
// sıralamasının çalışmasını engelliyordu.
function isFileDrag(e){ return e.dataTransfer && e.dataTransfer.types && Array.from(e.dataTransfer.types).includes('Files'); }
// Collection'da tarayıcıdan gelen PLM model görseli de "Files" taşır; eski
// Excel dropzone bunu dosya importu sanıp tüm ekranı kapatıyordu. PLM importer
// kendi payload sözleşmesini bildiriyorsa global dropzone tamamen geri çekilir.
function isCollectionPlmImageDrag(e){
  return document.body.dataset.activeTab==='koleksiyon'
    && Boolean(window.BLCollectionPlmDragImport?.isCandidateTransfer?.(e.dataTransfer));
}
window.addEventListener('dragenter', e=>{ if(!isFileDrag(e)||isCollectionPlmImageDrag(e)) return; e.preventDefault(); dragCounter++; dz.classList.add('show'); });
window.addEventListener('dragleave', e=>{ if(!isFileDrag(e)||isCollectionPlmImageDrag(e)) return; e.preventDefault(); dragCounter--; if(dragCounter<=0) dz.classList.remove('show'); });
window.addEventListener('dragover', e=>{ if(!isFileDrag(e)||isCollectionPlmImageDrag(e)) return; e.preventDefault(); });
window.addEventListener('drop', e=>{
  if(!isFileDrag(e)||isCollectionPlmImageDrag(e)) return;
  e.preventDefault(); dragCounter=0; dz.classList.remove('show');
  const files = Array.from(e.dataTransfer.files||[]).filter(f=>/\.xlsx$/i.test(f.name));
  if(!files.length) return;
  let pending = files.length;
  let asasFound = false;
  const results = [];
  files.forEach(f=>{
    readFile(f, (wb,name)=>{
      classifyAndLoadDropped(wb, name, ()=>{ asasFound = true; });
      results.push(name);
      pending--;
      if(pending===0){
        if(asasFound || state.asasOrders){
          updSourceHint(`Sürükle-bırak ile ${results.length} dosya işlendi: ${results.join(', ')}. Otomatik oluşturuluyor…`);
          generateCPFromASAS();
        }
      }
    });
  });
});
function classifyAndLoadDropped(wb, name, onASAS){
  // ASAS - Fabric adlı eski ayrı çalışma kitabı artık kullanılmıyor. Kumaş
  // alanları ana ASAS kaynağından gelir; yanlış dosyanın ana sipariş kaynağı
  // olarak seçilmesini yine engelleriz.
  // replace the operational ASAS order set merely because both files contain
  // the "Sipariş Kod" header.
  if(/^ASAS\s*-\s*Fabric(?:\s|\.|$)/i.test(String(name||''))){
    showToast(appLang==='en'
      ? 'The separate ASAS - Fabric source is no longer used. Map the fabric fields in the main ASAS connection.'
      : 'Ayrı ASAS - Fabric kaynağı artık kullanılmıyor. Kumaş alanlarını ana ASAS bağlantısında eşleyin.');
    return;
  }
  // sniff first sheet header rows to classify raw source files
  const firstRows = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], {header:1, raw:true, defval:null});
  const flatHeaders = new Set();
  for(let i=0;i<Math.min(firstRows.length,25);i++){ (firstRows[i]||[]).forEach(c=>{ if(c!=null) flatHeaders.add(norm(c)); }); }
  const hasAntrepoSheet = wb.SheetNames.some(n=>/antrepo/i.test(n));
  if(flatHeaders.has('Sipariş Kod') && flatHeaders.has('Renk Tanım') || hasAntrepoSheet){
    state.antrepoMap = parseAntrepoWorkbook(wb);
    updSourceHint(`Antrepo okundu (${name}): ${Object.keys(state.antrepoMap).length} eşleşme anahtarı.`);
    return;
  }
  if(flatHeaders.has('Sipariş Kod')){
    const parsed = parseASASWorkbook(wb);
    if(parsed){
      state.asasOrders = parsed.orders;
      updSourceHint(`ASAS okundu (${name}): ${parsed.orders.length} sipariş-renk satırı.`);
      onASAS();
      return;
    }
  }
  if(flatHeaders.has('Supplier') && flatHeaders.has('PO')){
    parseCPUpdateWorkbook(wb);
    showToast(`Sub-Mfr/Supp.FOB dosyası (${name}) okundu ve uygulandı.`);
    return;
  }
  console.warn('Tanımlanamayan dosya (sürükle-bırak):', name);
}

