const _selectionActionIds=['cpQuotationsBtn','cpCreateOcBtn','cpPriceHistoryBtn','selectedBacklogBtn','cpProdStatusBtn','navToShipping','cpSendPricingBtn'];
const _sharedTableActionIds=['undoBtn','redoBtn','cpCopyToKolBtn','navCopy','navCopyMenuBtn','gridSelectionStatus','navFitColumnsBtn','navFreezeBtn','navClearFilters','navColsBtn',..._selectionActionIds];
function sharedTableActionNode(id){
  const el=document.getElementById(id);
  if(!el) return null;
  return id==='navColsBtn' ? (el.closest('.navColsRight')||el.parentElement) : el;
}
function vfProfileMenuNode(kind){ return document.querySelector(`.vfMenuWrap[data-vf-kind="${kind}"]`); }
function restoreSharedTableActions(){
  const homeEnd=document.getElementById('vfSharedActionsEnd');
  if(!homeEnd) return;
  _sharedTableActionIds.forEach(id=>{ const node=sharedTableActionNode(id); if(node) homeEnd.before(node); });
  ['navExcelBtn'].forEach(id=>{const node=document.getElementById(id);if(node)homeEnd.before(node);});
  const rowBreak=document.querySelector('.vfBarRowBreak[data-dimbreak="1"]');
  ['view','filter'].forEach(kind=>{const node=vfProfileMenuNode(kind);if(node&&rowBreak)rowBreak.before(node);});
  const shipHome=document.getElementById('shipSecondaryToolbar'),shipAnchor=document.getElementById('shipCount');
  if(shipHome&&shipAnchor){['shipExportBtn','shipUpdateFxBtn','shipDeleteBtn'].forEach(id=>{const node=document.getElementById(id);if(node){node.classList.remove('navActionBtn');shipHome.insertBefore(node,shipAnchor);}});}
}
/* Tek bağlama: bu satır eskiden restoreSharedTableActions İÇİNDEYDİ ve her sekme
   geçişinde yeni bir dinleyici ekleyip tek tıkta birden çok PLM senkronu başlatıyordu. */
document.getElementById('shipPlmSyncBtn')?.addEventListener('click',event=>openCurrentViewImageAction(event.currentTarget));
function appendSharedTableActions(targetId,ids){
  const target=document.getElementById(targetId); if(!target) return;
  ids.forEach(id=>{const node=sharedTableActionNode(id)||document.getElementById(id);if(node)target.appendChild(node);});
}
/* v7.81 — Bir paylaşılan eylemi hedefin SONUNA değil, verilen düğümün
   ÖNÜNE yerleştirir. "Filtreleri Temizle"nin ⋯ düğmesinin solunda
   durabilmesi için gerekli; appendSharedTableActions yalnız sona ekler. */
function placeSharedActionsBefore(refId,ids){
  const ref=document.getElementById(refId); if(!ref) return;
  ids.forEach(id=>{const node=sharedTableActionNode(id)||document.getElementById(id);if(node)ref.before(node);});
}
/* v7.81 — "Sütun Ekle" / "Hesaplanan Sütun" ⋯ More Actions menüsünde.
   Düğmeler her sekme geçişinde yeniden kurulur; eskiler önce silinir ki
   menü çoğalmasın. Her tablo YALNIZ gerçekten desteklediği eylemi görür —
   çalışmayan bir düğme koymaktansa hiç koymamak dürüst olanı. */
function appendColumnActions(targetId,tableKey){
  const menu=document.getElementById(targetId); if(!menu) return;
  menu.querySelectorAll('[data-col-action]').forEach(el=>el.remove());
  const rerender=()=>{const info=activeTableInfo(); if(info&&typeof info.rerender==='function') info.rerender();};
  const add=(action,icon,label,run)=>{
    const btn=document.createElement('button');
    btn.type='button'; btn.className='tbtn'; btn.dataset.colAction=action;
    btn.innerHTML=`<svg class="ic"><use href="#${icon}"/></svg><span>${escapeHtml(label)}</span>`;
    btn.addEventListener('click',()=>{ menu.hidden=true; run(); });
    menu.appendChild(btn);
  };
  const addColLabel=appLang==='en'?'Add Column':'Sütun Ekle';
  const calcLabel=appLang==='en'?'Add Calculated Column':'Hesaplanan Sütun Ekle';
  if(tableKey==='cp'||tableKey==='orders'){
    // Orders'ın sütun şeması CP_COLS'un kopyası (syncOrdersColumnsFromCp); aynı
    // pencere kullanılır, ikinci bir sütun sistemi kurulmaz.
    add('add','i-columns-3',addColLabel,()=>openCpModelColumnModal(null,rerender));
  }else if(tableKey==='koleksiyon'){
    add('add','i-columns-3',addColLabel,()=>kolAddCustomColumn(null));
  }
  /* Formül modülü tembel yükleniyor (perf-runtime). Varlığına menü KURULURKEN
     bakılsaydı düğme ilk açılışta sessizce eksik kalır, yalnız sekme değişince
     belirirdi — ölçüldü. Bu yüzden kontrol tıklama anına alındı. */
  if(FORMULA_COLUMN_TABLES.has(tableKey)){
    add('calc','i-calculator',calcLabel,()=>{
      const fc=window.BLFormulaColumns;
      if(!fc){showToast(appLang==='en'?'Calculated columns are still loading.':'Hesaplanan sütunlar henüz yükleniyor.');return;}
      fc.open(tableKey,null,rerender);
    });
  }
}
function appendVfProfiles(targetId){
  const target=document.getElementById(targetId);if(!target)return;
  ['view','filter'].forEach(kind=>{const node=vfProfileMenuNode(kind);if(node)target.appendChild(node);});
}
// Temel (boyut) filtreleri sayfa başlığının yanına taşır. CP ve Siparişler'in kendi
// grubu vardır; aktif sekmeninki başlığın yanında görünür, diğeri vfBar'daki evine
// döner. Böylece CP/Siparişler'de ayrı bir eylem şeridine gerek kalmaz.
function placeCpDimensionFilters(tab=document.body.dataset.activeTab){
  const slot=document.getElementById('pageTitleFilters');
  if(!slot) return;
  const groupId=tab==='cp'?'cpDimFilterGroup':(tab==='orders'?'ordersDimFilterGroup':'');
  // Slotta AYNI ANDA yalnız bir grup bulunur; diğeri vfBar'daki evine döner.
  // (İkisi birden bırakılırsa filtreler ekranda iki kez görünüyordu.)
  const home=document.getElementById('vfSharedActionsEnd');
  ['cpDimFilterGroup','ordersDimFilterGroup'].forEach(id=>{
    if(id===groupId) return;
    const other=document.getElementById(id);
    if(other && other.parentElement===slot && home) home.before(other);
  });
  const group=groupId?document.getElementById(groupId):null;
  if(group){
    if(group.parentElement!==slot) slot.appendChild(group);
    slot.hidden=false;
  }else{
    slot.hidden=true;
  }
}
function placeShippingActionsAfterCopy(){
  let ref=document.getElementById('navCopy');if(!ref)return;
  ['shipExportBtn','shipFreightBtn','shipUpdateFxBtn','shipDeleteBtn'].forEach(id=>{const node=document.getElementById(id);if(node){node.classList.add('navActionBtn');ref.after(node);ref=node;}});
}
function syncTableToolbarActions(tab=document.body.dataset.activeTab){
  window.BLToolbarResponsive?.reset?.();
  restoreSharedTableActions();
  const genericExcel=document.getElementById('navExcelBtn');
  if(genericExcel){genericExcel.hidden=false;genericExcel.style.display='';}
  // Orders ve Collection kendi aktif-filtre çubuklarında satır içi temizleme
  // eylemi sunar. Aynı eylemi genel araç çubuğunda tekrar etmek, filtre yokken
  // bile anlamsız bir denetim ve filtre varken iki eşdeğer yol oluşturuyordu.
  const contextualClear=document.getElementById('navClearFilters');
  if(contextualClear)contextualClear.hidden=tab==='orders'||tab==='koleksiyon';
  placeCpDimensionFilters(tab);
  if(tab==='cp'){
    appendSharedTableActions('cpTableActions',['undoBtn','redoBtn','navCopy','navCopyMenuBtn','gridSelectionStatus','cpCopyToKolBtn','navExcelBtn']);
    appendSharedTableActions('cpToolsMenu',_selectionActionIds);
    appendSharedTableActions('cpTableViewActions',['navColsBtn']);
    appendSharedTableActions('cpMoreMenu',['navFitColumnsBtn','navFreezeBtn']);
    placeSharedActionsBefore('cpMoreWrap',['navClearFilters']);
    appendColumnActions('cpMoreMenu','cp');
    appendVfProfiles('cpMoreMenu');
  }else if(tab==='orders'){
    appendSharedTableActions('ordersTableActions',['undoBtn','redoBtn','navCopy','navCopyMenuBtn','gridSelectionStatus','navExcelBtn']);
    appendSharedTableActions('ordersTableViewActions',['navColsBtn']);
    // Siparişler'de "Koleksiyona Kopyala" ve CP'ye özgü Fiyat Çalışmaları yok.
    appendSharedTableActions('ordersToolsMenu',_selectionActionIds.filter(id=>id!=='cpQuotationsBtn'));
    appendSharedTableActions('ordersMoreMenu',['navFitColumnsBtn','navFreezeBtn']);
    placeSharedActionsBefore('ordersMoreWrap',['navClearFilters']);
    appendColumnActions('ordersMoreMenu','orders');
    appendVfProfiles('ordersMoreMenu');
  }else if(tab==='koleksiyon'){
    appendSharedTableActions('kolTableViewActions',['navColsBtn']);
    appendSharedTableActions('kolMoreMenu',['navFitColumnsBtn','navFreezeBtn']);
    placeSharedActionsBefore('kolMoreWrap',['navClearFilters']);
    appendColumnActions('kolMoreMenu','koleksiyon');
    // Görünüm (Page Options) ve Filtre profilleri de ⋯ menüsünün içine girer.
    appendVfProfiles('kolMoreMenu');
  }else if(tab==='shipping'){
    placeShippingActionsAfterCopy();
  }
  // Eylem düğümleri yer değiştirdi: ortak duyarlı araç çubuğu yeniden ölçmeli.
  window.BLToolbarResponsive?.refresh?.(null,{remeasure:true});
}
