// ================= GORUNMEYEN SEKMEYI CIZME =================
// Acilista varsayilan sekme Overview olmasina ragmen CP ve Siparişler tablolari da tam
// olarak DOM'a kurulabiliyordu; büyük tablolar hiç bakılmadan çizilip atılıyordu. Artık
// gorunmeyen bir sayfanin cizimi ISTEK OLARAK isaretlenir ve o sayfaya ilk gecildiginde
// tek seferde uygulanir. Cagri yerleri degismedi: renderCP/renderOverview
// isimleri artik bu erteleyici sarmalayicilar.
var _deferredTabRenders=new Set();
var DEFERRED_TAB_RENDERERS={cp:'renderCPNow',orders:'renderOrdersNow',overview:'renderOverviewNow'};
function currentActiveTab(){
  return document.body.dataset.activeTab||document.querySelector('nav.tabs button.active')?.dataset.tab||'';
}
function runDeferredRender(tab){
  const fnName=DEFERRED_TAB_RENDERERS[tab];
  if(!fnName)return;
  _deferredTabRenders.delete(tab);
  const fn=window[fnName];
  if(typeof fn==='function')fn();
}
function deferRenderForTab(tab){
  if(currentActiveTab()===tab)runDeferredRender(tab);
  else _deferredTabRenders.add(tab);
}
function flushDeferredRenderForTab(tab){
  if(_deferredTabRenders.has(tab))runDeferredRender(tab);
}
function renderCP(){ deferRenderForTab('cp'); }
function renderOrders(){ deferRenderForTab('orders'); }
function renderOverview(){ deferRenderForTab('overview'); }
/* ---------------------------------------------------------------------------
   UFUK ROZETİ.

   İki filtre katmanı var: model ufku (veriyi ÇEKEN sınır) ve sayfa filtreleri
   (çekileni GÖSTEREN sınır). Sayfa filtresi seçenekleri yalnız çekilmiş
   satırlardan üretildiği için, ufkun dışarıda bıraktığı bir sezon filtre
   listesinde hiç görünmez — "yok" ile "çekilmedi" ayırt edilemez. Rozet bu
   sınırı sürekli görünür kılar.
--------------------------------------------------------------------------- */
const HORIZON_BADGE_IDS={cp:'cpHorizonBadge',orders:'ordersHorizonBadge',backlog:'backlogHorizonBadge',lfl:'lflHorizonBadge',priceanalysis:'priceAnalysisHorizonBadge',intake:'intakeHorizonBadge'};
/* v7.81 — Kişisel ufuk önbelleği (/api/user-workspace okuması) kaldırıldı;
   rozet artık /api/horizon-summary ile kaynak filtresini gösteriyor. */

function horizonBadgeScope(byTarget,target){
  if(byTarget[target]) return byTarget[target];
  // LFL kendi kapsamı yoksa CP (yoksa Backlog) kapsamından beslenir —
  // sunucudaki loadFromModelConnections ile aynı sıra.
  if(target==='lfl') return byTarget.cp||byTarget.backlog||null;
  return null;
}

function horizonCompactFilterChips(horizon){
  const groups=Array.isArray(horizon&&horizon.groups)?horizon.groups:[];
  const conditions=groups.flatMap(group=>Array.isArray(group&&group.conditions)?group.conditions:[]).filter(Boolean);
  const label=condition=>{
    const field=String(condition.field||'').trim()||'—';
    const values=Array.isArray(condition.values)?condition.values.filter(value=>String(value||'').trim()):[];
    const value=values.length?values.join(', '):(condition.from||condition.to?[condition.from,condition.to].filter(Boolean).join(' – '):'');
    return value?`${field}: ${value}`:field;
  };
  if(conditions.length)return conditions.slice(0,4).map(label);
  const seasons=Array.isArray(horizon&&horizon.seasons)?horizon.seasons.filter(Boolean):[];
  if(seasons.length)return [`${appLang==='en'?'Season':'Sezon'}: ${seasons.join(', ')}`];
  return [];
}

/* v7.81 — KİŞİSEL HORIZON KALDIRILDI.

   Önce ortak ayarlar (bağlantı, alan eşlemesi, kapsam) Veri Yönetimi
   ekranına taşınmış, geriye kişisel ufuk ve kendi düzenleyicisi
   (horizon-editor.js) kalmıştı. Kullanıcı kararıyla o katman da kalktı:
   iki ayrı ufuk kaynağı olması "hangisi geçerli?" sorusunu üretiyordu.

   Artık tek kaynak var: Veri Yönetimi'ndeki KAYNAK filtresi. Modül
   başlıkları yalnız salt okunur özet gösterir (/api/horizon-summary),
   düzenleme yolu taşımaz. horizon-editor.js silindi. */

function openHorizonTextInput(options={}){
  const en=appLang==='en';
  const title=String(options.title||'').trim();
  const label=String(options.label||title).trim();
  const initial=String(options.initial||'');
  const maxLength=Number(options.maxLength)||80;
  const confirmLabel=String(options.confirmLabel||(en?'Continue':'Devam')).trim();
  const cancelLabel=String(options.cancelLabel||(en?'Cancel':'Vazgeç')).trim();
  document.getElementById('_horizonTextInputModal')?.remove();
  const modal=document.createElement('div');
  modal.id='_horizonTextInputModal';
  modal.className='warnOverlay horizonTextInputOverlay';
  modal.innerHTML=`<div class="modalCard horizonTextInputCard" role="dialog" aria-modal="true" aria-labelledby="_horizonTextInputTitle">
    <div class="modelConnHead"><div><div class="modalTitle" id="_horizonTextInputTitle">${escapeHtml(title)}</div></div>
      <button type="button" class="pricingRuleIconBtn" data-horizon-text-cancel aria-label="${escapeHtml(en?'Close':'Kapat')}"><svg class="ic"><use href="#i-x"/></svg></button>
    </div>
    <div class="horizonTextInputBody"><label for="_horizonTextInput">${escapeHtml(label)}</label><input id="_horizonTextInput" type="text" maxlength="${maxLength}" autocomplete="off" value="${escapeHtml(initial)}"></div>
    <div class="modelConnFoot"><span></span><span style="flex:1"></span><button type="button" class="tbtn" data-horizon-text-cancel>${escapeHtml(cancelLabel)}</button><button type="button" class="navActionBtn" data-horizon-text-confirm>${escapeHtml(confirmLabel)}</button></div>
  </div>`;
  document.body.appendChild(modal);
  const input=modal.querySelector('#_horizonTextInput');
  return new Promise(resolve=>{
    let settled=false;
    const finish=value=>{if(settled)return;settled=true;modal.remove();resolve(value);};
    modal.querySelectorAll('[data-horizon-text-cancel]').forEach(button=>button.addEventListener('click',()=>finish(null)));
    modal.querySelector('[data-horizon-text-confirm]')?.addEventListener('click',()=>finish(String(input?.value||'').trim()));
    modal.addEventListener('click',event=>{if(event.target===modal)finish(null);});
    modal.addEventListener('keydown',event=>{
      if(event.key==='Escape'){event.preventDefault();finish(null);}
      else if(event.key==='Enter'){event.preventDefault();finish(String(input?.value||'').trim());}
    });
    setTimeout(()=>{input?.focus();input?.select();},0);
  });
}

/* v7.81 — Modül başlığı: SALT OKUNUR ufuk özeti.

   Veri state'ten gelir (/api/data yanıtındaki modelScopes +
   appliedHorizons); rozet çizimi AĞ İSTEĞİ ATMAZ. Kişisel ufuk
   kaldırıldığı için eski /api/user-workspace okuması da yok.
   Düzenleme yolu taşımaz: ufuk Veri Yönetimi'nden ayarlanır. */
function renderHorizonBadges(){
  const en=(typeof appLang!=='undefined'&&appLang==='en');
  const scopes=Array.isArray(state.modelScopes)?state.modelScopes:[];
  const appliedHorizons=state.modelHorizons&&typeof state.modelHorizons==='object'?state.modelHorizons:{};
  const byTarget={};
  scopes.forEach(entry=>{ if(entry&&entry.target) byTarget[entry.target]=entry; });

  Object.keys(HORIZON_BADGE_IDS).forEach(target=>{
    const el=document.getElementById(HORIZON_BADGE_IDS[target]);
    if(!el)return;
    const scope=horizonBadgeScope(byTarget,target);
    const horizon=appliedHorizons[target]||(scope&&scope.horizon)||{};
    const chips=horizonCompactFilterChips(horizon);
    const sourceName=scope?String(scope.connection||'').replace(/^Model:\s*/i,'').trim():'';

    el.textContent='';
    el.hidden=false;
    el.classList.add('horizonSummaryBadge');
    el.classList.remove('isOpen');

    const label=document.createElement('span');
    label.className='horizonSummaryLabel';
    label.textContent='Horizon';
    el.appendChild(label);

    if(sourceName){
      const source=document.createElement('span');
      source.className='horizonSummarySource';
      source.textContent=sourceName;
      source.title=en?'The source feeding this screen':'Bu ekranı besleyen kaynak';
      el.appendChild(source);
    }

    if(chips.length){
      chips.forEach(text=>{
        const chip=document.createElement('span');
        chip.className='horizonSummaryChip';
        chip.textContent=text;
        el.appendChild(chip);
      });
    }else{
      const none=document.createElement('span');
      none.className='horizonSummaryNone';
      none.textContent=en?'no filter':'filtre yok';
      el.appendChild(none);
    }

    el.title=chips.length
      ?(en?'Active source filter — change it in Data Management.':'Aktif kaynak filtresi — Veri Yönetimi ekranından değiştirilir.')
      :(en?'No filter on this source.':'Bu kaynakta filtre yok.');
  });
}

/* v7.81 — data-horizon-action işleyicisi kaldırıldı: rozet salt okunur
   olduğu için bu attribute'u üreten hiçbir element kalmadı. */


try{renderHorizonBadges();}catch(_){}

function sourceFilterNoticeText(status,message){
  const en=appLang==='en';
  const labels=en?{cp:'CP / Overview',orders:'Orders',backlog:'Backlog',lfl:'LFL'}:{cp:'CP / Genel Bakış',orders:'Siparişler',backlog:'Backlog',lfl:'LFL'};
  const missing=Array.isArray(status&&status.missingTargets)?status.missingTargets:[];
  const scope=missing.map(target=>labels[target]||target).join(', ');
  /* v7.81: metin, filtrenin GERÇEKTE durduğu yeri söyler. "Horizon ve
     Bağlantı" ekranı silindi; kullanıcıyı var olmayan bir ekrana yollayan bir
     uyarı, engelin kendisinden daha kötüdür. */
  return {
    title:en?'A data filter is required':'Veri filtresi gerekli',
    detail:en
      ?`No data was loaded${scope?` for ${scope}`:''}. Open Data Management, add at least one complete condition to this module's filter, save it, then run Refresh.`
      :(message||`Veri yüklenmedi${scope?`: ${scope}`:''}. Veri Yönetimi ekranını açıp bu modülün filtresine en az bir tamamlanmış koşul ekleyin, kaydedin ve ardından Yenile'yi çalıştırın.`),
    action:en?'Open Data Management':'Veri Yönetimi\'ni Aç',
    close:en?'Close':'Kapat'
  };
}
/* v7.81 — "VERİ KAYNAĞI VE FİLTRELER" ARTIK VERİ YÖNETİMİ EKRANIDIR.

   Bu giriş noktası eski modalı açıyordu. Ortak olan her şey — bağlantı, alan
   eşlemesi, CP sütunları, eşleştirme kuralı, sorgu modu, modül bağlantıları
   ve ortak filtreler — artık o ekranda.

   YETKİSİ OLMAYAN KULLANICI ÇIKMAZA SOKULMAZ: Veri Yönetimi'ne erişemeyen
   biri için kendi kişisel ufkunu düzenleyebileceği düzenleyici açılır. Onun
   değiştirebileceği tek katman zaten odur. */
function openDataSourceAndFilters(options={}){
  const current=typeof currentActiveTab==='function'?String(currentActiveTab()||''):'';
  const target=String(options&&options.target||(['cp','orders','backlog','lfl','priceanalysis','intake'].includes(current)?current:'cp'));
  
  const connectionId=String(options&&options.connectionId||'');
  const openMapping=Boolean(options&&options.openMapping);
  const mappingRepair=options&&options.mappingRepair&&typeof options.mappingRepair==='object'
    ? options.mappingRepair : null;
  if(typeof window.BLCanAccessArea==='function'&&!window.BLCanAccessArea('source')){
    /* v7.81 — Kişisel ufuk kaldırıldı: ufku yalnız Veri Yönetimi yetkisi
       olan değiştirebilir. Eskiden burada kişisel düzenleyici açılırdı;
       artık yapılacak şey durumu söylemek. */
    if(typeof showToast==='function'){
      showToast(appLang==='en'
        ?'The horizon is managed in Data Management; you do not have access to that screen.'
        :'Ufuk Veri Yönetimi ekranından yönetilir; bu ekrana erişiminiz yok.');
    }
    return;
  }
  if(switchTab('source')===false)return;
  void window.BLPerf.ensureFeature('dataManagement').then(()=>{
    const screen=window.BLDataManagement;
    if(!screen)return;
    // Onarım bir modal içinden gelmiş olabilir; Veri Yönetimi lazy yüklendiğinde
    // root'un hazır olduğundan emin ol ve aynı canlı hata bilgisini editöre taşı.
    screen.mount?.(document.getElementById('dataManagementRoot'));
    // Belirli bir kaynak hedeflendiyse ona, yoksa sayfanın modülüne odaklan.
    if(connectionId&&typeof screen.focusSource==='function')screen.focusSource(connectionId,{openMapping,mappingRepair});
    else if(typeof screen.focusModule==='function')screen.focusModule(target);
  }).catch(error=>{ if(typeof showToast==='function')showToast(error&&error.message||String(error)); });
}
function hideSourceFilterRequiredNotice(){document.getElementById('_sourceFilterRequiredModal')?.remove();}
function showSourceFilterRequiredNotice(status,message){
  const text=sourceFilterNoticeText(status,message);
  // Bu uyarı kullanıcıyı yenilemeden alıkoyan bir engeldir; toast ve merkez
  // bildirimleri gibi geçmişe de yazılır, yoksa modal kapatıldıktan sonra
  // "neden veri gelmedi?" sorusunun izi hiçbir yerde kalmıyordu (v6.14).
  notificationHistoryAdd(`${text.title}: ${text.detail}`,'toast');
  const targets=Array.isArray(status&&status.missingTargets)?status.missingTargets:[];
  const preferredTarget=targets[0]||'cp';
  document.getElementById('_sourceFilterRequiredModal')?.remove();
  const modal=document.createElement('div');
  modal.id='_sourceFilterRequiredModal';modal.className='warnOverlay';
  modal.innerHTML=`<div class="modalCard sourceFilterRequiredCard" role="alertdialog" aria-modal="true" aria-labelledby="_sourceFilterRequiredTitle">
    <div class="sourceFilterRequiredIcon"><svg class="ic" aria-hidden="true"><use href="#i-binary-tree-2"/></svg></div>
    <div><div class="modalTitle" id="_sourceFilterRequiredTitle">${escapeHtml(text.title)}</div><p>${escapeHtml(text.detail)}</p></div>
    <div class="sourceFilterRequiredActions"><button type="button" class="tbtn" data-source-filter-close>${escapeHtml(text.close)}</button><button type="button" class="navActionBtn" data-source-filter-open>${escapeHtml(text.action)}</button></div>
  </div>`;
  document.body.appendChild(modal);
  bindBuyerLogUpdatePanel(modal);
  void refreshBuyerLogUpdatePanel();
  modal.__refreshCanonicalRecipients=()=>{prepareEmailFillFromShared();if(typeof refreshAll==='function')refreshAll();};
  modal.addEventListener('click',event=>{const manage=event.target.closest('[data-manage-email-groups]');if(manage){event.preventDefault();window.BLEmailGroups?.open?.();}});
  const close=()=>modal.remove();
  modal.querySelectorAll('[data-source-filter-close]').forEach(btn=>btn.addEventListener('click',close));
  modal.querySelector('[data-source-filter-open]')?.addEventListener('click',()=>{close();openDataSourceAndFilters({target:preferredTarget});});
  modal.addEventListener('click',e=>{if(e.target===modal)close();});
  return modal;
}
window.openDataSourceAndFilters=openDataSourceAndFilters;
window.showSourceFilterRequiredNotice=showSourceFilterRequiredNotice;

/* Field Mapping onarımından sonra yalnız hatayı üreten kapsamları yeniden dene.
   Hedef bilgisi yoksa güvenli geri dönüş tam yenilemedir. Başarısız olursa
   loadFromServer aynı onarım modalını yeniden gösterir; sessiz başarısızlık yok. */
async function retryRefreshAfterFieldMapping(repairAction={}){
  const targets=Array.isArray(repairAction&&repairAction.targets)
    ? [...new Set(repairAction.targets.map(value=>String(value||'').trim()).filter(Boolean))]
    : [];
  const ok=await loadFromServer(true,targets.length?targets:undefined);
  if(ok&&typeof showToast==='function'){
    showToast(appLang==='en'
      ?'Field mapping repair was verified and the refresh completed.'
      :'Alan eşleme onarımı doğrulandı ve yenileme tamamlandı.');
  }
  return ok;
}
window.BLRetryRefreshAfterFieldMapping=retryRefreshAfterFieldMapping;

let ordersLoadPromise=null;
let cpLoadPromise=null;
let overviewLoadPromise=null;
let collectionCatalogLoadPromise=null;
// Overview CP dependency lifecycle: CP projection is intentionally lazy, but
// Overview consumes it. Loading/ready/error is distinct from a genuinely empty
// CP dataset so the first render never freezes on a fake zero-state.
let overviewCpLoadState='idle';
let overviewCpLoadError='';
let overviewRenderFrame=0;
function scheduleOverviewRender(reason='data'){
  window.BLPerf?.mark?.('OVERVIEW_INVALIDATED',{reason});
  if(currentActiveTab()!=='overview'){_deferredTabRenders.add('overview');return;}
  if(overviewRenderFrame)return;
  const raf=window.requestAnimationFrame||((fn)=>setTimeout(fn,0));
  overviewRenderFrame=raf(()=>{
    overviewRenderFrame=0;
    if(currentActiveTab()==='overview')renderOverview();
    else _deferredTabRenders.add('overview');
  });
}
function renderOverviewCpDependencyState(mode,errorMessage=''){
  const host=document.getElementById('cpAssistant');
  const attention=document.getElementById('cpAssistantAttention');
  const coverage=document.getElementById('cpAssistantCoverage');
  if(attention)attention.innerHTML='';
  if(coverage)coverage.innerHTML='';
  if(!host)return;
  const en=appLang==='en';
  const title=en?"Today's Production Focus":'Bugünün Üretim Öncelikleri';
  if(mode==='error'){
    const message=errorMessage||(en?'Production priority data could not be loaded.':'Üretim önceliği verileri yüklenemedi.');
    const retry=en?'Retry':'Tekrar dene';
    host.innerHTML=`<section class="cpaCard"><header><b>${escapeHtml(title)}</b></header><div class="cpaCardBody"><p class="cpaEmpty">${escapeHtml(message)}</p><div class="cpaRowBetween"><span></span><button type="button" class="cpaBtn sm" data-overview-cp-retry>${escapeHtml(retry)}</button></div></div></section>`;
    host.querySelector('[data-overview-cp-retry]')?.addEventListener('click',()=>{
      overviewCpLoadState='idle';overviewCpLoadError='';renderOverviewCpDependencyState('loading');
      void ensureOverviewCpDependency();
    });
    return;
  }
  host.innerHTML=`<section class="cpaCard"><header><b>${escapeHtml(title)}</b></header><div class="cpaCardBody"><p class="cpaEmpty">${escapeHtml(en?'Preparing production priorities…':'Üretim öncelikleri hazırlanıyor…')}</p></div></section>`;
}
function ensureOverviewCpDependency(){
  if(state.cp){overviewCpLoadState='ready';overviewCpLoadError='';return Promise.resolve(true);}
  if(window.BL_CP_SOURCE_FILTER_REQUIRED||window.BL_HAS_CACHED_MODEL_DATA===false)return Promise.resolve(false);
  // Bir hata kartı kullanıcı Retry demeden otomatik request-loop'a dönüşmesin.
  if(overviewCpLoadState==='error')return Promise.resolve(false);
  overviewCpLoadState='loading';
  if(!cpLoadPromise)window.BLPerf?.mark?.('CP_LOAD_START',{reason:'overview'});
  return Promise.resolve(ensureCpLoaded({deferRender:true,reason:'overview'}));
}
const projectionRequestGeneration={overview:0,cp:0,orders:0,'collection-catalog':0};
async function parseProjectionResponse(module,generation,res){
  if(!res.ok){
    const payload=await res.json().catch(()=>({}));
    if(payload.code==='USER_SELECTION_REQUIRED'){location.href='/select-user.html';return {cancelled:true};}
    const error=new Error(payload.error||res.statusText);error.code=payload.code||'';error.sourceFilterStatus=payload.sourceFilterStatus||null;throw error;
  }
  const parseStarted=performance.now(),payload=await res.json();
  window.BLPerf?.record?.(`${module}.jsonParseMs`,performance.now()-parseStarted);
  if(generation!==projectionRequestGeneration[module])return {cancelled:true};
  return {payload,generation};
}
async function fetchProjectionWithFallback(module,fallbackUrl){
  const generation=++projectionRequestGeneration[module];
  let res=await fetch(`/api/page-projection/${encodeURIComponent(module)}`,{cache:'no-store'});
  if(res.status===404)res=await fetch(fallbackUrl,{cache:'no-store'});
  return parseProjectionResponse(module,generation,res);
}
async function fetchOrdersProjection(){
  const generation=++projectionRequestGeneration.orders;
  let res=await fetch('/api/page-projection/orders',{cache:'no-store'});
  if(res.status===404)res=await fetch('/api/data/orders',{cache:'no-store'});
  return parseProjectionResponse('orders',generation,res);
}
async function ensureOverviewLoaded(){
  if(!state.overviewDeferred)return true;
  if(overviewLoadPromise)return overviewLoadPromise;
  overviewLoadPromise=(async()=>{
    try{
      const result=await fetchProjectionWithFallback('overview','/api/data/overview');if(result.cancelled)return false;
      const data=result.payload||{},rows=Array.isArray(data.rows)?data.rows:(Array.isArray(data.overviewSummary)?data.overviewSummary:[]);
      reviveServerDates(rows);
      state.overviewSummary={fname:'Hazır ekran önbelleği',rows};state.overviewDeferred=false;
      window.BL_HAS_CACHED_MODEL_DATA=true;
      if(document.body.dataset.activeTab==='overview')renderOverview();
      return true;
    }catch(err){
      const message=(appLang==='en'?'Overview data could not be loaded: ':'Genel Bakış verisi yüklenemedi: ')+(err&&err.message||err);
      showToast(message);return false;
    }finally{overviewLoadPromise=null;}
  })();
  return overviewLoadPromise;
}
async function ensureCpLoaded(options={}){
  if(state.cp&&!options.force){overviewCpLoadState='ready';overviewCpLoadError='';return true;}
  if(cpLoadPromise)return cpLoadPromise;
  if(options.reason==='overview'){overviewCpLoadState='loading';overviewCpLoadError='';}
  cpLoadPromise=(async()=>{
    try{
      const result=await fetchProjectionWithFallback('cp','/api/data/cp');if(result.cancelled)return false;
      const data=result.payload||{},rows=Array.isArray(data.rows)?data.rows:[];
      reviveServerDates(rows);
      state.cp={fname:'Hazır ekran önbelleği',rows};state.cpLogisticExpanded.clear();
      overviewCpLoadState='ready';overviewCpLoadError='';
      invalidateUnifiedPriorityDecisions('cp-projection-loaded',['cp']);
      syncCpModelColumns(Array.isArray(data.cpModelColumns)?data.cpModelColumns:[]);
      buildCPFilters();applyCoreAutoFilterState();refreshSubmfrList();refreshLicenseList();refreshLicensorList();if(!options.deferRender)renderCP();
      window.BLPerf?.mark?.('CP_LOAD_READY',{reason:options.reason||'cp',rows:rows.length,revision:_unifiedPriorityDataRevision});
      // CP hangi sekme tarafından yüklenmiş olursa olsun Overview artık dirty'dir.
      // Görünürse aynı frame'de bir kez, görünmüyorsa ilk girişte çizilir.
      scheduleOverviewRender('cp-ready');
      return true;
    }catch(err){
      const message=(appLang==='en'?'CP could not be loaded: ':'CP yüklenemedi: ')+(err&&err.message||err);
      if(options.reason==='overview'||currentActiveTab()==='overview'){
        overviewCpLoadState='error';overviewCpLoadError=message;scheduleOverviewRender('cp-load-error');
      }
      showToast(message);return false;
    }finally{cpLoadPromise=null;}
  })();
  return cpLoadPromise;
}
async function ensureCollectionCatalogLoaded(options={}){
  if(!options.force&&collectionCatalogsReady(state.collectionCatalogs))return true;
  if(collectionCatalogLoadPromise)return collectionCatalogLoadPromise;
  collectionCatalogLoadPromise=(async()=>{
    try{
      const result=await fetchProjectionWithFallback('collection-catalog','/api/data/collection-catalog');if(result.cancelled)return false;
      const data=result.payload||{};state.collectionCatalogs=data.catalogs&&typeof data.catalogs==='object'?data.catalogs:{};
      /* v7.41 — Koleksiyon artık yenileme sırasında düzenlemeye AÇIK kaldığı
         için, bu tazeleme o an açık bir düzenlemeyi bozmamalı. Açık bir
         düzenleyici varsa çizim ertelenir; kullanıcı alanı bırakınca zaten
         normal akışta çizilir. Filtre katalogları state'e yazılmış durumda,
         yani hiçbir veri kaybolmaz. */
      const kolEditing=document.activeElement&&typeof document.activeElement.closest==='function'
        &&document.activeElement.closest('#view-koleksiyon input,#view-koleksiyon textarea,#view-koleksiyon select,#view-koleksiyon [contenteditable="true"]');
      if(document.body.dataset.activeTab==='koleksiyon'&&typeof renderKol==='function'&&!kolEditing&&!options.deferRender)renderKol();
      return true;
    }catch(err){showToast((appLang==='en'?'Collection filters could not be loaded: ':'Koleksiyon filtreleri yüklenemedi: ')+(err&&err.message||err));return false;}
    finally{collectionCatalogLoadPromise=null;}
  })();
  return collectionCatalogLoadPromise;
}
function setOrdersLoadingState(loading,message){
  const empty=document.getElementById('ordersEmpty'),content=document.getElementById('ordersContent');
  if(!empty||!content)return;
  if(loading){
    empty.textContent=message||(appLang==='en'?'Loading Orders on demand…':'Siparişler gerektiğinde yükleniyor…');
    empty.style.display='flex';content.style.display='none';
  }
}
async function ensureOrdersLoaded(options={}){
  if(state.orders)return true;
  if(ordersLoadPromise)return ordersLoadPromise;
  setOrdersLoadingState(true);
  ordersLoadPromise=(async()=>{
    try{
      const result=await fetchOrdersProjection();if(result.cancelled)return false;
      const data=result.payload||{};
      const rows=Array.isArray(data.rows)?data.rows:(Array.isArray(data.orders)?data.orders:[]);
      reviveServerDates(rows);
      const sourceName=data.sources&&data.sources.asas?data.sources.asas:(appLang==='en'?'Server':'Sunucu');
      state.orders={fname:`Sunucu: ${sourceName}`,rows:rows.map(row=>({...row,_canEdit:false}))};
      state.ordersLogisticExpanded.clear();
      invalidateUnifiedPriorityDecisions('orders-projection-loaded',['orders']);
      // Sipariş projeksiyonu yenilemeden sonra belleğe alındığında, açık ekranda
      // tutulan lisans royalty kuralları da aynı satırlara yeniden uygulanmalı.
      // Çizim aşağıda tek kez yapılır; burada yalnız türetilmiş fiyatlar hesaplanır.
      applyPricingRulesToLoadedRows({render:false});
      if(data.collectionCatalogs&&typeof data.collectionCatalogs==='object')state.collectionCatalogs=data.collectionCatalogs;
      else void ensureCollectionCatalogLoaded();
      buildOrdersFilters();applyCoreAutoFilterState();if(!options.deferRender)renderOrders();
      return true;
    }catch(err){
      const message=(appLang==='en'?'Orders could not be loaded: ':'Siparişler yüklenemedi: ')+(err&&err.message||err);
      setOrdersLoadingState(true,message);showToast(message);return false;
    }finally{ordersLoadPromise=null;}
  })();
  return ordersLoadPromise;
}
window.BLEnsureOrdersLoaded=ensureOrdersLoaded;
window.BLEnsureCpLoaded=ensureCpLoaded;
/* Global Flow Map veri kaynağı. Harita CP/Orders sayfasının görünür/filtreli
   satırlarını veya son sayfa filtresini DEĞİL, kaynağın bütün veri kümesini
   (state.cp.rows / state.orders.rows) kullanır; yalnız kendi filtreleri
   daraltır. Critical, tek kanonik Unified Action Priority kodundan okunur;
   karar motoru henüz yüklenmediyse yüklendiğinde harita yeniden beslenir. */
function globalFlowSourceRows(tableKey){
  const rows=state[tableKey]&&Array.isArray(state[tableKey].rows)?state[tableKey].rows:[];
  if(rows.length&&!syncUnifiedPrioritiesForTable(tableKey)){
    Promise.resolve(window.BLPerf?.ensureFeature?.('cpAssistant')).then(()=>{
      if(syncUnifiedPrioritiesForTable(tableKey))window.dispatchEvent(new CustomEvent('bl:global-flow-data-changed',{detail:{reason:'priority-ready',tables:[tableKey]}}));
    }).catch(()=>{});
  }
  return rows;
}
/* Yükleme Overview'un koruma yolundan geçer: gizli ızgara çizilmez (deferRender),
   kaynak filtresi zorunluyken/önbellek yokken istek atılmaz ve başarısız bir
   yükleme yalnız kullanıcı haritayı elle yenilediğinde tekrar denenir. */
const globalFlowLoadFailed={cp:false,orders:false};
async function globalFlowEnsure(tableKey,options){
  if(state[tableKey])return true;
  if(window.BL_CP_SOURCE_FILTER_REQUIRED||window.BL_HAS_CACHED_MODEL_DATA===false)return false;
  if(globalFlowLoadFailed[tableKey]&&!(options&&options.force))return false;
  const ok=tableKey==='cp'
    ?(options&&options.force&&overviewCpLoadState==='error'?await ensureCpLoaded({deferRender:true,reason:'overview'}):await ensureOverviewCpDependency())
    :await ensureOrdersLoaded({deferRender:true});
  globalFlowLoadFailed[tableKey]=!ok;return Boolean(ok);
}
window.BLGlobalFlowDataProviders={
  cp:async options=>(await globalFlowEnsure('cp',options))?globalFlowSourceRows('cp'):[],
  orders:async options=>(await globalFlowEnsure('orders',options))?globalFlowSourceRows('orders'):[],
  revision:tableKey=>(_unifiedPriorityTableRevision[tableKey]||0)+':'+(_unifiedPriorityCache[tableKey]?1:0),
};
window.BLEnsureCollectionCatalogLoaded=ensureCollectionCatalogLoaded;

function switchTab(tab){
  const accessArea=(tab==='quotations'||tab==='pricinghistory')?'koleksiyon':tab;
  if(typeof window.BLCanAccessArea==='function'&&!window.BLCanAccessArea(accessArea)){
    if(typeof showToast==='function')showToast(appLang==='en'?'You do not have access to this area.':'Bu yetki alanına erişiminiz bulunmuyor.');
    return false;
  }
  void window.buyerLogDesktop?.workspace?.setModule?.(tab);
  const previousTab=document.body.dataset.activeTab||document.querySelector('nav.tabs button.active')?.dataset.tab||'';
  if(previousTab==='cp'||previousTab==='orders') saveCoreAutoFilterState();
  if(typeof closeAllColumnPanels==='function') closeAllColumnPanels();
  document.body.dataset.activeTab = tab;
  if(tab==='overview'&&state.overviewDeferred)void ensureOverviewLoaded();
  flushDeferredRenderForTab(tab);
  syncTableToolbarActions(tab);
  syncNavExcelButtonLabel(tab);
  syncActivePageTitle();
  document.querySelectorAll('nav.tabs button[data-tab]').forEach(b=>{
    const active=b.dataset.tab===tab;
    const current=b.dataset.tab===tab?'page':null;
    b.classList.toggle('active',active);
    if(current)b.setAttribute('aria-current',current);else b.removeAttribute('aria-current');
  });
  document.querySelectorAll('main section').forEach(s=>s.classList.remove('active'));
  document.getElementById('view-'+tab).classList.add('active');
  const profileAllowed=['cp','orders','shipping','koleksiyon'].includes(tab);
  const profileFirstVisit=profileAllowed&&!_favoritesAppliedPages.has(tab);
  if(profileFirstVisit)_favoritesAppliedPages.add(tab);
  const profileReady=profileFirstVisit?applyProfilesForCurrentPage(true):Promise.resolve();
  if(profileFirstVisit)void profileReady.then(()=>{if(currentActiveTab()!==tab)_favoritesAppliedPages.delete(tab);});
  if(tab==='cp'&&!state.cp){
    const dataReady=ensureCpLoaded({deferRender:profileFirstVisit});
    void (profileFirstVisit?Promise.all([dataReady,profileReady]).then(()=>{
      if(currentActiveTab()!=='cp'||!state.cp)return;
      applyStoredProfilesForCurrentPage(true);
      renderCP();
    }):dataReady);
  }
  if(tab==='orders'&&!state.orders){
    const dataReady=ensureOrdersLoaded({deferRender:profileFirstVisit});
    void (profileFirstVisit?Promise.all([dataReady,profileReady]).then(()=>{
      if(currentActiveTab()!=='orders'||!state.orders)return;
      applyStoredProfilesForCurrentPage(true);
      renderOrders();
    }):dataReady);
  }
  if(tab==='koleksiyon'&&profileFirstVisit){
    const dataReady=ensureCollectionCatalogLoaded({deferRender:true});
    void Promise.all([dataReady,profileReady]).then(()=>{if(currentActiveTab()==='koleksiyon'&&typeof renderKol==='function')renderKol();});
  }
  if(tab==='koleksiyon'||tab==='priceanalysis'||tab==='quotations'||tab==='pricinghistory'){
    void window.BLPerf.ensureFeature('collectionTools').then(()=>{
      if(tab==='priceanalysis')return window.initPriceSupplierAnalysis?.();
      if(tab==='quotations')return window.BL_QUOTATIONS?.mountWorkspace?.(document.getElementById('quotationWorkspacePage'),{source:'collection',preserveContext:true});
      if(tab==='pricinghistory')return window.BL_QUOTATIONS?.mountPricingHistory?.(document.getElementById('pricingHistoryWorkspacePage'),{preserveContext:true});
      if(tab==='koleksiyon')window.BL_QUOTATIONS?.syncCollectionPricingUI?.();
    }).catch(err=>showToast(err.message));
  }
  if(tab==='overview')void ensureOverviewOabModule();
  /* v7.81 — Veri Yönetimi. Lazy: ilk geçişte yüklenir, açılışta değil.
     Sekmeden çıkılıp geri dönülürse modül zaten yüklüdür ve yalnız tazelenir. */
  if(tab==='source'){
    void window.BLPerf.ensureFeature('dataManagement').then(()=>{
      if(currentActiveTab()!=='source')return;
      window.BLDataManagement?.mount?.(document.getElementById('dataManagementRoot'));
    }).catch(err=>showToast(err&&err.message||String(err)));
  }
  if(['cp','orders','shipping'].includes(tab)){
    // Özellik zaten yüklüyse değişmemiş tablo baştan çizilmez (30k satırda her
    // girişte ≈1,3 sn donma). Veri değiştiyse ertelenmiş çizim zaten çalışır.
    const deferredUiWasLoaded=window.BLPerf?.isFeatureLoaded?.('deferredUi')===true;
    void window.BLPerf.ensureFeature('deferredUi').then(()=>{
      if(currentActiveTab()!==tab||deferredUiWasLoaded)return;
      // İlk girişte veri ve kullanıcı profili birlikte çözümleniyor; erken
      // çizim favori görünüm/filtre uygulanmadan yanlış bir tablo göstermemeli.
      if(profileFirstVisit)return;
      if(tab==='cp'&&state.cp)renderCP();
      if(tab==='orders'&&state.orders)renderOrders();
      if(tab==='shipping'&&typeof renderShipTable==='function')renderShipTable();
    }).catch(err=>showToast(err.message));
  }
  if(tab==='koleksiyon'){
    void ensureCollectionCatalogLoaded();
    void (window.BLPerf?.ensureFeature?.('deferredUi') || Promise.resolve()).catch(()=>{});
  }
  if(tab==='backlog'&&typeof fetchCurrentBacklog==='function'&&!backlogLoadedOnce)fetchCurrentBacklog();
  // v9.46 — Teslimat riski analizi açılış kritik yolunda değil: Backlog sekmesi
  // ilk açıldığında lazy yüklenir. Panel kapalıysa hiçbir veri çekmez.
  if(tab==='backlog')void (window.BLPerf?.ensureFeature?.('backlogAnalysis')||Promise.resolve()).catch(()=>{});
  /* v9.48 — Genel Bakış'ın üretim öncelikleri paneli açılış kritik yolunda
     değil: sekmeye geçildiğinde yüklenir, yüklendiğinde mevcut satırlarla
     kendini çizer (Genel Bakış zaten çizilmiş olabilir). */
  if(tab==='overview'){
    // Motor zaten yüklüyse "hazır" olayı yeniden işlenmez: her girişte kararları
    // temizlemek CP/Siparişler önceliklerini ≈1 sn baştan hesaplatıyordu.
    const decisionEngineWasReady=Boolean(window.BLCpAssistant&&typeof window.BLCpAssistant.computeDecisionsForRows==='function');
    void (window.BLPerf?.ensureFeature?.('cpAssistant')||Promise.resolve())
      .then(()=>{if(decisionEngineWasReady)return;try{invalidateUnifiedPriorityDecisions('overview-decision-engine-ready');syncUnifiedPrioritiesForTable('cp');renderOverview();}catch(_){}}).catch(()=>{});
  }
  document.querySelectorAll('.vfMenu.open').forEach(x=>x.classList.remove('open'));
  const bar=document.querySelector('.vfBar');
  const allowed=['cp','orders','shipping','koleksiyon'].includes(tab);
  if(bar){
    bar.hidden=!allowed;
    bar.style.display=allowed?'flex':'none';
    bar.setAttribute('aria-hidden',allowed?'false':'true');
  }
  if(typeof updateShippingBtnVisibility==='function') updateShippingBtnVisibility();
  // Her sayfanın profili ilk girişte yukarıda veri yükleme ile birlikte çözülür;
  // aynı sayfaya dönüldüğünde kullanıcının geçici seçimi korunur.
  if(tab==='koleksiyon' && !profileFirstVisit && typeof renderKol==='function') renderKol();
  if(tab==='shipping' && profileFirstVisit){
    void profileReady.then(()=>{if(currentActiveTab()==='shipping'&&typeof renderShipTable==='function'){
      applyStoredProfilesForCurrentPage(true);
      renderShipTable();
    }});
  }
  if(tab==='lfl')void window.BLPerf.ensureFeature('lfl').then(()=>window.initLFL?.()).catch(err=>showToast(err.message));
  if(tab==='opencosting'){ window.BLPerf.ensureFeature('openCosting').then(()=>window.initOpenCosting?.()).catch(err=>showToast(err.message)); }
  if(tab==='automations')void window.BLPerf.ensureFeature('automations').then(()=>{window.initAutomationStudio?.();window.initAiAutomationImport?.();}).catch(err=>showToast(err.message));
  if(typeof fitTableHeights==='function') setTimeout(fitTableHeights, 0);
  if(typeof syncFreezeButtonState==='function')setTimeout(syncFreezeButtonState,0);
}
function activeTableInfo(){
  const btn = document.querySelector('nav.tabs button.active');
  // Koleksiyon görünüm başlığındaki ortak eylemler (Sütunlar dahil) araç
  // çubuğundan taşınabiliyor. Bu sırada eski sekme düğümünün `.active`
  // sınıfı kısa süreliğine DOM'da bulunmayabiliyor; body'deki aktif sayfa
  // ise tek ve güncel durum kaynağıdır.
  const tab = document.body.dataset.activeTab || btn?.dataset.tab || 'overview';
  const map = {
    cp: {tableKey:'cp', tableSel:'#cpTable', cols:()=>CP_COLS, rowsFn:()=>filteredCP(), selSet:()=>state.cpSelected, computeFn:computeFlags, rerender:()=>renderCP(), csvName:'cp_filtered.csv',
      filterIds:['cpSearch','cpFPriority','cpFCountry','cpFLicense','cpFDelType','cpFStatus','cpFSeason']},
    orders: {tableKey:'orders', tableSel:'#ordersTable', cols:()=>ORDERS_COLS, rowsFn:()=>filteredOrders(), selSet:()=>state.ordersSelected, computeFn:computeFlags, rerender:()=>renderOrders(), csvName:'orders_filtered.csv',
      filterIds:['ordersSearch','ordersFPriority','ordersFCountry','ordersFLicense','ordersFDelType','ordersFStatus','ordersFSeason']},
    shipping: {tableKey:'ship', tableSel:'#shipTable', idAttr:'data-shipid', cols:()=>SHIP_COLS, rowsFn:()=>shipRows.map(r=>({...r,_id:r._shipId})), selSet:()=>new Set([...shipSelected]), computeFn:null, rerender:()=>renderShipTable(), csvName:'nakliye_kiyaslama.csv',
      filterIds:[]},
    koleksiyon: {tableKey:'koleksiyon', tableSel:'#kolTable', cols:()=>kolColDefs(), rowsFn:()=>filteredKol(), selSet:()=>kolSelected, computeFn:null, rerender:()=>renderKol(), csvName:'koleksiyon.xlsx',
      filterIds:['kolSearch']},
  };
  return map[tab] || null;
}
document.getElementById('cpProdStatusBtn')?.addEventListener('click', prepareEmailOpenFromCp);
function fitActiveTableColumns(){
  const info=activeTableInfo();if(!info)return;
  if(info.tableKey==='cp'||info.tableKey==='orders'){
    const tableKey=info.tableKey;
    (COLS_BY_TABLE[tableKey]||[]).forEach(col=>{colmgr[tableKey].widthPx[col.k]=defaultMinPx(col,tableKey);});
    saveAutoTableColumnState();
    info.rerender();
  }else if(info.tableKey==='koleksiyon'){
    kolColDefs().forEach(col=>{kolColWidths[col.k]=kolColMinWidth(col);});
    [
      {kind:'best',k:'__bestPrice__',label:L('Best Price')},
      {kind:'confirmedName',k:'__confirmedName__',label:L('Conf. Manufacturer')},
      {kind:'confirmedPrice',k:'__confirmedPrice__',label:L('Conf. FOB')},
    ].forEach(descriptor=>{kolColWidths[descriptor.k]=kolDescriptorMinWidth(descriptor);});
    saveKolColState();
    renderKol();
  }else return;
  showToast(appLang==='en'?'All columns fitted to their narrowest readable width.':'Tüm sütunlar en dar okunabilir genişliğe ayarlandı.');
}
document.getElementById('navFitColumnsBtn')?.addEventListener('click',fitActiveTableColumns);
document.getElementById('navFreezeBtn')?.addEventListener('click', freezeStart);
loadFreezeState();
function activeFilterColumnLabel(tableKey,key){
  if(tableKey==='koleksiyon')return L(kolFilterMeta(key)?.label||key);
  const column=(COLS_BY_TABLE[tableKey]||[]).find(item=>item.k===key);
  return L(column?.l||column?.k||key);
}
function activeFilterEntrySummary(entry){
  const values=[...(entry?.values||[])].map(value=>norm(value)||'—');
  if(values.length===1)return values[0];
  if(values.length===2)return values.join(', ');
  if(values.length>2)return appLang==='en'?`${values.length} values`:`${values.length} değer`;
  if(entry?.numericRule)return appLang==='en'?'Number rule':'Sayı kuralı';
  if(entry?.granularity)return appLang==='en'?'Date rule':'Tarih kuralı';
  return appLang==='en'?'Active':'Aktif';
}
function activeTableFilterTokens(tableKey){
  const tokens=[];
  const searchId=tableKey==='koleksiyon'?'kolSearch':`${tableKey}Search`;
  const search=norm(document.getElementById(searchId)?.value);
  if(search)tokens.push({kind:'search',key:searchId,label:appLang==='en'?'Search':'Arama',detail:search});
  if(tableKey==='koleksiyon'){
    Object.entries(kolColFilters||{}).forEach(([key,entry])=>{
      if(entry&&entry.size)tokens.push({kind:'column',key,label:activeFilterColumnLabel(tableKey,key),detail:activeFilterEntrySummary({values:entry})});
    });
    const checked=normalizeCheckFilterMode(kolCheckFilter);
    if(checked)tokens.push({kind:'check',key:'',label:appLang==='en'?'Rows':'Satırlar',detail:checked==='checked'?(appLang==='en'?'Checked':'İşaretli'):(appLang==='en'?'Unchecked':'İşaretsiz')});
    return tokens;
  }
  const selectLabels={
    [`${tableKey}FPriority`]:'Priority',[`${tableKey}FCountry`]:appLang==='en'?'Country':'Ülke',[`${tableKey}FLicense`]:appLang==='en'?'License':'Lisans',
    [`${tableKey}FDelType`]:'Del. Type',[`${tableKey}FStatus`]:'STATUS',[`${tableKey}FSeason`]:'Season',
  };
  Object.entries(selectLabels).forEach(([id,label])=>{const value=norm(document.getElementById(id)?.value);if(value)tokens.push({kind:'select',key:id,label,detail:value});});
  Object.entries(state.colFilters[tableKey]||{}).forEach(([key,entry])=>{
    if(entry)tokens.push({kind:'column',key,label:activeFilterColumnLabel(tableKey,key),detail:activeFilterEntrySummary(entry)});
  });
  const checked=normalizeCheckFilterMode(state.checkFilter[tableKey]);
  if(checked)tokens.push({kind:'check',key:'',label:appLang==='en'?'Rows':'Satırlar',detail:checked==='checked'?(appLang==='en'?'Checked':'İşaretli'):(appLang==='en'?'Unchecked':'İşaretsiz')});
  if(tableKey==='orders'&&state.ordersQuickActive?.size)tokens.push({kind:'quickActive',key:'',label:appLang==='en'?'Order state':'Sipariş durumu',detail:[...state.ordersQuickActive].map(value=>value==='Active'?(appLang==='en'?'Active':'Aktif'):(appLang==='en'?'Inactive':'Pasif')).join(', ')});
  if(tableKey==='orders'&&norm(state.ordersQuickExf))tokens.push({kind:'quickExf',key:'',label:'Ex-Factory',detail:state.ordersQuickExf});
  return tokens;
}
function renderActiveFilterContext(tableKey){
  if(tableKey!=='cp'&&tableKey!=='orders'&&tableKey!=='koleksiyon')return;
  const prefix=tableKey==='koleksiyon'?'kol':tableKey;
  const bar=document.getElementById(`${prefix}ActiveFilters`),wrap=document.getElementById(`${prefix}ActiveFilterTokens`);
  if(!bar||!wrap)return;
  bar.setAttribute('aria-label',appLang==='en'?'Active table filters':'Aktif tablo filtreleri');
  const tokens=activeTableFilterTokens(tableKey),removeText=appLang==='en'?'Remove filter':'Filtreyi kaldır';
  wrap.innerHTML=tokens.length?tokens.map(token=>{
    const text=`${token.label}: ${token.detail}`;
    return `<button type="button" class="activeFilterToken" data-filter-remove data-filter-kind="${escapeHtml(token.kind)}" data-filter-key="${escapeHtml(token.key)}" title="${escapeHtml(`${removeText}: ${text}`)}" aria-label="${escapeHtml(`${removeText}: ${text}`)}"><span>${escapeHtml(text)}</span><svg class="ic" aria-hidden="true"><use href="#i-x"/></svg></button>`;
  }).join(''):`<span class="activeFilterEmpty">${escapeHtml(appLang==='en'?'No active table filters':'Aktif tablo filtresi yok')}</span>`;
  bar.dataset.activeCount=String(tokens.length);
  const clear=bar.querySelector('[data-active-filter-clear]');if(clear)clear.hidden=!tokens.length;
  wrap.querySelectorAll('[data-filter-remove]').forEach(button=>button.addEventListener('click',()=>removeActiveFilterToken(tableKey,button.dataset.filterKind,button.dataset.filterKey)));
}
function removeActiveFilterToken(tableKey,kind,key){
  if(kind==='search'||kind==='select'){const input=document.getElementById(key);if(input)input.value='';}
  else if(kind==='column'){
    if(tableKey==='koleksiyon'){delete kolColFilters[key];saveKolColState();}
    else if(state.colFilters[tableKey])delete state.colFilters[tableKey][key];
  }else if(kind==='check'){
    if(tableKey==='koleksiyon'){kolCheckFilter='';saveKolColState();}
    else state.checkFilter[tableKey]='';
  }else if(tableKey==='orders'&&kind==='quickActive')state.ordersQuickActive.clear();
  else if(tableKey==='orders'&&kind==='quickExf')state.ordersQuickExf='';
  saveCoreAutoFilterState();
  if(tableKey==='cp')renderCP();else if(tableKey==='orders')renderOrders();else if(tableKey==='koleksiyon')renderKol();
}
function clearTableFilters(tableKey,{announce=true}={}){
  const filterIds={
    cp:['cpSearch','cpFPriority','cpFCountry','cpFLicense','cpFDelType','cpFStatus','cpFSeason'],
    orders:['ordersSearch','ordersFPriority','ordersFCountry','ordersFLicense','ordersFDelType','ordersFStatus','ordersFSeason'],
    koleksiyon:['kolSearch'],
  }[tableKey]||[];
  filterIds.forEach(id=>{const control=document.getElementById(id);if(control)control.value='';});
  if(tableKey==='koleksiyon'){
    kolColFilters={};kolCheckFilter='';saveKolColState();
  }else if(tableKey==='cp'||tableKey==='orders'){
    state.colFilters[tableKey]={};state.checkFilter[tableKey]='';
    if(tableKey==='cp')state.cpQuickExf='';
    if(tableKey==='orders'){state.ordersQuickExf='';state.ordersQuickActive.clear();}
  }
  // Sayfa kapsamı (Buyer, Country, MAG, MMYG vb.) bilerek korunur. Bu eylem
  // yalnız tablonun arama/hızlı/sütun/işaretleme filtrelerini sıfırlar.
  if(tableKey==='cp')renderCP();
  else if(tableKey==='orders')renderOrders();
  else if(tableKey==='koleksiyon')renderKol();
  else if(tableKey==='ship')renderShipTable();
  saveCoreAutoFilterState();
  if(announce)showToast(appLang==='en'?'Table filters cleared; page scope preserved.':'Tablo filtreleri temizlendi; sayfa kapsamı korundu.');
}
document.querySelectorAll('[data-active-filter-clear]').forEach(button=>button.addEventListener('click',()=>clearTableFilters(button.dataset.activeFilterClear)));
document.getElementById('navClearFilters').addEventListener('click', ()=>{
  const info=activeTableInfo();if(info)clearTableFilters(info.tableKey);
});
// CTRL+C (macOS'ta CMD+C): etkin sayfanın Kopyala düğmesini çalıştırır.
// Metin seçiliyse ya da bir alana yazılıyorsa araya girilmez — orada tarayıcının
// kendi kopyalaması (ve hücre aralığı kopyalayan 'copy' dinleyicisi) doğru olan.
function blActiveCopyButton(){
  const btn = document.querySelector('nav.tabs button.active');
  const tab = btn ? btn.dataset.tab : '';
  const id = tab==='koleksiyon' ? 'kolCopySelectedBtn' : 'navCopy';
  const node = document.getElementById(id);
  if(!node || node.disabled || !node.offsetParent) return null;
  return node;
}
function updateGridSelectionStatus(tableKey,size){
  const node=document.getElementById('gridSelectionStatus');if(!node)return;
  if(String(document.body.dataset.activeTab||'')!==String(tableKey)||!size){node.textContent='';node.hidden=true;return;}
  node.hidden=false;node.textContent=`${size.label} · ${size.cells} ${appLang==='en'?'cells':'hücre'}`;
}
function managedGridHasRange(tab=document.body.dataset.activeTab){
  const tableId=tab==='cp'?'cpTable':tab==='orders'?'ordersTable':'';
  return Boolean(tableId&&window.BLGridClipboard?.state?.(tableId)?.selectionRange);
}
// İşaretli satır varsa Copy, bayat hücre/aralık durumu render gecikmesiyle
// hâlâ ayakta kalmış olsa bile satırları esas alır (bkz. registerManagedGridClipboard).
function managedTableHasCheckedRows(tab){
  if(tab==='cp')return state.cpSelected.size>0;
  if(tab==='orders')return state.ordersSelected.size>0;
  return false;
}
function copyGridSelection(includeHeaders=true,event=null){
  const tab=document.body.dataset.activeTab||'';
  if(tab==='koleksiyon'){
    if(window.BLCollectionSpreadsheet?.handleCopyShortcut?.(event||new Event('copy'),{includeHeaders}))return true;
    // İşaretli model varsa handleCopyShortcut kasıtlı olarak devretti (satır
    // seçimi hücre seçiminden önceliklidir); mevcut satır-kopyalama düğmesini kullan.
    document.getElementById('kolCopySelectedBtn')?.click();
    return true;
  }
  if(!managedTableHasCheckedRows(tab)&&managedGridHasRange(tab)){void window.BLGridClipboard.copyActive(event,{includeHeaders});return true;}
  if(includeHeaders){blActiveCopyButton()?.click();return true;}
  showToast(appLang==='en'?'Select a rectangular cell range first.':'Önce dikdörtgen bir hücre aralığı seçin.');return false;
}
let _gridClipboardOutsideHandler=null;
function closeGridClipboardMenu(){
  if(_gridClipboardOutsideHandler){document.removeEventListener('pointerdown',_gridClipboardOutsideHandler,true);_gridClipboardOutsideHandler=null;}
  const menu=document.getElementById('gridClipboardMenu');
  if(menu){window.BLLayerSystem?.closeMenu(menu);menu.remove();}
  document.getElementById('navCopyMenuBtn')?.setAttribute('aria-expanded','false');
}
function openClipboardDiagnostics(){
  closeGridClipboardMenu();document.querySelector('.gridClipboardDiagnosticsOverlay')?.remove();
  const entries=window.BLGridClipboard?.diagnostics?.list?.()||[],overlay=document.createElement('div');overlay.className='kolSpreadsheetPasteOverlay gridClipboardDiagnosticsOverlay';
  const rows=entries.length?entries.slice().reverse().map(item=>`<tr><td>${escapeHtml(item.at||'')}</td><td>${escapeHtml(item.module||'')}</td><td>${escapeHtml(item.operation||'')}</td><td>${escapeHtml(item.selection?`${item.selection.rows}×${item.selection.columns}`:'—')}</td><td>${item.ok?'✓':'×'}</td><td>${escapeHtml(item.error||'')}</td></tr>`).join(''):`<tr><td colspan="6">${appLang==='en'?'No clipboard events recorded.':'Kaydedilmiş pano olayı yok.'}</td></tr>`;
  overlay.innerHTML=`<div class="kolSpreadsheetPasteCard gridClipboardDiagnosticsCard" role="dialog" aria-modal="true" aria-labelledby="gridClipboardDiagnosticsTitle" tabindex="-1"><div class="kolSpreadsheetPasteHead"><b id="gridClipboardDiagnosticsTitle">${appLang==='en'?'Clipboard diagnostics':'Pano hata teşhisi'}</b><span>${appLang==='en'?'Metadata only; copied values are never recorded.':'Yalnız metadata; kopyalanan değerler kaydedilmez.'}</span></div><div class="kolSpreadsheetPasteBody"><table class="gridClipboardDiagnosticsTable"><thead><tr><th>${appLang==='en'?'Time':'Zaman'}</th><th>${appLang==='en'?'Module':'Modül'}</th><th>${appLang==='en'?'Action':'İşlem'}</th><th>${appLang==='en'?'Range':'Alan'}</th><th>${appLang==='en'?'OK':'Başarılı'}</th><th>${appLang==='en'?'Error':'Hata'}</th></tr></thead><tbody>${rows}</tbody></table></div><div class="kolSpreadsheetPasteFoot"><button class="tbtn" data-clear>${appLang==='en'?'Clear':'Temizle'}</button><button class="tbtn primary" data-close>${appLang==='en'?'Close':'Kapat'}</button></div></div>`;
  const close=()=>overlay.remove();overlay.querySelector('[data-close]').onclick=close;overlay.querySelector('[data-clear]').onclick=()=>{window.BLGridClipboard?.diagnostics?.clear?.();close();showToast(appLang==='en'?'Clipboard diagnostics cleared.':'Pano tanılama kayıtları temizlendi.');};overlay.addEventListener('click',event=>{if(event.target===overlay)close();});document.body.appendChild(overlay);overlay.querySelector('.gridClipboardDiagnosticsCard')?.focus();
}
document.getElementById('navCopyMenuBtn')?.addEventListener('click',event=>{
  event.stopPropagation();closeGridClipboardMenu();const button=event.currentTarget,rect=button.getBoundingClientRect(),menu=document.createElement('div');menu.id='gridClipboardMenu';menu.className='kolSpreadsheetContextMenu';menu.setAttribute('role','menu');
  [{label:appLang==='en'?'Copy with headers':'Başlıklarla kopyala',run:()=>copyGridSelection(true)},{label:appLang==='en'?'Copy without headers':'Başlıksız kopyala',run:()=>copyGridSelection(false)},{label:appLang==='en'?'Clipboard diagnostics':'Pano hata teşhisi',run:openClipboardDiagnostics}].forEach(item=>{const node=document.createElement('button');node.type='button';node.setAttribute('role','menuitem');node.textContent=item.label;node.onclick=()=>{closeGridClipboardMenu();item.run();};menu.appendChild(node);});
  document.body.appendChild(menu);menu.style.left=Math.max(4,Math.min(rect.left,innerWidth-menu.offsetWidth-4))+'px';menu.style.top=Math.min(innerHeight-menu.offsetHeight-4,rect.bottom+4)+'px';button.setAttribute('aria-expanded','true');
  window.BLLayerSystem?.openMenu(menu,{trigger:button,onClose:closeGridClipboardMenu,label:appLang==='en'?'Copy options':'Kopyalama seçenekleri'});
  _gridClipboardOutsideHandler=outsideEvent=>{if(!menu.contains(outsideEvent.target))closeGridClipboardMenu();};
  setTimeout(()=>document.addEventListener('pointerdown',_gridClipboardOutsideHandler,true),0);
});
document.addEventListener('keydown', event=>{
  if(event.defaultPrevented) return;
  if(event.key!=='c' && event.key!=='C') return;
  if(!(event.ctrlKey||event.metaKey) || event.altKey || event.shiftKey) return;
  if(blOverlayOpen()) return;
  const target = event.target;
  // Collection single-click editing keeps the real input focused. Give the spreadsheet
  // controller first refusal: it preserves a deliberate substring selection, but when
  // there is no native text selection Ctrl+C still copies the active cell/range as TSV.
  if((document.body.dataset.activeTab||'')==='koleksiyon' && window.BLCollectionSpreadsheet?.handleCopyShortcut?.(event)) return;
  if(target && (target.closest('input,textarea,select,[contenteditable="true"]'))) return;
  const selection = window.getSelection();
  if(selection && selection.rangeCount && !selection.isCollapsed) return;
  const node = blActiveCopyButton(); if(!node) return;
  event.preventDefault();
  node.click();
});
document.getElementById('navCopy').addEventListener('click', event=>{
  const info = activeTableInfo(); if(!info){ showToast('Önce bir sekme seç'); return; }
  if((info.tableKey==='cp'||info.tableKey==='orders')&&!managedTableHasCheckedRows(info.tableKey)&&managedGridHasRange(info.tableKey)){void window.BLGridClipboard.copyActive(event,{includeHeaders:true});return;}
  // Shipping Comparison'da üstteki karar tablosu asıl kullanıcı görünümüdür.
  // Genel Copy düğmesi alt ham Excel/grid tablosunu değil, bu görünümün güncel
  // state'ini model başına tek satır olacak şekilde kopyalar.
  if(info.tableKey==='ship'){ void copyShipComparisonFlat(event.currentTarget); return; }
  // Kopyalama, "Excel'e Aktar" ile aynı hücre biçimini üretir: biçimler ekrandaki
  // tablodan (aydınlık temaya zorlanarak) okunur.
  // CP ve Orders ekrandan DEĞİL kayıttan serialize edilir: 1 kayıt = 1 <tr>.
  // Ekran DOM'u (pencereli çizim boşluk satırları, lojistik detay satırı,
  // dondurulmuş sütun katmanı, normalize edilmemiş hücre metni) Excel'de
  // satırı ikiye bölüp komşu sütunları dikey birleştiriyordu.
  if(info.tableKey==='cp'||info.tableKey==='orders'){
    void copyManagedTableLikeExcel(info.tableKey, info.rowsFn(), info.selSet(), 'navCopy');
    return;
  }
  if(info.tableSel && document.querySelector(info.tableSel)){
    // v10.10 — Orders sütun grupları CP ile aynıdır (ORDERS_COLS, CP_COLS
    // kopyası); CP'de yalnız gerçek sütun başlığı gittiği hâlde Orders'ta grup
    // başlık satırı da kopyaya sızıyordu (fazladan üst başlık). İkisi de
    // yalnız gerçek sütun başlıklarını taşımalı.
    copyStyledTableLikeExcel(info.tableSel, info.selSet(), info.idAttr, 'navCopy', info.rerender, {leafHeadersOnly:info.tableKey==='cp'||info.tableKey==='orders'});
    return;
  }
  copyRows(info.tableKey, info.rowsFn(), info.selSet(), 'navCopy', info.computeFn);
});

/* ===================================================================
   AÇILIR PENCERE ALTYAPISI (v5.80)

   İki eski sorun:

   1) ESC yalnız odak pencerenin İÇİNDEYKEN çalışıyordu. Modallar ESC'i kendi
      elemanlarına bağlıyor (modal.addEventListener('keydown', …)); kullanıcı
      pencereye tıklamadan ESC'e basınca olay hiç ulaşmıyordu.
   2) Pencere üzerinde tekerlek çevirince arkadaki sayfa da kayıyordu.

   Çözüm, her modalı tek tek değiştirmeden:
   · ESC belge düzeyinde YAKALAMA evresinde dinlenir, EN ÜSTTEKİ pencere bulunur
     ve ESC ona iletilir. Böylece her pencerenin KENDİ kapatma mantığı (iç panel
     varsa önce onu kapatma gibi) olduğu gibi çalışmaya devam eder; üst üste
     pencerelerde her ESC yalnız en üsttekini kapatır.
   · Tekerlek/dokunma, pencerenin içinde kaydırılabilir bir alan yoksa ya da o
     alan zaten sınırına gelmişse durdurulur — arkadaki sayfaya geçmez.

   .appBlockingOverlay bilerek listede yok: işlem sürerken kapatılamamalı.
   =================================================================== */
const BL_OVERLAY_SELECTOR = [
  '.warnOverlay', '.backlogDetailOverlay', '.backlogDimAddOverlay',
  '.accessAdminOverlay', '.autoModalOverlay', '.awModalOverlay',
  '.globalSearchOverlay', '.quotationAccessOverlay', '.uaOverlay',
].join(',');

function blOverlayStack(){
  // DOM sırası yığın sırasıdır: sonradan eklenen pencere üsttedir.
  return [...document.querySelectorAll(BL_OVERLAY_SELECTOR)].filter(el=>{
    if(el.hidden || el.classList.contains('appBlockingOverlay')) return false;
    const style=getComputedStyle(el);
    return style.display!=='none' && style.visibility!=='hidden';
  });
}
function blTopOverlay(){ const stack=blOverlayStack(); return stack.length?stack[stack.length-1]:null; }
function blOverlayOpen(){ return Boolean(blTopOverlay()); }

let _blEscRelay = false;
document.addEventListener('keydown', event=>{
  if(event.key!=='Escape' || _blEscRelay) return;
  const top = blTopOverlay(); if(!top) return;
  // Odak zaten pencerenin içindeyse kendi dinleyicisi çalışacak; araya girmeyiz,
  // yoksa iç panel/kademe mantığı iki kez tetiklenir.
  const active = document.activeElement;
  if(active && top.contains(active) && active!==document.body) return;
  _blEscRelay = true;
  try{
    top.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',code:'Escape',bubbles:true,cancelable:true}));
  } finally { _blEscRelay = false; }
  // Pencere kendi ESC dinleyicisini kurmamışsa kapatma düğmesine basılır.
  if(top.isConnected){
    const btn = top.querySelector('[data-overlay-close]')
      || [...top.querySelectorAll('button')].find(b=>/(^|[\s_])(close|kapat)/i.test(b.className)||/close|kapat/i.test(b.getAttribute('title')||''));
    if(btn) btn.click();
  }
  event.preventDefault(); event.stopPropagation();
}, true);

// Kaydırma zinciri: olayın hedefinden pencereye kadar çıkıp gerçekten
// kaydırılabilecek bir alan var mı diye bakılır. Yoksa olay burada biter.
function _blScrollableAncestor(node, root, deltaY){
  let el = node instanceof Element ? node : (node && node.parentElement);
  while(el && el!==root.parentElement){
    const style=getComputedStyle(el);
    const scrolls=/(auto|scroll|overlay)/.test(style.overflowY);
    if(scrolls && el.scrollHeight>el.clientHeight+1){
      const atTop = el.scrollTop<=0, atBottom = el.scrollTop+el.clientHeight>=el.scrollHeight-1;
      if(!((deltaY<0&&atTop)||(deltaY>0&&atBottom))) return el;
    }
    el=el.parentElement;
  }
  return null;
}
document.addEventListener('wheel', event=>{
  const overlay = event.target instanceof Element ? event.target.closest(BL_OVERLAY_SELECTOR) : null;
  if(!overlay || overlay.classList.contains('appBlockingOverlay')) return;
  if(_blScrollableAncestor(event.target, overlay, event.deltaY)) return;
  event.preventDefault();
}, {passive:false});

function resetColumnPanelPosition(panel){
  if(!panel) return;
  panel.classList.remove('viewportFloating');
  ['position','zIndex','left','top','right','bottom','visibility','display','maxWidth','maxHeight'].forEach(k=>panel.style[k]='');
}
function closeColumnPanel(panel){
  if(!panel) return;
  panel.classList.remove('show');
  (panel._buyerLogAnchor||panel.closest('.colPanelWrap')?.querySelector('[aria-expanded]'))?.setAttribute?.('aria-expanded','false');
  resetColumnPanelPosition(panel);
}
function closeAllColumnPanels(except=null){
  document.querySelectorAll('#navColPanel,#shipColPanel,#shipHiddenRowsPanel').forEach(panel=>{
    if(panel!==except) closeColumnPanel(panel);
  });
}
function positionColumnPanelAtAnchor(panel,anchor){
  if(!panel||!anchor||!panel.classList.contains('show')) return;
  panel.classList.add('viewportFloating');
  panel.style.position='fixed'; panel.style.right='auto'; panel.style.bottom='auto'; panel.style.zIndex='260';
  panel.style.display='block'; panel.style.visibility='hidden';
  const rect=anchor.getBoundingClientRect();
  const width=Math.min(Math.max(panel.offsetWidth||210,210),Math.max(210,window.innerWidth-16));
  const height=Math.min(panel.offsetHeight||320,Math.max(120,window.innerHeight-16));
  let left=rect.left+(rect.width-width)/2;
  left=Math.max(8,Math.min(left,window.innerWidth-width-8));
  let top=rect.bottom+6;
  if(top+height>window.innerHeight-8) top=Math.max(8,rect.top-height-6);
  panel.style.left=Math.round(left)+'px'; panel.style.top=Math.round(top)+'px';
  panel.style.maxWidth='calc(100vw - 16px)'; panel.style.maxHeight='min(360px, calc(100vh - 16px))';
  panel.style.visibility='visible';
}
function toggleColumnPanel(panel, renderFn, anchor){
  if(!panel) return;
  const wasOpen = panel.classList.contains('show');
  closeAllColumnPanels();
  if(wasOpen) return;
  // Araç çubuğu yatay kaydırılan/transform uygulanmış bir kabın içinde
  // olduğunda position:fixed bile o kaba göre hesaplanır ve sağ kenarda
  // kesilir. Paneli geçici değil, kalıcı bir popover katmanı olarak body'ye
  // taşıyoruz; ankora ait bilgi yeniden konumlandırmalar için saklanır.
  if(panel.parentElement!==document.body) document.body.appendChild(panel);
  panel._buyerLogAnchor=anchor||null;
  renderFn();
  panel.classList.add('show');
  anchor?.setAttribute?.('aria-expanded','true');
  requestAnimationFrame(()=>positionColumnPanelAtAnchor(panel,anchor||panel.closest('.colPanelWrap')?.querySelector('button')));
}
document.getElementById('navColsBtn').addEventListener('click', e=>{
  e.preventDefault();
  e.stopPropagation();
  const info = activeTableInfo(); if(!info) return;
  const panel = document.getElementById('navColPanel');
  toggleColumnPanel(panel, ()=>{
    if(info.tableKey==='koleksiyon') renderKolColumnPanel(panel);
    else renderColPanel(info.tableKey, panel, info.rerender);
  }, e.currentTarget);
});
// Click olayı bazı tablo yeniden çizimlerinde tetiklenmeyebildiği için dışarı tıklama
// pointerdown aşamasında yakalanır. Panelin veya tetikleyici düğmenin içindeki işlemler
// açık paneli kapatmaz; ekranın başka bir yerine basıldığında panel kesin olarak kapanır.
document.addEventListener('pointerdown', e=>{
  if(e.target.closest('#navColsBtn,#shipColsBtn,#shipHiddenRowsBtn')) return;
  if(e.target.closest('#navColPanel.show,#shipColPanel.show,#shipHiddenRowsPanel.show')) return;
  closeAllColumnPanels();
}, true);
document.addEventListener('keydown', e=>{
  if(e.key==='Escape') closeAllColumnPanels();
});

