let _imageDeleteConfirmPopover=null,_imageDeleteConfirmCleanup=null;
function closeImageDeleteConfirm(){
  if(_imageDeleteConfirmCleanup){try{_imageDeleteConfirmCleanup();}catch(_){} _imageDeleteConfirmCleanup=null;}
  if(_imageDeleteConfirmPopover)_imageDeleteConfirmPopover.remove();
  _imageDeleteConfirmPopover=null;
}
function openImageDeleteConfirm(anchorEl,{message,onConfirm}={}){
  closeImageDeleteConfirm();
  if(!anchorEl||!anchorEl.isConnected||typeof onConfirm!=='function')return;
  const pop=document.createElement('div');
  pop.className='imageDeleteConfirmPopover';
  pop.setAttribute('role','dialog');
  pop.setAttribute('aria-label',appLang==='en'?'Remove image confirmation':'Görsel kaldırma onayı');
  pop.innerHTML=`<div class="imageDeleteConfirmText">${escapeHtml(message||(appLang==='en'?'Remove this image?':'Bu görsel kaldırılsın mı?'))}</div><div class="imageDeleteConfirmActions">${typeof onFetch==='function'?`<button type="button" class="imageFetchPlm">${escapeHtml(appLang==='en'?'Fetch from PLM':'PLM\'den Çağır')}</button>`:''}<button type="button" class="imageDeleteCancel">${escapeHtml(appLang==='en'?'Cancel':'Vazgeç')}</button><button type="button" class="imageDeleteApprove">${escapeHtml(appLang==='en'?'Remove':'Kaldır')}</button></div>`;
  document.body.appendChild(pop);_imageDeleteConfirmPopover=pop;
  const place=()=>{
    if(!anchorEl.isConnected){closeImageDeleteConfirm();return;}
    const r=anchorEl.getBoundingClientRect(),margin=8,gap=7,w=pop.offsetWidth||220,h=pop.offsetHeight||82;
    if(r.bottom<=0||r.top>=innerHeight||r.right<=0||r.left>=innerWidth){closeImageDeleteConfirm();return;}
    let left=r.left+(r.width-w)/2;
    left=Math.max(margin,Math.min(left,innerWidth-w-margin));
    let top=r.bottom+gap,above=false;
    if(top+h>innerHeight-margin){top=Math.max(margin,r.top-h-gap);above=true;}
    pop.classList.toggle('isAbove',above);
    pop.style.left=Math.round(left)+'px';pop.style.top=Math.round(top)+'px';
    pop.style.setProperty('--image-confirm-arrow-x',Math.max(16,Math.min(w-16,r.left+r.width/2-left))+'px');
  };
  const outside=event=>{if(!pop.contains(event.target)&&event.target!==anchorEl)closeImageDeleteConfirm();};
  const esc=event=>{if(event.key==='Escape')closeImageDeleteConfirm();};
  const cancel=()=>closeImageDeleteConfirm();
  pop.querySelector('.imageDeleteCancel')?.addEventListener('click',cancel);
  pop.querySelector('.imageFetchPlm')?.addEventListener('click',async event=>{
    const btn=event.currentTarget;btn.disabled=true;
    const label=btn.textContent;btn.textContent=appLang==='en'?'Fetching…':'Çağrılıyor…';
    try{await onFetch();closeImageDeleteConfirm();}
    catch(err){btn.disabled=false;btn.textContent=label;showToast((appLang==='en'?'Image could not be fetched: ':'Görsel çağrılamadı: ')+(err&&err.message||err));}
  });
  pop.querySelector('.imageDeleteApprove')?.addEventListener('click',async event=>{
    const btn=event.currentTarget;btn.disabled=true;
    try{await onConfirm();closeImageDeleteConfirm();}
    catch(err){btn.disabled=false;showToast((appLang==='en'?'Image could not be removed: ':'Görsel kaldırılamadı: ')+(err&&err.message||err));}
  });
  document.addEventListener('pointerdown',outside,true);
  document.addEventListener('keydown',esc);
  window.addEventListener('resize',place,{passive:true});
  document.addEventListener('scroll',place,true);
  _imageDeleteConfirmCleanup=()=>{
    document.removeEventListener('pointerdown',outside,true);
    document.removeEventListener('keydown',esc);
    window.removeEventListener('resize',place);
    document.removeEventListener('scroll',place,true);
  };
  place();requestAnimationFrame(()=>pop.querySelector('.imageDeleteApprove')?.focus({preventScroll:true}));
}
window.BLConfirmImageDelete=openImageDeleteConfirm;
