const ORDERS_COLS = [ORDERS_STATUS_COL, ...CP_COLS.map(c=>({...c}))];
/* Grup bantları artık doygun renk + beyaz yazı yerine, tabloyla aynı sakin
   yüzey rengini kullanır; ayrım rengi ince bir ÜST ÇİZGİ ile verilir (yazı
   okunurluğu bozulmaz). Renkler CSS'te .groupRow th[data-grp] ile uygulanır. */
const GROUP_ACCENTS = {'ORDER INFO':'var(--acc)','ONAY':'var(--green)','LOJİSTİK':'var(--purple)','NOTLAR':'var(--ink2)','PRE-PROD':'var(--teal)','PRE-SHIP':'var(--acc)','KUMAŞ':'var(--orange)','Hesaplanan':'var(--pink,var(--purple))'};

function initColState(cols){ return { order: cols.map(c=>c.k), hidden:new Set(), widthPx:{} }; }
const colmgr = { cp: initColState(CP_COLS), orders:initColState(ORDERS_COLS), ship: initColState(SHIP_COLS) };
const COLS_BY_TABLE = { cp:CP_COLS, orders:ORDERS_COLS, ship:SHIP_COLS };
const CP_BASE_COLUMN_KEYS=new Set(CP_COLS.map(c=>c.k));
// Tek tip çözümleme kapısı: sütun tanımları ve ham satırlar ayrı tutulur;
// schema yalnız görünüm/filtre/sıralama/export katmanında kullanılır.
function resolveTableColumnSchemas(tableKey,rows){
  const resolver=window.BLColumnSchema&&window.BLColumnSchema.resolveColumnSchema;
  if(typeof resolver!=='function')return;
  (COLS_BY_TABLE[tableKey]||[]).forEach(column=>{
    column._blSchema=resolver(column,Array.isArray(rows)?rows:[],column.sourceMetadata||column.metadata);
  });
}
function columnSchemaFor(column,rows){
  if(!column)return null;
  const resolver=window.BLColumnSchema&&window.BLColumnSchema.resolveColumnSchema;
  if(typeof resolver!=='function')return null;
  return column._blSchema||resolver(column,Array.isArray(rows)?rows:[],column.sourceMetadata||column.metadata);
}

/* v7.42 — ÜST BAŞLIK (GRUP) YÖNETİMİ — TEK YERDE.

   Kullanıcı talebi (birebir): "sütun ve hesaplamalı sütun eklerken temel sütun
   başlığını da ayarlayabileyim. Şu an Calculated Column adı altında görünüyor,
   dilersem Order Info'ya dahil edebileyim, dilersem yeni alan adı
   yaratabileyim."

   Başlık satırı bandı, sütunların grup adından değil, YAN YANA duran aynı gruplu
   sütun dizisinden kurar. Bu yüzden bir sütuna "Order Info" demek yetmez; sütun o
   grubun yanına taşınmazsa ekranda İKİNCİ bir "Order Info" bandı belirir ve
   kullanıcı haklı olarak "dahil edemedim" der. Aşağıdaki iki işlevi hem veri
   tabanı sütunu hem hesaplanan sütun kullanır; davranış iki yerde yazılmaz. */
const groupKey=value=>String(value==null?'':value).trim().toLocaleLowerCase('tr-TR');
const DEFAULT_MODEL_COLUMN_GROUP='Database';
// Tabloda o an var olan başlıklar — kullanıcının ekranda gördüğü sırayla.
function existingColumnGroups(tableKey){
  const cols=COLS_BY_TABLE[tableKey]||[];
  const order=(colmgr[tableKey]&&colmgr[tableKey].order)||[];
  const byKey=new Map(cols.map(c=>[c.k,c]));
  const seen=[];
  const push=value=>{ const name=String(value==null?'':value).trim(); if(name&&!seen.some(item=>groupKey(item)===groupKey(name)))seen.push(name); };
  (order.length?order:cols.map(c=>c.k)).forEach(k=>push((byKey.get(k)||{}).group));
  cols.forEach(c=>push(c.group));
  return seen;
}
// Sütunu, seçilen başlığın son sütunundan hemen sonraya taşır. Başlık sırada hiç
// yoksa sütun sonda kalır: yeni bir bant açılır — istenen de budur.
function placeColumnInGroup(tableKey,key,group){
  const cols=COLS_BY_TABLE[tableKey]||[], cs=colmgr[tableKey];
  if(!cs||!Array.isArray(cs.order))return;
  const byKey=new Map(cols.map(c=>[c.k,c]));
  const target=groupKey(group);
  let lastIndex=-1;
  cs.order.forEach((item,index)=>{ if(item===key)return; if(groupKey((byKey.get(item)||{}).group)===target)lastIndex=index; });
  const current=cs.order.indexOf(key);
  if(current>=0)cs.order.splice(current,1);
  if(lastIndex<0){ cs.order.push(key); return; }
  cs.order.splice(lastIndex+(current>=0&&current<=lastIndex?0:1),0,key);
}
window.BLColumnGroups={ list:existingColumnGroups, placeInGroup:placeColumnInGroup, key:groupKey };

let CP_MODEL_COLUMN_DEFS=[];
function syncCpModelColumns(defs){
  const clean=(Array.isArray(defs)?defs:[]).filter(d=>d&&d.header&&d.label).map(d=>({...d}));
  // Bir önceki eşitlemedeki gruplar: sütun YALNIZ yeniyken ya da grubu
  // değiştiğinde taşınır; her eşitlemede taşımak elle sürüklenen sırayı bozardı.
  const previousGroup=new Map(CP_MODEL_COLUMN_DEFS.map(d=>[d.header,d.group||DEFAULT_MODEL_COLUMN_GROUP]));
  CP_MODEL_COLUMN_DEFS=clean;
  const base=CP_COLS.filter(c=>!c.modelCustom);
  const dynamic=clean.map(d=>({k:d.header,label:d.label,type:'ro',weight:10,group:String(d.group||'').trim()||DEFAULT_MODEL_COLUMN_GROUP,modelCustom:true,modelColumnId:d.id,connectionId:d.connectionId,role:d.role,sourceTable:d.table,sourceName:d.name,dataType:d.dataType||d.data_type,sourceMetadata:d.sourceMetadata||d.metadata||d.dbMetadata,percentageScale:d.percentageScale||d.scale}));
  CP_COLS.splice(0,CP_COLS.length,...base,...dynamic);
  invalidateColumnIndex('cp');
  const cs=colmgr.cp; const valid=CP_COLS.map(c=>c.k);
  cs.order=cs.order.filter(k=>valid.includes(k));
  dynamic.forEach(c=>{
    const isNew=!cs.order.includes(c.k);
    if(isNew)cs.order.push(c.k);
    if(isNew||groupKey(previousGroup.get(c.k)||'')!==groupKey(c.group))placeColumnInGroup('cp',c.k,c.group);
  });
  cs.hidden=new Set([...cs.hidden].filter(k=>valid.includes(k)));
  cs.widthPx=Object.fromEntries(Object.entries(cs.widthPx||{}).filter(([k])=>valid.includes(k)));
  Object.keys(state.colFilters.cp||{}).forEach(k=>{if(!valid.includes(k))delete state.colFilters.cp[k];});
  // v7.28: CP_COLS yeniden kurulduğu için kullanıcının hesaplanan sütunları
  // yeniden eklenir; aksi halde Database sütunu ekleyince formül sütunları
  // sessizce kaybolurdu.
  window.BLFormulaColumns?.syncColumns('cp');
  syncOrdersColumnsFromCp();
  saveAutoTableColumnState();
}

/* v10.9 — Kullanıcı tanımlı boş not sütunları (Packet 9). Aynı "Add Column"
   mimarisini kullanır: CP_COLS'a dinamik olarak eklenir, syncOrdersColumnsFromCp
   ile Orders'a miras kalır (Collection'daki kolCustomCols ile aynı fikir,
   yalnız kalıcılığı server-backed overrides.noteColumnDefs/noteColumnValues'te
   tutulur — ham ASAS verisi hiç değişmez). Hücreler CP_COLS'ta type:'text'
   olarak kayıtlı olduğu için mevcut genel editCell/commitCpEditor akışını
   OLDUĞU GİBİ kullanır; ikinci bir düzenleme yolu kurulmaz. */
let CP_NOTE_COLUMN_DEFS=[];
let CP_NOTE_COLUMN_DEFS_REVISION=0;
function syncCpNoteColumns(defs){
  CP_NOTE_COLUMN_DEFS=(Array.isArray(defs)?defs:[]).filter(d=>d&&d.id&&d.label).map(d=>({...d}));
  const base=CP_COLS.filter(c=>!c.noteCustom);
  const dynamic=CP_NOTE_COLUMN_DEFS.map(d=>({k:d.id,label:d.label,type:'text',weight:12,group:String(d.group||'').trim()||(appLang==='en'?'Notes':'Notlar'),noteCustom:true,noteColumnId:d.id}));
  CP_COLS.splice(0,CP_COLS.length,...base,...dynamic);
  invalidateColumnIndex('cp');
  const cs=colmgr.cp; const valid=CP_COLS.map(c=>c.k);
  cs.order=cs.order.filter(k=>valid.includes(k));
  dynamic.forEach(c=>{ if(!cs.order.includes(c.k))cs.order.push(c.k); });
  cs.hidden=new Set([...cs.hidden].filter(k=>valid.includes(k)));
  cs.widthPx=Object.fromEntries(Object.entries(cs.widthPx||{}).filter(([k])=>valid.includes(k)));
  Object.keys(state.colFilters.cp||{}).forEach(k=>{if(!valid.includes(k))delete state.colFilters.cp[k];});
  window.BLFormulaColumns?.syncColumns('cp');
  syncOrdersColumnsFromCp();
  saveAutoTableColumnState();
}
async function saveCpNoteColumnDefs(nextDefs){
  const res=await fetch('/api/note-columns',{method:'PUT',headers:{'Content-Type':'application/json','If-Match':String(CP_NOTE_COLUMN_DEFS_REVISION||0)},body:JSON.stringify({columns:nextDefs})});
  const data=await res.json().catch(()=>({}));
  if(!res.ok)throw new Error(data.error||res.statusText);
  CP_NOTE_COLUMN_DEFS_REVISION=Number(data.revision)||CP_NOTE_COLUMN_DEFS_REVISION;
  syncCpNoteColumns(data.columns||nextDefs);
}
async function addCpNoteColumn(rerenderFn){
  const name=await openHorizonTextInput({title:appLang==='en'?'Add note column':'Not sütunu ekle',label:appLang==='en'?'Name of the new note column':'Yeni not sütununun adı',confirmLabel:appLang==='en'?'Add':'Ekle'});
  if(!name)return false;
  if(CP_COLS.some(c=>String(c.label).toLocaleLowerCase('tr')===name.toLocaleLowerCase('tr'))){
    showToast(appLang==='en'?'A column with that name already exists.':'Bu adda bir sütun zaten var.');
    return false;
  }
  const id='note_'+Date.now().toString(36)+Math.random().toString(36).slice(2,8);
  try{
    await saveCpNoteColumnDefs([...CP_NOTE_COLUMN_DEFS,{id,label:name}]);
    if(typeof rerenderFn==='function')rerenderFn(); else renderCP();
    showToast(appLang==='en'?'Column added.':'Sütun eklendi.');
    return true;
  }catch(err){ showToast((appLang==='en'?'Column could not be added: ':'Sütun eklenemedi: ')+(err.message||err)); return false; }
}
async function renameCpNoteColumn(id,rerenderFn){
  const def=CP_NOTE_COLUMN_DEFS.find(d=>d.id===id); if(!def)return;
  const name=await openHorizonTextInput({title:appLang==='en'?'Rename note column':'Not sütununu yeniden adlandır',label:appLang==='en'?'New name':'Yeni ad',initial:def.label,confirmLabel:appLang==='en'?'Rename':'Yeniden adlandır'});
  if(!name||name===def.label)return;
  try{
    await saveCpNoteColumnDefs(CP_NOTE_COLUMN_DEFS.map(d=>d.id===id?{...d,label:name}:d));
    if(typeof rerenderFn==='function')rerenderFn(); else renderCP();
  }catch(err){ showToast((appLang==='en'?'Column could not be renamed: ':'Sütun yeniden adlandırılamadı: ')+(err.message||err)); }
}
async function removeCpNoteColumn(id,rerenderFn){
  const def=CP_NOTE_COLUMN_DEFS.find(d=>d.id===id); if(!def)return;
  const question=appLang==='en'
    ?`Remove "${def.label}" from CP/Orders? Values entered in this column will be lost.`
    :`"${def.label}" CP/Siparişler'den kaldırılsın mı? Bu sütundaki değerler kaybolacak.`;
  if(!confirm(question))return;
  try{
    await saveCpNoteColumnDefs(CP_NOTE_COLUMN_DEFS.filter(d=>d.id!==id));
    if(typeof rerenderFn==='function')rerenderFn(); else renderCP();
    showToast(appLang==='en'?'Column removed.':'Sütun kaldırıldı.');
  }catch(err){ showToast((appLang==='en'?'Column could not be removed: ':'Sütun kaldırılamadı: ')+(err.message||err)); }
}

function syncOrdersColumnsFromCp(){
  // Siparişler tablosu CP sütunlarının kopyasıdır; ancak hesaplanan sütunlar
  // tabloya ÖZELDİR (CP'nin formülü Siparişler'e taşınmaz), bu yüzden kopyadan
  // çıkarılıp Siparişler'in kendi tanımları eklenir.
  const rebuilt=[ORDERS_STATUS_COL,...CP_COLS.filter(c=>!c.formulaCustom).map(c=>({...c}))];
  ORDERS_COLS.splice(0,ORDERS_COLS.length,...rebuilt);
  invalidateColumnIndex('orders');
  const cs=colmgr.orders,valid=ORDERS_COLS.map(c=>c.k);
  cs.order=cs.order.filter(k=>valid.includes(k));
  valid.forEach(k=>{if(!cs.order.includes(k))cs.order.push(k);});
  cs.hidden=new Set([...cs.hidden].filter(k=>valid.includes(k)));
  cs.widthPx=Object.fromEntries(Object.entries(cs.widthPx||{}).filter(([k])=>valid.includes(k)));
  Object.keys(state.colFilters.orders||{}).forEach(k=>{if(!valid.includes(k))delete state.colFilters.orders[k];});
  window.BLFormulaColumns?.syncColumns('orders');
}
function cpModelColumnDefinitionsFromConnections(items){
  return (Array.isArray(items)?items:[]).flatMap(item=>(Array.isArray(item.cpColumns)?item.cpColumns:[]).map(col=>({...col,role:item.role,connectionId:item.id,connectionName:item.name||item.catalog||item.server})));
}
// Shared CP-style table framework. Analysis pages can register read-only tables here
// and reuse the exact same column ordering, resizing, freezing and Excel-style filters.
const GENERIC_TABLE_SOURCES = Object.create(null);
function restoreRegisteredTableColumnState(tableKey){
  try{
    const saved=JSON.parse(BLStorage.getItem(AUTO_TABLE_COL_STATE_KEY)||'null');
    const entry=saved&&saved[tableKey]; if(!entry)return;
    const valid=(COLS_BY_TABLE[tableKey]||[]).map(c=>c.k);
    colmgr[tableKey].order=normalizedColumnOrder(tableKey,entry.order);
    colmgr[tableKey].hidden=new Set((entry.hidden||[]).filter(k=>valid.includes(k)));
    colmgr[tableKey].widthPx=Object.fromEntries(Object.entries(entry.widthPx||{}).filter(([k,v])=>valid.includes(k)&&Number.isFinite(Number(v))));
  }catch(e){}
}
function registerGenericTable(tableKey,columns,getRows){
  const mapped=(columns||[]).map((c,index)=>({
    k:c.k||c.key,
    label:c.label||c.k||c.key,
    type:c.type||'ro',
    weight:c.weight||10,
    group:c.group||'',
    dataType:c.dataType,
    percentageScale:c.percentageScale||c.scale,
    sourceMetadata:c.sourceMetadata||c.metadata,
    schema:c.schema,
    _genericIndex:index,
  })).filter(c=>c.k);
  const previous=colmgr[tableKey];
  COLS_BY_TABLE[tableKey]=mapped;
  invalidateColumnIndex(tableKey);
  if(!previous){colmgr[tableKey]=initColState(mapped);restoreRegisteredTableColumnState(tableKey);}
  else{
    const valid=mapped.map(c=>c.k);
    previous.order=normalizedColumnOrder(tableKey,previous.order);
    previous.hidden=new Set([...previous.hidden].filter(k=>valid.includes(k)));
    previous.widthPx=Object.fromEntries(Object.entries(previous.widthPx||{}).filter(([k])=>valid.includes(k)));
  }
  if(!state.colFilters[tableKey])state.colFilters[tableKey]={};
  const validKeys=new Set(mapped.map(c=>c.k));
  Object.keys(state.colFilters[tableKey]).forEach(key=>{if(!validKeys.has(key))delete state.colFilters[tableKey][key];});
  if(!state.checkFilter[tableKey])state.checkFilter[tableKey]='';
  GENERIC_TABLE_SOURCES[tableKey]=typeof getRows==='function'?getRows:()=>[];
  return mapped;
}
const AUTO_TABLE_COL_STATE_KEY='lcw.table.columnState.v1';
function normalizedColumnOrder(tableKey, savedOrder){
  const valid=(COLS_BY_TABLE[tableKey]||[]).map(c=>c.k);
  const validSet=new Set(valid),seen=new Set();
  const order=Array.isArray(savedOrder)?savedOrder.filter(k=>validSet.has(k)&&!seen.has(k)&&seen.add(k)):[];
  const orderSet=new Set(order);
  valid.forEach((key,defaultIndex)=>{
    if(orderSet.has(key)) return;
    let insertAt=order.length;
    for(let i=defaultIndex-1;i>=0;i--){ const at=order.indexOf(valid[i]); if(at>=0){insertAt=at+1;break;} }
    if(insertAt===order.length){ for(let i=defaultIndex+1;i<valid.length;i++){ const at=order.indexOf(valid[i]); if(at>=0){insertAt=at;break;} } }
    order.splice(insertAt,0,key);
    orderSet.add(key);
  });
  return order.length?order:valid;
}
function saveAutoTableColumnState(){
  try{
    const payload={};
    Object.keys(COLS_BY_TABLE).forEach(t=>{ const cs=colmgr[t]; payload[t]={order:cs.order.slice(),hidden:[...cs.hidden],widthPx:{...cs.widthPx}}; });
    BLStorage.setItem(AUTO_TABLE_COL_STATE_KEY,JSON.stringify(payload));
  }catch(e){}
}
function loadAutoTableColumnState(){
  try{
    const saved=JSON.parse(BLStorage.getItem(AUTO_TABLE_COL_STATE_KEY)||'null');
    if(!saved||typeof saved!=='object') return;
    Object.keys(COLS_BY_TABLE).forEach(t=>{
      if(!saved[t]) return;
      const valid=(COLS_BY_TABLE[t]||[]).map(c=>c.k);
      colmgr[t].order=normalizedColumnOrder(t,saved[t].order);
      colmgr[t].hidden=new Set((saved[t].hidden||[]).filter(k=>valid.includes(k)));
      colmgr[t].widthPx=Object.fromEntries(Object.entries(saved[t].widthPx||{}).filter(([k,v])=>valid.includes(k)&&Number.isFinite(Number(v))));
    });
  }catch(e){}
}
loadAutoTableColumnState();
// Eski "small" sütun genişliği de dahil olmak üzere CP görsel sütununu seçili
// Orta/Büyük moda hizala. Böylece önceki kullanıcı ayarları dar görünümü geri getirmez.
colmgr.cp.widthPx['__picture']=cpImageDims().col;
colmgr.orders.widthPx['__picture']=ordersImageDims().col;

function visibleCols(tableKey){
  const cols = COLS_BY_TABLE[tableKey]; const cs = colmgr[tableKey];
  const byKey = Object.fromEntries(cols.map(c=>[c.k,c]));
  return cs.order.filter(k=>!cs.hidden.has(k) && byKey[k]).map(k=>byKey[k]);
}

/* v10.34+ — Ortak tablo görünümü preset altyapısı.
   Presetler sütun sırasını, genişlikleri, filtreleri veya dondurmayı değiştirmez;
   yalnız mevcut görünürlük yöneticilerine bir görünürlük seti uygular.
   v10.34 davranışındaki Focus ve All korunur; Extended aynı editor/persistence
   zincirini kullanarak üçüncü bağımsız ve kullanıcıya özel preset olur. */
const TABLE_VIEW_PRESETS = Object.freeze({
  cp:Object.freeze({focus:Object.freeze(['__picture','Priority','Buyer','Manufacturer','Sub-Manufacturer','License','Category','PLM ID','Model Name','Order Code','FOB ($)','Ex-factory','HANDOVER Tarihi','Order Quantity','Remaining Units','%','STATUS'])}),
  orders:Object.freeze({focus:Object.freeze(['__picture','Priority','Buyer','Manufacturer','License','Category','PLM ID','Model Name','Order Code','FOB ($)','Ex-factory','HANDOVER Tarihi','Order Quantity','Remaining Units','%','STATUS'])}),
  koleksiyon:Object.freeze({focus:Object.freeze(['__picture__','plmId','modelKod','lisans','urunTipi','specialCode','line','colourCode','colour','fabric','fit','quantity','exFactory','targetPrice','__bestPrice__','__confirmedName__','__confirmedPrice__','durum','not'])}),
});
const TABLE_VIEW_FOCUS_KEY = 'lcw.tableViewFocus.v1';
const TABLE_VIEW_EDITABLE_PRESETS = Object.freeze(['focus','extended']);
const tableViewLastAppliedPreset=Object.create(null);

// CP / Orders Partial View yalnız SATIR sunumunu değiştirir. Sütun presetlerinden
// bilerek bağımsızdır; Focus / Extended / All seçimi olduğu gibi kalır.
const partialViewState={cp:false,orders:false};
function partialViewEnabled(tableKey){return (tableKey==='cp'||tableKey==='orders')&&partialViewState[tableKey]===true;}
function setPartialView(tableKey,enabled){
  if(tableKey!=='cp'&&tableKey!=='orders')return false;
  partialViewState[tableKey]=!!enabled;
  cpLogisticExpandedSet(tableKey).clear();
  renderTableViewContext(tableKey);
  if(tableKey==='cp')renderCP();else renderOrders();
  return true;
}
function tableViewPresetStored(){
  try{
    const value=JSON.parse(BLStorage.getItem(TABLE_VIEW_FOCUS_KEY)||'null');
    return value&&typeof value==='object'&&!Array.isArray(value)?value:{};
  }catch(_){return {};}
}
function tableViewAllKeys(tableKey){
  if(tableKey==='koleksiyon')return ['__picture__',...kolDefaultDisplayOrder()];
  return (COLS_BY_TABLE[tableKey]||[]).map(column=>column.k);
}
function tableViewColumnMeta(tableKey,key){
  if(tableKey==='koleksiyon'){
    if(key==='__picture__')return {k:key,label:appLang==='en'?'Picture':'Görsel',tableViewSystem:false};
    if(KOL_SYNTHETIC_COL_META?.[key])return {k:key,...KOL_SYNTHETIC_COL_META[key]};
    return kolColDefs().find(column=>column.k===key)||null;
  }
  return (COLS_BY_TABLE[tableKey]||[]).find(column=>column.k===key)||null;
}
function tableViewSavedPresetKeys(tableKey,preset){
  const page=tableViewPresetStored()[tableKey];
  // v10.34 legacy shape: { cp:[...], orders:[...], koleksiyon:[...] }.
  // Aynı anahtar yerinde genişletilir; eski Focus seçimi kaybolmaz.
  if(Array.isArray(page))return preset==='focus'?page:null;
  if(!page||typeof page!=='object')return null;
  return Array.isArray(page[preset])?page[preset]:null;
}
function tableViewFocusKeys(tableKey){
  const all=tableViewAllKeys(tableKey);
  const fallback=(TABLE_VIEW_PRESETS[tableKey]?.focus||[]).filter(key=>all.includes(key));
  const saved=tableViewSavedPresetKeys(tableKey,'focus');
  if(!Array.isArray(saved))return fallback;
  const valid=[...new Set(saved)].filter(key=>all.includes(key));
  return valid.length?valid:fallback;
}
function tableViewDefaultExtendedKeys(tableKey){
  const all=tableViewAllKeys(tableKey),focus=tableViewFocusKeys(tableKey).filter(key=>all.includes(key));
  if(!all.length||!focus.length)return focus;
  const focusSet=new Set(focus),focusIndexes=focus.map(key=>all.indexOf(key)).filter(index=>index>=0);
  const eligible=key=>{
    if(focusSet.has(key))return true;
    const meta=tableViewColumnMeta(tableKey,key)||{};
    if(tableKey==='koleksiyon'){
      // Kullanıcı sütunları ve hesaplanan uç-sonuç alanları All'da kalır;
      // Extended varsayılanı yalnız mevcut kanonik operasyonel metadata'dan türetilir.
      return !meta.custom&&!meta.endeksmatik&&!meta.ydLanded&&!meta.trLanded&&meta.tableViewSystem!==true;
    }
    // Dinamik Database / Notes / Formula sütunları kullanıcı isterse editörden eklenir;
    // yeni veya kaldırılmış özel sütunlar default Extended'ı kendiliğinden değiştirmez.
    return !meta.modelCustom&&!meta.noteCustom&&!meta.formulaCustom&&meta.tableViewSystem!==true;
  };
  const candidates=all.filter(key=>!focusSet.has(key)&&eligible(key));
  if(!candidates.length)return focus.slice();
  // Sayısal hedef yalnız görünüm katmanına aittir: varsayılan Extended, mevcut
  // Focus ile All'ın sütun sayısı arasında orta noktada kalır. Hangi sütunların
  // seçileceğini ise isim hard-code etmek yerine focus yakınlığı + mevcut group
  // metadata'sı belirler.
  const target=Math.min(all.length-1,focus.length+candidates.length,Math.max(focus.length+1,Math.round((focus.length+all.length)/2)));
  if(target<=focus.length)return focus.slice();
  const groupStats=new Map();
  all.forEach(key=>{
    if(!eligible(key))return;
    const group=String(tableViewColumnMeta(tableKey,key)?.group||'').trim();
    if(!group)return;
    const stat=groupStats.get(group)||{total:0,focus:0};stat.total++;
    if(focusSet.has(key))stat.focus++;
    groupStats.set(group,stat);
  });
  const scored=candidates.map(key=>{
    const index=all.indexOf(key),meta=tableViewColumnMeta(tableKey,key)||{},group=String(meta.group||'').trim();
    const stat=group?groupStats.get(group):null;
    const groupAffinity=stat&&stat.focus?18+(stat.focus/Math.max(1,stat.total))*6:0;
    const distance=focusIndexes.length?Math.min(...focusIndexes.map(focusIndex=>Math.abs(focusIndex-index))):all.length;
    const proximity=Math.max(0,16-distance*2);
    const stableOrderBias=(all.length-index)/Math.max(1,all.length);
    return {key,index,score:groupAffinity+proximity+stableOrderBias};
  }).sort((a,b)=>b.score-a.score||a.index-b.index);
  const selected=new Set(focus);
  scored.slice(0,target-focus.length).forEach(item=>selected.add(item.key));
  return all.filter(key=>selected.has(key));
}
function tableViewPresetKeys(tableKey,preset){
  const all=tableViewAllKeys(tableKey);
  if(preset==='all')return all;
  const fallback=preset==='focus'?tableViewFocusKeys(tableKey):preset==='extended'?tableViewDefaultExtendedKeys(tableKey):[];
  const saved=tableViewSavedPresetKeys(tableKey,preset);
  if(!Array.isArray(saved))return fallback;
  const valid=[...new Set(saved)].filter(key=>all.includes(key));
  return valid.length?valid:fallback;
}
function saveTableViewPreset(tableKey,preset,keys){
  if(!TABLE_VIEW_EDITABLE_PRESETS.includes(preset))return false;
  const all=tableViewAllKeys(tableKey),valid=[...new Set(Array.isArray(keys)?keys:[])].filter(key=>all.includes(key));
  if(!valid.length)return false;
  const stored=tableViewPresetStored(),current=stored[tableKey];
  const page=Array.isArray(current)?{focus:[...new Set(current)].filter(key=>all.includes(key))}:current&&typeof current==='object'?{...current}:{};
  page[preset]=valid;stored[tableKey]=page;
  try{BLStorage.setItem(TABLE_VIEW_FOCUS_KEY,JSON.stringify(stored));return true;}catch(_){return false;}
}
function tableViewFocusCatalog(tableKey){
  const all=tableViewAllKeys(tableKey);
  return all.map(key=>({key,label:tableViewColumnMeta(tableKey,key)?.label||key}));
}
function tableViewHiddenKeys(tableKey){
  if(tableKey==='koleksiyon')return new Set([...kolHiddenCols,...(kolPictureHidden?['__picture__']:[])]);
  return new Set(colmgr[tableKey]?.hidden||[]);
}
function tableViewPresetState(tableKey){
  const all=tableViewAllKeys(tableKey),hidden=tableViewHiddenKeys(tableKey);
  if(!all.some(key=>hidden.has(key)))return 'all';
  const visible=new Set(all.filter(key=>!hidden.has(key)));
  const matches=TABLE_VIEW_EDITABLE_PRESETS.filter(preset=>{
    const keys=new Set(tableViewPresetKeys(tableKey,preset));
    return keys.size===visible.size&&[...keys].every(key=>visible.has(key));
  });
  const preferred=tableViewLastAppliedPreset[tableKey];
  if(preferred&&matches.includes(preferred))return preferred;
  return matches[0]||'custom';
}
function renderTableViewContext(tableKey){
  const prefix=tableKey==='koleksiyon'?'kol':tableKey;
  const root=document.getElementById(`${prefix}TableViewActions`);
  if(!root)return;
  const preset=tableViewPresetState(tableKey);
  root.setAttribute('aria-label',appLang==='en'?'Table view':'Tablo görünümü');
  root.querySelectorAll('[data-table-view-preset]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.tableViewPreset===preset)));
  root.querySelectorAll('[data-partial-view-toggle]').forEach(button=>button.setAttribute('aria-pressed',String(partialViewEnabled(button.dataset.partialViewToggle))));
}
function applyTableViewPreset(tableKey,preset){
  const all=tableViewAllKeys(tableKey);if(!all.length||!TABLE_VIEW_PRESETS[tableKey]||!['focus','extended','all'].includes(preset))return false;
  const visible=new Set(tableViewPresetKeys(tableKey,preset));
  if(!visible.size)return false;
  tableViewLastAppliedPreset[tableKey]=preset;
  if(tableKey==='koleksiyon'){
    kolPictureHidden=!visible.has('__picture__');
    kolHiddenCols = new Set(all.filter(key=>key!=='__picture__'&&!visible.has(key)));
    saveKolColState();
  }else if(colmgr[tableKey]){
    colmgr[tableKey].hidden = new Set(all.filter(key=>!visible.has(key)));
    saveAutoTableColumnState();
  }else return false;
  const info=activeTableInfo();
  if(info?.tableKey===tableKey)info.rerender();
  else renderTableViewContext(tableKey);
  return true;
}
document.addEventListener('click',event=>{
  const button=event.target.closest?.('[data-table-view-preset][data-table-key]');if(!button)return;
  applyTableViewPreset(button.dataset.tableKey,button.dataset.tableViewPreset);
});
document.addEventListener('click',event=>{
  const button=event.target.closest?.('[data-partial-view-toggle]');if(!button)return;
  const tableKey=button.dataset.partialViewToggle;
  setPartialView(tableKey,!partialViewEnabled(tableKey));
});
function openTableViewFocusEditor(tableKey,preset='focus'){
  if(!TABLE_VIEW_EDITABLE_PRESETS.includes(preset))return;
  document.getElementById('_tableViewFocusModal')?.remove();
  const catalog=tableViewFocusCatalog(tableKey),selected=new Set(tableViewPresetKeys(tableKey,preset)),previousFocus=document.activeElement;
  const modal=document.createElement('div');modal.id='_tableViewFocusModal';modal.className='warnOverlay';
  const presetName=preset==='extended'?'Extended':(appLang==='en'?'Focus':'Odak');
  const title=appLang==='en'?`${presetName} columns`:`${presetName} sütunları`;
  const help=appLang==='en'?`Choose which columns remain visible when ${presetName} is selected.`:`${presetName} seçildiğinde görünür kalacak sütunları seçin.`;
  modal.innerHTML=`<div class="modalCard quickFilterEditorCard tableViewFocusEditorCard" role="dialog" aria-modal="true" aria-labelledby="_tableViewFocusTitle"><div class="modalTitle" id="_tableViewFocusTitle">${escapeHtml(title)}</div><div class="muted quickFilterEditorHelp">${escapeHtml(help)}</div><div class="quickFilterEditorList">${catalog.map(column=>`<label class="quickFilterEditorItem"><input type="checkbox" data-table-view-focus-key="${escapeHtml(column.key)}" ${selected.has(column.key)?'checked':''}> <span>${escapeHtml(L(column.label))}</span></label>`).join('')}</div><div class="modalFoot"><span></span><button type="button" class="tbtn" data-close>${escapeHtml(appLang==='en'?'Cancel':'Vazgeç')}</button><button type="button" class="tbtn primary" data-apply>${escapeHtml(appLang==='en'?'Apply':'Uygula')}</button></div></div>`;
  document.body.appendChild(modal);
  const close=()=>{document.removeEventListener('keydown',onKey,true);modal.remove();previousFocus?.focus?.();};
  const onKey=event=>{if(event.key==='Escape')close();};
  document.addEventListener('keydown',onKey,true);
  modal.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',close));
  modal.addEventListener('click',event=>{if(event.target===modal)close();});
  modal.querySelector('[data-apply]')?.addEventListener('click',()=>{
    const keys=[...modal.querySelectorAll('[data-table-view-focus-key]:checked')].map(input=>input.dataset.tableViewFocusKey);
    if(!keys.length){showToast(appLang==='en'?'Choose at least one column.':'En az bir sütun seçin.');return;}
    if(saveTableViewPreset(tableKey,preset,keys)){close();applyTableViewPreset(tableKey,preset);}
  });
  modal.querySelector('[data-table-view-focus-key]')?.focus();
}
document.addEventListener('dblclick',event=>{
  const button=event.target.closest?.('[data-table-view-preset][data-table-key]');if(!button||!TABLE_VIEW_EDITABLE_PRESETS.includes(button.dataset.tableViewPreset))return;
  event.preventDefault();event.stopImmediatePropagation();openTableViewFocusEditor(button.dataset.tableKey,button.dataset.tableViewPreset);
});

// Excel benzeri sütun görünürlük menüsü. Sağ tıklanan sütun gizlenebilir; aynı
// menüden daha önce gizlenen sütunlar tek tek veya topluca geri getirilebilir.
let _columnVisibilityMenu=null;
let _columnVisibilityOutsideHandler=null;
function closeColumnVisibilityMenu(){
  if(_columnVisibilityOutsideHandler){document.removeEventListener('pointerdown',_columnVisibilityOutsideHandler,true);_columnVisibilityOutsideHandler=null;}
  if(_columnVisibilityMenu){window.BLLayerSystem?.closeMenu(_columnVisibilityMenu);_columnVisibilityMenu.remove();_columnVisibilityMenu=null;}
}
function openColumnVisibilityMenu(event, options={}){
  event.preventDefault();event.stopPropagation();closeColumnVisibilityMenu();
  const columns=(options.columns||[]).filter(c=>c&&c.key);
  const hiddenKeys=new Set(options.hiddenKeys||[]);
  const currentKey=String(options.currentKey||'');
  const visibleCount=columns.filter(c=>!hiddenKeys.has(c.key)).length;
  const hidden=columns.filter(c=>hiddenKeys.has(c.key));
  const menu=document.createElement('div');menu.className='tableColumnContextMenu';menu.setAttribute('role','menu');
  const addButton=(label,handler,cls='')=>{
    const btn=document.createElement('button');btn.type='button';btn.className=`tableColumnContextItem ${cls}`.trim();btn.textContent=label;
    btn.addEventListener('click',e=>{e.stopPropagation();handler();closeColumnVisibilityMenu();});menu.appendChild(btn);
  };
  if(currentKey&&!hiddenKeys.has(currentKey)){
    const current=columns.find(c=>c.key===currentKey);const label=current?current.label:currentKey;
    const btn=document.createElement('button');btn.type='button';btn.className='tableColumnContextItem';btn.textContent=`${appLang==='en'?'Hide column':'Sütunu gizle'} · ${label}`;
    btn.disabled=visibleCount<=1;btn.title=btn.disabled?(appLang==='en'?'At least one column must remain visible':'En az bir sütun görünür kalmalı'):'';
    btn.addEventListener('click',e=>{e.stopPropagation();if(btn.disabled)return;options.onHide?.(currentKey);closeColumnVisibilityMenu();});menu.appendChild(btn);
  }
  if(hidden.length){
    const sep=document.createElement('div');sep.className='tableColumnContextSep';menu.appendChild(sep);
    const title=document.createElement('div');title.className='tableColumnContextTitle';title.textContent=appLang==='en'?'Show hidden columns':'Gizli sütunları göster';menu.appendChild(title);
    hidden.forEach(col=>addButton(`${appLang==='en'?'Show':'Göster'} · ${col.label}`,()=>options.onShow?.(col.key)));
    addButton(appLang==='en'?'Show all columns':'Tüm sütunları göster',()=>options.onShowAll?.(),'isPrimary');
  }
  if(!menu.children.length)return;
  document.body.appendChild(menu);_columnVisibilityMenu=menu;
  const rect=menu.getBoundingClientRect();
  const x=Math.max(8,Math.min(event.clientX,(window.innerWidth||1200)-rect.width-8));
  const y=Math.max(8,Math.min(event.clientY,(window.innerHeight||800)-rect.height-8));
  menu.style.left=`${x}px`;menu.style.top=`${y}px`;
  window.BLLayerSystem?.openMenu(menu,{trigger:event.currentTarget||document.activeElement,onClose:closeColumnVisibilityMenu,label:appLang==='en'?'Column options':'Sütun seçenekleri'});
  _columnVisibilityOutsideHandler=e=>{if(_columnVisibilityMenu&&!_columnVisibilityMenu.contains(e.target))closeColumnVisibilityMenu();};
  setTimeout(()=>document.addEventListener('pointerdown',_columnVisibilityOutsideHandler,true),0);
}
function openManagedTableColumnMenu(event,tableKey,currentKey,rerender){
  const cols=COLS_BY_TABLE[tableKey]||[],cs=colmgr[tableKey];if(!cs)return;
  openColumnVisibilityMenu(event,{
    currentKey,
    columns:cols.map(c=>({key:c.k,label:tableColumnLabel(tableKey,c)})),
    hiddenKeys:[...cs.hidden],
    onHide:key=>{cs.hidden.add(key);saveAutoTableColumnState();rerender?.();},
    onShow:key=>{cs.hidden.delete(key);saveAutoTableColumnState();rerender?.();},
    onShowAll:()=>{cs.hidden.clear();saveAutoTableColumnState();rerender?.();},
  });
}
let _tableHeaderMeasureCtx=null;
function tableHeaderTextWidth(label){
  try{
    if(!_tableHeaderMeasureCtx){
      const canvas=document.createElement('canvas');
      _tableHeaderMeasureCtx=canvas.getContext('2d');
    }
    if(_tableHeaderMeasureCtx){
      _tableHeaderMeasureCtx.font='700 10px Arial, sans-serif';
      // Başlıklar artık büyük harfe çevrilmiyor; genişlik gerçek metinle ölçülür.
      return Math.ceil(_tableHeaderMeasureCtx.measureText(String(label||'')).width);
    }
  }catch(e){}
  return Math.ceil(String(label||'').length*6.2);
}
function defaultMinPx(c, tableKey){
  const byType = {
    priority:48, status:52, active:46, ordercode:58, money:46, moneyEdit:50, pct:36,
    int:42, plm:46, num:40, date:54, exfactory:56, retailEdit:56, instoreEdit:56, retail:56,
    deltype:52, submfr:60, licensor:58, text:70,
    cpImage:tableImageSizeDimensions(tableKey,tableImageSizeBounds(tableKey).min).col
  };
  const label=tableColumnLabel(tableKey,c);
  // Başlık metni + iki yandaki hücre dolgusu + filtre oku + sıralama oku + resize tutamacı.
  // Böylece sütun başlığı hiçbir dilde okunamaz hâle gelecek kadar daraltılamaz.
  const readableHeaderPx=tableHeaderTextWidth(label)+54;
  const typeMin=tableKey==='ship'?44:(byType[c.type]||44);
  if(c.k==='Notes' || c.k==='Ek Not') return Math.max(220,readableHeaderPx);
  return Math.max(typeMin,readableHeaderPx);
}
function colWidthPx(tableKey, c){
  const cs = colmgr[tableKey];
  if(cs.widthPx[c.k]!=null) return Math.max(Number(cs.widthPx[c.k])||0, defaultMinPx(c, tableKey));
  return Math.round(defaultMinPx(c, tableKey) * 1.35);
}
function computeWidths(tableKey){
  const cols = visibleCols(tableKey);
  return cols.map(c=>({col:c, px: colWidthPx(tableKey,c)}));
}
function tableTotalPx(tableKey, withChk){
  return (withChk?30:0) + computeWidths(tableKey).reduce((s,w)=>s+w.px,0);
}
function buildColgroup(table, tableKey, withChk){
  const cg = table.querySelector('colgroup');
  const widths = computeWidths(tableKey);
  let html = withChk ? `<col data-key="__chk" style="width:30px">` : '';
  html += widths.map(w=>`<col data-key="${w.col.k}" style="width:${w.px}px">`).join('');
  cg.innerHTML = html;
  const totalPx = tableTotalPx(tableKey, withChk);
  table.style.minWidth = totalPx+'px';
  table.style.width = `max(100%, ${totalPx}px)`;
}
function applyColgroupWidths(table, tableKey, withChk){
  const widths = computeWidths(tableKey);
  const cg = table.querySelector('colgroup');
  widths.forEach(w=>{
    const col = cg.querySelector(`col[data-key="${CSS.escape(w.col.k)}"]`);
    if(col) col.style.width = w.px+'px';
  });
  const totalPx = tableTotalPx(tableKey, withChk);
  table.style.minWidth = totalPx+'px';
  table.style.width = `max(100%, ${totalPx}px)`;
}
// Sütun ayırıcı çizgisine ÇİFT TIKLAMA: sütunu izin verilen en dar genişliğe indirir.
// Alt sınır her sütunun kendi minimumudur (başlık metni + filtre/sıralama okları), yani
// başlık okunamaz hâle gelmez.
//
// Daraltılmış bir sütuna ikinci kez çift tıklanınca eski genişliğine döner. Bunu ekledim
// çünkü aksi hâlde geri açmanın tek yolu 7 piksellik tutamağı yakalayıp sürüklemek olurdu.
function attachCollapseOnDoubleClick(grip, api){
  // İpucu metni BİLEREK geç yazılıyor. Bu yardımcı, betiğin ortasında doğrudan
  // çalışan attachBacklogResize() çağrılarından da tetikleniyor; o noktada dil
  // değişkeni henüz tanımlanmamış oluyor ve burada okunursa betik komple çöküyor
  // (v3.55'te tam olarak bu oldu: uygulama açılıyor ama hiçbir veri/düğme gelmiyordu).
  // Fare üstüne gelince yazmak hem bu sorunu çözüyor hem de dil değiştirildiğinde
  // ipucunun güncel kalmasını sağlıyor.
  grip.addEventListener('mouseenter', ()=>{
    grip.title = (typeof appLang !== 'undefined' && appLang === 'en')
      ? 'Drag to resize · double-click to collapse'
      : 'Sürükleyerek genişlet · çift tıklayarak daralt';
  });
  grip.addEventListener('dblclick', e=>{
    e.preventDefault(); e.stopPropagation();
    const min = Math.round(Number(api.min())||0);
    const current = Math.round(Number(api.current())||0);
    const restore = Number(grip.dataset.restorePx)||0;
    if(current > min){ grip.dataset.restorePx = String(current); api.set(min); }
    else if(restore > min){ grip.dataset.restorePx = ''; api.set(restore); }
    else return;
    api.apply();
    if(api.save) api.save();
  });
}

function attachResize(th, key, tableKey, table, withChk=true){
  const grip = document.createElement('div');
  grip.className='colResizer';
  th.appendChild(grip);
  grip.addEventListener('mousedown', e=>{
    e.preventDefault(); e.stopPropagation();
    const cs = colmgr[tableKey];
    const col = COLS_BY_TABLE[tableKey].find(c=>c.k===key);
    const startPx = colWidthPx(tableKey, col);
    const startX = e.clientX;
    const minPx = defaultMinPx(col, tableKey);
    function onMove(ev){
      const newPx = Math.max(minPx, startPx + (ev.clientX-startX));
      cs.widthPx[key]=newPx;
      applyColgroupWidths(table,tableKey,withChk);
      applyFreeze(table.id,tableKey,withChk);
    }
    function onUp(){ saveAutoTableColumnState(); document.removeEventListener('mousemove',onMove); document.removeEventListener('mouseup',onUp); }
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
  });
  attachCollapseOnDoubleClick(grip, {
    current: ()=>colWidthPx(tableKey, COLS_BY_TABLE[tableKey].find(c=>c.k===key)),
    min: ()=>defaultMinPx(COLS_BY_TABLE[tableKey].find(c=>c.k===key), tableKey),
    set: px=>{ colmgr[tableKey].widthPx[key] = px; },
    apply: ()=>{applyColgroupWidths(table,tableKey,withChk);applyFreeze(table.id,tableKey,withChk);},
    save: ()=>saveAutoTableColumnState(),
  });
}
// Sütun sürükleme önizlemesi: yer değiştiren başlık bloklarını gerçek bırakma
// sırasına göre FLIP benzeri transformlarla kaydırır. Tablo gövdesindeki binlerce
// hücreyi her dragover olayında oynatmadığı için büyük veri setlerinde hafif kalır.
let _columnDragPreview=null;
function columnDragBlocks(row,keyAttr){
  if(!row)return [];
  const cells=[...row.children],draggables=cells.filter(cell=>cell.matches(`th[${keyAttr}]`));
  return draggables.map((cell,index)=>{
    const start=cells.indexOf(cell),next=index+1<draggables.length?cells.indexOf(draggables[index+1]):cells.length;
    const blockCells=cells.slice(start,next),firstRect=blockCells[0].getBoundingClientRect(),lastRect=blockCells[blockCells.length-1].getBoundingClientRect();
    return {key:String(cell.getAttribute(keyAttr)||''),anchor:cell,cells:blockCells,left:firstRect.left,width:Math.max(1,lastRect.right-firstRect.left)};
  });
}
function columnDragBlankImage(){
  const blank=document.createElement('span');
  blank.className='columnDragBlankImage';
  document.body.appendChild(blank);
  return blank;
}
function moveColumnDragGhost(clientX,clientY){
  const state=_columnDragPreview;if(!state||!state.ghost)return;
  state.pendingX=clientX-state.offsetX;state.pendingY=clientY-state.offsetY;
  if(state.ghostFrame)return;
  state.ghostFrame=requestAnimationFrame(()=>{
    state.ghostFrame=0;
    if(_columnDragPreview!==state||!state.ghost)return;
    state.ghost.style.transform=`translate3d(${Math.round(state.pendingX)}px,${Math.round(state.pendingY)}px,0)`;
  });
}
function beginColumnDragPreview(th,key,keyAttr,e){
  endColumnDragPreview();
  const row=th.closest('tr'),blocks=columnDragBlocks(row,keyAttr),source=blocks.find(block=>block.key===String(key));
  if(!row||!source)return;
  const rect=th.getBoundingClientRect(),ghost=document.createElement('div'),blank=columnDragBlankImage();
  ghost.className='columnDragGhost';ghost.setAttribute('aria-hidden','true');ghost.innerHTML=th.innerHTML;
  ghost.style.width=`${Math.round(rect.width)}px`;ghost.style.height=`${Math.round(rect.height)}px`;
  document.body.appendChild(ghost);
  const state={row,blocks,source,keyAttr,ghost,blank,offsetX:Math.max(10,Math.min(rect.width-10,(e.clientX||rect.left+16)-rect.left)),offsetY:Math.max(6,Math.min(rect.height-6,(e.clientY||rect.top+8)-rect.top)),ghostFrame:0,pendingX:rect.left,pendingY:rect.top,lastTarget:'',lastBefore:null};
  _columnDragPreview=state;row.classList.add('columnDragPreviewActive');
  blocks.forEach(block=>block.cells.forEach(cell=>cell.classList.add('columnDragPreviewCell')));
  source.cells.forEach(cell=>cell.classList.add('columnDragSourceBlock'));
  if(e.dataTransfer&&typeof e.dataTransfer.setDragImage==='function')e.dataTransfer.setDragImage(blank,0,0);
  state.documentDragOver=ev=>moveColumnDragGhost(ev.clientX,ev.clientY);
  document.addEventListener('dragover',state.documentDragOver,true);
  moveColumnDragGhost(e.clientX||rect.left+state.offsetX,e.clientY||rect.top+state.offsetY);
}
function applyColumnDragPreviewOrder(state,orderedBlocks){
  let left=state.blocks[0]?.left||0;
  const targetLeft=new Map();
  orderedBlocks.forEach(block=>{targetLeft.set(block.key,left);left+=block.width;});
  state.blocks.forEach(block=>{
    const delta=(targetLeft.get(block.key)??block.left)-block.left;
    block.cells.forEach(cell=>cell.style.setProperty('--column-drag-x',`${Math.round(delta)}px`));
  });
}
function updateColumnDragPreview(th,before,e){
  const state=_columnDragPreview;if(!state||th.closest('tr')!==state.row)return;
  moveColumnDragGhost(e.clientX,e.clientY);
  const targetKey=String(th.getAttribute(state.keyAttr)||''),target=state.blocks.find(block=>block.key===targetKey);
  if(!target)return;
  clearColDropHints(state.row);
  state.blocks.forEach(block=>block.cells.forEach(cell=>cell.classList.remove('columnDragTargetBlock')));
  if(target===state.source){
    applyColumnDragPreviewOrder(state,state.blocks);state.lastTarget='';state.lastBefore=null;return;
  }
  const remaining=state.blocks.filter(block=>block!==state.source),targetIndex=remaining.indexOf(target),insertAt=targetIndex+(before?0:1),ordered=remaining.slice();
  ordered.splice(insertAt,0,state.source);applyColumnDragPreviewOrder(state,ordered);
  target.cells.forEach(cell=>cell.classList.add('columnDragTargetBlock'));
  (before?target.cells[0]:target.cells[target.cells.length-1]).classList.add(before?'colDropBefore':'colDropAfter');
  state.lastTarget=targetKey;state.lastBefore=before;
}
function endColumnDragPreview(){
  const state=_columnDragPreview;if(!state)return;
  _columnDragPreview=null;
  if(state.ghostFrame)cancelAnimationFrame(state.ghostFrame);
  if(state.documentDragOver)document.removeEventListener('dragover',state.documentDragOver,true);
  clearColDropHints(state.row);state.row?.classList.remove('columnDragPreviewActive');
  state.blocks.forEach(block=>block.cells.forEach(cell=>{cell.classList.remove('columnDragPreviewCell','columnDragSourceBlock','columnDragTargetBlock','dragging');cell.style.removeProperty('--column-drag-x');}));
  state.ghost?.remove();state.blank?.remove();
}
function attachDrag(th, key, tableKey, rerenderFn){
  th.draggable = true;
  th.addEventListener('dragstart', e=>{
    if(e.dataTransfer){e.dataTransfer.setData('text/plain', key);e.dataTransfer.effectAllowed='move';}
    th.classList.add('dragging');th.setAttribute('aria-grabbed','true');beginColumnDragPreview(th,key,'data-k',e);
  });
  th.addEventListener('dragend', ()=>{th.classList.remove('dragging');th.setAttribute('aria-grabbed','false');endColumnDragPreview();});
  th.addEventListener('dragover', e=>{
    e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move';
    const rect=th.getBoundingClientRect(),before=(e.clientX-rect.left)<rect.width/2;
    updateColumnDragPreview(th,before,e);
  });
  th.addEventListener('dragleave', ()=>{ th.classList.remove('colDropBefore','colDropAfter'); });
  th.addEventListener('drop', e=>{
    e.preventDefault();
    const draggedKey=e.dataTransfer?.getData('text/plain')||_columnDragPreview?.source?.key||'';
    const rect=th.getBoundingClientRect(),before=(e.clientX-rect.left)<rect.width/2;
    endColumnDragPreview();
    if(draggedKey===key)return;
    const order=colmgr[tableKey].order,from=order.indexOf(draggedKey);
    if(from<0)return;
    order.splice(from,1);
    let to=order.indexOf(key);if(!before)to+=1;
    order.splice(to,0,draggedKey);saveAutoTableColumnState();rerenderFn();
  });
}
let _columnGroupDrag=null;
function moveColumnGroup(tableKey,sourceGroup,targetGroup,before){
  if(!['cp','orders'].includes(tableKey)||!sourceGroup||!targetGroup||sourceGroup===targetGroup)return false;
  const cs=colmgr[tableKey],defs=COLS_BY_TABLE[tableKey]||[];
  if(!cs)return false;
  const byKey=Object.fromEntries(defs.map(col=>[col.k,col]));
  const sourceKeys=cs.order.filter(key=>byKey[key]?.group===sourceGroup);
  if(!sourceKeys.length)return false;
  const sourceSet=new Set(sourceKeys);
  const remaining=cs.order.filter(key=>!sourceSet.has(key));
  const targetIndexes=[];
  remaining.forEach((key,index)=>{if(byKey[key]?.group===targetGroup)targetIndexes.push(index);});
  if(!targetIndexes.length)return false;
  const insertAt=before?targetIndexes[0]:targetIndexes[targetIndexes.length-1]+1;
  remaining.splice(insertAt,0,...sourceKeys);
  cs.order=remaining;
  saveAutoTableColumnState();
  return true;
}
function clearGroupDropHints(row){
  row?.querySelectorAll('.groupDragging,.groupDropBefore,.groupDropAfter').forEach(cell=>cell.classList.remove('groupDragging','groupDropBefore','groupDropAfter'));
}
function attachGroupDrag(th,group,tableKey,rerenderFn){
  if(!['cp','orders'].includes(tableKey)||!group)return;
  th.draggable=true;
  th.classList.add('draggableGroup');
  th.addEventListener('dragstart',event=>{
    if(_freezePick){event.preventDefault();return;}
    _columnGroupDrag={tableKey,group};
    th.classList.add('groupDragging');
    th.setAttribute('aria-grabbed','true');
    if(event.dataTransfer){
      event.dataTransfer.effectAllowed='move';
      event.dataTransfer.setData('application/x-buyerlog-column-group',group);
      event.dataTransfer.setData('text/plain',`group:${group}`);
    }
  });
  th.addEventListener('dragover',event=>{
    if(!_columnGroupDrag||_columnGroupDrag.tableKey!==tableKey||_columnGroupDrag.group===group)return;
    event.preventDefault();
    if(event.dataTransfer)event.dataTransfer.dropEffect='move';
    clearGroupDropHints(th.closest('tr'));
    const rect=th.getBoundingClientRect(),before=(event.clientX-rect.left)<rect.width/2;
    th.classList.add(before?'groupDropBefore':'groupDropAfter');
  });
  th.addEventListener('dragleave',()=>th.classList.remove('groupDropBefore','groupDropAfter'));
  th.addEventListener('drop',event=>{
    if(!_columnGroupDrag||_columnGroupDrag.tableKey!==tableKey)return;
    event.preventDefault();
    const source=_columnGroupDrag.group,rect=th.getBoundingClientRect(),before=(event.clientX-rect.left)<rect.width/2;
    _columnGroupDrag=null;clearGroupDropHints(th.closest('tr'));
    if(moveColumnGroup(tableKey,source,group,before))rerenderFn();
  });
  th.addEventListener('dragend',()=>{
    _columnGroupDrag=null;th.setAttribute('aria-grabbed','false');clearGroupDropHints(th.closest('tr'));
  });
}
function clearColDropHints(row){
  if(!row) return;
  row.querySelectorAll('.colDropBefore,.colDropAfter').forEach(el=> el.classList.remove('colDropBefore','colDropAfter'));
}
