// ================= CAPRAZ FILTRE IPUCU (facet) - TUM sayfalarda ortak =================
// Bir boyut secildiginde (or. Country=Egypt), diger boyutlarin secim listesinde
// (or. Buyer) o secimle birlikte GERCEKTEN var olan degerler uste ve normal renkte,
// var olmayanlar alta ve soluk gelir. Hicbir deger listeden kaybolmaz.
const _facetCacheByRows=new WeakMap();
const FACET_CACHE_MAX_ENTRIES=96;
function facetCacheValue(rows,key,build){
  if(!Array.isArray(rows))return build();
  let bucket=_facetCacheByRows.get(rows);if(!bucket){bucket=new Map();_facetCacheByRows.set(rows,bucket);}
  if(bucket.has(key)){const value=bucket.get(key);bucket.delete(key);bucket.set(key,value);return value;}
  const value=build();bucket.set(key,value);
  while(bucket.size>FACET_CACHE_MAX_ENTRIES)bucket.delete(bucket.keys().next().value);
  return value;
}
function invalidateCoreFacetCaches(){
  if(state.cp&&Array.isArray(state.cp.rows))_facetCacheByRows.delete(state.cp.rows);
  if(state.orders&&Array.isArray(state.orders.rows))_facetCacheByRows.delete(state.orders.rows);
}
function facetFilterSignature(entries){
  return (entries||[]).map(([set,col])=>`${col}:${[...(set||[])].map(norm).sort().join('\u001f')}`).sort().join('\u001e');
}
function computeValidValueSet(rows, otherFilterEntries, targetCol){
  const key=`valid\u0000${targetCol}\u0000${facetFilterSignature(otherFilterEntries)}`;
  return facetCacheValue(rows,key,()=>{
    const s=new Set();
    for(const row of rows){
      if(!otherFilterEntries.every(([set,col])=>!set||!set.size||set.has(norm(row[col]))))continue;
      s.add(norm(row[targetCol]));
    }
    return s;
  });
}
function sortWithFacet(vals, validSet){
  return [...vals].sort((a,b)=>{
    const av = validSet.has(a), bv = validSet.has(b);
    if(av!==bv) return av?-1:1;
    return String(a).localeCompare(String(b),'tr');
  });
}
function facetChecklistHtml(vals, validSet, selected, checkboxClass){
  return vals.map(v=>{
    const faded = !validSet.has(v);
    const style = faded ? 'display:flex;align-items:center;gap:6px;padding:3px 2px;opacity:.4;' : 'display:flex;align-items:center;gap:6px;padding:3px 2px;';
    return '<label style="'+style+'"><input type="checkbox" class="'+checkboxClass+'" value="'+escapeHtml(v)+'" '+(selected.has(v)?'checked':'')+'> '+(escapeHtml(v)||'(bos)')+'</label>';
  }).join('');
}
function uniqueVals(rows,key){
  return facetCacheValue(rows,`unique\u0000${key}`,()=>{
    const values=new Set();for(const row of rows){const value=norm(row&&row[key]);if(value)values.add(value);}
    return [...values].sort();
  });
}
function fillSelect(id, vals){
  const sel=document.getElementById(id); const cur=sel.value;
  sel.innerHTML = sel.options[0].outerHTML + vals.map(v=>`<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join('');
  if(vals.includes(cur)) sel.value=cur;
}
function fillPrioritySelect(id){
  const sel=document.getElementById(id);if(!sel)return;
  const cur=actionPriorityCode(sel.value);
  const first=sel.options[0]?sel.options[0].outerHTML:`<option value="">${appLang==='en'?'Priority: all':'Priority: hepsi'}</option>`;
  const codes=actionPriorityCodes();
  sel.innerHTML=first+codes.map(code=>`<option value="${escapeHtml(code)}">${escapeHtml(priorityDisplay(code))}</option>`).join('');
  if(cur&&codes.includes(cur))sel.value=cur;else sel.value='';
}
// Arama kutusunda her tuş vuruşunda tam tablo yeniden çizmek yerine, yazma durunca
// (150ms) bir kez çiz — büyük veri setlerinde yazarken takılmayı önler.
function debounce(fn, ms){
  if(window.BLPerf?.debounce)return window.BLPerf.debounce(fn,ms);
  let t;
  return function(){ clearTimeout(t);t=setTimeout(()=>fn.apply(this,arguments),ms); };
}
