function enterDateEdit(span){
  const id = span.dataset.id, key = span.dataset.key, kind = span.dataset.kind;
  const row = state.cp.rows.find(r=>r._id===Number(id));
  if(!row) return;
  if(row._canEdit===false){showToast(L('Bu sipariş için yalnız görüntüleme yetkiniz var.'));return;}
  const input = document.createElement('input');
  input.type='date'; input.className='editCell';
  input.dataset.id=id; input.dataset.key=key; input.dataset.kind=kind;
  input.dataset.historySession=`date:${id}:${key}:${Date.now()}:${Math.random().toString(36).slice(2)}`;
  input.value = toISODate(row ? row[key] : null);
  span.replaceWith(input);
  enhanceDateInput(input);
  const visibleInput=input._dateDisplayInput || input;
  const host=input.closest('.dateFieldWrap') || input;
  visibleInput.focus();
  if(visibleInput.select) visibleInput.select();
  // Editörü yalnızca bütün tarih bileşeninden gerçekten çıkıldığında kapat.
  // Metin alanı → takvim düğmesi/native input geçişi artık editörü yok etmez.
  host.addEventListener('focusout', function onFocusOut(e){
    if(e.relatedTarget && (host.contains(e.relatedTarget) || dateCalendarOwnsTarget(visibleInput,e.relatedTarget))) return;
    if(dateCalendarIsOpenFor(visibleInput)) return;
    setTimeout(()=>{
      if(!host.isConnected || host.contains(document.activeElement) || dateCalendarIsOpenFor(visibleInput)) return;
      // Geçersiz metinde odağı hücreye geri zorlamak, kullanıcıyı hücreden
      // çıkamaz hâle getiriyordu. Artık son geçerli değere dönülür ve düzenleme
      // normal şekilde kapanır.
      if(visibleInput._nativeDateInput && !commitEnhancedDateDisplay(visibleInput,true)){
        visibleInput.value=dateDisplayFromISO(visibleInput._nativeDateInput.value);
        visibleInput.classList.remove('dateInvalid');
        visibleInput.removeAttribute('aria-invalid');
      }
      if(!host.isConnected) return; // change handler satırı yeniden çizmiş olabilir
      const r2 = state.cp.rows.find(r=>r._id===Number(id));
      const newSpan = document.createElement('span');
      newSpan.className='exfDisplay'; newSpan.tabIndex=0;
      newSpan.dataset.id=id; newSpan.dataset.key=key; newSpan.dataset.kind=kind;
      // Değer değişmediyse satır yeniden çizilmez; bu yol da revizyon okunu
      // korumak zorunda, yoksa düzenleyici kapanınca "eski → yeni" kaybolur.
      const revBack = r2 ? revisionInfo(r2, key) : null;
      if(revBack) newSpan.innerHTML = revisionHtml(key, revBack);
      else newSpan.textContent = fmtDate(r2?r2[key]:null) || '—';
      host.replaceWith(newSpan);
    },0);
  });
}
bindEditHandlers('cpTable');
bindCpLogisticToggle('cpTable','cp',()=>renderCP());
bindCpLogisticToggle('ordersTable','orders',()=>renderOrders());
// Koleksiyon tarih hücreleri CP ile aynı görüntüleme/düzenleme davranışını kullanır:
// normal durumda GG.AA.YY metni, tıklanınca klavye + takvim destekli ortak tarih editörü.
function enterKolDateEdit(span){
  if(!span || !span.isConnected) return;
  const id=Number(span.dataset.id), key=span.dataset.k;
  const row=kolRows.find(r=>r.id===id);
  if(!row || !key) return;
  const input=document.createElement('input');
  input.type='date'; input.className='editCell kolDateCell';
  input.dataset.id=String(id); input.dataset.k=key;
  input.dataset.historySession=`kol-date:${id}:${key}:${Date.now()}:${Math.random().toString(36).slice(2)}`;
  input.value=toISODate(row[key]);
  span.replaceWith(input);
  // Dinamik eklenen native input, renderKol sırasında bağlanan doğrudan change
  // dinleyicilerinin dışında kaldığı için kendi kayıt dinleyicisini alır.
  input.addEventListener('change',()=>kolApplyCollectionCellChange({rowId:id,key,editor:input,source:'manual'},{rerender:true}));
  enhanceDateInput(input);
  const visibleInput=input._dateDisplayInput||input;
  const host=input.closest('.dateFieldWrap')||input;
  visibleInput.focus();
  if(visibleInput.select) visibleInput.select();
  host.addEventListener('focusout',function onKolDateFocusOut(e){
    if(e.relatedTarget && (host.contains(e.relatedTarget)||dateCalendarOwnsTarget(visibleInput,e.relatedTarget))) return;
    if(dateCalendarIsOpenFor(visibleInput)) return;
    setTimeout(()=>{
      if(!host.isConnected || host.contains(document.activeElement) || dateCalendarIsOpenFor(visibleInput)) return;
      if(visibleInput._nativeDateInput && !commitEnhancedDateDisplay(visibleInput,true)){
        visibleInput.focus();
        return;
      }
      if(!host.isConnected) return; // commit sonrası renderKol çalışmış olabilir
      const current=kolRows.find(r=>r.id===id);
      const display=document.createElement('span');
      display.className='exfDisplay kolDateDisplay'; display.tabIndex=0;
      display.dataset.id=String(id); display.dataset.k=key;
      display.title=L('Tarihi düzenle');
      display.textContent=fmtDate(current?current[key]:null)||'—';
      host.replaceWith(display);
    },0);
  });
}

// Koleksiyon tablosu: öneri açılır listeleri ve CP biçimindeki tarih editörü bağlanır.
// bindEditHandlers'ın tamamı kullanılamaz; o commitCpEditor'a bağlıdır, Koleksiyon ise
// commitKolEditor kullanır.
(function bindKolSuggestDrops(){
  const el = document.getElementById('kolTable');
  if(!el) return;
  const open = t => {
    if(!t || !t.dataset || t.classList.contains('kolSuggestCell')) return;
    if(t.dataset.kind==='license') showLicenseDrop(t);
    else if(t.dataset.kind==='submfr') showSubmfrDrop(t);
    else if(t.dataset.kind==='licensor') showLicensorDrop(t);
  };
  el.addEventListener('click',e=>{
    const dateDisplay=e.target.closest('.kolDateDisplay');
    if(dateDisplay&&!window.BLCollectionSpreadsheet?.enabled?.()) enterKolDateEdit(dateDisplay);
  });
  el.addEventListener('keydown',e=>{
    if(e.target.classList&&e.target.classList.contains('kolDateDisplay')&&(e.key==='Enter'||e.key===' ')){
      e.preventDefault(); enterKolDateEdit(e.target);
    }
  });
  el.addEventListener('input', e=>open(e.target));
  el.addEventListener('focus', e=>open(e.target), true);
})();

async function saveWorkbookWithValidations(wb, filename, validations, conditionalFormats, protections, workbookOptions){
  if(window.BLPerf) await window.BLPerf.ensureLibrary('jszip');
  const specs=Array.isArray(validations)?validations:[];
  const formats=Array.isArray(conditionalFormats)?conditionalFormats:[];
  const locks=Array.isArray(protections)?protections:[];
  const options=workbookOptions&&typeof workbookOptions==='object'?workbookOptions:{};
  const charts=Array.isArray(options.charts)?options.charts.filter(Boolean):[];
  const isBacklogReport=/^Backlog_Report_/i.test(String(filename||''));
  const pivotStyle=options.pivotStyle||(isBacklogReport?{name:'BuyerLogPivot',fillColor:'F2F4F7',fontColor:'475467',bodyFillColor:'FFFFFF',bodyFontColor:'101828',bold:true}:null);
  const freezePanes=Array.isArray(options.freezePanes)?options.freezePanes:(isBacklogReport?[{sheetPath:'xl/worksheets/sheet1.xml',rows:1,topLeftCell:'A2'}]:[]);
  const needsGuards=!!(specs.length||formats.length||locks.length||pivotStyle||freezePanes.length);
  if(!needsGuards&&!charts.length){XLSX.writeFile(wb,filename);return;}
  if(needsGuards&&(!window.BLExcelWorkbookGuards||typeof JSZip==='undefined'))throw new Error('Excel validation engine is unavailable.');
  if(charts.length&&(!window.BLBacklogChart||typeof window.BLBacklogChart.applyExcelCharts!=='function'||typeof JSZip==='undefined'))throw new Error('Excel chart engine is unavailable.');
  const raw=XLSX.write(wb,{type:'array',bookType:'xlsx',cellStyles:true});
  let patched=raw;
  if(needsGuards)patched=await BLExcelWorkbookGuards.applyWorkbookGuards(raw,{validations:specs,conditionalFormats:formats,protections:locks,pivotStyle,freezePanes},JSZip,'uint8array');
  const blob=charts.length
    ? await window.BLBacklogChart.applyExcelCharts(patched,charts,JSZip,'blob')
    : new Blob([patched],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();
  setTimeout(()=>URL.revokeObjectURL(url),1500);
}
async function saveWorkbookBufferWithValidations(raw,filename,validations,conditionalFormats,protections,workbookOptions){
  if(window.BLPerf)await window.BLPerf.ensureLibrary('jszip');
  const specs=Array.isArray(validations)?validations:[],formats=Array.isArray(conditionalFormats)?conditionalFormats:[],locks=Array.isArray(protections)?protections:[],options=workbookOptions&&typeof workbookOptions==='object'?workbookOptions:{};
  const pivotStyle=options.pivotStyle||(/^Backlog_Report_/i.test(String(filename||''))?{name:'BuyerLogPivot',fillColor:'F2F4F7',fontColor:'475467',bodyFillColor:'FFFFFF',bodyFontColor:'101828',bold:true}:null);
  const freezePanes=Array.isArray(options.freezePanes)?options.freezePanes:[{sheetPath:'xl/worksheets/sheet1.xml',rows:1,topLeftCell:'A2'}];
  let blob;
  if((specs.length||formats.length||locks.length||pivotStyle||freezePanes.length)&&window.BLExcelWorkbookGuards&&typeof JSZip!=='undefined')blob=await BLExcelWorkbookGuards.applyWorkbookGuards(raw,{validations:specs,conditionalFormats:formats,protections:locks,pivotStyle,freezePanes},JSZip,'blob');
  else blob=new Blob([raw],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
  const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);
}

function exportCsv(rows, cols, filename){
  const head = cols.map(c=>c.label).join(',');
  const body = rows.map(r=>cols.map(c=>{
    let v=r[c.k];
    if(v instanceof Date) v=fmtDate(v);
    v = norm(v).replace(/"/g,'""');
    return /[",\n]/.test(v) ? `"${v}"` : v;
  }).join(',')).join('\n');
  const blob = new Blob([head+'\n'+body], {type:'text/csv;charset=utf-8;'});
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = filename; a.click();
}

// ---------- OVERVIEW ----------
// Bir <select>'e, seçeneklerde olmayan bir değer atanacaksa geçici option ekleyerek atar.
function setSelectValue(id, val){
  const sel = document.getElementById(id); if(!sel) return;
  if(val && ![...sel.options].some(o=>o.value===val)){
    const o = document.createElement('option'); o.value = val; o.textContent = val; sel.appendChild(o);
  }
  sel.value = val || '';
}
function clearCpQuickFilters(){
  ['cpFPriority','cpFStatus','cpFDelType','cpFSeason','cpFCountry','cpFLicense'].forEach(id=>{const s=document.getElementById(id);if(s)s.value='';});
  state.cpQuickExf='';clearColumnFilters('cp',['Priority','STATUS','Del. Type','Season','Ex-factory']);
  // Genel Bakış'ta seçili olan Buying Group/Buyer/Country/MAG/MMYG filtresi, CP'ye
  // geçerken de korunur — aksi halde "drill-through" Genel Bakış'taki filtreyi görmezden gelirdi.
  const next = {};
  ['buyerGrup','buyer','country','merch','ageGroup'].forEach(dim=>{
    const set = ovDimFilters[dim];
    if(set && set.size) next[dim] = new Set(set);
  });
  cpDimFilters = next;
  saveCpDimFilters(); updateCpDimBtnLabels();
}
function bindMiniDrill(id, applyFn){
  document.querySelectorAll('#'+id+' tr').forEach(tr=>{
    const td = tr.querySelector('td'); if(!td) return;
    tr.style.cursor='pointer'; tr.title = "CP'de göster";
    tr.addEventListener('click', ()=>{ applyFn(td.textContent.trim()); switchTab('cp'); renderCP(); });
  });
}
// ================= GENEL BAKIŞ — KİŞİSELLEŞTİRME FİLTRESİ =================
// Kalem simgesiyle açılan tek paylaşılan popover; MAG, MMYG, Order Status (Active/Inactive),
// Season, Buying Group, Buyer, Country seçilebilir. Seçim tarayıcıda saklanır, programı
// kapatıp açınca son hali geri gelir. Hiçbir seçim yoksa ASAS+Antrepo'daki tüm veri özetlenir.
let ovDimFilters = {}; // {dim: Set(değerler)} — üstteki genel kartlar (Hızlı Filtreler, Sezon Bazlı, kartlar, sipariş KPI)
let ovBgDimFilters = {}; // Buying Group Bazlı Özet — bilinçli olarak AYRI ve bağımsız filtrelenir
const OV_DIM_META = {
  merch:      {label:'MAG',           labelTr:'MAG',          labelEn:'MAG',           col:'Merch Alt Grup Kod'},
  ageGroup:   {label:'MMYG',          labelTr:'MMYG',         labelEn:'MMYG',          col:'Merch Marka Yaş Grup Kod'},
  orderStatus:{label:'Order Status',  labelTr:'Sipariş Durumu',labelEn:'ORDER STATUS', col:'Active/Inactive', staticValues:['Active','Inactive']},
  season:     {label:'Season',        labelTr:'Sezon',        labelEn:'SEASON',        col:'Season'},
  buyerGrup:  {label:'Buying Group',  labelTr:'BUYING GRUP',  labelEn:'BUYING GROUP',  col:'Buyer Grup (TR)'},
  buyer:      {label:'Buyer',         labelTr:'Buyer',        labelEn:'BUYER',         col:'Buyer'},
  country:    {label:'Country',       labelTr:'Ülke',         labelEn:'COUNTRY',       col:'Country'},
};
function ovDimLabel(dim){
  const meta=OV_DIM_META[dim]||{};
  return appLang==='en' ? (meta.labelEn||meta.label||dim) : (meta.labelTr||meta.label||dim);
}
const OV_DIM_FILTERS_KEY = 'lcw.overview.dimFilters.v1';
const OV_BG_DIM_FILTERS_KEY = 'lcw.overview.bgDimFilters.v1';
function ovStateFor(scope){ return scope==='bg' ? ovBgDimFilters : ovDimFilters; }
function ovSetStateFor(scope, val){ if(scope==='bg') ovBgDimFilters = val; else ovDimFilters = val; }
function ovKeyFor(scope){ return scope==='bg' ? OV_BG_DIM_FILTERS_KEY : OV_DIM_FILTERS_KEY; }
window.BL_GET_OVERVIEW_FILTERS = () => Object.fromEntries(Object.entries(ovDimFilters).map(([key, values]) => [key, values instanceof Set ? [...values] : []]));
function saveOvDimFilters(scope){
  try{
    const src = ovStateFor(scope);
    const obj = {}; Object.entries(src).forEach(([d,s])=>{ if(s&&s.size) obj[d]=[...s]; });
    BLStorage.setItem(ovKeyFor(scope), JSON.stringify(obj));
  }catch(e){}
}
function loadOvDimFilters(scope){
  try{
    const raw = BLStorage.getItem(ovKeyFor(scope)); if(!raw) return;
    const obj = JSON.parse(raw);
    const target = {};
    Object.entries(obj).forEach(([d,vals])=>{ if(OV_DIM_META[d] && Array.isArray(vals) && vals.length) target[d]=new Set(vals.map(String)); });
    ovSetStateFor(scope, target);
  }catch(e){}
}
// CP satırları yapı gereği her zaman aktiftir (Kalan Miktar > 0); Order Status filtresi
// CP tabanlı kartlarda bu gerçeğe göre değerlendirilir (Inactive seçilirse CP kartları boş kalır).
function passesOvDimFilters(row, isCpRow, scope){
  const src = ovStateFor(scope);
  return Object.entries(src).every(([dim,set])=>{
    if(!set || !set.size) return true;
    if(dim==='orderStatus'){
      const val = isCpRow ? 'Active' : (norm(row['Active/Inactive'])||'Active');
      return set.has(val);
    }
    const col = OV_DIM_META[dim].col;
    return set.has(norm(row[col]));
  });
}
function ovFilteredCpRows(){ return state.cp ? state.cp.rows.filter(r=>passesOvDimFilters(r,true,'main')) : []; }
function overviewCpFilterSignature(){
  const src=ovStateFor('main');
  return Object.keys(src).sort().map(dim=>{
    const values=src[dim]&&src[dim].size?[...src[dim]].map(String).sort():[];
    return `${dim}:${values.join('¦')}`;
  }).join('|');
}
function ovFilteredOrderRows(){ return overviewSummaryRows().filter(r=>passesOvDimFilters(r,false,'main')); }
// Buying Group Bazlı Özet — talep gereği diğer kartlardan bağımsız, kendi filtresiyle çalışır.
function ovFilteredOrderRowsBg(){ return overviewSummaryRows().filter(r=>passesOvDimFilters(r,false,'bg')); }
function ovDimFilterCount(scope){ return Object.values(ovStateFor(scope)).filter(s=>s&&s.size).length; }
function updateOvFilterBadge(scope){
  const badge = document.getElementById(scope==='bg' ? 'ovFilterBadgeBg' : 'ovFilterBadge'); if(!badge) return;
  const n = ovDimFilterCount(scope);
  if(!n){ badge.style.display='none'; return; }
  const src = ovStateFor(scope);
  const parts = Object.entries(src).filter(([,s])=>s&&s.size).map(([d,s])=>{
    const label = ovDimLabel(d);
    return `${label}: ${s.size<=2 ? [...s].join(', ') : s.size+' '+(appLang==='en'?'selected':'seçili')}`;
  });
  const label = appLang==='en' ? 'FILTERS' : 'Aktif Filtreler';
  const clearLabel = appLang==='en' ? 'Clear' : 'Temizle';
  badge.innerHTML = `${label} — ${escapeHtml(parts.join(' · '))} <button type="button" class="ovFilterBadgeClear" data-scope="${scope}" style="margin-left:8px;border:none;background:none;color:var(--acc-ink);text-decoration:underline;cursor:pointer;font:inherit;">${clearLabel}</button>`;
  badge.style.display='block';
  badge.querySelector('.ovFilterBadgeClear')?.addEventListener('click', ()=>{
    ovSetStateFor(scope, {}); saveOvDimFilters(scope); updateOvFilterBadge(scope); renderOverview();
  });
}
function renderOvFilterPopover(scope){
  let modal = document.getElementById('ovFilterModal');
  if(modal) modal.remove();
  const orderRows = overviewSummaryRows();
  const src = ovStateFor(scope);
  modal = document.createElement('div');
  modal.id = 'ovFilterModal'; modal.className = 'warnOverlay';
  // Çapraz filtre ipucu: bir boyutu seçince diğer boyutların listesinde o seçimle
  // birlikte var olan değerler üste/normal, olmayanlar alta/soluk gelir.
  const section = (dim) => {
    const meta = OV_DIM_META[dim];
    const allVals = meta.staticValues ? meta.staticValues : uniqueVals(orderRows, meta.col);
    const otherEntries = Object.keys(OV_DIM_META).filter(d=>d!==dim).map(d=>[src[d], OV_DIM_META[d].col]);
    const validSet = computeValidValueSet(orderRows, otherEntries, meta.col);
    const vals = meta.staticValues ? allVals : sortWithFacet(allVals, validSet);
    const selected = src[dim] || new Set();
    return `<div class="ovFilterSection">
      <div class="ovFilterSectionTitle">${escapeHtml(ovDimLabel(dim))}</div>
      <div class="ovFilterChecklist" data-ovdim="${dim}">
        <label style="display:flex;align-items:center;gap:6px;padding:3px 2px;font-weight:600;">
          <input type="checkbox" class="ovDimAll" ${selected.size===0?'checked':''}> ${appLang==='en'?'All':'Hepsi'}
        </label>
        ${facetChecklistHtml(vals, validSet, selected, 'ovDimChk')}
      </div>
    </div>`;
  };
  const titleText = appLang==='en' ? 'FILTERS' : 'Filtreler';
  const gridHtml = () => Object.keys(OV_DIM_META).map(section).join('');
  modal.innerHTML = `<div class="modalCard" style="max-width:640px;width:92%;max-height:82vh;display:flex;flex-direction:column;padding:0;">
    <div class="modalTitle" style="margin:0;padding:16px 20px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;">
      ${escapeHtml(titleText)}
      <button type="button" class="ovFilterClose" style="border:none;background:none;cursor:pointer;color:var(--muted);font-size:15px;"><svg class="ic"><use href="#i-x"/></svg></button>
    </div>
    <div id="ovFilterGrid" style="padding:14px 20px;overflow:auto;display:grid;grid-template-columns:1fr 1fr;gap:14px;">
      ${gridHtml()}
    </div>
    <div style="padding:12px 20px;border-top:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;">
      <span style="font-size:11px;color:var(--muted);">${appLang==='en' ? 'If no selection is made, all data in ASAS and Antrepo will be summarized.' : "Hiçbir seçim yapılmazsa ASAS+Antrepo'daki tüm veri özetlenir."}</span>
      <div style="display:flex;gap:8px;">
        <button type="button" class="tbtn" id="ovFilterResetAll"><svg class="ic"><use href="#i-checklist"/></svg>${appLang==='en' ? 'Clear All' : 'Tümünü Temizle'}</button>
        <button type="button" class="navActionBtn pri" id="ovFilterApplyClose" style="background:var(--acc);border-color:var(--acc);color:var(--on-acc);"><svg class="ic"><use href="#i-checklist"/></svg>${appLang==='en' ? 'Apply and Close' : 'Uygula ve Kapat'}</button>
      </div>
    </div>
  </div>`;
  document.body.appendChild(modal);
  modal.__refreshCanonicalRecipients=()=>{prepareEmailFillFromShared();if(typeof refreshAll==='function')refreshAll();};
  modal.addEventListener('click',event=>{const manage=event.target.closest('[data-manage-email-groups]');if(manage){event.preventDefault();window.BLEmailGroups?.open?.();}});
  function wireGrid(){
    modal.querySelectorAll('.ovFilterChecklist').forEach(box=>{
      const dim = box.dataset.ovdim;
      box.querySelector('.ovDimAll').addEventListener('change', e=>{
        if(e.target.checked){ delete src[dim]; }
        else { e.target.checked = true; return; }
        refreshGrid();
      });
      box.querySelectorAll('.ovDimChk').forEach(chk=> chk.addEventListener('change', ()=>{
        if(!src[dim]) src[dim] = new Set();
        if(chk.checked) src[dim].add(chk.value); else src[dim].delete(chk.value);
        if(src[dim].size===0) delete src[dim];
        refreshGrid();
      }));
    });
  }
  function refreshGrid(){
    document.getElementById('ovFilterGrid').innerHTML = gridHtml();
    wireGrid();
  }
  wireGrid();
  const close = ()=>{ saveOvDimFilters(scope); updateOvFilterBadge(scope); renderOverview(); modal.remove(); };
  modal.querySelector('.ovFilterClose').addEventListener('click', close);
  modal.querySelector('#ovFilterApplyClose').addEventListener('click', close);
  modal.querySelector('#ovFilterResetAll').addEventListener('click', ()=>{
    Object.keys(OV_DIM_META).forEach(d=>delete src[d]);
    refreshGrid();
  });
  modal.addEventListener('click', e=>{ if(e.target===modal) close(); });
}
document.querySelectorAll('[data-ovfilter-trigger]').forEach(btn=> btn.addEventListener('click', ()=>{
  renderOvFilterPopover(btn.dataset.ovfilterTrigger === 'bg' ? 'bg' : 'main');
}));
loadOvDimFilters('main');
loadOvDimFilters('bg');

