      if(q.opdRange&&!pricingRuleDateRangeLabel(r).toLocaleLowerCase('tr-TR').includes(q.opdRange)) return false;
      if(q.seasons&&!pricingRuleSeasonLabel(r).toLocaleLowerCase('tr-TR').includes(q.seasons)) return false;
      if(q.countryGroup&&turknorm(r.countryGroup)!==turknorm(q.countryGroup)) return false;
      if(q.licensor&&!norm(r.licensor).toLocaleLowerCase('tr-TR').includes(q.licensor)) return false;
      if(q.license&&!norm(r.license).toLocaleLowerCase('tr-TR').includes(q.license)) return false;
      if(!numericFilter(r.royalty,ruleFilters.royalty)) return false;
      if(!numericFilter(r.hologramCost,ruleFilters.hologramCost)) return false;
      if(q.matches&&!String(matchCount).includes(q.matches)) return false;
