/* --- ASAS - IAS Eşleştirme Kuralı (v4.39) -------------------------------
 * Kullanıcı istediği sayıda koşul tanımlar. Koşullar AND ile bağlıdır ve yalnız
 * birebir değerler eşleşir; yakın/tahmini/yedek eşleştirme yapılmaz.
 */
function cloneMatchConfig(value){
  const conditions=Array.isArray(value&&value.conditions)?value.conditions:[];
  return {version:1,conditions:conditions.map((condition,index)=>({
    id:String(condition.id||`condition-${index+1}`),
    asas:{...(condition.asas||{})},
    ias:{...(condition.ias||{})},
  }))};
}
function matchFieldLabel(side,emptyText){
  if(!side||(!side.name&&!side.canonicalHeader&&!side.header))return emptyText;
  const canonical=String(side.canonicalHeader||side.header||'').trim();
  const source=[side.table,side.name].filter(Boolean).join(' · ');
  return canonical&&source?`${canonical} — ${source}`:(source||canonical);
}
/* v7.81 — ESKİ EŞLEŞTİRME KURALI MODALI KALDIRILDI.

   Kural artık Veri Yönetimi ekranında (data-management-matchrule.js): iki
   kaynak ARASINDAKİ bir ilişki olduğu için kaynak şeridinin altında, kendi
   başlığıyla duruyor. Denetim (match-audit) da oraya taşındı ve aşağıdaki
   renderMatchAudit ile ÇİZİLMEYE DEVAM EDİYOR — ikinci bir tablo yazılmadı. */
function renderMatchAudit(a,en){
  const fmt=n=>Number(n||0).toLocaleString('tr-TR');
  const conditions=Array.isArray(a.conditions)?a.conditions:[];
  const fieldRows=conditions.map(condition=>{
    const f=a.fields&&a.fields[condition.id];if(!f)return '';
    const risky=f.shared===0||(f.asasDistinct&&f.shared/f.asasDistinct<0.5);
    return `<tr class="${risky?'matchAuditBad':''}">
      <td><strong>${escapeHtml(condition.asasLabel||'')}</strong><br><small>IAS: ${escapeHtml(condition.iasLabel||'')}</small></td>
      <td>${fmt(f.asasDistinct)}${f.asasEmpty?` <small>(${fmt(f.asasEmpty)} ${en?'empty':'boş'})</small>`:''}</td>
      <td>${fmt(f.iasDistinct)}${f.iasEmpty?` <small>(${fmt(f.iasEmpty)} ${en?'empty':'boş'})</small>`:''}</td>
      <td><strong>${fmt(f.shared)}</strong></td>
      <td><small>ASAS: ${escapeHtml((f.asasOnly||[]).slice(0,3).join(' · '))||'—'}<br>IAS: ${escapeHtml((f.iasOnly||[]).slice(0,3).join(' · '))||'—'}</small></td>
    </tr>`;
  }).join('');
  const sampleRows=(a.samples||[]).slice(0,6).map(sample=>{
    const values=(source,row)=>conditions.map(condition=>`<div><strong>${escapeHtml(source==='asas'?condition.asasLabel:condition.iasLabel)}:</strong> ${escapeHtml((row&&row[condition.id])||'(boş)')}</div>`).join('');
    const ias=(sample.ias||[]).map(entry=>`<div class="matchAuditCandidate">${values('ias',entry.values)}${entry.statu?`<small>${escapeHtml(entry.statu)}</small>`:''}</div>`).join('');
    const bad=(sample.mismatch||[]).map(id=>{const condition=conditions.find(item=>item.id===id);return condition?`${condition.asasLabel} = ${condition.iasLabel}`:id;}).join(' + ');
    return `<tr><td>${escapeHtml(sample.anchor||'—')}</td><td>${values('asas',sample.asas)}</td><td>${ias||'—'}</td><td class="matchAuditBad">${escapeHtml(bad||'—')}</td></tr>`;
  }).join('');
  const t=a.totals||{};
  /* ÇÖZÜLEMEYEN ALAN DENETİMDE DE SÖYLENİR. Aksi hâlde kullanıcı "0 eşleşti"
     tablosuna bakıp veriyi suçlar; sebep kuralın kendisidir. */
  const broken=(a.unresolved||[]).map(entry=>`${entry.label||entry.sourceId} (${entry.reason==='source'?(en?'source not connected':'kaynak bağlı değil'):(en?'column missing':'sütun yok')})`);
  const warn=broken.length?`<div class="matchAuditHead matchAuditBad">${escapeHtml(en?'Unresolved fields — fix the rule before trusting this result:':'Çözülemeyen alanlar — bu sonuca güvenmeden önce kuralı düzeltin:')} ${escapeHtml(broken.join(' · '))}</div>`:'';
  return warn+`<div class="matchAuditHead">${escapeHtml(en?'Rule':'Kural')}: <strong>${escapeHtml(a.ruleLabel||'')}</strong> ·
      ${fmt(t.asasRows)} ${escapeHtml(en?'ASAS lines':'ASAS satırı')} · ${fmt(t.iasRows)} ${escapeHtml(en?'IAS records':'IAS kaydı')} ·
      <strong>${fmt(t.matched)}</strong> ${escapeHtml(en?'matched':'eşleşti')} · ${fmt(t.unmatched)} ${escapeHtml(en?'unmatched':'eşleşmedi')}</div>
    <table class="matchAuditTable"><thead><tr><th>${escapeHtml(en?'Condition':'Koşul')}</th><th>ASAS</th><th>IAS</th><th>${escapeHtml(en?'Shared':'Ortak')}</th><th>${escapeHtml(en?'Only on one side':'Yalnız bir tarafta')}</th></tr></thead><tbody>${fieldRows}</tbody></table>
    ${sampleRows?`<div class="matchAuditHead">${escapeHtml(en?'Rows sharing the first condition but failing another condition:':'İlk koşulu ortak olup diğer koşullardan birinde eşleşmeyen satırlar:')}</div>
    <table class="matchAuditTable"><thead><tr><th>${escapeHtml(en?'Anchor':'İlk koşul')}</th><th>ASAS</th><th>IAS</th><th>${escapeHtml(en?'Mismatching condition':'Tutmayan koşul')}</th></tr></thead><tbody>${sampleRows}</tbody></table>`:''}`;
}
/* --- Veri Modeli Bağlantısı -------------------------------------------------
 * Kaynak Excel dosyalarındaki pivotlar SSAS Tabular modellerine bağlıdır. Bu pencere
 * aynı modeli Excel'i hiç açmadan sorgulamayı, süresini ölçmeyi ve sonucu CSV/JSON
 * olarak dışa aktarmayı sağlar.
 *
 * Ana Refresh akışında ASAS bu bağlantılardan gelir. Antrepo varsayılan Excel
 * kaynağındadır; yalnız Database seçildiğinde IAS bağlantısı sorgulanır.
 */
const MODEL_CONNECTION_PRESETS=[
  {name:'ASAS', server:'lcwtabular_s30', catalog:'ASAS_30', role:'asas', refreshEnabled:true},
  {name:'IAS',  server:'lcwtabular_p32', catalog:'IASv2', role:'antrepo', refreshEnabled:true},
  {name:'INTAKE', server:'lcwtabular_s20', catalog:'WSSI Intake Raporu4', role:'intake', refreshEnabled:true},
];
const MODEL_CONNECTION_DEFAULT_SEASONS=Object.freeze(['W6','W7','S6','S7']);
const MODEL_ROLE_TARGETS={asas:['cp','orders','backlog','lfl'],antrepo:['cp','orders','backlog'],intake:['intake']};
MODEL_ROLE_TARGETS.asas.push('priceanalysis');
const MODEL_TARGET_LABELS={cp:'CP',orders:'Orders / Siparişler',backlog:'Backlog',lfl:'LFL',priceanalysis:'Price & Supplier Analysis',intake:'INTAKE'};
function modelAllowedTargets(role){ return (MODEL_ROLE_TARGETS[role]||[]).slice(); }
function modelScopeLabel(scope){
  const name=String(scope&&scope.name||'').trim();
  if(name) return name;
  return (scope&&scope.targets||[]).map(t=>MODEL_TARGET_LABELS[t]||t).join(' + ')||'—';
}
const MODEL_QUERY_PLACEHOLDER='// Once "Tablolari Listele" ile tablo adini bul, listeden tikla.\n// Sorgu buraya kendisi yazilir.';
let modelConnState={items:[],revision:0,selectedId:null,supported:true,exportFolder:'',loaded:false};
let modelConnFields={};      // rol → alan kataloğu (sunucudan bir kez alınır)
let modelConnColumns={};     // tablo adı → model sütunları

async function modelConnLoadFieldCatalogue(role){
  if(modelConnFields[role]) return modelConnFields[role];
  const res=await fetch(`/api/model-fields?role=${encodeURIComponent(role)}`);
  const data=await res.json().catch(()=>({}));
  if(!res.ok) throw new Error(data.error||res.statusText);
  modelConnFields[role]={fields:Array.isArray(data.fields)?data.fields:[],derived:Array.isArray(data.derived)?data.derived:[]};
  return modelConnFields[role];
}
function modelConnMappingPresent(value){
  if(value&&typeof value==='object')return Boolean(String(value.name||'').trim())&&(value.kind==='measure'||Boolean(String(value.table||'').trim()));
  return Boolean(String(value==null?'':value).trim());
}
function modelConnMappingWarningKey(value){
  return String(value==null?'':value).toLocaleUpperCase('tr-TR')
    .replace(/İ/g,'I').replace(/Ş/g,'S').replace(/Ğ/g,'G').replace(/Ü/g,'U').replace(/Ö/g,'O').replace(/Ç/g,'C')
    .replace(/[^A-Z0-9]+/g,' ').trim();
}
async function modelConnRequiredMappingIssues(items=modelConnState.items){
  const issues=[];
  for(const item of (Array.isArray(items)?items:[])){
    if(!item||!['asas','antrepo'].includes(item.role)||item.refreshEnabled===false)continue;
    // Kaynak Excel olarak seçiliyse bu bağlantı hiç sorgulanmaz; eşlenmemiş
    // alanlar için kullanıcıyı uyarmak/Yenile'yi engellemek yanlış olur.
    if(item.role==='antrepo'&&antrepoSourceMode==='excel')continue;
    if(item.role==='asas'&&asasSourceMode==='excel')continue;
    let catalogue;
    try{catalogue=await modelConnLoadFieldCatalogue(item.role);}catch(_){continue;}
    const missing=(catalogue.fields||[]).filter(field=>{
      // LFL Para Birimi bilinçli istisnadır; kullanıcı talebi gereği kırmızı
      // eşleme uyarısını ve Yenile engelini tetiklemez.
      if(modelConnMappingWarningKey(field.header)==='PARA BIRIMI'&&modelConnMappingWarningKey(field.usedBy)==='LFL')return false;
      return field.required&&!modelConnMappingPresent((item.mapping||{})[field.header]);
    });
    if(missing.length)issues.push({connectionId:item.id,connectionName:item.name||item.catalog||item.server||'—',role:item.role,missing});
  }
  return issues;
}
async function refreshFieldMappingReadinessUI(items=modelConnState.items){
  const warning=document.getElementById('fieldMappingWarning');
  const buttons=['topRefreshBtn','serverRefreshBtn'].map(id=>document.getElementById(id)).filter(Boolean);
  const issues=await modelConnRequiredMappingIssues(items);
  buttons.forEach(btn=>btn.classList.toggle('fieldMappingError',issues.length>0));
  if(!warning)return issues;
  if(!issues.length){warning.hidden=true;warning.textContent='';warning.removeAttribute('data-connection-id');return issues;}
  const first=issues[0],count=issues.reduce((sum,entry)=>sum+entry.missing.length,0);
  warning.hidden=false;
  warning.dataset.connectionId=first.connectionId||'';
  warning.textContent=appLang==='en'
    ?`${count} required Field Mapping item${count===1?' is':'s are'} missing. Click to open.`
    :`Field Mapping'de ${count} zorunlu alan eşlenmemiş. Açmak için tıkla.`;
  warning.title=issues.map(entry=>`${entry.connectionName}: ${entry.missing.map(field=>field.header).join(', ')}`).join('\n');
  return issues;
}
let modelConnSchema=null;    // { columns:[{table,name,kind}], measures:[{table,folder,name,kind}] }
function modelConnSchemaEntries(){
  if(!modelConnSchema) return [];
  return (modelConnSchema.measures||[]).concat(modelConnSchema.columns||[]);
}
function modelConnEntryId(entry){ return `${entry.kind}|${entry.table}|${entry.name}`; }
// Sütun tekil değerleri: catalog|tablo|sütun → değer listesi. Bir kez çekilir,
// aynı pencerede tekrar açıldığında anında gelir.
let modelConnValueCache={};
async function modelConnDistinct(item,table,field){
  const key=`${item.catalog}|${table}|${field}`;
  if(modelConnValueCache[key]) return modelConnValueCache[key];
  const res=await fetch('/api/model-connections/distinct',{method:'POST',headers:{'Content-Type':'application/json'},
    body:JSON.stringify({server:item.server,catalog:item.catalog,table,field})});
  const data=await res.json().catch(()=>({}));
  if(!res.ok) throw new Error(data.error||res.statusText);
  modelConnValueCache[key]={values:Array.isArray(data.values)?data.values:[],truncated:Boolean(data.truncated)};
  return modelConnValueCache[key];
}
function modelConnKnownSeasons(){
  try{ return [...new Set((state.asasOrders||[]).map(o=>String(o.season||'').trim()).filter(Boolean))]; }
  catch(_){ return []; }
}



// SERVER_BACKED ana iş verisinin en az bir kez başarıyla yüklenip yüklenmediğini
// anlatır; yerel Buyer Log API'sinin erişilebilirliğini anlatmaz. Kurumsal
// kaynak/VPN kapalıyken ana yükleme başarısız olabilir fakat bağlantı ayarları
// aynı localhost sunucusundan hâlâ okunup yazılabilmelidir.
function modelConnectionApiAvailable(){
  return location.protocol==='http:'||location.protocol==='https:';
}

async function modelConnLoad(){
  if(!modelConnectionApiAvailable()){ modelConnState.loaded=true; return modelConnState; }
  const res=await fetch('/api/model-connections');
  const data=await res.json().catch(()=>({}));
  if(!res.ok) throw new Error(data.error||res.statusText);
  modelConnState.items=(Array.isArray(data.items)?data.items:[]).filter(item=>item&&item.role!=='fabric');
  modelConnState.revision=Number(data.revision)||0;
  modelConnState.supported=data.supported!==false;
  modelConnState.exportFolder=String(data.exportFolder||'');
  modelConnState.loaded=true;
  void refreshFieldMappingReadinessUI(modelConnState.items);
  return modelConnState;
}

async function modelConnSave(items){
  if(!modelConnectionApiAvailable()){ modelConnState.items=items; void refreshFieldMappingReadinessUI(items); return items; }
  const res=await fetch('/api/model-connections',{method:'PUT',
    headers:{'Content-Type':'application/json','If-Match':String(modelConnState.revision||0)},
    body:JSON.stringify({items})});
  const data=await res.json().catch(()=>({}));
  if(!res.ok) throw new Error(data.error||res.statusText);
  modelConnState.items=Array.isArray(data.items)?data.items:items;
  modelConnState.revision=Number(data.revision)||modelConnState.revision;
  void refreshFieldMappingReadinessUI(modelConnState.items);
  return modelConnState.items;
}

function modelConnDurationLabel(ms){ return fmtDurationSn(ms); }

