async function persistTransitRules(rules){
  const clean=normalizeTransitRules(rules);
  // Sunucu, bayat revizyonda yalnız kullanıcının gerçekten değiştirdiği rota
  // kayıtlarını rebase eder; böylece başka bir rotadaki eşzamanlı güncelleme kaybolmaz.
  const baseRules=normalizeTransitRules(state.overrides.transitRules);
  state.overrides.transitRules=clean; saveLocalTransitRules(clean);
  invalidateUnifiedPriorityDecisions('transit-rules-local');
  scheduleOverviewRender('transit-rules-local');
  if(window.SERVER_BACKED){
    const res=await fetch('/api/transit-rules',{method:'PUT',headers:{'Content-Type':'application/json','If-Match':String(state.storeRevisions.transitRules||0),...(window.BL_CLIENT_ID?{'X-Client-Id':window.BL_CLIENT_ID}:{})},body:JSON.stringify({rules:clean,baseRules})});
    const data=await res.json().catch(()=>({})); if(!res.ok) throw new Error(data.error||res.statusText);
    state.storeRevisions.transitRules=Number(data.revision)||state.storeRevisions.transitRules||0;
    state.overrides.transitRules=normalizeTransitRules(data.rules||clean); saveLocalTransitRules(state.overrides.transitRules);
    invalidateUnifiedPriorityDecisions('transit-rules-server');
    await loadFromServer(false);
  }else{
    [state.cp&&state.cp.rows,state.orderSummary&&state.orderSummary.rows].forEach(rows=>(rows||[]).forEach(applyFormulas));
    if(state.cp){renderCP();} if(state.orderSummary)renderOverview();
    if(typeof fetchCurrentBacklog==='function')fetchCurrentBacklog();
  }
  if(typeof renderKol==='function')renderKol();
  return clean;
}
