const COUNTRY_MAP = { 'HINDISTAN':'India','BANGLADES':'Bangladesh','CIN':'China','TURKIYE':'Turkey','MISIR':'Egypt','FAS':'Morocco','MYANMAR':'Myanmar','ENDONEZYA':'Indonesia' };
function countryEN(raw){ return COUNTRY_MAP[turknorm(raw)] || raw; }
const EXCL_COUNTRIES_NORM = new Set(['TURKIYE','MISIR']);
const BG_WHITELIST = new Set(['DENIM','DOKUMA ALT','DOKUMA UST','LISANS','ORME','ORME ALT','ORME BASIC','TAKIM','TRIKO']);
const MERCH_WHITELIST = new Set(['CK1E','CK4E','CK4L','CU1E','CU4E']);
const AGE_WHITELIST = new Set(['CKW1','CKW4','CUW1','CUW4']);

function yyyymmdd(v){ return coerceDateLoose(v); }
function parseDateFlexible(v){ return coerceDateLoose(v); }
function findAnchorRow(rows, anchors, maxScan){
  for(let i=0;i<Math.min(rows.length, maxScan||25);i++){
    const cells = (rows[i]||[]).map(c=>norm(c));
    if(anchors.every(a=>cells.includes(a))) return i;
  }
  return -1;
}

function parseASASWorkbook(wb){
  const sheet = wb.Sheets[wb.SheetNames[0]];
  const rows = XLSX.utils.sheet_to_json(sheet, {header:1, raw:true, defval:null});
  const hIdx = findAnchorRow(rows, ['Sipariş Kod'], 25);
  if(hIdx<0) return null;
  const header = rows[hIdx].map(h=>norm(h));
  const idx = {}; header.forEach((h,i)=>{ if(h) idx[h]=i; });
  const g = (row,name)=> idx[name]!=null ? row[idx[name]] : null;
  const canonAsasHeader = v=>turknorm(v).replace(/[^A-Z0-9]+/g,' ').replace(/\s+/g,' ').trim();
  const findHeader=(exact,patterns)=>{
    for(const name of exact||[]) if(idx[name]!=null) return name;
    for(const terms of patterns||[]){
      const hit=header.find(name=>{const key=canonAsasHeader(name);return terms.every(term=>key.includes(term));});
      if(hit) return hit;
    }
    return null;
  };
  const shipConfHeader = findHeader(['Buying Son Onay Tarihi'],[
    ['BUYING','SON','ONAY','TARIH'],['BUYING','APPROVAL','DATE']
  ]);
  const productDescriptionHeader=findHeader(['Ürün Tanım','Ürün Tanımı'],[
    ['URUN','TANIM'],['PRODUCT','DESCRIPTION'],['PRODUCT','DEFINITION']
  ]);
  const mainFabricHeader=findHeader(['Ana Kumaş Mı'],[
    ['ANA','KUMAS','MI'],['MAIN','FABRIC'],['IS','MAIN','FABRIC']
  ]);
  const fabricHeaders={
    fabricCategory:findHeader(['Kumaş Kategorisi'],[['KUMAS','KATEGORI'],['FABRIC','CATEGORY']]),
    fabricSupplierCountry:findHeader(['Kumaşçı Ülkesi'],[['KUMASCI','ULKE'],['FABRIC','SUPPLIER','COUNTRY'],['MILL','COUNTRY']]),
    fabricSupplier:findHeader(['Kumaşçı'],[['KUMASCI'],['FABRIC','SUPPLIER'],['FABRIC','MILL']]),
    kumasTipi:findHeader(['Kumaş Tipi'],[['KUMAS','TIP'],['FABRIC','TYPE']]),
    iplikNo:findHeader(['İplik No'],[['IPLIK','NO'],['YARN','COUNT'],['YARN','NO']]),
    fabricWeight:findHeader(['Gramaj','Kumaş Gramajı'],[['GRAMAJ'],['GSM'],['FABRIC','WEIGHT']]),
    karisim:findHeader(['Karışım'],[['KARISIM'],['COMPOSITION'],['BLEND']]),
  };
  const isMainFabric=value=>{
    if(value===true)return true;
    if(typeof value==='number')return Number.isFinite(value)&&value===1;
    const text=norm(value).replace(',','.');
    return /^1(?:\.0+)?$/.test(text)||['EVET','YES','TRUE'].includes(turknorm(text));
  };
  const fabricFields=Object.keys(fabricHeaders);
  const toOrder=row=>{
    const main=!!mainFabricHeader&&isMainFabric(g(row,mainFabricHeader));
    const order={
      ocode: Math.trunc(Number(g(row,'Sipariş Kod'))),
      colour: norm(g(row,'Renk')), ccode: norm(g(row,'Renk Kod')),
      qty: Number(g(row,'Net Alım Sipariş Miktarı'))||0,
      kalan: Number(g(row,'Kalan Alım Sipariş Miktarı'))||0,
      antrepo: Number(g(row,'Antrepoya Giren Miktar'))||0,
      merkezSevkeHazirKalan: Number(g(row,'Kalan Alım Sipariş Miktarı_Merkez Sevke Hazır Depo'))||0,
      fob: Number(g(row,'FOB Fiyatı')),
      plm: g(row,'Plm Kod'), ozel: norm(g(row,'Özel Kod 1')),
      manufacturer: norm(g(row,'Üretici')), season: norm(g(row,'Sezon')),
      category: norm(g(row,'Ürün Klasman')), merch: norm(g(row,'Merch Alt Grup Kod')).toUpperCase(),
      ageGroup: norm(g(row,'Merch Marka Yaş Grup Kod')).toUpperCase(),
      buyerGrup: norm(g(row,'Buyer Grup (TR)')), countryRaw: norm(g(row,'Siparişin Üretildiği Ülke')),
      license: norm(g(row,'Lisans')), model: norm(g(row,'Model Adı')),
      productDescription:productDescriptionHeader?norm(g(row,productDescriptionHeader)):'',
      ex: yyyymmdd(g(row,'Orijinal Exfactory Merch Tarih')),
      retail: yyyymmdd(g(row,'Retail Depo Tarih Yıl Ay Gün')),
      mb: yyyymmdd(g(row,'Model Bütçe Tarih Yıl Ay Gün')),
      opd: yyyymmdd(g(row,'Sipariş Yerleştirme MerchTarih')),
      shipConf: shipConfHeader ? yyyymmdd(g(row,shipConfHeader)) : null,
      buyer:norm(g(row,'Buyer')),line:norm(g(row,'Line')),
      _isMainFabric:main,
    };
    fabricFields.forEach(field=>{order[field]=main&&fabricHeaders[field]?norm(g(row,fabricHeaders[field])):'';});
    return order;
  };
  const seen = new Map();
  let mainRowCount=0,ignoredNonMainRows=0;
  for(let r=hIdx+1;r<rows.length;r++){
    const row = rows[r]; if(!row) continue;
    const oc = g(row,'Sipariş Kod'); if(oc==null||oc==='') continue;
    const order=toOrder(row);
    if(mainFabricHeader){if(order._isMainFabric)mainRowCount++;else ignoredNonMainRows++;}
    const key=JSON.stringify([norm(oc),order.model,order.ccode]);
    const current=seen.get(key);
    if(!current){seen.set(key,order);continue;}
    if(order._isMainFabric){
      fabricFields.forEach(field=>{if(order[field]||!current._isMainFabric)current[field]=order[field];});
      current._isMainFabric=true;
    }
  }
  const orders=[...seen.values()].map(order=>{const out={...order};delete out._isMainFabric;return out;});
  const warnings=[];
  if(!mainFabricHeader)warnings.push('ASAS sonucunda "Ana Kumaş Mı" alanı bulunamadı; kumaş bilgileri uygulanmadı.');
  return {header,orders,fabricHeaderInfo:{source:'ASAS',mainRowCount,ignoredNonMainRows,warnings}};
}

function parseAntrepoWorkbook(wb){
  const sheetName = wb.SheetNames.find(n=>/antrepo/i.test(n)) || wb.SheetNames[0];
  const rows = XLSX.utils.sheet_to_json(wb.Sheets[sheetName], {header:1, raw:true, defval:null});
  const hIdx = findAnchorRow(rows, ['Sipariş Kod','Renk Tanım'], 25);
  if(hIdx<0) return {};
  const header = rows[hIdx].map(h=>norm(h));
  const idx = {}; header.forEach((h,i)=>{ if(h) idx[h]=i; });
  const g = (row,name)=> idx[name]!=null ? row[idx[name]] : null;
  // HANDOVER Tarihi başlığını büyük/küçük harf, satır sonu ve boşluk farklarından
  // etkilenmeden bul; ör. "HANDOVER Tarihi" ve "HANDOVER DATE" desteklenir.
  const canonHeader = v=>turknorm(v).replace(/[^A-Z0-9]+/g,' ').replace(/\s+/g,' ').trim();
  const handoverHeader = header.find(h=>{
    const c=canonHeader(h);
    return c.includes('HANDOVER') && (c.includes('TARIH') || c.includes('DATE'));
  }) || null;
  const map = {};
  for(let r=hIdx+1;r<rows.length;r++){
    const row = rows[r]; if(!row) continue;
    const oc = idx['Sipariş Kod']!=null ? row[idx['Sipariş Kod']] : null;
    if(oc==null||oc==='') continue;
    const colour = idx['Renk Tanım']!=null ? norm(row[idx['Renk Tanım']]) : '';
    const key = `${Math.trunc(Number(oc))}|${turknorm(colour)}`;
    const statu = idx['Supplier Portal Statü']!=null ? norm(row[idx['Supplier Portal Statü']]) : '';
    const arr = idx['Tahmini Antrepo Giriş Tarihi']!=null ? parseDateFlexible(row[idx['Tahmini Antrepo Giriş Tarihi']]) : null;
    const handover = handoverHeader ? parseDateFlexible(g(row,handoverHeader)) : null;
    const vasita = idx['Vasita Tanim']!=null ? norm(row[idx['Vasita Tanim']]) : '';
    const ord = arr ? arr.getTime() : -1;
    const cur = map[key];
    if(!cur || ord>=cur._ord){
      map[key] = {statu, arr, vasita, handover:handover || (cur&&cur.handover) || null, _ord:ord};
    }else if(!cur.handover && handover){
      cur.handover = handover;
    }
  }
  return map;
}

function parseCPUpdateWorkbook(wb){
  const sheetName = wb.SheetNames[0];
  const rows = XLSX.utils.sheet_to_json(wb.Sheets[sheetName], {header:1, raw:true, defval:null});
  const hIdx = findAnchorRow(rows, ['Supplier','PO'], 10);
  if(hIdx<0) return {sub:0, fob:0};
  const header = rows[hIdx].map(h=>norm(h));
  const idx = {}; header.forEach((h,i)=>{ if(h) idx[h]=i; });
  let nsub=0, nfob=0;
  for(let r=hIdx+1;r<rows.length;r++){
    const row = rows[r]; if(!row) continue;
    const supplier = idx['Supplier']!=null ? norm(row[idx['Supplier']]) : '';
    const mfob = idx['Manufacturer FOB']!=null ? Number(row[idx['Manufacturer FOB']]) : null;
    [idx['PO'], idx['PO2']].forEach(ci=>{
      if(ci==null) return;
      const oc = row[ci]; if(oc==null||oc==='') return;
      const ocN = Math.trunc(Number(oc));
      if(supplier){ state.overrides.submap[ocN]=supplier; nsub++; }
      if(mfob!=null && !isNaN(mfob)){ state.overrides.suppfobmap[ocN]=roundHalfUp(mfob,2); nfob++; }
    });
  }
  return {sub:nsub, fob:nfob};
}

const RETAIL_WAITING_THRESHOLD_RATE = 0.05;
function deriveOperationalStatus(baseStatus, order){
  let status = baseStatus || '';
  const qty = Math.max(0, Number(order && order.qty) || 0);
  const readyQty = Math.max(0, Number(order && order.merkezSevkeHazirKalan) || 0);
  if(turknorm(status)==='DEPODA' && qty>0 && readyQty>qty*RETAIL_WAITING_THRESHOLD_RATE){
    status='Retaile Aktarım Bekleniyor';
  }
  return status;
}

function buildCPRowsFromASAS(){
  const orders = state.asasOrders;
  const ov = state.overrides;
  const filtered = orders.filter(o=> turknorm(o.buyerGrup)==='LISANS' && o.merch==='CU4E' && !EXCL_COUNTRIES_NORM.has(turknorm(o.countryRaw)) && o.kalan>0);
  const imageByIdentity=new Map(),resolvedImageKeys=new Set();
  filtered.forEach(order=>{
    const key=cpImageOverrideKey(order.plm,order.ccode);if(!key)return;
    const imageMap=ov.imagemap||{};
    if(Object.prototype.hasOwnProperty.call(imageMap,key)){imageByIdentity.set(key,norm(imageMap[key]));resolvedImageKeys.add(key);return;}
    const legacyPlmKey=cpLegacyPlmImageOverrideKey(order.plm);
    if(legacyPlmKey&&Object.prototype.hasOwnProperty.call(imageMap,legacyPlmKey)){imageByIdentity.set(key,norm(imageMap[legacyPlmKey]));resolvedImageKeys.add(key);return;}
    if(resolvedImageKeys.has(key)||imageByIdentity.get(key))return;
    const legacyRef=cpImageRefFromOverride(ov,order.plm,order.ccode,order.ocode,order.model,order.ccode,order.colour||order.color||'');
    if(legacyRef)imageByIdentity.set(key,legacyRef);
  });
  return filtered.map((o,i)=>{
    const derivedLicensor = kolResolveLicensorsForLicense(o.license).displayValue || '';
    const hasLicensorOverride = Object.prototype.hasOwnProperty.call(ov.licensormap||{},o.ocode);
    const licensor = o.license && hasLicensorOverride ? norm(ov.licensormap[o.ocode]) : derivedLicensor;
    const key = `${o.ocode}|${turknorm(o.colour)}`;
    const hit = state.antrepoMap[key];
    let status = deriveOperationalStatus(hit ? (hit.statu||'Üretimde') : 'Üretimde', o);
    let ant = hit ? hit.arr : null;
    const handover = hit ? (hit.handover||null) : null;
    let delType = hit ? (hit.vasita||'') : '';
    if(status==='Üretimde' && !delType) delType='Gemi';
    if(ov.delmap[o.ocode]) delType = ov.delmap[o.ocode];
    const sub = licensor==='DTR' ? norm(o.manufacturer) : norm(ov.submap[lineKeyOfOrder(o)] ?? ov.submap[o.ocode] ?? '');
    const hasSuppfobOverride = Object.prototype.hasOwnProperty.call(ov.suppfobmap, o.ocode);
    const suppfobOverride = ov.suppfobmap[o.ocode];
    const suppFobMeta=normalizeSuppFobMeta((ov.suppfobmetamap||{})[o.ocode]);
    const isRuleOverride=!!(hasSuppfobOverride&&suppFobMeta&&suppFobMeta.source==='rule');
    const fobRounded = isFinite(o.fob)?roundHalfUp(o.fob,2):null;
    const priced = calculateSuppFobFromRule(fobRounded,o.opd,countryEN(o.countryRaw),o.season,licensor,o.license);
    const suppfob = hasSuppfobOverride ? suppfobOverride : (priced.value!=null ? priced.value : (licensor==='DTR' ? fobRounded : null));
    const notesRec = ov.notesmap?.[lineKeyOfOrder(o)] || ov.notesmap?.[o.ocode] || {};
    const imageKey=cpImageOverrideKey(o.plm,o.ccode),imageRef=imageKey?(imageByIdentity.get(imageKey)||''):'';
    const row = {
      _id:i, _imageKey:imageKey, _imageRef:imageRef, _imageUrl:imageRef?`${CP_IMAGE_API}/${encodeURIComponent(imageRef)}`:'', Priority:'', Season:o.season, Country:countryEN(o.countryRaw), Manufacturer:o.manufacturer,
      'Sub-Manufacturer':sub, Licensor:licensor, License:o.license, Category:o.category, 'Special Code':o.ozel,
      'PLM ID': (o.plm!=null && !isNaN(Number(o.plm))) ? Math.trunc(Number(o.plm)) : '',
      'Model Name':o.model, 'Ürün Tanım':o.productDescription||'', 'C.Code':o.ccode, Colour:o.colour,
      'Kumaş Kategorisi':o.fabricCategory||'', 'Kumaşçı Ülkesi':o.fabricSupplierCountry||'', 'Kumaşçı':o.fabricSupplier||'',
      'Kumaş Tipi':o.kumasTipi||'', 'İplik No':o.iplikNo||'', 'Gramaj':o.fabricWeight||'', 'Karışım':o.karisim||'',
      'Order Code':o.ocode,
      'FOB ($)': fobRounded, 'Supp. FOB': suppfob!=null?suppfob:null,
      _suppFobManual:hasSuppfobOverride&&!isRuleOverride, _suppFobRule:isRuleOverride?(suppFobMeta.ruleId||true):((!hasSuppfobOverride&&priced.rule)?(priced.rule.id||true):null), _suppFobMeta:isRuleOverride?suppFobMeta:((!hasSuppfobOverride&&priced.rule)?automaticSuppFobRuleMeta(priced.rule,false):suppFobMeta), _suppFobOverride:hasSuppfobOverride, _licensorManual:hasLicensorOverride, _nonDtrManufacturerRule:false,
      OPD:o.opd, 'Ex-factory':o.ex, _asasExFactory:o.ex, 'HANDOVER Tarihi':handover, 'Retail Date':o.retail, 'Ex→Retail':'',
      'Buying Son Onay Tarihi':o.shipConf, 'In-Store (Model Budget)':o.mb,
      'Order Quantity':o.qty, 'Shipment Quantity':Math.max(0,toNum(hit&&((hit.loadedQty!=null)?hit.loadedQty:hit._loadedQty))||0), 'Remaining Units':o.kalan, '%': o.qty? (o.qty-o.kalan)/o.qty : '',
      STATUS:status, 'Ant. Arrival':ant, 'Del. Type':delType,
      Notes: notesRec.Notes||'', 'Ek Not': notesRec.EkNot||'',
      _notesAt: notesRec.NotesAt||'', _ekNotAt: notesRec.EkNotAt||'',
      // v7.29 — not yazarı (Overview yalnız kendi notlarını gösterir).
      _notesBy: notesRec.NotesBy||'', _notesByName: notesRec.NotesByName||'',
      _ekNotBy: notesRec.EkNotBy||'', _ekNotByName: notesRec.EkNotByName||''
    };
    applyFormulas(row);
    return row;
  });
}
function buildOrderSummaryRowsFromASAS(){
  const orders = state.asasOrders;
  const ov = state.overrides;
  const T = toDateOnly(new Date());
  const filtered = orders;
  const built = filtered.map(o=>{
    const derivedLicensor = kolResolveLicensorsForLicense(o.license).displayValue || '';
    const hasLicensorOverride = Object.prototype.hasOwnProperty.call(ov.licensormap||{},o.ocode);
    const licensor = o.license && hasLicensorOverride ? norm(ov.licensormap[o.ocode]) : derivedLicensor;
    const key = `${o.ocode}|${turknorm(o.colour)}`;
    const hit = state.antrepoMap[key];
    const isActive = o.kalan>0;
    let status = deriveOperationalStatus(hit ? (hit.statu||'') : (isActive?'Üretimde':''), o);
    let ant = hit ? hit.arr : null;
    let delType = hit ? (hit.vasita||'') : '';
    const sub = licensor==='DTR' ? norm(o.manufacturer) : norm(ov.submap[lineKeyOfOrder(o)] ?? ov.submap[o.ocode] ?? '');
    const fobRounded = isFinite(o.fob)?roundHalfUp(o.fob,2):null;
    const hasSuppfobOverride = Object.prototype.hasOwnProperty.call(ov.suppfobmap,o.ocode);
    const suppFobMeta=normalizeSuppFobMeta((ov.suppfobmetamap||{})[o.ocode]);
    const isRuleOverride=!!(hasSuppfobOverride&&suppFobMeta&&suppFobMeta.source==='rule');
    const priced = calculateSuppFobFromRule(fobRounded,o.opd,countryEN(o.countryRaw),o.season,licensor,o.license);
    const suppfob = hasSuppfobOverride ? ov.suppfobmap[o.ocode] : (priced.value!=null ? priced.value : (licensor==='DTR'?fobRounded:null));
    let risk;
    if(!isActive) risk='5-Closed';
    else if(o.mb && o.mb<T) risk='1-Missed in-store';
    else if(o.retail && o.retail<T) risk='2-Retail date passed';
    else if(o.ex && o.ex<T) risk='3-Overdue at factory';
    else risk='4-On track';
    const exRetail = (o.ex && o.retail) ? daysBetween(o.ex,o.retail) : '';
    const daysToGo = o.ex ? daysBetween(T,o.ex) : '';
    const delivPct = o.qty ? (o.antrepo/o.qty) : '';
    return {
      'Active/Inactive': isActive?'Active':'Inactive', 'Merch Alt Grup Kod':o.merch, 'Buyer Grup (TR)':o.buyerGrup,
      Season:o.season, Country:countryEN(o.countryRaw), Manufacturer:o.manufacturer, 'Sub-Manufacturer':sub,
      Licensor:licensor, License:o.license, Category:o.category, 'Model Name':o.model, 'Ürün Tanım':o.productDescription||'', 'C.Code':o.ccode, Colour:o.colour,
      'PLM ID': (o.plm!=null && !isNaN(Number(o.plm))) ? Math.trunc(Number(o.plm)) : '', 'Special Code':o.ozel,
      'Order Code':o.ocode, 'FOB ($)': fobRounded, 'Supp. FOB': suppfob!=null?suppfob:null,
      _suppFobManual:hasSuppfobOverride&&!isRuleOverride, _suppFobRule:isRuleOverride?(suppFobMeta.ruleId||true):((!hasSuppfobOverride&&priced.rule)?(priced.rule.id||true):null), _suppFobMeta:isRuleOverride?suppFobMeta:((!hasSuppfobOverride&&priced.rule)?automaticSuppFobRuleMeta(priced.rule,false):suppFobMeta), _suppFobOverride:hasSuppfobOverride, _licensorManual:hasLicensorOverride, _nonDtrManufacturerRule:false,
      OPD:o.opd, 'Ex-factory':o.ex, 'Retail Date':o.retail, 'Ex→Retail':exRetail, 'In-Store (Model Budget)':o.mb, 'Days to go':daysToGo,
      'Order Quantity':o.qty, Received:o.antrepo, Remaining:o.kalan, '%': o.qty? (o.qty-o.kalan)/o.qty : '', 'Deliv.%':delivPct,
      Risk:risk, STATUS:status, 'Ant. Arrival':ant, 'Del. Type':delType, _sevSort:isActive?0:1
    };
  });
  const sev={'1-Missed in-store':1,'2-Retail date passed':2,'3-Overdue at factory':3,'4-On track':4,'5-Closed':5};
  built.sort((a,b)=> (a._sevSort-b._sevSort) || (sev[a.Risk]-sev[b.Risk]) || 0);
  built.forEach((r,i)=>{ r._id=i; delete r._sevSort; });
  return built;
}

function syncOverridesFromRow(row){
  const oc=row['Order Code'];if(oc==null)return;
  const key=lineKeyOfRow(row)||oc;
  state.overrides.notesmap=state.overrides.notesmap||{};
  const notes={...(state.overrides.notesmap[key]||state.overrides.notesmap[oc]||{})};
  const nextNotes=row['Notes'] instanceof Date?toISODate(row['Notes']):norm(row['Notes']);
  const nextEkNot=row['Ek Not'] instanceof Date?toISODate(row['Ek Not']):norm(row['Ek Not']);
  const nowIso=new Date().toISOString();
  /* v7.29 — yazar damgası burada da yazılır ki Overview'deki kendi not listeniz
     sunucu yanıtını beklemeden güncellensin. ASIL kayıt sunucudadır: sunucu
     yazarı oturumdan belirler ve buradaki değeri kullanmaz (§32). */
  const author=noteAuthorIdentity();
  const stampAuthor=(atField,byField,byNameField,text)=>{
    notes[atField]=text?nowIso:'';
    if(!text){ delete notes[byField]; delete notes[byNameField]; return; }
    if(author.id||author.name){ notes[byField]=author.id||author.name; notes[byNameField]=author.name||author.id; }
  };
  if(String(notes.Notes==null?'':notes.Notes)!==String(nextNotes)){
    stampAuthor('NotesAt','NotesBy','NotesByName',nextNotes);
    row._notesAt=notes.NotesAt||'';
    row._notesBy=notes.NotesBy||''; row._notesByName=notes.NotesByName||'';
  }
  if(String(notes.EkNot==null?'':notes.EkNot)!==String(nextEkNot)){
    stampAuthor('EkNotAt','EkNotBy','EkNotByName',nextEkNot);
    row._ekNotAt=notes.EkNotAt||'';
    row._ekNotBy=notes.EkNotBy||''; row._ekNotByName=notes.EkNotByName||'';
  }
  notes.Notes=nextNotes;
  notes.EkNot=nextEkNot;
  state.overrides.notesmap[key]=notes;
  if(row['Del. Type'])state.overrides.delmap[key]=row['Del. Type'];
  const isDtr=turknorm(row.Licensor)==='DTR';
  if(isDtr){
    row['Sub-Manufacturer']=norm(row.Manufacturer);
    if(state.overrides.submap)delete state.overrides.submap[key];
  }else{
    state.overrides.submap=state.overrides.submap||{};
    state.overrides.submap[key]=norm(row['Sub-Manufacturer']);
  }
  if(row._licensorManual===true)state.overrides.licensormap[key]=norm(row.Licensor);
  if(row._suppFobManual===true){
    state.overrides.suppfobmap[key]=(row['Supp. FOB']==null||row['Supp. FOB']==='')?null:Number(row['Supp. FOB']);
    state.overrides.suppfobmetamap=state.overrides.suppfobmetamap||{};
    state.overrides.suppfobmetamap[key]={source:'manual'};
  }
  // v10.9 — kullanıcı tanımlı boş not sütunları: değer satırdan (kart hücresi
  // değil, genel CP metin hücresi) okunur, notesmap ile aynı anahtarla tutulur.
  if(CP_NOTE_COLUMN_DEFS.length){
    state.overrides.noteColumnValues=state.overrides.noteColumnValues||{};
    const bucket={};
    CP_NOTE_COLUMN_DEFS.forEach(def=>{ bucket[def.id]=row[def.id] instanceof Date?toISODate(row[def.id]):norm(row[def.id]); });
    state.overrides.noteColumnValues[key]=bucket;
  }
  syncOverrideToServer(oc,notes,row);
}
// Kullanıcı düzenlemesini sunucudaki kalıcı depoya gönderir (best-effort, sessiz başarısız olur —
// sunucu çalışmıyorsa/dosya elle yüklendiyse uygulama yine de tarayıcıda çalışmaya devam eder).
// Elle revize edilen tarihler kalıcı depoya yazılır (overrides.datemap). Orijinaline
// eşit olan alan için null gönderilir; sunucu o revizyonu kaydından siler. Böylece
// model yenilemesi revizyonu ezmez, revizyondan vazgeçmek de tek adımdır.
/* -------------------------------------------------------------------
   v6.34 — BEKLEYEN YAZMA KAYDI (veri kaybı önlemi)
   Gecikmeli yazma zamanlayıcıları eskiden YALNIZ sipariş koduyla
   anahtarlanıyordu (_dateSyncTimers[orderCode] / _syncTimers[orderCode]).
   Oysa v4.19'dan beri kalıcı yazma anahtarı ÜÇLÜ: Sipariş Kod + Model Adı +
   Renk Kod. Aynı sipariş kodunun iki FARKLI satırında arka arkaya düzenleme
   yapıldığında ikinci çağrının clearTimeout'u birinci satırın bekleyen
   yazmasını iptal ediyordu; o düzenleme sunucuya hiç gitmiyor, ekranda
   görünüp ilk yenilemede kayboluyordu. Anahtar artık satır bazlı.
   Ayrıca bekleyen yazmalar tek bir kayıtta toplanır ki sayfa kapanırken ve
   yenilemeden önce boşaltılabilsin.
   ------------------------------------------------------------------- */
const _pendingOverrideWrites = new Map();
function overrideSyncKey(row, orderCode){
  return lineKeyOfRow(row) || String(orderCode==null ? '' : orderCode);
}
function schedulePendingOverrideWrite(key, delay, run){
  const existing = _pendingOverrideWrites.get(key);
  if(existing) clearTimeout(existing.timer);
  const entry = {run};
  entry.timer = setTimeout(()=>{ _pendingOverrideWrites.delete(key); try{run();}catch(err){console.warn('Bekleyen yazma çalıştırılamadı:',err&&err.message);} }, delay);
  _pendingOverrideWrites.set(key, entry);
}
function pendingOverrideWriteCount(){ return _pendingOverrideWrites.size; }
// Bekleyen bütün yazmaları hemen çalıştırır. Sayfa kapanışında ve yenilemeden
// önce çağrılır; kuyruğa girmiş isteklerin bitmesi ayrıca beklenir.
function flushPendingOverrideWrites(){
  const entries = [..._pendingOverrideWrites.values()];
  _pendingOverrideWrites.clear();
  entries.forEach(entry=>{
    clearTimeout(entry.timer);
    try{ entry.run(); }catch(err){ console.warn('Bekleyen yazma boşaltılamadı:',err&&err.message); }
  });
  return entries.length;
}
// Hem bekleyen gecikmeli yazmaları boşaltır hem de override kuyruğunun
// tamamlanmasını bekler. Yenileme bu söz verilmeden başlamamalı.
async function settleOverrideWrites(){
  flushPendingOverrideWrites();
  try{ await overrideMutationsSettled(); }catch(_){ }
}
function saveDateOverrides(row){
  if(!window.SERVER_BACKED || !row) return;
  const orderCode = row['Order Code'];
  if(orderCode==null) return;
  const revised = new Set(BLRevision.revisedDateKeys(row));
  const payloadKeys = {'Ex-factory':'exFactory','Retail Date':'retailDate','In-Store (Model Budget)':'inStoreDate'};
  const dates = {};
  for(const [key,field] of Object.entries(payloadKeys)){
    dates[field] = revised.has(key) ? (toISODate(row[key])||null) : null;
  }
  schedulePendingOverrideWrite(`date:${overrideSyncKey(row, orderCode)}`, 400, ()=>{
    enqueueOverrideMutation('orders',`/api/overrides/${orderCode}`, {
      method:'PATCH', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({...lineIdentity(row), dates}),
    }).catch(err=>{
      console.warn('Tarih revizyonu kaydedilemedi:',err.message);
      if(err.code!=='REVISION_CONFLICT') notifyOverrideSaveError(appLang==='en'?'The date revision could not be saved to the server.':'Tarih revizyonu sunucuya kaydedilemedi.');
    });
  });
}

function syncOverrideToServer(orderCode,notes,row){
  if(!window.SERVER_BACKED)return;
  schedulePendingOverrideWrite(`notes:${overrideSyncKey(row, orderCode)}`, 500, ()=>{
    enqueueOverrideMutation('orders',`/api/overrides/${orderCode}`,{
      method:'PATCH',headers:{'Content-Type':'application/json'},
      body:JSON.stringify((()=>{
        const body={...lineIdentity(row),notes,delType:row['Del. Type']||undefined};
        /* Copilot önerisinden gelen yazma işaretlenir. Bayrak TEK KULLANIMLIK:
           debounce penceresinden sonra elle yapılan bir düzenleme yanlışlıkla
           "Copilot" etiketi almamalı. */
        if(row._copilotOrigin){ body.origin=row._copilotOrigin; delete row._copilotOrigin; }
        if(turknorm(row.Licensor)!=='DTR')body.subManufacturer=norm(row['Sub-Manufacturer']);
        if(row._licensorManual===true)body.licensor=norm(row.Licensor);
        if(row._suppFobManual===true){
          body.suppFob=(row['Supp. FOB']!=null&&row['Supp. FOB']!=='')?Number(row['Supp. FOB']):null;
          body.suppFobMeta={source:'manual'};
        }
        if(CP_NOTE_COLUMN_DEFS.length){
          const noteBucket=state.overrides.noteColumnValues&&state.overrides.noteColumnValues[overrideSyncKey(row,orderCode)];
          if(noteBucket)body.noteColumns=noteBucket;
        }
        return body;
      })())
    }).catch(err=>{console.warn('Sunucuya kaydedilemedi:',err.message);if(err.code!=='REVISION_CONFLICT')notifyOverrideSaveError(appLang==='en'?'The change could not be saved to the server.':'Değişiklik sunucuya kaydedilemedi.');});
  });
}

let appWarnings = [];
let appWarningDetails = new Map();
function warningDetailKey(value){return String(value||'').replace(/\s+/g,' ').trim();}
function setWarnings(list,details){
  appWarnings = [...new Set((list||[]).filter(Boolean).map(value=>String(value)))];
  appWarningDetails = new Map();
  (Array.isArray(details)?details:[]).forEach(detail=>{
    if(!detail||!detail.message)return;
    const key=warningDetailKey(detail.message);
    if(!key||appWarningDetails.has(key))return;
    appWarningDetails.set(key,detail);
  });
  refreshWarnChips();
}
function refreshWarnChips(){
  ['serverStatus','sourceStatusInline','sourceHint'].forEach(id=>{
    const el = document.getElementById(id); if(!el) return;
    el.querySelectorAll('.warnChip').forEach(x=>x.remove());
    if(appWarnings.length){
      const warningCountText=appLang==='en'?`⚠ ${appWarnings.length} warnings`:`⚠ ${appWarnings.length} uyarı`;
      const warningDetailsTitle=appLang==='en'?'Show warning details':'Uyarı detaylarını göster';
      const b = document.createElement('button');
      b.type='button'; b.className='warnChip';
      b.textContent = warningCountText;
      b.title = warningDetailsTitle;
      b.addEventListener('click', e=>{ e.stopPropagation(); showWarnDetails(); });
      el.appendChild(document.createTextNode(' '));
      el.appendChild(b);
    }
  });
}
function warningDetailValue(value){
  if(value==null||value==='')return '—';
  if(value instanceof Date&&!isNaN(value))return value.toLocaleDateString(appLang==='en'?'en-GB':'tr-TR');
  return String(value);
}
function showWarningDetailTable(detail){
  if(window.BLDetailDrawer?.open){
    const sharedRows=Array.isArray(detail&&detail.rows)?detail.rows:[];
    const sharedColumns=Array.isArray(detail&&detail.columns)&&detail.columns.length?detail.columns.map(col=>({key:col.key,label:col.label||col.key,value:row=>warningDetailValue(row&&row[col.key])})):[...new Set(sharedRows.flatMap(row=>Object.keys(row||{})))].map(key=>({key,label:key,value:row=>warningDetailValue(row&&row[key])}));
    const sharedTotal=Number(detail&&detail.totalRows)||sharedRows.length,sharedTrunc=detail&&detail.truncated&&sharedTotal>sharedRows.length;
    window.BLDetailDrawer.open({storageKey:'warning.detail',source:'warning-detail',title:detail&&detail.title||(appLang==='en'?'Warning Details':'Uyarı Detayları'),subtitle:[detail&&detail.source,String(sharedTotal)+' '+(appLang==='en'?'rows':'satır')].filter(Boolean).join(' · '),note:[detail&&detail.message,sharedTrunc?(appLang==='en'?'First '+sharedRows.length+' rows are shown.':'İlk '+sharedRows.length+' satır gösteriliyor.'):''].filter(Boolean).join(' · '),rows:sharedRows,columns:sharedColumns,images:true,fileName:'Warning_Detail'});
    return;
  }
  if(!detail)return;
  document.getElementById('warningDetailOverlay')?.remove();
  const rows=Array.isArray(detail.rows)?detail.rows:[];
  const columns=Array.isArray(detail.columns)&&detail.columns.length
    ? detail.columns
    : [...new Set(rows.flatMap(row=>Object.keys(row||{})))].map(key=>({key,label:key}));
  const ov=document.createElement('div');
  ov.id='warningDetailOverlay';ov.className='warnOverlay warningDetailOverlay';
  const total=Number(detail.totalRows)||rows.length;
  const trunc=detail.truncated&&total>rows.length;
  ov.innerHTML=`<section class="modalCard warningDetailCard" role="dialog" aria-modal="true">
    <header class="warningDetailHead">
      <div><h2>${escapeHtml(detail.title||(appLang==='en'?'Warning Details':'Uyarı Detayları'))}</h2>
      <p>${escapeHtml(detail.source||'')} · ${total.toLocaleString(appLang==='en'?'en-GB':'tr-TR')} ${appLang==='en'?'rows':'satır'}${trunc?` · ${escapeHtml(appLang==='en'?`first ${rows.length} shown`:`ilk ${rows.length} satır gösteriliyor`)}`:''}</p></div>
      <button type="button" class="warnClose warningDetailClose" aria-label="${escapeHtml(appLang==='en'?'Close':'Kapat')}"><svg class="ic"><use href="#i-x"/></svg></button>
    </header>
    <div class="warningDetailMessage">${escapeHtml(detail.message||'')}</div>
    <div class="warningDetailTableWrap"><table class="warningDetailTable"><thead><tr>${columns.map(col=>`<th>${escapeHtml(col.label||col.key)}</th>`).join('')}</tr></thead>
    <tbody>${rows.length?rows.map(row=>`<tr>${columns.map(col=>`<td>${escapeHtml(warningDetailValue(row&&row[col.key]))}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${Math.max(1,columns.length)}" class="empty">${escapeHtml(appLang==='en'?'No detailed rows are available.':'Detay satırı bulunamadı.')}</td></tr>`}</tbody></table></div>
  </section>`;
  ov.addEventListener('click',e=>{if(e.target===ov||e.target.closest('.warningDetailClose'))ov.remove();});
  document.body.appendChild(ov);
}
function showWarnDetails(){
  document.getElementById('warnOverlay')?.remove();
  const ov = document.createElement('div');
  ov.id='warnOverlay'; ov.className='warnOverlay';
  ov.innerHTML = `<div class="modalCard warningListCard">
    <div class="modalTitle warningListTitle">${escapeHtml(appLang==='en'?`Warnings (${appWarnings.length})`:`Uyarılar (${appWarnings.length})`)}
      <button type="button" class="warnClose" aria-label="${escapeHtml(appLang==='en'?'Close':'Kapat')}"><svg class="ic"><use href="#i-x"/></svg></button></div>
    <ol class="warningList">
      ${appWarnings.map((w,index)=>{
        const hasDetail=appWarningDetails.has(warningDetailKey(w));
        return `<li data-warning-index="${index}" class="${hasDetail?'hasDetail':''}"${hasDetail?` title="${escapeHtml(appLang==='en'?'Double-click to view the related rows':'İlgili satırları görmek için çift tıkla')}"`:''}><span>${escapeHtml(w)}</span>${hasDetail?`<small>${escapeHtml(appLang==='en'?'Double-click for details':'Detay için çift tıkla')}</small>`:''}</li>`;
      }).join('')}
    </ol>
  </div>`;
  ov.addEventListener('click', e=>{ if(e.target===ov || e.target.closest('.warnClose')) ov.remove(); });
  ov.addEventListener('dblclick',e=>{
    const item=e.target.closest('.warningList li.hasDetail');if(!item)return;
    const message=appWarnings[Number(item.dataset.warningIndex)];
    const detail=appWarningDetails.get(warningDetailKey(message));
    if(detail){e.preventDefault();e.stopPropagation();showWarningDetailTable(detail);}
  });
  document.body.appendChild(ov);
}
function updSourceHint(msg){ const hint=document.getElementById('sourceHint'); if(hint)hint.textContent=msg; const inline=document.getElementById('sourceStatusInline'); if(inline)inline.textContent=msg; refreshWarnChips(); }
