// ================= dynamic table height (fills available viewport, keeps sticky headers reliable) =================
function fitTableHeights(){
  document.querySelectorAll('.tablewrap').forEach(tw=>{
    const rect = tw.getBoundingClientRect();
    if(rect.top<=0 && rect.height===0) return; // hidden (inactive tab), skip
    const h = window.innerHeight - rect.top - 14;
    // rect.top/window.innerHeight are already post-zoom screen pixels, but maxHeight is a
    // layout value inside the zoomed element's own coordinate space — without dividing by
    // the table's zoom factor here, a zoomed-out (z<1) table renders shorter than intended
    // and leaves a gap below it instead of reaching the bottom of the window.
    const z = (typeof tableZoom!=='undefined' && tableZoom[tw.id]) || 1;
    const fit = Math.max(220, h/z) + 'px';
    // minHeight de aynı değere kurulur: satır sayısı az olduğunda tablo içeriği
    // kadar kısalıp altında ölü boşluk bırakmasın, her zaman pencerenin altına ulaşsın.
    tw.style.maxHeight = fit;
    tw.style.minHeight = fit;
  });
}
window.addEventListener('resize', fitTableHeights);
window.addEventListener('load', fitTableHeights);
/* v7.81 — Kaynak Veri şeridi kaldırıldı. Bu gözlemci şeridin açılıp
   kapanmasına göre tablo yüksekliklerini yeniden hesaplıyordu; şerit yokken
   izleyecek bir şey de yok. observe(null) TypeError fırlatır ve app-main.js'in
   geri kalanını durdururdu. */
setTimeout(fitTableHeights, 50);

// ================= touchpad/ctrl+wheel: zoom scoped to the table under the cursor, not the whole page =================
const tableZoom = {};
document.querySelectorAll('.tablewrap').forEach(tw=>{
  tableZoom[tw.id || (tw.id = 'tw_'+Math.random().toString(36).slice(2))] = 1;
  tw.addEventListener('wheel', e=>{
    if(!e.ctrlKey) return;
    e.preventDefault();
    const id = tw.id;
    let z = tableZoom[id] - e.deltaY*0.0012;
    z = Math.min(1.6, Math.max(0.55, z));
    tableZoom[id] = z;
    tw.style.zoom = z;
    fitTableHeights();
  }, {passive:false});
  tw.addEventListener('dblclick', e=>{
    if(!e.ctrlKey && !e.altKey) return;
    tableZoom[tw.id] = 1; tw.style.zoom = 1; fitTableHeights();
  });
});
