function sourceRefreshDateParts(iso){
  const d=new Date(iso); if(isNaN(d)) return {date:String(iso||''),time:''};
  const locale=appLang==='en'?'en-GB':'tr-TR';
  return {
    date:d.toLocaleDateString(locale,{day:'2-digit',month:'2-digit',year:'numeric'}),
    time:d.toLocaleTimeString(locale,{hour:'2-digit',minute:'2-digit',second:'2-digit'}),
  };
}
function sourceRefreshFiltered(){
  const q=norm(_sourceRefreshHistoryState.query).toLocaleLowerCase('tr-TR');
  if(!q) return _sourceRefreshHistoryState.items;
  return _sourceRefreshHistoryState.items.filter(rec=>{
    const hay=[rec.createdAt,rec.sources?.current?.asas,rec.sources?.current?.antrepo,
      ...(rec.details||[]).flatMap(d=>[d.source,d.ocode,d.colourCode,d.colour,d.modelName,d.importFile,d.containerNo,d.manufacturer,d.changeType,d.field,d.before,d.after,d.detail])]
      .join(' ').toLocaleLowerCase('tr-TR');
    return hay.includes(q);
  });
}
function sourceRefreshSummaryRows(rec){
  const en=appLang==='en', s=rec.summary||{};
  return [
    [en?'Total orders':'Toplam sipariş',`${Number(s.oldOrderCount||0).toLocaleString(appLang==='en'?'en-GB':'tr-TR')} → ${Number(s.newOrderCount||0).toLocaleString(appLang==='en'?'en-GB':'tr-TR')}`],
    [en?'New orders':'Yeni görünen',Number(s.newlyAppeared||0).toLocaleString(appLang==='en'?'en-GB':'tr-TR')],
    [en?'Removed orders':'Artık görünmeyen',Number(s.disappeared||0).toLocaleString(appLang==='en'?'en-GB':'tr-TR')],
    [en?'Status changes':'Durum değişiklikleri',Number(s.statusChanged||0).toLocaleString(appLang==='en'?'en-GB':'tr-TR')],
    [en?'Quantity changes':'Kalan adet değişiklikleri',Number(s.qtyChangedOrders||0).toLocaleString(appLang==='en'?'en-GB':'tr-TR')],
    [en?'ASAS details':'ASAS detayları',Number(s.asasChangeCount||0).toLocaleString(appLang==='en'?'en-GB':'tr-TR')],
    [en?'Bonded warehouse details':'Antrepo detayları',Number(s.antrepoChangeCount||0).toLocaleString(appLang==='en'?'en-GB':'tr-TR')],
  ];
}
function sourceRefreshScopeNote(rec){
  const en=appLang==='en', scopes=Array.isArray(rec&&rec.scope&&rec.scope.sourceScopes)?rec.scope.sourceScopes:[];
  const labels=scopes.map(item=>{const target=String(item&&item.target||'').toUpperCase(),scope=String(item&&item.scope||'').trim();return [target,scope].filter(Boolean).join(': ');}).filter(Boolean);
  const base=en?'Current on-screen CP table filters do not affect this record. The history compares the source data returned by the configured connection scope.':'Ekrandaki mevcut CP tablo filtreleri bu kaydı etkilemez. Geçmiş, tanımlı bağlantı kapsamının döndürdüğü kaynak veriyi karşılaştırır.';
  return labels.length?`${base} ${en?'Source scope':'Kaynak kapsamı'}: ${labels.join(' · ')}`:base;
}
function renderSourceRefreshHistoryNav(){
  const host=document.getElementById('sourceRefreshHistNav'); if(!host)return;
  const t=sourceRefreshHistoryText(), list=sourceRefreshFiltered(), all=_sourceRefreshHistoryState.items;
  if(!list.length){host.innerHTML=`<div class="verHistEmpty">${escapeHtml(all.length?t.empty:t.none)}</div>`;return;}
  if(!list.some(r=>r.id===_sourceRefreshHistoryState.selectedId)) _sourceRefreshHistoryState.selectedId=list[0].id;
  // Kayit, listede acilmadan silinebilsin: her satirin sag ust kosesinde cop kutusu.
  // Ic ice <button> gecersiz HTML uretecegi icin secim dugmesi ile silme dugmesi
  // konumlandirilmis bir sarmalayicinin KARDES ogeleri olarak duruyor.
  host.innerHTML=list.map((rec,idx)=>{
    const dt=sourceRefreshDateParts(rec.createdAt), s=rec.summary||{}, active=rec.id===_sourceRefreshHistoryState.selectedId;
    const total=Number(s.totalChanges||rec.detailsTotal||(rec.details||[]).length||0);
    const removeLabel=`${t.remove} — ${dt.date} ${dt.time}`;
    return `<div class="verHistNavRow${active?' isActive':''}">
      <button type="button" class="verHistNavItem${active?' isActive':''}" data-refresh-id="${escapeHtml(rec.id)}">
        <span class="verHistNavTop"><span class="verHistNavVer">${escapeHtml(dt.date)}</span>${rec.id===(all[0]&&all[0].id)?`<span class="verHistNow">${escapeHtml(t.latest)}</span>`:''}</span>
        <span class="verHistNavTitle">${total.toLocaleString(appLang==='en'?'en-GB':'tr-TR')} ${appLang==='en'?'changes':'değişiklik'} · ASAS ${Number(s.asasChangeCount||0)} · ${appLang==='en'?'Warehouse':'Antrepo'} ${Number(s.antrepoChangeCount||0)}</span>
        <span class="verHistNavDate">${escapeHtml(dt.time)}</span>
      </button>
      <button type="button" class="verHistNavDelete" data-refresh-delete="${escapeHtml(rec.id)}" title="${escapeHtml(removeLabel)}" aria-label="${escapeHtml(removeLabel)}"><svg class="ic"><use href="#i-trash"/></svg></button>
    </div>`;
  }).join('');
  const cnt=document.getElementById('sourceRefreshHistCount'); if(cnt)cnt.textContent=t.count(list.length);
  const clearBtn=document.getElementById('sourceRefreshHistClearAll');
  if(clearBtn)clearBtn.disabled=!all.length||_sourceRefreshHistoryState.deleting;
}
function sourceRefreshDetailTable(rec){
  const en=appLang==='en';
  const rows=(rec.details||[]).map(d=>`<tr>
    <td><span class="sourceRefreshChip ${d.source==='ASAS'?'isAsas':'isAntrepo'}">${escapeHtml(d.source||'')}</span></td>
    <td class="sourceRefreshMono">${escapeHtml(String(d.ocode||''))}</td><td>${escapeHtml(d.colourCode||'')}</td><td>${escapeHtml(d.colour||'')}</td>
    <td>${escapeHtml(d.modelName||'')}</td><td>${escapeHtml(d.importFile||'')}</td><td>${escapeHtml(d.containerNo||'')}</td>
    <td>${escapeHtml(d.subMfr||'')}</td><td>${escapeHtml(d.specialCode||'')}</td>
    <td>${escapeHtml(d.mag||'')}</td><td>${escapeHtml(d.mmyg||'')}</td><td>${escapeHtml(d.buyer||'')}</td>
    <td>${escapeHtml(d.buyingGroup||'')}</td><td>${escapeHtml(d.season||'')}</td><td>${escapeHtml(d.manufacturer||'')}</td>
    <td>${escapeHtml(d.changeType||'')}</td><td>${escapeHtml(d.field||'')}</td><td class="sourceRefreshValue">${escapeHtml(d.before||'')}</td><td class="sourceRefreshValue">${escapeHtml(d.after||'')}</td><td>${escapeHtml(d.detail||'')}</td>
  </tr>`).join('');
  if(!rows)return `<div class="verHistEmpty">${escapeHtml(en?'No detail rows.':'Detay satırı yok.')}</div>`;
  const shown=(rec.details||[]).length,total=Number(rec.detailsTotal)||shown;
  const clipped=total>shown?`<div class="verHistEmpty">${escapeHtml(en
    ?`Showing the first ${shown.toLocaleString('en-GB')} of ${total.toLocaleString('en-GB')} rows. Older detail is not kept, to keep the history file small.`
    :`${total.toLocaleString('tr-TR')} satırın ilk ${shown.toLocaleString('tr-TR')} tanesi gösteriliyor. Geçmiş dosyası küçük kalsın diye gerisi saklanmıyor.`)}</div>`:'';
  const heads=en?['Source','Order','Colour Code','Colour','Model','Import File','Container','Sub-Mfr','Special Code','MAG','MMYG','Buyer','Buying Group','Season','Manufacturer','Change','Field','Previous','New','Detail']:
    ['Kaynak','Sipariş','Renk Kodu','Renk','Model','İthalat Dosyası','Konteyner','Sub-Mfr','Special Code','MAG','MMYG','Buyer','Buying Group','Season','Üretici','Değişiklik','Alan','Önceki','Yeni','Detay'];
  return `<div class="sourceRefreshTableWrap"><table class="sourceRefreshTable"><thead><tr>${heads.map(h=>`<th>${escapeHtml(h)}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>${clipped}`;
}
function renderSourceRefreshHistoryDetail(){
  const host=document.getElementById('sourceRefreshHistDetail'); if(!host)return;
  const t=sourceRefreshHistoryText(), all=_sourceRefreshHistoryState.items;
  const rec=all.find(r=>r.id===_sourceRefreshHistoryState.selectedId);
  if(!rec){host.innerHTML=`<div class="verHistEmpty">${escapeHtml(t.none)}</div>`;return;}
  const dt=sourceRefreshDateParts(rec.createdAt), s=rec.summary||{}, cur=rec.sources?.current||{};
  host.innerHTML=`<div class="verHistDetailHead">
      <span class="verHistTag isCurrent">${escapeHtml(dt.date)} ${escapeHtml(dt.time)}</span>
      <span class="verHistDate">${escapeHtml(cur.asas||'ASAS')}${cur.antrepo?` · ${escapeHtml(cur.antrepo)}`:''}</span>
    </div>
    <h3 class="verHistDetailTitle">${Number(s.totalChanges||rec.detailsTotal||(rec.details||[]).length||0).toLocaleString(appLang==='en'?'en-GB':'tr-TR')} ${appLang==='en'?'source-data changes':'kaynak veri değişikliği'}</h3>
    <p class="sourceRefreshScopeNote">${escapeHtml(sourceRefreshScopeNote(rec))}</p>
    <div class="sourceRefreshSummaryGrid">${sourceRefreshSummaryRows(rec).map(([k,v])=>`<div class="sourceRefreshStat"><span>${escapeHtml(k)}</span><strong>${escapeHtml(v)}</strong></div>`).join('')}</div>
    <div class="sourceRefreshDetailHead"><span class="verHistNotesLabel">${escapeHtml(t.details)}</span><div class="sourceRefreshDetailActions"><button type="button" class="tbtn" id="sourceRefreshHistDownload"><svg class="ic"><use href="#i-file-export"/></svg>${escapeHtml(t.download)}</button><button type="button" class="tbtn sourceRefreshDeleteBtn" id="sourceRefreshHistDelete" title="${escapeHtml(t.remove)}" aria-label="${escapeHtml(t.remove)}"><svg class="ic"><use href="#i-trash"/></svg>${escapeHtml(t.remove)}</button></div></div>
    ${sourceRefreshDetailTable(rec)}`;
  host.querySelector('#sourceRefreshHistDownload')?.addEventListener('click',()=>downloadSourceRefreshRecord(rec));
  const deleteBtn=host.querySelector('#sourceRefreshHistDelete');
  if(deleteBtn)deleteBtn.addEventListener('click',()=>deleteSourceRefreshRecord(rec));
}
function renderSourceRefreshHistoryModal(items,selectedId,revision=0){
  const t=sourceRefreshHistoryText();
  _sourceRefreshHistoryState.items=Array.isArray(items)?items:[];
  _sourceRefreshHistoryState.selectedId=selectedId||(_sourceRefreshHistoryState.items[0]&&_sourceRefreshHistoryState.items[0].id)||null;
  _sourceRefreshHistoryState.query='';
  _sourceRefreshHistoryState.revision=Number(revision)||0;
  if(state&&state.storeRevisions)state.storeRevisions.refreshHistory=_sourceRefreshHistoryState.revision;
  _sourceRefreshHistoryState.deleting=false;
  document.getElementById('_refreshSummaryModal')?.remove();
  const modal=document.createElement('div'); modal.id='_refreshSummaryModal'; modal.className='warnOverlay';
  modal.innerHTML=`<div class="modalCard verHistCard sourceRefreshHistCard" role="dialog" aria-modal="true" aria-labelledby="sourceRefreshHistTitle">
    <div class="verHistTop"><div><h2 id="sourceRefreshHistTitle">${escapeHtml(t.title)}</h2><p class="verHistSub">${escapeHtml(t.sub)}</p></div>
      <button type="button" class="verHistClose" title="${escapeHtml(t.close)}" aria-label="${escapeHtml(t.close)}"><svg class="ic"><use href="#i-x"/></svg></button></div>
    <div class="verHistTools"><input type="search" id="sourceRefreshHistSearch" placeholder="${escapeHtml(t.search)}" autocomplete="off"><span class="verHistCount" id="sourceRefreshHistCount"></span><button type="button" class="tbtn sourceRefreshDeleteBtn" id="sourceRefreshHistClearAll"><svg class="ic"><use href="#i-trash"/></svg>${escapeHtml(t.clearAll)}</button></div>
    <div class="verHistBody"><div class="verHistNav" id="sourceRefreshHistNav"></div><div class="verHistDetail" id="sourceRefreshHistDetail"></div></div>
    <div class="verHistFoot"><label class="refreshAutoOpenToggle"><input type="checkbox" id="sourceRefreshHistAutoOpen"${refreshHistoryAutoOpen()?' checked':''}><span>${escapeHtml(t.autoOpen)}</span></label><span style="flex:1"></span><button type="button" class="tbtn" id="sourceRefreshHistCloseBtn">${escapeHtml(t.close)}</button></div>
  </div>`;
  document.body.appendChild(modal);
  modal.__refreshCanonicalRecipients=()=>{prepareEmailFillFromShared();if(typeof refreshAll==='function')refreshAll();};
  modal.addEventListener('click',event=>{const manage=event.target.closest('[data-manage-email-groups]');if(manage){event.preventDefault();window.BLEmailGroups?.open?.();}});
  renderSourceRefreshHistoryNav(); renderSourceRefreshHistoryDetail();
  const close=()=>{modal.remove();document.removeEventListener('keydown',onKey);};
  const onKey=e=>{if(e.key==='Escape')close();}; document.addEventListener('keydown',onKey);
  modal.addEventListener('click',e=>{if(e.target===modal)close();});
  modal.querySelector('.verHistClose').addEventListener('click',close);
  modal.querySelector('#sourceRefreshHistCloseBtn').addEventListener('click',close);
  modal.querySelector('#sourceRefreshHistAutoOpen')?.addEventListener('change',e=>setRefreshHistoryAutoOpen(e.currentTarget.checked));
  const search=modal.querySelector('#sourceRefreshHistSearch');
  search.addEventListener('input',()=>{_sourceRefreshHistoryState.query=search.value;renderSourceRefreshHistoryNav();renderSourceRefreshHistoryDetail();});
  modal.querySelector('#sourceRefreshHistClearAll')?.addEventListener('click',clearAllSourceRefreshHistory);
  modal.querySelector('#sourceRefreshHistNav').addEventListener('click',e=>{
    const del=e.target.closest('[data-refresh-delete]');
    if(del){
      const rec=_sourceRefreshHistoryState.items.find(r=>r.id===del.dataset.refreshDelete);
      if(rec)deleteSourceRefreshRecord(rec);
      return;
    }
    const btn=e.target.closest('[data-refresh-id]');if(!btn)return;
    _sourceRefreshHistoryState.selectedId=btn.dataset.refreshId;renderSourceRefreshHistoryNav();renderSourceRefreshHistoryDetail();
    modal.querySelector('#sourceRefreshHistDetail')?.scrollTo({top:0});
  });
  setTimeout(()=>search.focus(),0);
}
/* Yenileme bitince değişiklik notlarını otomatik aç (v5.84).
   Önceden sonuç yalnız Genel Bakış ekranındaki karta yazılıyordu; kullanıcı o
   ekranda değilse yeniliğin ne olduğunu görmüyordu. Artık DEĞİŞİKLİK VARSA
   geçmiş penceresi kendiliğinden açılır. Değişiklik yoksa açılmaz — okunacak
   bir not olmadığı hâlde pencere açmak yalnız rahatsız ederdi.
   Pencerenin altındaki kutucukla kapatılabilir; tercih kullanıcıda saklanır. */
const REFRESH_AUTO_OPEN_KEY='bl.refreshHistory.autoOpen.v1';
function refreshHistoryAutoOpen(){
  try{ return BLStorage.getItem(REFRESH_AUTO_OPEN_KEY)!=='0'; }catch(_){ return true; }
}
function setRefreshHistoryAutoOpen(on){
  try{ BLStorage.setItem(REFRESH_AUTO_OPEN_KEY,on?'1':'0'); }catch(_){}
}
// Yenileme bittiğinde çağrılır. Açma kararı burada tek yerde verilir.
async function autoOpenRefreshHistory(result){
  if(!result||!result.hasChanges||!result.historyItemId)return false;
  if(!refreshHistoryAutoOpen())return false;
  // Kullanıcı o sırada bir pencereyle uğraşıyorsa araya girme; kart zaten
  // Genel Bakış'ta duruyor ve oradan açılabiliyor.
  if(typeof blOverlayOpen==='function'&&blOverlayOpen())return false;
  await openSourceRefreshHistory(result.historyItemId);
  return true;
}
async function openSourceRefreshHistory(selectedId){
  try{
    const res=await fetch('/api/refresh-history',{cache:'no-store'});
    if(!res.ok){const e=await res.json().catch(()=>({error:res.statusText}));throw new Error(e.error||res.statusText);}
    const data=await res.json(); renderSourceRefreshHistoryModal(data.items||[],selectedId,data._revision);
  }catch(err){showToast((appLang==='en'?'ASAS & ANTREPO history could not be loaded: ':'ASAS & ANTREPO geçmişi yüklenemedi: ')+err.message);}
}
async function deleteSourceRefreshRecord(rec){
  if(!rec||!rec.id||_sourceRefreshHistoryState.deleting)return;
  const t=sourceRefreshHistoryText();
  if(!confirm(t.removeConfirm))return;
  const currentIndex=_sourceRefreshHistoryState.items.findIndex(item=>item.id===rec.id);
  _sourceRefreshHistoryState.deleting=true;
  const lockButtons=on=>document.querySelectorAll('#sourceRefreshHistDelete,.verHistNavDelete,#sourceRefreshHistClearAll').forEach(b=>{b.disabled=on;});
  lockButtons(true);
  try{
    const data=await fetchJSON(`/api/refresh-history/${encodeURIComponent(rec.id)}`,{method:'DELETE',expectedRevision:_sourceRefreshHistoryState.revision});
    _sourceRefreshHistoryState.items=Array.isArray(data.items)?data.items:[];
    _sourceRefreshHistoryState.revision=Number(data._revision)||_sourceRefreshHistoryState.revision;
    if(state&&state.storeRevisions)state.storeRevisions.refreshHistory=_sourceRefreshHistoryState.revision;
    const remaining=sourceRefreshFiltered();
    const nextIndex=Math.max(0,Math.min(currentIndex,remaining.length-1));
    _sourceRefreshHistoryState.selectedId=remaining[nextIndex]?.id||null;
    renderSourceRefreshHistoryNav();renderSourceRefreshHistoryDetail();
    showToast(t.removed);
  }catch(err){
    showToast(t.removeFailed+err.message);
    if(err.code==='REVISION_CONFLICT')await openSourceRefreshHistory();
  }finally{
    _sourceRefreshHistoryState.deleting=false;
    lockButtons(false);
    const clearBtn=document.getElementById('sourceRefreshHistClearAll');
    if(clearBtn)clearBtn.disabled=!_sourceRefreshHistoryState.items.length;
  }
}
async function clearAllSourceRefreshHistory(){
  if(_sourceRefreshHistoryState.deleting||!_sourceRefreshHistoryState.items.length)return;
  const t=sourceRefreshHistoryText();
  if(!confirm(t.clearAllConfirm))return;
  _sourceRefreshHistoryState.deleting=true;
  const buttons=document.querySelectorAll('#sourceRefreshHistDelete,.verHistNavDelete,#sourceRefreshHistClearAll');
  buttons.forEach(button=>{button.disabled=true;});
  try{
    const data=await fetchJSON('/api/refresh-history',{method:'DELETE',expectedRevision:_sourceRefreshHistoryState.revision});
    _sourceRefreshHistoryState.items=Array.isArray(data.items)?data.items:[];
    _sourceRefreshHistoryState.revision=Number(data._revision)||_sourceRefreshHistoryState.revision;
    _sourceRefreshHistoryState.selectedId=null;
    _sourceRefreshHistoryState.query='';
    const search=document.getElementById('sourceRefreshHistSearch');if(search)search.value='';
    if(state&&state.storeRevisions)state.storeRevisions.refreshHistory=_sourceRefreshHistoryState.revision;
    renderSourceRefreshHistoryNav();renderSourceRefreshHistoryDetail();
    showToast(t.cleared);
  }catch(err){
    showToast(t.clearAllFailed+err.message);
    if(err.code==='REVISION_CONFLICT')await openSourceRefreshHistory();
  }finally{
    _sourceRefreshHistoryState.deleting=false;
    renderSourceRefreshHistoryNav();
  }
}
function downloadSourceRefreshRecord(rec){
  const s=rec.summary||{}, details=rec.details||[], refreshDate=new Date(rec.createdAt);
  const summaryRows=[['Yenileme Tarihi',Number.isNaN(refreshDate.getTime())?'':refreshDate],['Önceki toplam sipariş',Number(s.oldOrderCount||0)],['Yeni toplam sipariş',Number(s.newOrderCount||0)],['Yeni görünen sipariş',Number(s.newlyAppeared||0)],['Artık görünmeyen sipariş',Number(s.disappeared||0)],['Durumu değişen sipariş',Number(s.statusChanged||0)],['Kalan adedi değişen sipariş',Number(s.qtyChangedOrders||0)],['Kalan adet net değişimi',Number(s.kalanDelta||0)],['ASAS detay sayısı',Number(s.asasChangeCount||0)],['Antrepo detay sayısı',Number(s.antrepoChangeCount||0)]];
  const detailHeader=['Kaynak','Sipariş Kodu','Renk Kodu','Renk','Model Adı','İthalat Dosyası','Konteyner','Sub-Mfr','Special Code','MAG','MMYG','BUYER','BUYING GROUP','SEASON','MANUFACTURER','Değişiklik','Alan','Önceki','Yeni','Detay'];
  const detailRows=details.map(d=>[d.source||'',String(d.ocode||'').replace(/\.(?=\d{3}(?:\D|$))/g,''),d.colourCode||'',d.colour||'',d.modelName||'',d.importFile||'',d.containerNo||'',d.subMfr||'',d.specialCode||'',d.mag||'',d.mmyg||'',d.buyer||'',d.buyingGroup||'',d.season||'',d.manufacturer||'',d.changeType||'',d.field||'',d.before||'',d.after||'',d.detail||'']);
  const wb=XLSX.utils.book_new(), wsSummary=XLSX.utils.aoa_to_sheet(summaryRows), wsDetail=XLSX.utils.aoa_to_sheet([detailHeader,...detailRows]);
  wsSummary['!cols']=[{wch:31},{wch:24}]; wsDetail['!cols']=[{wch:12},{wch:18},{wch:14},{wch:16},{wch:30},{wch:22},{wch:20},{wch:24},{wch:18},{wch:12},{wch:12},{wch:20},{wch:22},{wch:14},{wch:28},{wch:28},{wch:28},{wch:32},{wch:32},{wch:60}];
  if(detailRows.length)wsDetail['!autofilter']={ref:`A1:T${detailRows.length+1}`}; wsDetail['!freeze']={xSplit:0,ySplit:1};
  for(let r=1;r<=detailRows.length;r++){const c=wsDetail[XLSX.utils.encode_cell({r,c:1})];if(c){c.t='s';c.v=String(c.v??'');c.z='@';}}
  XLSX.utils.book_append_sheet(wb,wsSummary,'Özet');XLSX.utils.book_append_sheet(wb,wsDetail,'Detay');
  const d=new Date(rec.createdAt),p=x=>String(x).padStart(2,'0');XLSX.writeFile(wb,`ASAS_Antrepo_Guncelleme_${d.getFullYear()}${p(d.getMonth()+1)}${p(d.getDate())}_${p(d.getHours())}${p(d.getMinutes())}.xlsx`);
}
document.getElementById('sourceUpdateNotesBtn')?.addEventListener('click',()=>openSourceRefreshHistory());

// ================= BİLDİRİM GEÇMİŞİ =================
const NOTIFICATION_HISTORY_KEY='lcw.notifications.history.v1';
const NOTIFICATION_HISTORY_LIMIT=250;
let _notificationHistoryState=null;
function notificationHistoryText(){const en=appLang==='en';return{title:en?'Notification History':'Bildirim Geçmişi',sub:en?'Recent messages shown by Buyer Log':'Buyer Log tarafından gösterilen son mesajlar',search:en?'Search notifications…':'Bildirimlerde ara…',empty:en?'No notifications yet.':'Henüz bildirim yok.',noMatch:en?'No matching notifications.':'Eşleşen bildirim yok.',clear:en?'Clear all':'Tümünü temizle',confirm:en?'Clear the entire notification history?':'Tüm bildirim geçmişi temizlensin mi?',close:en?'Close':'Kapat',count:n=>en?`${n} notification(s)`:`${n} bildirim`,toast:en?'Quick notification':'Kısa bildirim',center:en?'Important notification':'Önemli bildirim',remove:en?'Remove notification':'Bildirimi kaldır'};}
function notificationHistoryLoad(){if(_notificationHistoryState)return _notificationHistoryState;let state=null;try{state=JSON.parse(BLStorage.getItem(NOTIFICATION_HISTORY_KEY)||'null');}catch(_){}if(!state||!Array.isArray(state.items))state={items:[]};state.items=state.items.filter(item=>item&&item.message).slice(0,NOTIFICATION_HISTORY_LIMIT).map(item=>({...item,read:item.read===true}));_notificationHistoryState=state;return state;}
function notificationHistorySave(){try{BLStorage.setItem(NOTIFICATION_HISTORY_KEY,JSON.stringify(notificationHistoryLoad()));return true;}catch(_){return false;}}
function notificationHistoryUnread(){return notificationHistoryLoad().items.reduce((count,item)=>count+(item.read?0:1),0);}
function notificationHistoryUpdateBadge(){const button=document.getElementById('notificationsBtn'),badge=document.getElementById('notificationUnreadBadge'),count=notificationHistoryUnread(),t=notificationHistoryText();if(badge){badge.hidden=!count;badge.textContent=count>99?'99+':String(count);}if(button){button.classList.toggle('hasUnread',count>0);button.setAttribute('aria-label',count?`${t.title} (${count})`:t.title);}}
function notificationHistoryAdd(message,kind='toast'){const text=String(message==null?'':message).replace(/\s+/g,' ').trim().slice(0,5000);if(!text)return;const state=notificationHistoryLoad();state.items.unshift({id:`notification-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`,message:text,kind:kind==='center'?'center':'toast',createdAt:new Date().toISOString(),read:false});if(state.items.length>NOTIFICATION_HISTORY_LIMIT)state.items.length=NOTIFICATION_HISTORY_LIMIT;notificationHistorySave();notificationHistoryUpdateBadge();}
function notificationHistoryDate(value){const date=new Date(value);if(Number.isNaN(date.getTime()))return'';return new Intl.DateTimeFormat(appLang==='en'?'en-GB':'tr-TR',{dateStyle:'medium',timeStyle:'short'}).format(date);}
function renderNotificationHistoryList(query=''){const host=document.getElementById('notificationHistoryList'),countEl=document.getElementById('notificationHistoryCount');if(!host)return;const t=notificationHistoryText(),all=notificationHistoryLoad().items,q=String(query||'').trim().toLocaleLowerCase('tr-TR'),items=q?all.filter(item=>item.message.toLocaleLowerCase('tr-TR').includes(q)):all;if(countEl)countEl.textContent=t.count(items.length);if(!items.length){host.innerHTML=`<div class="verHistEmpty">${escapeHtml(all.length?t.noMatch:t.empty)}</div>`;return;}host.innerHTML=items.map(item=>`<article class="notificationHistoryItem${item.read?'':' isUnread'}" data-notification-id="${escapeHtml(item.id)}"><span class="notificationHistoryMarker" aria-hidden="true"></span><div class="notificationHistoryCopy"><div class="notificationHistoryMeta"><span>${escapeHtml(item.kind==='center'?t.center:t.toast)}</span><time datetime="${escapeHtml(item.createdAt||'')}">${escapeHtml(notificationHistoryDate(item.createdAt))}</time></div><p>${escapeHtml(item.message)}</p></div><button type="button" class="notificationHistoryRemove" data-notification-remove="${escapeHtml(item.id)}" title="${escapeHtml(t.remove)}" aria-label="${escapeHtml(t.remove)}"><svg class="ic"><use href="#i-trash"/></svg></button></article>`).join('');}
function notificationHistoryMarkAllRead(){const state=notificationHistoryLoad();let changed=false;state.items.forEach(item=>{if(!item.read){item.read=true;changed=true;}});if(changed)notificationHistorySave();notificationHistoryUpdateBadge();}
function openNotificationHistory(){const t=notificationHistoryText();document.getElementById('notificationHistoryModal')?.remove();notificationHistoryMarkAllRead();const modal=document.createElement('div');modal.id='notificationHistoryModal';modal.className='warnOverlay';modal.innerHTML=`<div class="modalCard verHistCard notificationHistoryCard" role="dialog" aria-modal="true" aria-labelledby="notificationHistoryTitle"><div class="verHistTop"><div><h2 id="notificationHistoryTitle">${escapeHtml(t.title)}</h2><p class="verHistSub">${escapeHtml(t.sub)}</p></div><button type="button" class="verHistClose" data-notification-close title="${escapeHtml(t.close)}" aria-label="${escapeHtml(t.close)}"><svg class="ic"><use href="#i-x"/></svg></button></div><div class="verHistTools"><input type="search" id="notificationHistorySearch" placeholder="${escapeHtml(t.search)}" autocomplete="off"><span class="verHistCount" id="notificationHistoryCount"></span><button type="button" class="tbtn" id="notificationUpdateHistoryBtn"><svg class="ic"><use href="#i-reload"/></svg>${escapeHtml(appLang==='en'?'Update history':'Güncelleme geçmişi')}</button><button type="button" class="notificationHistoryClear" id="notificationHistoryClear"><svg class="ic"><use href="#i-trash"/></svg>${escapeHtml(t.clear)}</button></div><div class="notificationHistoryList" id="notificationHistoryList"></div><div class="verHistFoot"><button type="button" class="tbtn" data-notification-close>${escapeHtml(t.close)}</button></div></div>`;document.body.appendChild(modal);renderNotificationHistoryList('');const close=()=>{modal.remove();document.removeEventListener('keydown',onKey);},onKey=event=>{if(event.key==='Escape')close();};document.addEventListener('keydown',onKey);modal.addEventListener('click',event=>{if(event.target===modal){close();return;}if(event.target.closest('[data-notification-close]')){close();return;}const remove=event.target.closest('[data-notification-remove]');if(remove){const state=notificationHistoryLoad();state.items=state.items.filter(item=>item.id!==remove.dataset.notificationRemove);notificationHistorySave();renderNotificationHistoryList(modal.querySelector('#notificationHistorySearch')?.value||'');notificationHistoryUpdateBadge();}});// v7.26 — "Güncelleme geçmişi" artık Kaynak Veri şeridinde değil, bildirim
// penceresinin içinde: iki ayrı yerde iki ayrı geçmiş aramak yerine tek yer.
modal.querySelector('#notificationUpdateHistoryBtn')?.addEventListener('click',()=>{close();openSourceRefreshHistory();});
modal.querySelector('#notificationHistorySearch').addEventListener('input',event=>renderNotificationHistoryList(event.target.value));modal.querySelector('#notificationHistoryClear').addEventListener('click',()=>{if(!notificationHistoryLoad().items.length||!confirm(t.confirm))return;notificationHistoryLoad().items=[];notificationHistorySave();renderNotificationHistoryList('');notificationHistoryUpdateBadge();});setTimeout(()=>modal.querySelector('#notificationHistorySearch')?.focus(),0);}
notificationHistoryUpdateBadge();

// Ekranin ORTASINDA gosterilen kisa bildirim. Alt kenardaki toast, yenileme sonucu gibi
// beklenen bir bildirimde gozden kaciyordu; bu not bakisin zaten bulundugu yerde belirir,
// kendiliginden kapanir ve tiklama/Esc ile de kapatilabilir.
function showCenterNotice(msg, opts){
  const o=opts||{};
  notificationHistoryAdd(msg,'center');
  const notify=window.BLUI?.notify;
  if(typeof notify==='function'){
    // Bir modal/overlay açıkken merkez bildirim onun üzerine/içine düşüyordu;
    // bu durumda standart sağ üst bildirim şeridine (edge) yönlendirilir. Ekranda
    // modal yoksa bilinçli merkez konumlandırma (bkz. yukarıdaki not) korunur.
    const overlayOpen=typeof blOverlayOpen==='function'&&blOverlayOpen();
    const close=notify(msg,{...o,placement:overlayOpen?'edge':'center',kind:o.kind||(o.icon===false?'info':'success'),language:appLang});
    return close;
  }
  document.getElementById('_centerNotice')?.remove();
  const wrap=document.createElement('div');
  wrap.id='_centerNotice';
  wrap.className='centerNotice';
  wrap.setAttribute('role','status');
  wrap.setAttribute('aria-live','polite');
  wrap.innerHTML=`<div class="centerNoticeCard">${o.icon===false?'':'<svg class="ic centerNoticeIcon"><use href="#i-check"/></svg>'}<span class="centerNoticeText"></span></div>`;
  wrap.querySelector('.centerNoticeText').textContent=String(msg==null?'':msg);
  document.body.appendChild(wrap);
  const close=()=>{
    if(!wrap.isConnected)return;
    wrap.classList.add('isLeaving');
    document.removeEventListener('keydown',onKey);
    setTimeout(()=>wrap.remove(),180);
  };
  const onKey=e=>{ if(e.key==='Escape')close(); };
  document.addEventListener('keydown',onKey);
  wrap.addEventListener('click',close);
  requestAnimationFrame(()=>wrap.classList.add('isIn'));
  const ms=Number(o.duration);
  wrap._t=setTimeout(close, Number.isFinite(ms)&&ms>0?ms:2800);
  return close;
}
function showToast(msg,opts){
  const o=opts||{};
  notificationHistoryAdd(msg,'toast');
  const notify=window.BLUI?.notify;
  if(typeof notify==='function')return notify(msg,{...o,placement:'edge',kind:o.kind||'info',language:appLang});
  let el = document.getElementById('_toast');
  if(!el){ el=document.createElement('div'); el.id='_toast'; document.body.appendChild(el); }
  el.textContent = msg; el.style.opacity='1';
  clearTimeout(el._t); el._t = setTimeout(()=>{ el.style.opacity='0'; }, 1700);
  return ()=>{clearTimeout(el._t);el.style.opacity='0';};
}
// Buyer Log'un oluşturduğu/indirdiği dosyalar için ORTAK sağ üst bildirim
// kartı: dosya adı + kayıt konumu, Aç/Klasörde Göster aksiyonlarıyla. Kaynak
// akış (sunucuda yazılan PO gibi) gerçek yolu zaten biliyorsa onOpen/onReveal
// üzerinden kendi (order code tabanlı) uç noktasını çağırır; renderer hiçbir
// zaman ham bir dosya yolunu geri göndermez. Aksiyon başarısız olursa (dosya
// silinmiş/taşınmış) kart çökmez, kontrollü bir hata toast'ı gösterir.
function notifyFileReady({filename, path, mode='created', onOpen, onReveal}={}){
  const en=appLang==='en';
  const label=mode==='downloaded'?(en?'File downloaded':'Dosya indirildi'):(en?'File created':'Dosya oluşturuldu');
  const text=String(filename||'');
  notificationHistoryAdd(`${label}: ${text}`,'toast');
  const notify=window.BLUI?.notify;
  if(typeof notify!=='function'){showToast(`${label}: ${text}`);return()=>{};}
  const actions=[];
  if(typeof onOpen==='function')actions.push({id:'open',label:en?'Open':'Aç',primary:true});
  if(typeof onReveal==='function')actions.push({id:'reveal',label:en?'Show in folder':'Klasörde Göster'});
  return notify(text,{
    kind:'success',placement:'edge',kindLabel:label,detail:path||'',language:appLang,duration:0,actions,
    onAction:async id=>{
      try{
        if(id==='open'&&onOpen)await onOpen();
        else if(id==='reveal'&&onReveal)await onReveal();
      }catch(err){
        showToast((err&&err.message)||(en?'Action failed.':'İşlem başarısız oldu.'),{kind:'error'});
      }
    },
  });
}
// Masaüstü (Electron) kabuğu, tarayıcı indirme yöneticisinden geçen HER
// dosyayı (CP/Orders Excel dışa aktarımı dâhil) will-download ile yakalar ve
// çakışma-güvenli GERÇEK son yolu bilir (bkz. electron/main.js). Köprü bu
// olayı yalnız opak bir token ile bildirir; Aç/Klasörde Göster de token
// üzerinden çalışır — renderer hiçbir zaman bir yolu geri göndermez. Köprü
// yoksa (tarayıcıda geliştirme kipi) gerçek son yol bilinmediği için kart hiç
// gösterilmez; yol uydurulmaz.
if(window.buyerLogDesktop&&typeof window.buyerLogDesktop.onDownloadComplete==='function'){
  window.buyerLogDesktop.onDownloadComplete(info=>{
    if(!info||!info.success||!info.token)return;
    notifyFileReady({
      filename:info.filename||'',
      path:info.path||'',
      mode:'created',
      onOpen:()=>window.buyerLogDesktop.openDownload(info.token).then(r=>{
        if(!r||!r.ok)throw new Error(appLang==='en'?'File could not be opened.':'Dosya açılamadı.');
      }),
      onReveal:()=>window.buyerLogDesktop.revealDownload(info.token).then(r=>{
        if(!r||!r.ok)throw new Error(appLang==='en'?'Folder could not be shown.':'Klasör gösterilemedi.');
      }),
    });
  });
}
const TABLE_META = {
  cpTable: {tableKey:'cp', rowsFn:()=>filteredCP(), computeFn:computeFlags},
  ordersTable: {tableKey:'orders', rowsFn:()=>filteredOrders(), computeFn:computeFlags},
  kolTable: {
    tableKey:'kol', rowsFn:()=>kolCollectionExportProjection(filteredKol()), computeFn:null,
    colsFn: ()=>kolDisplayDescriptors(),
    cellText: (col,record)=>kolCollectionExportCellText(col,record),
    cellStyle: (col,record)=>{
      const row=kolCollectionProjectionSource(record);
      if(col.kind==='price'){
        const pricing=kolEffectivePricing(row),v=pricing&&pricing[col.manufacturer], n=kolParseMoneyNum(v);
        if(v==='0'||v==='0,00') return '';
        if(Number.isFinite(n)&&n>0){
          const valid=kolManufacturers.map(m=>kolParseMoneyNum(pricing&&pricing[m.name])).filter(x=>Number.isFinite(x)&&x>0);
          return `background-color:${kolPriceGradientHex(n,valid)};`;
        }
        return '';
      }
      if(col.kind==='best'){const best=kolBestPricing(row),delta=kolBestPriceTargetDelta(row,best);return delta&&delta.meetsTarget?'background-color:#E4F3EB;color:#177A4C;font-weight:bold;':'';}
      if(col.kind==='confirmedName'||col.kind==='confirmedPrice'){
        const display=kolConfirmedDisplay(row);
        return !display?'':(display.isFallback?'color:#98A2B3;font-weight:600;':'background-color:#E4F3EB;color:#177A4C;font-weight:bold;');
      }
      if(col.kind==='base'&&(col.col.ruleReadonly||col.col.formulaReadonly)) return 'background-color:#F2F4F7;color:#475467;';
      return '';
    },
  },
};
function registerManagedGridClipboard(tableId,tableKey){
  if(!window.BLGridClipboard)return;
  const meta=TABLE_META[tableId];
  window.BLGridClipboard.register(tableId,{
    label:()=>appLang==='en'
      ?(tableKey==='orders'?'Orders data grid':'CP Tracker data grid')
      :(tableKey==='orders'?'Siparişler veri tablosu':'CP Tracker veri tablosu'),
    isActive:()=>String(document.body.dataset.activeTab||'')===tableKey&&!blOverlayOpen(),
    rows:table=>table?._blRenderedRows||meta.rowsFn(),
    columns:table=>table?._blRenderedColumns||visibleCols(meta.tableKey),
    rowId:row=>row?._id,
    columnId:column=>column?.k,
    header:column=>tableColumnLabel(meta.tableKey,column),
    value:(row,column)=>meta.cellText
      ? meta.cellText(column,row)
      : cellPlainText(column,row,meta.computeFn?meta.computeFn(row):null),
    exporter:BLTableExport,
    selectionChanged:size=>updateGridSelectionStatus(tableKey,size),
    copy:async (matrix,range,selectionState,options={})=>{
      const payload=window.BLGridClipboard.serialize(matrix,BLTableExport,options),plain=payload.plain,html=payload.html;
      const ok=await copyRichToClipboard(html,plain);
      window.BLGridClipboard.diagnostics.record({module:tableKey,operation:'copy',selection:window.BLGridClipboard.selectionSize(range),includeHeaders:payload.includeHeaders,transport:'rich',ok});
      showToast(ok
        ? `${matrix.recordCount}×${matrix.columnCount} ${appLang==='en'?(payload.includeHeaders?'cells copied with headers':'cells copied without headers'):(payload.includeHeaders?'hücre başlıklarıyla kopyalandı':'hücre başlıksız kopyalandı')}`
        : (appLang==='en'?'Copy failed.':'Kopyalama başarısız.'));
      return ok;
    },
  });
}
registerManagedGridClipboard('cpTable','cp');
registerManagedGridClipboard('ordersTable','orders');
function cellOf(node){
  if(!node) return null;
  const el = node.nodeType===3 ? node.parentElement : node;
  return el ? el.closest('td[data-c]') : null;
}
document.addEventListener('copy', e=>{
  if(e.defaultPrevented)return;
  const sel = window.getSelection();
  if(!sel || sel.rangeCount===0 || sel.isCollapsed) return; // nothing selected: let default (e.g. copying inside an input) happen
  const anchorTd = cellOf(sel.anchorNode), focusTd = cellOf(sel.focusNode);
  if(!anchorTd || !focusTd) return; // selection isn't within our data tables: let native copy proceed
  const table = anchorTd.closest('table');
  if(!table || table !== focusTd.closest('table')) return;
  if(anchorTd === focusTd) return; // single-cell text selection: let the browser copy the highlighted plain text normally
  const meta = TABLE_META[table.id]; if(!meta) return;
  const r0=Math.min(+anchorTd.dataset.r, +focusTd.dataset.r), r1=Math.max(+anchorTd.dataset.r, +focusTd.dataset.r);
  const c0=Math.min(+anchorTd.dataset.c, +focusTd.dataset.c), c1=Math.max(+anchorTd.dataset.c, +focusTd.dataset.c);
  const rowsArr = meta.rowsFn();
  const cols = meta.colsFn ? meta.colsFn() : visibleCols(meta.tableKey);
  const colsSlice = cols.slice(c0, c1+1);
  const getText = (col,row,cf) => meta.cellText ? meta.cellText(col,row) : cellPlainText(col,row,cf);
  const getStyle = (col,row,cf) => meta.cellStyle ? meta.cellStyle(col,row) : cellStyleFor(col,row,cf);
  /* Seçilen ARALIKTAKİ kayıtlar. Var olmayan satır atlanır — boş bir satır
     eklemek, kayıt sayısıyla dışa aktarım satır sayısını ayrıştırırdı. */
  const picked=[]; for(let r=r0;r<=r1;r++){ if(rowsArr[r]) picked.push(rowsArr[r]); }
  const matrix = BLTableExport.buildMatrix({
    records:picked, columns:colsSlice,
    columnLabel:col=>meta.tableKey?tableColumnLabel(meta.tableKey,col):(col.label||col.k),
    cellText:(col,row)=>getText(col,row,meta.computeFn?meta.computeFn(row):null),
  });
  // Kopyalama her zaman aydınlık temaya göre: gri başlık (mavi değil).
  const html = BLTableExport.toHTML(matrix,{
    border:_COPY_BORDER,
    cell:(colIndex,rowIndex)=>{
      const col=colsSlice[colIndex], row=picked[rowIndex];
      return {style:getStyle(col,row,meta.computeFn?meta.computeFn(row):null)+`border:${_COPY_BORDER};`};
    },
  });
  e.preventDefault();
  e.clipboardData.setData('text/plain', BLTableExport.toTSV(matrix));
  e.clipboardData.setData('text/html', html);
  showToast(`${matrix.recordCount}×${matrix.columnCount} hücre kopyalandı`);
});

