let syncStatusModalRenderer=null, syncStatusPollTimer=0;
function syncStatusRelativeTime(value){
  const date=value?new Date(value):null;if(!date||Number.isNaN(date.getTime()))return null;
  const elapsed=Date.now()-date.getTime(),abs=Math.abs(elapsed),units=abs<60000?['second',1000]:abs<3600000?['minute',60000]:abs<86400000?['hour',3600000]:['day',86400000];
  const amount=Math.round(-elapsed/units[1]);let label='';
  try { label=new Intl.RelativeTimeFormat(appLang==='en'?'en':'tr',{numeric:'always'}).format(amount,units[0]); }
  catch (_) { label=date.toLocaleString(appLang==='en'?'en-GB':'tr-TR',{dateStyle:'medium',timeStyle:'medium'}); }
  return {label,title:date.toLocaleString(appLang==='en'?'en-GB':'tr-TR',{dateStyle:'medium',timeStyle:'medium'})};
}
function syncStatusTime(value){const relative=syncStatusRelativeTime(value);return relative?`<span class="syncStatusTime" title="${escapeHtml(relative.title)}">${escapeHtml(relative.label)}</span>`:'—';}
function syncStatusBytes(value){
  const bytes=Math.max(0,Number(value)||0);if(bytes<1024)return `${Math.round(bytes)} B`;
  const units=['KB','MB','GB'];let amount=bytes/1024,index=0;while(amount>=1024&&index<units.length-1){amount/=1024;index++;}
  return `${amount>=100?amount.toFixed(0):amount>=10?amount.toFixed(1):amount.toFixed(2)} ${units[index]}`;
}
function syncStatusPath(value){const raw=String(value||'').trim();if(!raw)return '—';return `<span class="syncStatusPath" title="${escapeHtml(raw)}">${escapeHtml(raw.length>64?`…${raw.slice(-61)}`:raw)}</span>`;}
function syncStatusTransferCard(direction,q,tx){
  const upload=direction==='upload',progress=q.progress&&q.progress.phase===direction?q.progress:null,pending=Number(upload?q.pendingUpload:q.pendingDownload)||0;
  const total=Number(progress&&(upload?progress.uploadTotal:progress.downloadTotal))||0;
  const done=Number(progress&&(upload?progress.uploadDone:progress.downloadDone))||0;
  const packageTotal=Number(progress&&progress.packageTotal)||0,packageDone=Number(progress&&progress.packageDone)||0;
  const percent=total?Math.min(100,Math.round(done/total*100)):(packageTotal?Math.min(100,Math.round(packageDone/packageTotal*100)):0);
  const label=upload?tx('Yükleme','Upload'):tx('İndirme','Download'),activeLabel=upload?tx('Yükleniyor…','Uploading…'):tx('İndiriliyor…','Downloading…');
  let body='';
  if(progress){
    const eventLabel=upload?`${done}/${total} ${tx('olay','events')}`:`${Number(progress.eventDone)||0} ${tx('olay','events')}`;
    const packageLabel=packageTotal?`${tx('Paket','Package')} ${packageDone}/${packageTotal}`:'';
    const totalRemaining=upload&&Number.isFinite(Number(progress.totalRemaining))?`${Number(progress.totalRemaining).toLocaleString(appLang==='en'?'en-US':'tr-TR')} ${tx('toplam bekleyen','total remaining')}`:'';
    body=`<div class="syncTransferPercent">${percent}%</div><div class="syncProgressTrack" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}"><span style="width:${percent}%"></span></div><div class="syncTransferMeta"><span>${escapeHtml(eventLabel)}</span><span>${escapeHtml(syncStatusBytes(progress.bytesDone||0))}${progress.bytesTotal?` / ${escapeHtml(syncStatusBytes(progress.bytesTotal))}`:''}</span></div><div class="syncTransferMeta"><span>${escapeHtml(packageLabel||`${packageDone} ${tx('paket','packages')}`)}</span><span>${escapeHtml(totalRemaining)}</span></div><div class="syncTransferMeta"><span>${escapeHtml(syncStatusBytes(progress.speedBytesPerSecond||0))}/s</span><span>${progress.etaSeconds==null?'':escapeHtml(`~${progress.etaSeconds}s ${tx('kaldı','remaining')}`)}</span></div>`;
  }else{
    const packageSummary=upload&&Number(q.uploadedPackages)?`${Number(q.uploadedPackages)} ${tx('paket yüklendi','packages uploaded')}`:!upload&&Number(q.downloadedPackages)?`${Number(q.downloadedPackages)} ${tx('paket alındı','packages received')}`:'';
    body=`<div class="syncTransferValue">${pending?escapeHtml(`${pending.toLocaleString(appLang==='en'?'en-US':'tr-TR')} ${tx('bekleyen','pending')}`):escapeHtml(upload?tx('Up to date','Up to date'):tx('No new remote changes','No new remote changes'))}</div><div class="syncTransferMeta"><span>${upload?escapeHtml(`${tx('Create','Create')} ${Number(q.localCreate)||0} · ${tx('Update','Update')} ${Number(q.localUpdate)||0} · ${tx('Delete','Delete')} ${Number(q.localDelete)||0}`):escapeHtml(tx('No new remote changes','No new remote changes'))}</span><span>${escapeHtml(packageSummary)}</span></div>`;
  }
  return `<article class="syncTransferCard${progress?' is-active':''}" data-sync-transfer="${direction}"><div class="syncTransferHead"><div><span class="syncTransferArrow" aria-hidden="true">${upload?'↑':'↓'}</span><span class="syncCardEyebrow">${escapeHtml(progress?activeLabel:label)}</span></div><b>${progress?escapeHtml(total?`${done}/${total}`:`${packageDone}/${packageTotal}`):escapeHtml(`${pending}`)}</b></div>${body}</article>`;
}
function syncStatusNetwork(q,tx){const online=Boolean(q&&q.online),active=Boolean(q&&q.progress),configured=Boolean(q&&q.sharedSyncRoot);return `<span class="syncNetworkBadge ${active?'is-syncing':online?'is-online':'is-offline'}"><i aria-hidden="true"></i>${escapeHtml(active?tx('Syncing…','Syncing…'):online?tx('Connected','Connected'):configured?tx('Unavailable','Unavailable'):tx('Not configured','Not configured'))}</span>`;}
