  period.onchange=async()=>{try{const response=await fetch('/api/sync-period',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({syncPeriodMinutes:period.value})});const result=await response.json();if(result.status)render(result.status);}catch(error){showToast(error.message||String(error));}};
  retention.onchange=async()=>{try{const response=await fetch('/api/sync-package-retention',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({packageRetentionDays:Number(retention.value)})});const result=await response.json();if(result.status)render(result.status);}catch(error){showToast(error.message||String(error));}};
  modal.querySelector('[data-test]').onclick=async()=>{try{const response=await fetch('/api/sync-settings/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sharedSyncRoot:latestStatus.sharedSyncRoot||''})});const result=await response.json();if(!result.ok)throw new Error(result.error||tx('Connection failed.','Connection failed.'));showToast(tx('Bağlantı başarılı.','Connection successful.'));}catch(error){const box=modal.querySelector('[data-sync-error]');box.hidden=false;modal.querySelector('[data-sync-error-detail]').textContent=error.message||String(error);}};
  const runSync=()=>{if(syncRequest)return syncRequest;syncRequest=(async()=>{try{const response=await fetch('/api/sync-settings/sync-now',{method:'POST'});const result=await response.json();if(result.settings)render(result.settings);if(!result.ok)throw new Error(result.error||tx('Sync failed.','Sync failed.'));if(result.settings&&result.settings.online){const uploaded=Number(result.settings.uploadedEvents)||0,received=Number(result.settings.downloadedEvents)||0,duration=((Number(result.settings.lastDurationMs)||0)/1000).toFixed(1);showToast(tx(`${uploaded} değişiklik yüklendi · ${received} değişiklik alındı · ${duration} sn tamamlandı`,`${uploaded} changes uploaded · ${received} received · Completed in ${duration} sec`));}}catch(error){render({...latestStatus,lastError:error.message||String(error),online:false});}finally{syncRequest=null;}})();render(latestStatus);return syncRequest;};
