document.getElementById('syncStatusBtn')?.addEventListener('click',()=>void openSyncStatusModal());

function blDataMaintBytes(value){const n=Math.max(0,Number(value)||0);if(n<1024)return `${n} B`;const units=['KB','MB','GB','TB'];let v=n/1024,i=0;while(v>=1024&&i<units.length-1){v/=1024;i++;}return `${v>=100?v.toFixed(0):v>=10?v.toFixed(1):v.toFixed(2)} ${units[i]}`;}
/* host verilirse SATIR İÇİ çizer (Veri Yönetimi ekranı), verilmezse eskisi
   gibi tam ekran diyalog açar. İkinci bir Data Maintenance arayüzü yazmamak
   için tek fonksiyon iki yüzeyi de besler (§9). */
async function openDataMaintenanceModal(host=null){
  document.getElementById('_blDataMaintenance')?.remove();
  const en=appLang==='en';
  const inline=Boolean(host);
  const modal=document.createElement('div');
  modal.id='_blDataMaintenance';
  modal.className=inline?'blDataMaintInline':'warnOverlay';
  modal.innerHTML=`<div class="modalCard blDataMaintCard${inline?' isInline':''}" role="${inline?'region':'dialog'}"${inline?'':' aria-modal="true"'} aria-labelledby="_blDataMaintTitle">
    <div class="blDataMaintHead"><div><h2 id="_blDataMaintTitle">Data Maintenance</h2><p>${escapeHtml(en?'Analyze storage, local-first data, PLM and Shared Sync without deleting business data.':'İş verisini silmeden storage, local-first data, PLM ve Shared Sync sağlığını analiz et.')}</p></div><button type="button" class="pricingRuleIconBtn blDataMaintClose" title="${escapeHtml(en?'Close':'Kapat')}"><svg class="ic"><use href="#i-x"/></svg></button></div>
    <div class="blDataMaintToolbar">
      <button type="button" class="navActionBtn" data-dm="analyze"><svg class="ic"><use href="#i-search"/></svg>${escapeHtml(en?'Analyze':'Analyze')}</button>
      <button type="button" class="tbtn" data-dm="verify">${escapeHtml(en?'Verify':'Verify')}</button>
      <button type="button" class="tbtn" data-dm="safe">${escapeHtml(en?'Safe Clean':'Safe Clean')}</button>
      <button type="button" class="tbtn" data-dm="browser">${escapeHtml(en?'Clean Browser Cache':'Clean Browser Cache')}</button>
      <button type="button" class="tbtn" data-dm="legacy">${escapeHtml(en?'Verified Legacy':'Doğrulanmış Legacy')}</button>
      <button type="button" class="tbtn" data-dm="compact">${escapeHtml(en?'Compact Local Data':'Compact Local Data')}</button>
      <span style="flex:1"></span>
      <button type="button" class="tbtn" data-dm="plm">PLM Health</button>
      <button type="button" class="tbtn" data-dm="sync">Sync Health</button>
    </div>
    <div class="blDataMaintBody"><div class="blDataMaintStatus" data-dm-status>${escapeHtml(en?'Ready. Analyze is read-only. Safe Clean always previews first.':'Hazır. Analyze salt okunurdur. Safe Clean her zaman önce önizleme gösterir.')}</div><div data-dm-content></div></div>
  </div>`;
  if(inline){host.innerHTML='';host.appendChild(modal);}else document.body.appendChild(modal);
  modal.__refreshCanonicalRecipients=()=>{prepareEmailFillFromShared();if(typeof refreshAll==='function')refreshAll();};
  modal.addEventListener('click',event=>{const manage=event.target.closest('[data-manage-email-groups]');if(manage){event.preventDefault();window.BLEmailGroups?.open?.();}});
  const status=modal.querySelector('[data-dm-status]'),content=modal.querySelector('[data-dm-content]');
  /* Satır içi hâlde ARKA PLANA TIKLAYINCA KAPANMAZ: ekranın kendisi arka
     plandır ve kullanıcı analiz tablosunun yanına tıklayınca paneli
     kaybetmemeli. Kapatma yalnız kendi düğmesiyle. */
  const close=()=>{modal.remove();if(inline&&typeof host.__onDataMaintClosed==='function')host.__onDataMaintClosed();};
  modal.querySelector('.blDataMaintClose').onclick=close;
  if(!inline)modal.addEventListener('click',e=>{if(e.target===modal)close();});
  modal.addEventListener('keydown',e=>{if(e.key==='Escape')close();});
  const setStatus=(text,kind='')=>{status.textContent=text;status.className=`blDataMaintStatus${kind?` ${kind}`:''}`;};
  const request=async(url,opts={})=>{const response=await fetch(url,opts),data=await response.json().catch(()=>({}));if(!response.ok||data.ok===false)throw new Error(data.error||response.statusText);return data;};
  const renderAnalyze=data=>{
    const rows=Array.isArray(data.rows)?data.rows:[],db=data.localDb||{};
    content.innerHTML=`<div class="blDataMaintSummary"><div class="blDataMaintMetric"><span>${escapeHtml(en?'Active storage':'Aktif storage')}</span><strong>${escapeHtml(blDataMaintBytes(data.totalSize))}</strong></div><div class="blDataMaintMetric"><span>${escapeHtml(en?'Files scanned':'Taranan dosya')}</span><strong>${Number(data.totalFiles)||0}</strong></div><div class="blDataMaintMetric"><span>Local DB</span><strong>${escapeHtml(blDataMaintBytes(db.bytes))}</strong></div><div class="blDataMaintMetric"><span>${escapeHtml(en?'Journal':'Journal')}</span><strong>${Number(db.journal)||0}</strong></div><div class="blDataMaintMetric"><span>${escapeHtml(en?'Verified legacy':'Doğrulanmış legacy')}</span><strong>${Number((data.verifiedDuplicates||[]).length)||0} · ${escapeHtml(blDataMaintBytes(data.verifiedDuplicateBytes))}</strong></div></div>
    <div class="blDataMaintSection" style="margin-top:10px"><div class="blDataMaintSectionHead">Storage Overview</div><div style="max-height:430px;overflow:auto"><table class="blDataMaintTable"><thead><tr><th>Category</th><th>Path</th><th>Classification</th><th>Files</th><th>Size</th><th>${escapeHtml(en?'Safe?':'Safe?')}</th><th>${escapeHtml(en?'Reason':'Neden')}</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${escapeHtml(row.category||'')}</td><td class="path">${escapeHtml(row.path||'')}</td><td><span class="blDataMaintTag ${escapeHtml(row.classification||'UNKNOWN')}">${escapeHtml(row.classification||'UNKNOWN')}</span></td><td class="num">${Number(row.fileCount)||0}</td><td class="num">${escapeHtml(blDataMaintBytes(row.size))}</td><td>${row.safeToClean?'✓':'—'}</td><td>${escapeHtml(row.reason||'')}</td></tr>`).join('')}</tbody></table></div></div>`;
  };
  const run=async(kind)=>{
    modal.querySelectorAll('[data-dm]').forEach(btn=>btn.disabled=true);setStatus(en?'Working…':'Çalışıyor…');
    try{
      if(kind==='analyze'){const data=await request('/api/data-maintenance/analyze');renderAnalyze(data);setStatus(en?'Analysis completed. No files were changed.':'Analiz tamamlandı. Hiçbir dosya değiştirilmedi.','isOk');}
      else if(kind==='verify'){const data=await request('/api/data-maintenance/verify');content.innerHTML=`<div class="blDataMaintHealth"><div class="blDataMaintSection"><div class="blDataMaintSectionHead">Integrity Verification</div><pre class="blDataMaintJson">${escapeHtml(JSON.stringify(data.result,null,2))}</pre></div></div>`;setStatus(data.result&&data.result.ok?(en?'Business integrity verified.':'Business integrity doğrulandı.'):(en?'Verification failed.':'Doğrulama başarısız.'),data.result&&data.result.ok?'isOk':'isError');}
      else if(kind==='plm'||kind==='sync'){const url=kind==='plm'?'/api/data-maintenance/plm-health':'/api/data-maintenance/sync-health',data=await request(url);content.innerHTML=`<div class="blDataMaintSection"><div class="blDataMaintSectionHead">${kind==='plm'?'PLM Health':'Sync Health'}</div><pre class="blDataMaintJson">${escapeHtml(JSON.stringify(data.result,null,2))}</pre></div>`;setStatus(en?'Health check completed.':'Sağlık kontrolü tamamlandı.','isOk');}
      else if(kind==='safe'||kind==='browser'||kind==='legacy'){
        const scope=kind==='browser'?'browser':kind==='legacy'?'legacy':'all';const preview=await request('/api/data-maintenance/clean',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({apply:false,scope})});const plan=preview.result;
        const planLabel=scope==='legacy'?(en?'byte-identical inactive duplicate files':'byte-identical inactive duplicate dosya'):(en?'verified rebuildable files':'doğrulanmış yeniden üretilebilir dosya');
        content.innerHTML=`<div class="blDataMaintSection"><div class="blDataMaintSectionHead">${escapeHtml(en?'Safe Clean Preview':'Safe Clean Önizleme')}</div><div style="padding:12px;font-size:12px">${Number(plan.fileCount)||0} ${escapeHtml(planLabel)} · <strong>${escapeHtml(blDataMaintBytes(plan.estimatedBytes))}</strong><br><span class="muted">${escapeHtml((plan.categories||[]).join(' · ')||'—')}</span></div></div>`;
        setStatus(en?'Preview only — nothing has been deleted.':'Yalnız önizleme — hiçbir şey silinmedi.');
        const confirmText=scope==='legacy'?(en?`Delete ${plan.fileCount} byte-identical files from verified inactive legacy roots (${blDataMaintBytes(plan.estimatedBytes)})? Active copies stay untouched.`:`Doğrulanmış inactive legacy root içindeki ${plan.fileCount} byte-identical dosya (${blDataMaintBytes(plan.estimatedBytes)}) silinsin mi? Aktif kopyalara dokunulmaz.`):(en?`Delete ${plan.fileCount} verified safe files (${blDataMaintBytes(plan.estimatedBytes)})? Business data and browser session/auth are excluded.`:`${plan.fileCount} doğrulanmış güvenli dosya (${blDataMaintBytes(plan.estimatedBytes)}) silinsin mi? İş verisi ve browser session/auth kapsam dışıdır.`);
        if(plan.fileCount&&confirm(confirmText)){
          const applied=await request('/api/data-maintenance/clean',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({apply:true,scope})});setStatus(`${en?'Cleaned':'Temizlendi'}: ${applied.result.removed||0} · ${blDataMaintBytes(applied.result.freed||0)}`,'isOk');
        }
      }else if(kind==='compact'){
        if(!confirm(en?'Compact uploaded local journal payloads now? Unsynced changes and business state are preserved, and integrity is verified before the atomic swap.':'Yüklenmiş local journal payloadları compact edilsin mi? Unsynced değişiklikler ve business state korunur; atomic swap öncesi integrity doğrulanır.')){setStatus(en?'Compaction cancelled.':'Compaction iptal edildi.');return;}
        const data=await request('/api/data-maintenance/compact-local-db',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({keepUploadedTail:1000})}),r=data.result;content.innerHTML=`<div class="blDataMaintSummary"><div class="blDataMaintMetric"><span>Compacted</span><strong>${Number(r.compacted)||0}</strong></div><div class="blDataMaintMetric"><span>${escapeHtml(en?'Freed':'Boşalan')}</span><strong>${escapeHtml(blDataMaintBytes(r.bytesFreed))}</strong></div><div class="blDataMaintMetric"><span>Before</span><strong>${escapeHtml(blDataMaintBytes((r.before&&r.before.bytes)||0))}</strong></div><div class="blDataMaintMetric"><span>After</span><strong>${escapeHtml(blDataMaintBytes((r.after&&r.after.bytes)||0))}</strong></div><div class="blDataMaintMetric"><span>Integrity</span><strong>${r.businessHashBefore===r.businessHashAfter?'✓':'!'}</strong></div></div>`;setStatus(en?'Local data compacted and verified.':'Local data compact edildi ve doğrulandı.','isOk');
      }
    }catch(error){setStatus(error.message||String(error),'isError');}
    finally{modal.querySelectorAll('[data-dm]').forEach(btn=>btn.disabled=false);}
  };
  modal.querySelectorAll('[data-dm]').forEach(btn=>btn.addEventListener('click',()=>void run(btn.dataset.dm)));
  await run('analyze');
}
