function closeOtherToolbarAndColumnPopups(target){
  document.querySelectorAll('.toolbarMoreMenu:not([hidden])').forEach(menu=>{
    const wrap=menu.closest('.toolbarMoreWrap');if(wrap&&wrap.contains(target))return;
    menu.hidden=true;wrap?.querySelector('[aria-expanded="true"]')?.setAttribute('aria-expanded','false');
  });
  document.querySelectorAll('.colPanel').forEach(panel=>{
    const wrap=panel.closest('.colPanelWrap');if(panel.closest('.themeDock'))return;
    if(panel.contains(target))return;
    if(wrap&&wrap.contains(target))return;
    const visible=panel.classList.contains('show')||(getComputedStyle(panel).display!=='none'&&!panel.hidden);if(!visible)return;
    if(panel.id==='navColPanel'||panel.id==='shipColPanel')closeColumnPanel(panel);
    else panel.style.display='none';
    wrap?.querySelector('[aria-expanded="true"]')?.setAttribute('aria-expanded','false');
  });
  if(typeof closeHeaderFilter==='function'&&_openFilterPanel&&!_openFilterPanel.contains(target)&&!target.closest?.('.thFilterBtn,.chkFilterBtn'))closeHeaderFilter();
}
