// "Kur Dosyası Yükle": Ön Maliyet'teki "Pick FX Excel" ile aynı işi yapar —
// Aylık Kur Tahmin Raporu Excel'ini okuyup kurları kaydeder.
// "LFL İçin ASAS Yükle" düğmesi kaldırıldı: LFL artık kendi Excel/Database
// seçicisinden yönetiliyor ve Excel modunda ASAS çalışma kitabının aynısını
// kullanıyor; ayrı bir LFL dosyası yüklemeye gerek kalmadı.

const SOURCE_FX_GRACE_DAYS=7;
let sourceFxFreshnessTimer=0;
function sourceFxReferenceDate(data){
  const raw=data?.sourceType==='KUR'?(data.sourceModifiedAt||data.updatedAt):(data?.updatedAt||data?.sourceModifiedAt);
  const date=raw?new Date(raw):null;
  return date&&!Number.isNaN(date.getTime())?date:null;
}
function sourceFxFreshnessState(data,now=new Date()){
  const loadedAt=sourceFxReferenceDate(data);
  if(!loadedAt)return {available:false,stale:false,loadedAt:null,warnAt:null};
  // Yüklendiği ayın bitiminden sonra yedi tam gün tolerans verilir. Örneğin
  // Temmuz içinde yüklenen dosya için uyarı 8 Ağustos 00:00'da başlar.
  const warnAt=new Date(loadedAt.getFullYear(),loadedAt.getMonth()+1,1+SOURCE_FX_GRACE_DAYS,0,0,0,0);
  return {available:true,stale:now.getTime()>=warnAt.getTime(),loadedAt,warnAt};
}
function sourceFxDateText(date){
  return date?date.toLocaleDateString(appLang==='en'?'en-GB':'tr-TR',{day:'2-digit',month:'2-digit',year:'numeric'}):'—';
}
function renderSourceFxFreshness(data){
  const btn=document.getElementById('btnSourceFx'),badge=document.getElementById('sourceFxWarning');
  if(!btn||!badge)return sourceFxFreshnessState(data);
  const state=sourceFxFreshnessState(data),en=appLang==='en';
  btn.classList.toggle('isStale',state.stale);
  badge.hidden=!state.stale;
  badge.textContent=state.stale?(en?'Update':'Güncelle'):'';
  if(!state.available){
    btn.title=en?'Upload the monthly FX Excel file.':"Aylık kur Excel'ini yükle.";
  }else if(state.stale){
    btn.title=en
      ?`FX Excel loaded on ${sourceFxDateText(state.loadedAt)} is out of date. Upload the new monthly file.`
      :`${sourceFxDateText(state.loadedAt)} tarihinde yüklenen kur Excel'i güncelliğini yitirdi. Yeni aylık dosyayı yükleyin.`;
  }else{
    btn.title=en
      ?`Last FX Excel: ${sourceFxDateText(state.loadedAt)} · warning after ${sourceFxDateText(state.warnAt)}`
      :`Son kur Excel'i: ${sourceFxDateText(state.loadedAt)} · uyarı tarihi: ${sourceFxDateText(state.warnAt)}`;
  }
  btn.setAttribute('aria-label',btn.title);
  if(sourceFxFreshnessTimer){clearTimeout(sourceFxFreshnessTimer);sourceFxFreshnessTimer=0;}
  const nextCheck=state.available&&!state.stale?Math.max(1000,state.warnAt.getTime()-Date.now()+1000):24*60*60*1000;
  sourceFxFreshnessTimer=setTimeout(()=>refreshSourceFxFreshnessWarning(),Math.min(nextCheck,24*60*60*1000));
  return state;
}
async function refreshSourceFxFreshnessWarning(){
  if(!window.BLFX)return null;
  try{await BLFX.load();}catch(_){}
  return renderSourceFxFreshness(BLFX.store);
}

document.getElementById('sourceFxFile')?.addEventListener('change', async e=>{
  const file=e.target.files?.[0];
  e.target.value='';
  if(!file) return;
  const btn=document.getElementById('btnSourceFx');
  const label=btn?.querySelector('span:not(.dot)');
  const prev=label?label.textContent:'';
  if(label) label.textContent='Okunuyor…';
  try{
    if(!window.BLFX) throw new Error('Kur modülü yüklenmedi.');
    const parsed=await BLFX.importFile(file);
    await BLFX.save({...parsed.data,sourceType:'UPLOAD',sourceModifiedAt:file.lastModified?new Date(file.lastModified).toISOString():null});
    const st=parsed.stats;
    btn?.classList.add('loaded');
    showToast(`Kurlar güncellendi: ${st.currencyCount} döviz, ${st.monthCount} ay (${st.sheetCount} sayfa okundu).`);
    // Ön Maliyet ekranı açıksa rozetleri tazele.
    try{ if(typeof window.renderOpenCostingLanguage==='function' && document.body.dataset.activeTab==='opencosting') window.renderOpenCostingLanguage(); }catch(_){}
    renderSourceFxFreshness(BLFX.store);
  }catch(err){
    showToast('Kur dosyası okunamadı: '+err.message);
  }finally{
    if(label) label.textContent=prev;
  }
});
// Sayfa açılışında sunucu ayakta ve daha önce config'lenmişse veriyi otomatik çek.
