document.getElementById('viewDeleteBtn').addEventListener('click', async ()=>{
  const id = document.getElementById('viewSelect').value; if(!id) return;
  const page=activeProfilePage();
  if(!viewStore.items.some(it=>it.id===id&&it.data?.__page===page)){alert('Bu görünüm aktif sayfaya ait değil.');return;}
  if(!confirm('Bu görünümü silmek istediğine emin misin?')) return;
  const oldFavorite=pageFavoriteId('view',page,viewStore);
  try{
    const saved=await enqueueProfileMutation('view',()=>fetchJSON(`/api/views/${id}`,{method:'DELETE',expectedRevision:viewStore._revision}));
    viewStore=setProfileStore('view',saved,page);
    if(oldFavorite===id)BLStorage.removeItem(`lcw_view_favorite_${page}`);
    if(activeProfilePage()!==page)return;
    fillProfileSelect(document.getElementById('viewSelect'),viewStore,'view');
    const fallback=pageFavoriteId('view',page,viewStore);
    if(fallback){
      document.getElementById('viewSelect').value=fallback;
      applyViewState(profileItem('view',fallback,page)?.data);
      window.syncProfilePicker?.(document.getElementById('viewSelect'));
    }else resetViewToSystemDefault();
  }
  catch(err){ alert('Silinemedi: '+err.message); }
});
async function renameProfile(kind){
  const select=document.getElementById(kind==='view'?'viewSelect':'filterSelect'),id=select?.value,page=activeProfilePage();
  const store=kind==='view'?viewStore:filterStore,item=profileItem(kind,id,page);if(!item)return;
  const name=await openHorizonTextInput({title:kind==='view'?(appLang==='en'?'Rename view':'Görünümü yeniden adlandır'):(appLang==='en'?'Rename filter':'Filtreyi yeniden adlandır'),label:appLang==='en'?'New name':'Yeni ad',initial:item.name,confirmLabel:appLang==='en'?'Rename':'Yeniden adlandır'});if(!name||name===item.name)return;
  const data=item.data;
  try{
    const saved=await enqueueProfileMutation(kind,()=>fetchJSON(`/api/${kind==='view'?'views':'filter-profiles'}/${encodeURIComponent(id)}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.trim(),data}),expectedRevision:(kind==='view'?viewStore:filterStore)._revision}));
    setProfileStore(kind,saved,page);
    if(activeProfilePage()===page){fillProfileSelect(select,kind==='view'?viewStore:filterStore,kind);select.value=id;window.syncProfilePicker?.(select);}
    showToast(kind==='view'?'Görünüm yeniden adlandırıldı.':'Filtre yeniden adlandırıldı.');
  }catch(err){alert('Ad değiştirilemedi: '+err.message);}
}
document.getElementById('viewRenameBtn')?.addEventListener('click',()=>renameProfile('view'));

function clearActiveProfileSelection(kind){
  const select=document.getElementById(kind==='view'?'viewSelect':'filterSelect');
  if(select){select.value='';window.syncProfilePicker?.(select);}
}
function resetViewToSystemDefault(){
  const page=activeProfilePage();
  if(!isProfilePage(page))return;
  if(!state.freeze)state.freeze={};
  delete state.freeze[page];
  if(page==='koleksiyon'){
    kolColOrder=null;kolColWidths={};kolHiddenCols=new Set();kolPictureHidden=false;
    saveKolColState();
  }else if(colmgr[page]){
    colmgr[page]=initColState(COLS_BY_TABLE[page]||[]);
    if(page==='cp'||page==='orders')colmgr[page].widthPx.__picture=tableImageSizeDimensions(page,tableImageSizeCurrentValue(page)).col;
    saveAutoTableColumnState();
  }
  if(page==='cp')state.cpSort={key:null,dir:1};
  if(page==='orders')state.ordersSort={key:null,dir:1};
  saveFreezeState();clearProfileSelection('view');
  if(page==='cp'&&state.cp)renderCP();
  else if(page==='orders'&&state.orders)renderOrders();
  else if(page==='koleksiyon'&&typeof renderKol==='function')renderKol();
  else if(page==='ship'&&typeof renderShipTable==='function')renderShipTable();
  syncFreezeButtonState();
  showToast(appLang==='en'?'System default view restored.':'Sistem varsayılan görünümü geri yüklendi.');
}
function resetFiltersToSystemDefault(){
  const page=activeProfilePage(),info=activeTableInfo();
  if(!info)return;
  info.filterIds.forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  if(page==='koleksiyon'){
    kolColFilters={};kolCheckFilter='';saveKolColState();
  }else{
    state.colFilters[page]={};state.checkFilter[page]='';
    if(page==='cp'){cpDimFilters={};state.cpQuickExf='';saveCpDimFilters();updateCpDimBtnLabels();}
    if(page==='orders'){ordersDimFilters={};state.ordersQuickExf='';state.ordersQuickActive.clear();saveOrdersDimFilters();updateOrdersDimBtnLabels();}
  }
  clearProfileSelection('filter');info.rerender();saveCoreAutoFilterState();
  showToast(appLang==='en'?'System default filters restored.':'Sistem varsayılan filtreleri geri yüklendi.');
}
document.getElementById('viewResetBtn')?.addEventListener('click',resetViewToSystemDefault);

