// Pivot sorgusunun parametreleri tek yerden üretilir: hem /api/backlog hem de
// /api/backlog-detail aynı filtreleri görmek zorunda, yoksa detay penceresi
// pivottan farklı bir satır kümesi gösterir.
function buildBacklogParams(){
  const params = {
    retailFrom: document.getElementById('backlogFrom').value || undefined,
    retailTo: document.getElementById('backlogTo').value || undefined,
    inStoreFrom: document.getElementById('backlogInStoreFrom').value || undefined,
    inStoreTo: document.getElementById('backlogInStoreTo').value || undefined,
    antrepoFrom: document.getElementById('backlogAntrepoFrom').value || undefined,
    antrepoTo: document.getElementById('backlogAntrepoTo').value || undefined,
    groupBy: backlogGroupBy.concat(backlogColBy).join(','),
  };
  if(backlogGroupBy.concat(backlogColBy).includes('antrepoDate') && backlogDateLevels.length) params.antrepoDateLevels = backlogDateLevels.join(',');
  if(backlogBuyerGrupSelected.size) params.buyerGrup = [...backlogBuyerGrupSelected].join(',');
  const dimFiltersObj = {};
  Object.entries(backlogDimFilters).forEach(([dim,set])=>{ if(set.size) dimFiltersObj[dim] = [...set]; });
  // Antrepo Giriş Tarihi kova filtresi (Yıl/Ay/Hafta/Gün).
  if(backlogDateFilter.granularity && (backlogDateFilter.values||[]).length){
    dimFiltersObj.antrepoDate = {granularity:backlogDateFilter.granularity, values:backlogDateFilter.values};
  }
  if(Object.keys(dimFiltersObj).length) params.dimFilters = JSON.stringify(dimFiltersObj);
  return params;
}
