function attachBacklogResize(th, widthKey, minPx){
  if(!th || th.querySelector('.colResizer')) return;
  const grip = document.createElement('div');
  grip.className = 'colResizer';
  th.appendChild(grip);
  grip.addEventListener('mousedown', e=>{
    e.preventDefault(); e.stopPropagation();
    const startPx = backlogColWidths[widthKey];
    const startX = e.clientX;
    function onMove(ev){
      backlogColWidths[widthKey] = Math.max(minPx, startPx + (ev.clientX - startX));
      applyBacklogColWidths();
    }
    function onUp(){ saveBacklogColWidths(); document.removeEventListener('mousemove',onMove); document.removeEventListener('mouseup',onUp); }
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
  });
  attachCollapseOnDoubleClick(grip, {
    current: ()=>backlogColWidths[widthKey],
    min: ()=>minPx,
    set: px=>{ backlogColWidths[widthKey] = px; },
    apply: applyBacklogColWidths,
    save: saveBacklogColWidths,
  });
}
