// ================= NAKLİYE TİPİNE GÖRE MALİYET KIYASLAMASI =================
let shipRows = []; // sunucudan gelen satırlar (her biri _shipId ile)
let shipRevision=0, shipMutationQueue=Promise.resolve();
let shipSelected = new Set();

/* ================= Kıyaslama satır düzeni ve gizleme (kalıcı, istemci taraflı) =================
   Sıra ve gizli küme _shipId ile tutulur (sunucu kimliği kalıcıdır), localStorage'da
   saklanır ve yeniden çizim/yeniden yükleme boyunca hayatta kalır. Gizleme SİLME
   DEĞİLDİR: satır sunucuda ve shipRows içinde kalır, yalnız kart tablosunda gösterilmez. */
const SHIP_ROW_ORDER_KEY='buyerlog.shipCompare.order.v1';
const SHIP_ROW_HIDDEN_KEY='buyerlog.shipCompare.hidden.v1';
let shipRowOrder=[];
let shipRowHidden=new Set();
(function loadShipRowPrefs(){
  try{ const raw=JSON.parse(BLStorage.getItem(SHIP_ROW_ORDER_KEY)||'[]'); if(Array.isArray(raw)) shipRowOrder=raw.map(String); }catch(_){}
  try{ const raw=JSON.parse(BLStorage.getItem(SHIP_ROW_HIDDEN_KEY)||'[]'); if(Array.isArray(raw)) shipRowHidden=new Set(raw.map(String)); }catch(_){}
})();
function saveShipRowOrder(){ try{ BLStorage.setItem(SHIP_ROW_ORDER_KEY,JSON.stringify(shipRowOrder)); }catch(_){} }
function saveShipRowHidden(){ try{ BLStorage.setItem(SHIP_ROW_HIDDEN_KEY,JSON.stringify([...shipRowHidden])); }catch(_){} }
// Kayıtlı sırayla, kayıtta olmayan (yeni gelen) satırlar sonda olacak şekilde.
function shipOrderedRows(){
  const byId=new Map(shipRows.map(row=>[String(row._shipId),row]));
  const ordered=[];
  shipRowOrder.forEach(id=>{ const row=byId.get(id); if(row){ ordered.push(row); byId.delete(id); } });
  byId.forEach(row=>ordered.push(row));
  return ordered;
}
function shipVisibleRows(){ return shipOrderedRows().filter(row=>!shipRowHidden.has(String(row._shipId))); }
function shipHiddenRows(){ return shipOrderedRows().filter(row=>shipRowHidden.has(String(row._shipId))); }
function setShipRowHidden(shipId,hidden){
  const id=String(shipId);
  if(hidden) shipRowHidden.add(id); else shipRowHidden.delete(id);
  saveShipRowHidden();
}
// Sürüklenen satırı görünür sıra içinde hedef satırın önüne/arkasına taşır;
// gizli satırların göreli konumu dokunulmadan kalır.
function shipMoveRow(draggedId,targetId,after){
  const order=shipOrderedRows().map(row=>String(row._shipId));
  const from=order.indexOf(String(draggedId));
  if(from<0) return;
  order.splice(from,1);
  let to=order.indexOf(String(targetId));
  if(to<0) return;
  if(after) to++;
  order.splice(to,0,String(draggedId));
  shipRowOrder=order;
  saveShipRowOrder();
  renderShipDecision();
}
function updateShipHiddenRowsUi(){
  const badge=document.getElementById('shipHiddenCount');
  if(!badge) return;
  const n=shipHiddenRows().length;
  badge.textContent=n?` (${n})`:'';
}
function shipHideRow(shipId){
  setShipRowHidden(shipId,true);
  shipSelected.delete(String(shipId));
  renderShipDecision();
  showToast(appLang==='en'?'Row hidden. Use "Hidden" to restore it.':'Satır gizlendi. Geri getirmek için "Gizlenenler"i kullanın.');
}
function shipShowRow(shipId){
  setShipRowHidden(shipId,false);
  renderShipDecision();
}
function renderShipHiddenRowsPanel(panel){
  if(!panel) return;
  const tr=appLang!=='en';
  const hidden=shipHiddenRows();
  panel.innerHTML = hidden.length
    ? hidden.map(row=>`<label class="colPanelItem"><span class="colPanelName">${escapeHtml(row.styleName||row.orderCode||String(row._shipId))}</span><button type="button" class="colPanelDrop" data-ship-restore="${escapeHtml(String(row._shipId))}" title="${escapeHtml(tr?'Göster':'Show')}">↺</button></label>`).join('')
      + `<button type="button" class="colPanelAdd" id="shipRestoreAllBtn">${escapeHtml(tr?'Tümünü Göster':'Show All')}</button>`
    : `<label class="colPanelItem"><span class="colPanelName">${escapeHtml(tr?'Gizlenen satır yok.':'No hidden rows.')}</span></label>`;
  panel.querySelectorAll('[data-ship-restore]').forEach(btn=>{
    btn.addEventListener('click',()=>{ shipShowRow(btn.dataset.shipRestore); renderShipHiddenRowsPanel(panel); });
  });
  panel.querySelector('#shipRestoreAllBtn')?.addEventListener('click',()=>{
    shipHiddenRows().forEach(row=>setShipRowHidden(row._shipId,false));
    renderShipDecision();
    renderShipHiddenRowsPanel(panel);
  });
}
// Sağ tık "Düzenle": satırın kart içindeki tüm düzenleme alanlarını (varsayılan
// gizli olanlar dâhil) açar ve ilk alanı odaklar — mevcut commitShipEditor
// yolunun DIŞINDA yeni bir düzenleme mekanizması kurulmaz.
