function updateShipSelectionActions(){
  const fxBtn=document.getElementById('shipUpdateFxBtn');
  if(fxBtn){
    fxBtn.disabled=!shipSelected.size;
    fxBtn.title=shipSelected.size
      ? (appLang==='en' ? `Update FX for ${shipSelected.size} selected rows using Ex-Factory month` : `${shipSelected.size} seçili satırın kurunu Ex-Factory ayına göre güncelle`)
      : (appLang==='en' ? 'Select rows to update FX' : 'Kur güncellemek için satır seç');
  }
}
function shipFxMonthForDate(value){
  const d=coerceDateLoose(value);
  if(!d || isNaN(d)) return null;
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
}
function shipRoundHalfUp2(value){
  const n=Number(value);if(!Number.isFinite(n))return null;
  const sign=n<0?-1:1;return sign*Math.floor(Math.abs(n)*100+0.5+1e-10)/100;
}
function shipRateDisplay(value){
  const n=shipRoundHalfUp2(value);return n==null?'':n.toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2,useGrouping:false});
}
function shipFxInfoForExFactory(value){
  if(!window.BLFX) return {rate:null,requestedMonth:null,resolvedMonth:null,exact:false};
  const requestedMonth=shipFxMonthForDate(value);
  if(!requestedMonth) return {rate:null,requestedMonth:null,resolvedMonth:null,exact:false};
  const snap=BLFX.snapshotForMonth(requestedMonth,'TRY');
  const rate=BLFX.convert(1,'USD','TRY',snap);
  return {
    rate:Number.isFinite(rate)?shipRoundHalfUp2(rate):null,
    requestedMonth,
    resolvedMonth:snap.month||null,
    exact:!!snap.exact,
  };
}
async function updateShipFxByExFactory(rows, options={}){
  const list=(Array.isArray(rows)?rows:[]).filter(Boolean);
  if(!list.length) return {updated:0,missing:0,invalid:0};
  if(!window.BLFX){
    if(options.notify!==false) showToast(appLang==='en'?'FX module is unavailable.':'Kur modülü kullanılamıyor.');
    return {updated:0,missing:list.length,invalid:0};
  }
  const requests=list.map(row=>({row,token:(row._shipFxToken=(Number(row._shipFxToken)||0)+1),exFactory:String(row.exFactory||'')}));
  await BLFX.load();
  let updated=0,missing=0,invalid=0;
  requests.forEach(req=>{
    const {row,token,exFactory}=req;
    if(row._shipFxToken!==token || String(row.exFactory||'')!==exFactory) return;
    const info=shipFxInfoForExFactory(exFactory);
    if(!info.requestedMonth){ invalid++; return; }
    if(!Number.isFinite(info.rate)){ missing++; return; }
    const prev=row.kur;
    const next=shipRoundHalfUp2(info.rate);
    row.kur=next;
    row._kurRequestedMonth=info.requestedMonth;
    row._kurResolvedMonth=info.resolvedMonth;
    row._kurExact=info.exact;
    row._kurManual=false;
    row._kurUpdatedAt=new Date().toISOString();
    computeShipFormulas(row);
    const patch={kur:next,_kurRequestedMonth:info.requestedMonth,_kurResolvedMonth:info.resolvedMonth,_kurExact:info.exact,_kurManual:false,_kurUpdatedAt:row._kurUpdatedAt};
    patchShipRow(row._shipId,patch);
    if(options.history!==false && !editableValuesEqual(prev,next) && typeof pushUndo==='function')
      pushUndo({kind:'ship',shipId:row._shipId,fields:[{key:'kur',prev,next}]});
    updated++;
  });
  if(options.rerender!==false) renderShipTable();
  if(options.notify!==false){
    const parts=[];
    if(updated) parts.push(appLang==='en'?`${updated} FX rates updated`:`${updated} satırın kuru güncellendi`);
    if(invalid) parts.push(appLang==='en'?`${invalid} rows have no valid Ex-Factory date`:`${invalid} satırda geçerli Ex-Factory tarihi yok`);
    if(missing) parts.push(appLang==='en'?`${missing} rows have no TRY rate for the resolved month`:`${missing} satır için ilgili ayda TRY kuru bulunamadı`);
    showToast(parts.join(' · ') || (appLang==='en'?'No FX value was updated.':'Güncellenecek kur bulunamadı.'));
  }
  return {updated,missing,invalid};
}

// Kopyalama/disa aktarma sirasinda hucre bicimleri EKRANDAN okundugu icin tema gecici
// olarak aciga zorlanir. Karanlik temada bu, ekranin bir an bembeyaz olmasina yol
// aciyordu. Bu perde, gecis oncesindeki gercek renkleri satir ici stil olarak alip uste
// serer; tema arkada degisir, kullanici beyaz parlama gormez.
function beginThemeSwapCurtain(label){
  const body=document.body;
  if(!body) return ()=>{};
  const cs=getComputedStyle(body);
  const curtain=document.createElement('div');
  curtain.id='_themeSwapCurtain';
  curtain.setAttribute('role','status');
  curtain.setAttribute('aria-live','polite');
  curtain.style.cssText='position:fixed;inset:0;z-index:2147483646;display:flex;align-items:center;justify-content:center;font:500 14px/1.45 system-ui,-apple-system,sans-serif;';
  curtain.style.background=cs.backgroundColor||'#fff';
  curtain.style.color=cs.color||'#000';
  curtain.textContent=String(label||'');
  body.appendChild(curtain);
  return ()=>{ try{ curtain.remove(); }catch(e){} };
}
function selectedCpRowsForAction(){
  // CP ve Siparişler ayni satir seklini paylasir (ikisi de ASAS'tan uretilir), ama
  // secim state'leri ayridir. Aktif sekmeye gore dogru kaynagi kullaniriz; aksi halde
  // Siparişler'de satir secilmesine ragmen bu butonlar bos CP secimini okurdu.
  const activeTab=document.body.dataset.activeTab||document.querySelector('nav.tabs button.active')?.dataset.tab||'';
  const onOrders=activeTab==='orders';
  const store=onOrders?state.orders:state.cp;
  const selected=onOrders?state.ordersSelected:state.cpSelected;
  if(!store || !selected || !selected.size) return [];
  // ONCE FILTRE, SONRA SECIM: aktif filtre yuzunden gizlenmis bir satir, isaretli
  // kalmis olsa bile hicbir toplu isleme (e-posta, Excel, durum degisikligi) dahil
  // edilmez. Kullanicinin gormedigi satir islenmemeli.
  const rows=(onOrders?filteredOrders():filteredCP()).filter(r=>selected.has(r._id));
  // Siparişler sekmesinde _canEdit, kullaniciya ozel bir yetki sinyali degil: tablo
  // salt-okunur bir ayna oldugu icin yuklemede TUM satirlara false yazilir. Bu
  // butonlarin yaptigi isler (maliyet olustur, e-posta taslagi, nakliye kiyaslama,
  // fiyat gecmisi) secili satirlari degistirmez, yalnizca okur. Dolayisiyla duzenleme
  // yetkisi kontrolu yalnizca CP'de anlamlidir; Siparişler'de uygulanirsa butonlar
  // hicbir zaman calismaz.
  const denied=onOrders?[]:rows.filter(r=>r._canEdit===false);
  if(denied.length){
    const message=appLang==='en'
      ?`${denied.length} selected order(s) are view-only. Remove them from the selection before performing this action.`
      :`Seçili siparişlerin ${denied.length} tanesi yalnız görüntülenebilir. Bu işlem için önce bu satırların seçimini kaldırın.`;
    showToast(message); return null;
  }
  return rows;
}
window.selectedCpRowsForAction=selectedCpRowsForAction;

function updateShippingBtnVisibility(){
  // CP araç çubuğundaki seçime bağlı butonlar: Koleksiyon'daki "Fiyatlamaya Gönder"
  // ile aynı davranış — seçim yokken pasif (karanlık), seçim varken aktif (aydınlık).
  const activeTab=document.querySelector('nav.tabs button.active')?.dataset.tab||document.body.dataset.activeTab||'';
  const cpCount = (state.cpSelected && state.cpSelected.size) || 0;
  const ordersCount = (state.ordersSelected && state.ordersSelected.size) || 0;
  const count = activeTab==='orders' ? ordersCount : cpCount;
  const has = activeTab==='cp' && cpCount>0;
  // Maliyet Oluştur / E-Posta Hazırla / Nakliye Kıyaslama, Siparişler sekmesinde de
  // seçime göre çalışır (selectedCpRowsForAction artık aktif sekmenin seçimini okur).
  const hasActionSelection=(activeTab==='cp'||activeTab==='orders')&&count>0;
  const hasPricingSelection=(activeTab==='cp'||activeTab==='orders')&&count>0;
  const hasBacklogSelection = (activeTab==='cp'||activeTab==='orders') && count>0;
  const ship = document.getElementById('navToShipping');
  if(ship){
    ship.style.display='';           // CSS sekmeye göre gösterir; artık gizlenmez
    ship.disabled = !hasActionSelection;
    ship.title = hasActionSelection ? `${count} satırı Nakliye Kıyaslama tablosuna aktar`
                     : 'Nakliye kıyaslamasına aktarmak için önce satır seç';
  }
  const oc = document.getElementById('cpCreateOcBtn');
  if(oc){
    oc.disabled = !hasActionSelection;
    oc.title = hasActionSelection ? `${count} satırdan ön maliyet oluştur` : 'Ön maliyet oluşturmak için önce satır seç';
  }
  const sp = document.getElementById('cpSendPricingBtn');
  if(sp){
    sp.hidden=true;
    sp.disabled=true;
  }
  const ph = document.getElementById('cpPriceHistoryBtn');
  if(ph){
    ph.disabled=!hasPricingSelection;
    ph.title=hasPricingSelection?`${count} sipariş için kayıtlı fiyat geçmişini göster`:'Fiyat geçmişi için önce sipariş seç';
  }
  const ps = document.getElementById('cpProdStatusBtn');
  if(ps){
    ps.disabled = !hasActionSelection;
    ps.title = hasActionSelection ? `${count} sipariş için e-posta taslağı hazırla` : 'E-posta hazırlamak için önce sipariş seç';
  }
  const ctk = document.getElementById('cpCopyToKolBtn');
  if(ctk){
    ctk.disabled = !has;
    ctk.title = has ? `${cpCount} satırı Koleksiyon'a kopyala` : "Koleksiyon'a kopyalamak için önce satır seç";
  }
  const endeksmatikBtn=document.getElementById('ordersEndeksmatikBtn');
  if(endeksmatikBtn){
    const enabled=activeTab==='orders'&&ordersCount===1;
    endeksmatikBtn.disabled=!enabled;
    endeksmatikBtn.title=enabled
      ?(appLang==='en'?'Calculate the selected order’s Endeksmatik price one year later':'Seçili siparişin 1 yıl sonraki Endeksmatik fiyatını hesapla')
      :(appLang==='en'?'Select exactly one order first':'Endeksmatik için önce tek bir sipariş seçin');
  }
  /* "Seçilenleri Güncelle" seçim YOKKEN kapalıdır. Kapalı bırakmak, sessizce
     tüm filtrelenmiş kümeye genişlemekten güvenlidir. */
  const ordersPlmSelectedBtn=document.getElementById('ordersModelLinksSelectedBtn');
  if(ordersPlmSelectedBtn){
    const enabled=activeTab==='orders'&&ordersCount>0;
    ordersPlmSelectedBtn.disabled=!enabled;
    ordersPlmSelectedBtn.title=enabled
      ?(appLang==='en'?`Update model links for ${ordersCount} selected order row(s)`:`${ordersCount} seçili sipariş satırının model linkini güncelle`)
      :(appLang==='en'?'Select an order before updating selected rows':'Seçilenleri güncellemek için önce sipariş seç');
  }
  const cpPlmSelectedBtn=document.getElementById('cpModelLinksSelectedBtn');
  if(cpPlmSelectedBtn){
    const enabled=activeTab==='cp'&&cpCount>0;
    cpPlmSelectedBtn.disabled=!enabled;
    cpPlmSelectedBtn.title=enabled
      ?(appLang==='en'?`Update model links for ${cpCount} selected row(s)`:`${cpCount} seçili satırın model linkini güncelle`)
      :(appLang==='en'?'Select a row before updating selected rows':'Seçilenleri güncellemek için önce satır seç');
  }
  const backlogBtn=document.getElementById('selectedBacklogBtn');
  if(backlogBtn){
    backlogBtn.disabled=!hasBacklogSelection;
    backlogBtn.title=hasBacklogSelection
      ?(appLang==='en'
        ?`Open the Backlog report for ${count} selected order row(s)`
        :`${count} seçili sipariş satırının Backlog raporunu aç`)
      :(appLang==='en'
        ?'Select order rows first to open their Backlog report'
        :'Backlog raporu için önce sipariş satırı seç');
  }
}

// CP satırındaki alanları Nakliye tablosunun "auto" sütunlarına eşler.
function mapCPRowToShip(row){
  const transitSnapshot=isProductionStatus(row['STATUS']) ? {
    version:1,
    createdAt:new Date().toISOString(),
    Gemi:resolveTransitDaysForValues('Gemi',row['Ex-factory'],row.Season,row.Country,row['STATUS'],false).days,
    'Gemi+Uçak':resolveTransitDaysForValues('Gemi+Uçak',row['Ex-factory'],row.Season,row.Country,row['STATUS'],false).days,
    Uçak:resolveTransitDaysForValues('Uçak',row['Ex-factory'],row.Season,row.Country,row['STATUS'],false).days,
    'Gemi+Tır':resolveTransitDaysForValues('Gemi+Tır',row['Ex-factory'],row.Season,row.Country,row['STATUS'],false).days,
  } : null;
  return {
    orderCode: row['Order Code'] ?? '',
    status: row['STATUS'] || '',
    buyerGroup: row['Buyer Grup (TR)'] || '',
    buyer: row['Buyer'] || '',
    category: row['Category'] || '',
    line: row['Line'] || '',
    retailDate: row['Retail Date'] instanceof Date ? toISODate(row['Retail Date']) : (row['Retail Date']||null),
    opd: row['OPD'] instanceof Date ? toISODate(row['OPD']) : (row['OPD']||null),
    exFactory: row['Ex-factory'] instanceof Date ? toISODate(row['Ex-factory']) : (row['Ex-factory']||null),
    specialCode: row['Special Code'] || '',
    // Görsel referansı satıra YAZILIR: kullanıcı CP'yi hiç açmadan Nakliye'ye
    // geçtiğinde override haritası boş olur ve canlı çözüm hiçbir şey bulamaz.
    // PLM kimliği de taşınır ki harita yüklüyken canlı çözüm çalışabilsin.
    plm: row['PLM ID'] ?? row['PLM Code'] ?? row.plmId ?? '',
    _imageRef: row._imageRef || '',
    styleName: row['Model Name'] || '',
    colour: row['Colour'] || '',
    colorCode: row['C.Code'] || '',
    quantity: toNum(row['Order Quantity']) ?? '',
    country: row['Country'] || '',
    season: row['Season'] || '',
    delType: row['Del. Type'] || '',
    _transitDaysSnapshot: transitSnapshot,
    supplier: row['Manufacturer'] || '',
    fob: toNum(row['FOB ($)']) ?? '',
    suppFob: toNum(row['Supp. FOB']) ?? '',
  };
}
function collectionShippingModelKey(row){
  const normalize=value=>String(value==null?'':value).trim().toLocaleUpperCase('tr-TR')
    .replace(/İ/g,'I').replace(/Ş/g,'S').replace(/Ç/g,'C').replace(/Ö/g,'O').replace(/Ü/g,'U').replace(/Ğ/g,'G');
  const plm=normalize(row&&row.plmId);
  if(plm)return `PLM:${plm}`;
  const model=normalize(row&&row.modelKod);
  if(model)return `MODEL:${model}\u001f${normalize(row&&row.season)}`;
  const order=normalize(row&&row._sourceOrderCode);
  return order?`ORDER:${order}`:'';
}
function mapCollectionRowToShip(row){
  if(!row)return null;
  const date=value=>value instanceof Date?(toISODate(value)||''):String(value||'').trim();
  const modelKey=collectionShippingModelKey(row);
  if(!modelKey)return null;
  const supplier=norm(row.confirmedManufacturer)||norm(row.buyingSampleManufacturer)||'';
  return {
    _sourceModule:'collection', _modelKey:modelKey,
    orderCode:row._sourceOrderCode||'', status:row.durum||'', buyerGroup:row.buyingGroup||'', buyer:row.buyer||'',
    category:row.urunTipi||'', line:row.line||'', retailDate:date(row.retail), opd:'', exFactory:date(row.exFactory),
    specialCode:row.specialCode||'', plm:row.plmId||'', _imageRef:row.imgRef||row.img||'', styleName:row.modelKod||'',
    colour:row.colour||'', colorCode:row.colourCode||'', quantity:toNum(row.quantity)??'', country:row.country||'', season:row.season||'',
    delType:normalizeTransitDelType(row.delType)||'Gemi', supplier, fob:toNum(row.fob)??'', suppFob:toNum(row.targetPrice)??'',
    trFiyatTl:toNum(row.trPrice)??'', kur:toNum(row.trFx)??'',
  };
}
function collectionShippingColourOptions(row){
  const clean=value=>String(value==null?'':value).trim();
  const source=Array.isArray(row&&row._colourOptions)
    ? row._colourOptions
    : [{colour:row&&row.colour,colorCode:row&&row.colorCode}];
  const seen=new Set(), options=[];
  source.forEach(item=>{
    const colour=clean(item&&item.colour), colorCode=clean(item&&(item.colorCode??item.colourCode));
    const identity=colorCode||colour;
    if(!identity)return;
    const key=identity.toLocaleUpperCase('tr-TR');
    if(seen.has(key))return;
    seen.add(key); options.push({colour,colorCode});
  });
  return options;
}
function mergeCollectionShippingColourOptions(target,incoming){
  if(!target)return target;
  const options=[], seen=new Map();
  [...collectionShippingColourOptions(target),...collectionShippingColourOptions(incoming)].forEach(option=>{
    const identity=option.colorCode||option.colour, key=identity.toLocaleUpperCase('tr-TR');
    const existing=seen.get(key);
    if(existing){
      if(!existing.colour&&option.colour)existing.colour=option.colour;
      if(!existing.colorCode&&option.colorCode)existing.colorCode=option.colorCode;
      return;
    }
    seen.set(key,option); options.push(option);
  });
  if(options.length){
    target._colourOptions=options;
    target.colour=options.map(option=>option.colour).join(', ');
    target.colorCode=options.map(option=>option.colorCode).join(', ');
  }
  return target;
}
function mergeCollectionShippingRows(mappedRows){
  const unique=new Map();
  (Array.isArray(mappedRows)?mappedRows:[]).forEach(mapped=>{
    if(!mapped||!mapped._modelKey)return;
    const current=unique.get(mapped._modelKey);
    if(current)mergeCollectionShippingColourOptions(current,mapped);
    else unique.set(mapped._modelKey,mergeCollectionShippingColourOptions({...mapped},mapped));
  });
  return [...unique.values()];
}

// Formül sütunlarını (K,Y,Z,AA,AB,AE,AF,AG,AH,AI,AJ) diğer alanlardan hesaplar.
/*
 * NAKLİYE SÜRELERİ — Kaynak > Transfer Lead Times.
 *
 * Süreler artık merkezi kural tablosundan CANLI çözülür: satırın kendi ülkesi,
 * sezonu ve Ex-Factory tarihine göre. Ex-Factory bu ekranda elle değiştirilebildiği
 * için bu önemli — tarih değişince geçerli kural da değişebiliyor.
 *
 * Sıra: (1) merkezi kural, (2) satır oluşturulurken alınmış snapshot,
 * (3) son çare sabitler (Gemi 75 / Gemi+Uçak 45 / Uçak 15).
 *
 * DAVRANIŞ DEĞİŞİKLİĞİ: eskiden snapshot önce geliyordu ve kural değişiklikleri
 * eski satırlara yansımıyordu. Artık kural tablosu güncellenince bu sayfadaki
 * tahmini teslim tarihleri de güncellenir.
 */
const SHIP_TRANSIT_FALLBACK={'Gemi':75,'Gemi+Uçak':45,'Uçak':15};
function shipTransitDays(row){
  const snap=row&&row._transitDaysSnapshot&&row._transitDaysSnapshot.version===1?row._transitDaysSnapshot:null;
  const out={},src={};
  ['Gemi','Gemi+Uçak','Uçak'].forEach(delType=>{
    let days=null, source='default';
    if(typeof resolveTransitDaysForValues==='function'){
      // forceRules: bu sayfa bir "ne olurdu" karşılaştırması; sipariş durumu
      // kural aramasını engellememeli.
      const res=resolveTransitDaysForValues(delType,row&&row.exFactory,row&&row.season,row&&row.country,row&&row.status,true);
      if(res&&res.dynamic&&Number.isFinite(Number(res.days))){ days=Number(res.days); source='rule'; }
    }
    if(days==null&&snap&&Number.isFinite(Number(snap[delType]))){ days=Number(snap[delType]); source='snapshot'; }
    if(days==null){ days=SHIP_TRANSIT_FALLBACK[delType]; source='default'; }
    out[delType]=days; src[delType]=source;
  });
  out._source=src;
  return out;
}

function shipLandedMultipliers(){
  const raw=(typeof state!=='undefined'&&state&&state.overrides&&state.overrides.landedMultipliers)||{};
  const pick=(value,fallback)=>{const n=Number(value);return Number.isFinite(n)&&n>0?n:fallback;};
  return {tr:pick(raw.tr,1.05), overseas:pick(raw.overseas,1.11)};
}
function computeShipFormulas(row){
  const exf = row.exFactory ? coerceDateLoose(row.exFactory) : null;
  const opd = row.opd ? coerceDateLoose(row.opd) : null;
  row.leadTime = (exf && opd && !isNaN(exf) && !isNaN(opd)) ? Math.round((exf-opd)/86400000) : '';
  const multipliers = shipLandedMultipliers();
  const trTl = toNum(row.trFiyatTl), kur = toNum(row.kur);
  row.trFiyatUsd = (trTl!=null && kur) ? (trTl/kur) : '';
  row.trFiyatFobUsdLanded = (row.trFiyatUsd!=='' ) ? (row.trFiyatUsd*multipliers.tr) : '';
  const fob = toNum(row.fob);
  row.ydFiyatUsd = fob!=null ? fob : '';
  row.ydFiyatUsdLandedGemi = fob!=null ? (fob*multipliers.overseas) : '';
  /* Avantajın tabanı DOMESTIC LANDED'dır (TR USD × tr çarpanı), domestic FOB
     değil. YD tarafındaki üç değerin hepsi landed olduğu için ancak böyle
     elma-elma bir oran çıkar. */
  const trLanded = row.trFiyatFobUsdLanded;
  const gemiUcak = toNum(row.ydFiyatUsdLandedGemiUcak), ucak = toNum(row.ydFiyatUsdLandedUcak);
  const advantage = landed => (trLanded!=='' && trLanded!==0 && landed!=null && landed!=='') ? (landed/trLanded - 1) : '';
  row.gemiAvantaj = advantage(row.ydFiyatUsdLandedGemi===''?null:row.ydFiyatUsdLandedGemi);
  row.gemiUcakAvantaj = advantage(gemiUcak);
  row.ucakAvantaj = advantage(ucak);
  const addDaysIso = (dateStr, n) => {
    // YYYY-MM-DD iş tarihidir, saat anı değildir. `new Date('2026-08-01')`
    // UTC olarak ayrıştırılıp yerel getDate/setDate ile işlendiğinde UTC eksi
    // saat dilimlerinde bir gün geriye kayar. Tarih-only girdiyi UTC takvim
    // aritmetiğiyle taşı; diğer desteklenen girdiler eski yerel yolu korusun.
    const match=String(dateStr==null?'':dateStr).trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if(match){const d=new Date(Date.UTC(Number(match[1]),Number(match[2])-1,Number(match[3])));d.setUTCDate(d.getUTCDate()+Number(n||0));return d.toISOString().slice(0,10);}
    const d=coerceDateLoose(dateStr);if(!d)return '';d.setDate(d.getDate()+Number(n||0));return toISODate(d);
  };
  const days=shipTransitDays(row);
  const vesselDays=days.Gemi, seaAirDays=days['Gemi+Uçak'], airDays=days['Uçak'];
  row.retailTrWithVessel = addDaysIso(row.exFactory, vesselDays);
  row.gemiUcakAntrepoTeslim = addDaysIso(row.exFactory, seaAirDays);
  row.ucakAntrepoTeslim = addDaysIso(row.exFactory, airDays);

  // TOPLAM ETKİ (USD).
  //
  // Avantaj sütunları birim bazında yüzde veriyor; karar ise toplam paraya bakar:
  // %3 fark 500 adette başka, 50.000 adette başka bir şeydir. Burada aynı
  // karşılaştırmanın adet çarpılmış hâli hesaplanır — yani (YD landed − TR USD) × Adet.
  //
  // Karşılaştırma tabanı Avantaj formülleriyle AYNI olmalıdır; ikisi de artık
  // DOMESTIC LANDED kullanır (kullanıcı kararı — bkz. avantaj formülü).
  // Bu alanlar v9.18'den beri ekranda gösterilmez; hesap ucuz ve sınanmış
  // olduğu için, ileride yeniden istenirse diye yerinde bırakıldı.
  //
  // Alanlar alt çizgiyle başlar: SHIP_COLS ve SHIP_EXCEL_HEADERS'a girmezler,
  // dolayısıyla tabloya ve Excel şablonuna dokunmazlar. Yalnız karar kartlarında
  // gösterilirler.
  const qty = toNum(row.quantity);
  const totalDiff = landed => (trLanded!=='' && landed!=null && landed!=='' && qty!=null) ? ((landed - trLanded) * qty) : null;
  row._totalGemi = totalDiff(row.ydFiyatUsdLandedGemi==='' ? null : row.ydFiyatUsdLandedGemi);
  row._totalGemiUcak = totalDiff(gemiUcak);
  row._totalUcak = totalDiff(ucak);
  row._totalTr = (trLanded!=='' && qty!=null) ? (trLanded * qty) : null;
  return row;
}

function shipCellDisplay(c, row){
  const v = row[c.k];
  if(c.type==='formula-date' || c.type.endsWith('-date')) return v ? fmtDate(v) : '';
  if(c.k.includes('Avantaj') && v!=='' && v!=null) return (v*100).toFixed(1)+'%';
  if((c.type.includes('num') || c.type==='formula') && v!=='' && v!=null && !isNaN(v) && c.k!=='leadTime') return Number(v).toFixed(2);
  return v==null?'':String(v);
}

// Orijinal Excel şablonundaki başlık dolgu renkleri (birebir).
const SHIP_HEADER_COLORS = {
  onay:'#FFFF00', status:'#00B0F0', talepTipi:'#00B0F0', buyerGroup:'#00B0F0', buyer:'#00B0F0',
  category:'#00B0F0', line:'#00B0F0', retailDate:'#00B0F0', opd:'#00B0F0', exFactory:'#FFC000',
  leadTime:'#00B0F0', specialCode:'#00B0F0', styleName:'#00B0F0', productMainCategory:'#00B0F0',
  fit:'#00B0F0', colour:'#00B0F0', colorCode:'#00B0F0', quantity:'#FFFF00', country:'#00B0F0',
  supplier:'#00B0F0', fob:'#FF0000', suppFob:'#FF0000', kur:'#FFC000', trFiyatTl:'#FFFF00',
  trFiyatUsd:'#FFFF00', trFiyatFobUsdLanded:'#FFFF00', ydFiyatUsd:'#FFFF00', ydFiyatUsdLandedGemi:'#FFFF00',
  ydFiyatUsdLandedGemiUcak:'#FFFF00', ydFiyatUsdLandedUcak:'#FFFF00', gemiAvantaj:'#FFFF00',
  gemiUcakAvantaj:'#FFFF00', ucakAvantaj:'#FFFF00', retailTrWithVessel:'#FFFF00', gemiUcakAntrepoTeslim:'#FFFF00',
  ucakAntrepoTeslim:'#FFFF00', nihaiVasitaKarar:'#FFC000', retailTarihPblTalep:'#FFC000', retailAyPblTalep:'#FFC000',
  modelButceIstenenGun:'#FFC000', gecikmeSonrasiAntrepo:'#FFC000', siparisGecilenGrup:'#FFC000',
  ucakNavlunKimOdeyecek:'#FFC000', ucakYuklemeSebebi:'#FFC000', acilIhtiyacVarMi:'#FFC000',
  hizliGemiDegerlendirildiMi:'#FFC000', orderCode:'#D9D9D9',
};
/* ---------------------------------------------------------------------------
   KARAR KARTLARI.

   Sayfanın asıl sorusu tek: bu siparişi TR'de mi ürettirmeli, yoksa yurtdışında
   üretip Gemi / Gemi+Uçak / Uçak ile mi getirmeli? Bu karşılaştırma 47 sütunluk
   tabloda üç ayrı avantaj sütunu ve üç ayrı teslim tarihi olarak dağılmış
   durumdaydı; kullanıcı seçenekleri gözüyle eşleştirmek zorundaydı.

   Kartlar dört seçeneği yan yana koyar ve iki rozet basar: EN UCUZ (birim landed
   fiyata göre) ve EN ERKEN (tahmini antrepo teslim tarihine göre). İkisi aynı
   karttaysa karar açıktır; farklıysa gerçek ödünleşim görünür hâle gelir.

   Kartlar yalnız GÖSTERİR: hiçbir değeri değiştirmez, karar alanını doldurmaz.
   Nihai Vasıta PBL Karar elle girilmeye devam eder.
--------------------------------------------------------------------------- */
function shipMoney(v){
  if(v==null||v===''||!Number.isFinite(Number(v))) return '—';
  return '$'+Number(v).toLocaleString(appLang==='en'?'en-GB':'tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2});
}
function shipTotal(v){
  if(v==null||!Number.isFinite(Number(v))) return null;
  const n=Number(v);
  return (n>0?'+':(n<0?'−':''))+'$'+Math.abs(n).toLocaleString(appLang==='en'?'en-GB':'tr-TR',{maximumFractionDigits:0});
}
function shipPct(v){
  if(v===''||v==null||!Number.isFinite(Number(v))) return null;
  const n=Number(v)*100;
  return (n>0?'+':'')+n.toFixed(1)+'%';
}

/*
 * Fiyat kartları soldan sağa sabit sıradadır:
 * FOB / Domestic FOB / SEA Landed / SEA+AIR Landed / AIR Landed.
 * Domestic FOB yüzde karşılaştırmasının referansıdır. Ham FOB karar alternatifi
 * değildir; fiyat zincirinin başlangıcını aynı hizada göstermek için eklenmiştir.
 * Elle girilen değerler kendi kartında, Ex-Factory kompakt model şeridinde kalır.
 */
function shipDecisionOptions(row){
  const tr=appLang!=='en';
  const num=v=>(v===''||v==null||!Number.isFinite(Number(v)))?null:Number(v);
  const trUnit=num(row.trFiyatUsd);
  const fob=num(row.fob);
  const qty=num(row.quantity);
  // Yüzdeler computeShipFormulas'ta DOMESTIC LANDED tabanıyla hesaplanır;
  // burada yeniden türetilmez ki tablo, Excel ve bu görünüm ayrışmasın.
  const days=shipTransitDays(row);
  return [
    {key:'fob', name:tr?'Overseas FOB':'Overseas FOB', source:true, decision:false, priceOnly:true,
     unit:fob, pct:null, date:null},
    {key:'tr', name:tr?'Domestic Landed':'Domestic Landed', baseline:true, priceOnly:true,
     unit:num(row.trFiyatFobUsdLanded), pct:null, date:null,
     sub:trUnit!=null?(tr?'FOB '+shipMoney(trUnit):'FOB '+shipMoney(trUnit)):'',
     inputs:[{key:'trFiyatTl', label:'TL'},
             {key:'kur', label:tr?'Kur':'FX'}]},
    {key:'gemi', name:'SEA Landed',
     unit:num(row.ydFiyatUsdLandedGemi), pct:num(row.gemiAvantaj), date:row.retailTrWithVessel, transit:days['Gemi']},
    {key:'gemiUcak', name:'SEA+AIR Landed',
     unit:num(row.ydFiyatUsdLandedGemiUcak), pct:num(row.gemiUcakAvantaj), date:row.gemiUcakAntrepoTeslim, transit:days['Gemi+Uçak'],
     inputs:[{key:'ydFiyatUsdLandedGemiUcak', label:'USD'}]},
    {key:'ucak', name:'AIR Landed',
     unit:num(row.ydFiyatUsdLandedUcak), pct:num(row.ucakAvantaj), date:row.ucakAntrepoTeslim, transit:days['Uçak'],
     inputs:[{key:'ydFiyatUsdLandedUcak', label:'USD'}]},
  ];
}

function shipCardInput(row,key,label,type){
  const canEdit=row._canEdit!==false;
  const raw=row[key]==null?'':row[key];
  const value=type==='date'?String(raw||''):(key==='kur'?shipRateDisplay(raw):String(raw));
  return `<label class="shipField">
    <span>${escapeHtml(label)}</span>
    <input type="${type==='date'?'date':'text'}" ${type==='date'?'':'inputmode="decimal"'}
      class="shipCardInput" data-shipid="${escapeHtml(String(row._shipId))}" data-key="${escapeHtml(key)}"
      value="${escapeHtml(value)}" ${canEdit?'':'disabled'}>
  </label>`;
}

function shipParseEditorValue(inp,col){
  if(!inp||!col) return {ok:false,value:''};
  let value=inp.value;
  if(col.type.endsWith('num')){
    const source=String(value==null?'':value).trim().replace(/[\s\u00a0]/g,'');
    if(!source) return {ok:true,value:''};
    const normalized=normalizeDecimalText(source);
    const parsed=Number(normalized);
    if(!Number.isFinite(parsed)) return {ok:false,value:null};
    value=col.k==='kur'?shipRoundHalfUp2(parsed):parsed;
  }
  return {ok:true,value};
}
function shipRowByEditor(inp){
  const id=inp&&inp.dataset?String(inp.dataset.shipid||''):'';
  return shipRows.find(row=>String(row&&row._shipId||'')===id)||null;
}
function shipDecisionState(row){
  const options=shipDecisionOptions(row);
  // Ham FOB bir taşıma alternatifi değildir; yalnız fiyat sırasının ilk referansıdır.
  // Bu nedenle "En ucuz" kararı Domestic/SEA/SEA+AIR/AIR seçenekleri arasında verilir.
  const priced=options.filter(option=>option.unit!=null&&option.decision!==false);
  const cheapest=priced.length?Math.min(...priced.map(option=>option.unit)):null;
  const dated=options.filter(option=>option.date);
  const earliest=dated.length?dated.map(option=>option.date).sort()[0]:null;
  return {options,cheapest,earliest};
}
function shipDecisionBadges(option,state,tr){
  // Sea/Sea+AIR/Air kartlarında "En ucuz"/"En erken" rozetleri artık basılmaz:
  // kullanıcı kararı fiyatı doğrudan Overseas FOB ile aynı görsel ağırlıkta
  // okuyarak verir. state.cheapest/state.earliest hâlâ hesaplanıyor — kopyalama
  // (shipComparisonClipboardRows) bu değerleri kullanmaya devam ediyor.
  const badges=[];
  if(option.source) badges.push(`<i class="shipBadge isSource">${tr?'Kaynak':'Source'}</i>`);
  if(option.baseline) badges.push(`<i class="shipBadge isBase">${tr?'Referans':'Baseline'}</i>`);
  return badges.join('');
}
function shipMetricEmpty(text){ const value=String(text==null?'':text).trim(); return !value||value==='—'; }
function shipSetPreviewValue(node,text,className=''){
  if(!node) return;
  node.textContent=text;
  node.classList.remove('isGood','isBad');
  if(className) node.classList.add(className);
  // Yoğun satırda boş metrik satır yüksekliği yemesin.
  node.classList.toggle('isEmpty',shipMetricEmpty(text));
}
function previewShipCardInput(inp){
  const row=shipRowByEditor(inp);
  if(!row) return false;
  const key=inp.dataset.key;
  const col=SHIP_COLS.find(item=>item.k===key);
  if(!col) return false;
  const parsed=shipParseEditorValue(inp,col);
  inp.classList.toggle('isInvalid',!parsed.ok);
  if(!parsed.ok) return false;

  const preview={...row,[key]:parsed.value};
  computeShipFormulas(preview);
  const wrap=inp.closest('.shipRowCards');
  if(!wrap) return false;
  const tr=appLang!=='en';
  const state=shipDecisionState(preview);
  state.options.forEach(option=>{
    const card=wrap.querySelector(`.shipCard[data-ship-option="${option.key}"]`);
    if(!card) return;
    card.classList.toggle('isMissing',option.unit==null);
    const badges=card.querySelector('[data-ship-badges]');
    if(badges) badges.innerHTML=shipDecisionBadges(option,state,tr);
    shipSetPreviewValue(card.querySelector('[data-ship-unit]'),shipMoney(option.unit));
    // Transit ve tarih fiyat sütunlarında yoktur; boş kalanlar gizli kalır.
    const pctClass=option.pct==null?'':(option.pct<0?'isGood':(option.pct>0?'isBad':''));
    shipSetPreviewValue(card.querySelector('[data-ship-pct]'),shipPct(option.pct)||'—',pctClass);
    const totalClass=option.total==null?'':(option.total<0?'isGood':(option.total>0?'isBad':''));
    shipSetPreviewValue(card.querySelector('[data-ship-total]'),shipTotal(option.total)||'—',totalClass);
    shipSetPreviewValue(card.querySelector('[data-ship-date]'),option.date?fmtDate(option.date):'—');
  });
  const transit=wrap.querySelector('[data-ship-transit]');
  if(transit){
    const days=shipTransitDays(preview);
    const ruleBased=Object.values(days._source||{}).some(value=>value==='rule');
    transit.innerHTML=`<b>${tr?'Transit':'Transit'}</b><span>SEA ${days['Gemi']} · SEA+AIR ${days['Gemi+Uçak']} · AIR ${days['Uçak']} ${tr?'gün':'days'}</span>${ruleBased?'':`<i>${tr?'varsayılan':'default'}</i>`}`;
  }
  return true;
}

// Model bilgisi artık fiyat kartlarının solunda geniş bir kart kaplamaz.
// Tek satırlık kompakt şerit, aşağıdaki beş fiyat kartına daha fazla yatay alan bırakır.
function shipRowImageRef(row){
  if(!row) return '';
  const stored=String(row._imageRef||'').trim();
  try{
    const map=(state&&state.overrides&&state.overrides.imagemap)||{};
    // Harita bu PLM hakkında BİR ŞEY biliyorsa (dolu kayıt ya da mezar taşı)
    // canlı sonuç doğrudur: CP'de silinen görsel burada da silinmiş görünmeli.
    // Bilmiyorsa aktarım anındaki referans kullanılır.
    const known=row.plm?cpPlmImageKeysFor(map,row.plm).length>0:false;
    const live=cpImageRefFromOverride(state&&state.overrides,row.plm,row.colorCode,row.orderCode,row.styleName,row.colorCode,row.colour||row.color||'')||'';
    if(known) return live;
    return live||stored;
  }catch(_){ return stored; }
}
function shipModelCard(row){
  const tr=appLang!=='en';
  const qty=toNum(row.quantity);
  const ref=shipRowImageRef(row);
  const imageUrl=ref?`${CP_IMAGE_API}/${encodeURIComponent(ref)}`:'';
  // Ürün sütunu: tanım üstte, künye altta. Sezon/ülke/üretici/adet tek satırda
  // akar; ayrı ayrı sütun açmak tabloyu yatayda gereksiz uzatıyordu.
  const identity=[row.season,row.country,row.supplier].map(v=>String(v||'').trim()).filter(Boolean);
  const dates=[
    ['OPD', row.opd?fmtDate(row.opd):''],
    ['Ex-Fac.', row.exFactory?fmtDate(row.exFactory):''],
    ['Retail', row.retailDate?fmtDate(row.retailDate):''],
  ];
  // Ex-Factory artık her zaman görünen ayrı bir giriş taşımaz: tarih satırının
  // kendisi çift tıklamayla açılan bir düzenleyicidir (bkz. renderShipDecision).
  return `<td class="shipCellChk"><input type="checkbox" class="shipCompareChk" data-shipid="${escapeHtml(String(row._shipId))}" ${shipSelected.has(row._shipId)?'checked':''} ${row._canEdit===false?'disabled':''}></td>
    <td class="shipCellImage">${detailImageThumbHtml(imageUrl,{modelId:row.plm||row.styleName,plmId:row.plm||'',modelName:row.styleName||'',colourCode:row.colorCode||'',colour:row.colour||''},{classes:'shipThumb',allowEmpty:true,title:tr?'Büyük önizleme için üzerine gelin':'Hover for large preview'})}</td>
    <td class="shipCellProduct">
      <div class="shipProductName" title="${escapeHtml(row.styleName||row.orderCode||'')}">${escapeHtml(row.styleName||row.orderCode||'—')}</div>
      <div class="shipProductSub">${escapeHtml(String(row.orderCode||''))}${row.colour?' · '+escapeHtml(row.colour):''}${row.colorCode?' ('+escapeHtml(row.colorCode)+')':''}</div>
      <div class="shipProductMeta" title="${escapeHtml(identity.join(' · '))}">${escapeHtml(identity.join(' · ')||'—')}</div>
      <div class="shipProductQty">${qty!=null?escapeHtml(qty.toLocaleString(tr?'tr-TR':'en-GB')):'—'} ${tr?'adet':'pcs'}${row.category?' · '+escapeHtml(row.category):''}</div>
    </td>
    <td class="shipCellDates">
      ${dates.map(([k,v])=>`<div class="shipDateRow${k==='Ex-Fac.'?' shipDateEditable':''}"${k==='Ex-Fac.'?' data-ship-exfac':''} title="${k==='Ex-Fac.'?escapeHtml(tr?'Değiştirmek için çift tıkla':'Double-click to edit'):''}"><span>${escapeHtml(k)}</span><b>${escapeHtml(v||'—')}</b></div>`).join('')}
      ${shipCardInput(row,'exFactory','','date')}
    </td>`;
}

// Sea+AIR ve Air'in kendi girişleri (tek alan) varsayılan gizli: fiyata çift
// tıklanınca açılır. Domestic Landed'in TL+Kur girişi kapsam dışı, hep açık kalır.
const SHIP_PRICE_EDITABLE_KEYS=new Set(['gemiUcak','ucak']);
function shipCompareCards(row){
  const tr=appLang!=='en';
  const state=shipDecisionState(row);

  return state.options.map(option=>{
    const missing=option.unit==null;
    const priceEditable=SHIP_PRICE_EDITABLE_KEYS.has(option.key);
    const inputs=(option.inputs||[]).map(field=>shipCardInput(row,field.key,field.label,'num')).join('');
    const priceText=shipMoney(option.unit);
    const pctText=shipPct(option.pct);
    const pctClass=option.pct==null?'':(option.pct<0?'isGood':(option.pct>0?'isBad':''));
    const dateText=option.date?fmtDate(option.date):'';
    // Ana değer artık TÜM sütunlarda fiyattır — Overseas FOB ile aynı görsel
    // ağırlık. Yüzde ikinci sıraya, metrik satırına indi.
    const head=`<b class="shipCardPrice" data-ship-unit>${priceText}</b>`;
    const sub=option.priceOnly
      ? `<span class="shipCardRow${option.sub?'':' isEmpty'}">${escapeHtml(option.sub||'')}</span><span class="shipCardRow isEmpty" data-ship-pct></span><span class="shipCardRow isEmpty" data-ship-date></span><span class="shipCardRow isEmpty" data-ship-total></span>`
      : `<span class="shipCardRow ${pctClass}" data-ship-pct>${pctText||'—'}</span><span class="shipCardRow${dateText?'':' isEmpty'}" data-ship-date title="${escapeHtml(tr?'Tahmini antrepo giriş':'Est. warehouse arrival')}">${escapeHtml(dateText)}</span><span class="shipCardRow shipTransit" title="${escapeHtml(tr?'Transit süresi':'Transit time')}">${Number(option.transit)||0}${tr?'g':'d'}</span><span class="shipCardRow isEmpty" data-ship-total></span>`;
    return `<td class="shipCard${option.source?' isSource':''}${option.baseline?' isBaseline':''}${option.priceOnly?' isPriceOnly':''}${missing?' isMissing':''}${priceEditable?' isPriceEditable':''}" data-ship-option="${escapeHtml(option.key)}">
      <div class="shipCardTop">${head}<span class="shipCardBadges" data-ship-badges>${shipDecisionBadges(option,state,tr)}</span></div>
      <div class="shipCardMetrics">${sub}</div>
      ${inputs?`<div class="shipCardInputs">${inputs}</div>`:''}
    </td>`;
  }).join('');
}
/*
 * v9.17 — HER MODEL TEK SATIR.
 *
 * Önceki düzen model başına iki katmanlı bir kart öbeği çiziyordu: geniş model
 * kartı + altında beş fiyat kartı. Model başına ~170px yüksekliğe mal oluyor,
 * ekrana üç dört model sığıyordu. Oysa sayfanın işi KARŞILAŞTIRMA; karşılaştırma
 * ise ancak değerler aynı sütunda alt alta hizalandığında gözle yapılabilir.
 *
 * Artık gerçek bir tablo var. Sütun sırası değişmez:
 *   Model | Bilgi | Ex-Factory | Transit | FOB | Domestic FOB | SEA | SEA+AIR | AIR
 * Fiyat hücreleri Koleksiyon'daki Endeksmatik hücresinin desenini izler: ana
 * değer kalın, altında küçük puntoda oran/fark/tarih, durum yalnız minimal
 * rozetle. Seçenek adı hücrede TEKRARLANMAZ — sütun başlığı zaten söylüyor.
 *
 * Hesaplama, düzenleme ve canlı önizleme sözleşmesi AYNEN korundu:
 * .shipRowCards sarmalayıcı, .shipCard[data-ship-option], .shipCardInput ve
 * data-ship-unit/pct/total/date/badges kancalarının hepsi yerinde.
 */
// Kart listesi uzun olabildiği için tablo gizlenebilir. Tablo, kartlarda
// olmayan onlarca manuel alanın girildiği yer; bu yüzden varsayılan olarak açık.
let shipTableHidden=false;
function applyShipTableVisibility(){
  const panel=document.getElementById('shipTablePanel');
  const btn=document.getElementById('shipTableToggle');
  if(panel) panel.style.display=shipTableHidden?'none':'';
  if(btn){
    btn.setAttribute('aria-pressed',shipTableHidden?'false':'true');
    const span=btn.querySelector('span');
    if(span) span.textContent=appLang==='en'?(shipTableHidden?'Show Table':'Hide Table'):(shipTableHidden?'Tabloyu Göster':'Tabloyu Gizle');
  }
}
document.getElementById('shipResetWidthsBtn')?.addEventListener('click',()=>resetShipCompareWidths());
document.getElementById('shipHiddenRowsBtn')?.addEventListener('click', e=>{
  e.preventDefault(); e.stopPropagation();
  const panel=document.getElementById('shipHiddenRowsPanel');
  toggleColumnPanel(panel, ()=>renderShipHiddenRowsPanel(panel), e.currentTarget);
});
document.getElementById('shipCopyCompareBtn')?.addEventListener('click',event=>void copyShipComparison(event.currentTarget));
document.getElementById('shipTableToggle')?.addEventListener('click',()=>{
  shipTableHidden=!shipTableHidden;
  applyShipTableVisibility();
});

const SHIP_COMPARE_WIDTH_KEY='buyerlog.shipCompare.colWidths.v1';
/* Varsayılanlar içeriğe göre ölçüldü: girişi olan sütun daha geniş, ham fiyat
   sütunu dar. Başlık metni de sığmalı, yoksa iki satıra kırılıp satırı uzatır. */
const SHIP_COMPARE_COLUMNS=[
  {key:'chk',      def:34,  min:30},
  {key:'image',    def:62,  min:44},
  {key:'product',  def:214, min:150},
  {key:'dates',    def:120, min:96},
  {key:'fob',      def:104, min:76},
  {key:'tr',       def:150, min:104},
  {key:'gemi',     def:118, min:88},
  {key:'gemiUcak', def:132, min:104},
  {key:'ucak',     def:132, min:104},
];
let _shipCompareWidths=null;
function shipCompareWidths(){
  if(_shipCompareWidths) return _shipCompareWidths;
  let saved={};
  try{ saved=JSON.parse(BLStorage.getItem(SHIP_COMPARE_WIDTH_KEY)||'{}')||{}; }catch(_){ saved={}; }
  _shipCompareWidths={};
  for(const column of SHIP_COMPARE_COLUMNS){
    const value=Number(saved[column.key]);
    _shipCompareWidths[column.key]=Number.isFinite(value)&&value>0?Math.max(column.min,value):column.def;
  }
  return _shipCompareWidths;
}
function saveShipCompareWidths(){
  try{ BLStorage.setItem(SHIP_COMPARE_WIDTH_KEY,JSON.stringify(shipCompareWidths())); }catch(_){}
}
function shipCompareColgroup(){
  const widths=shipCompareWidths();
  return `<colgroup>${SHIP_COMPARE_COLUMNS.map(column=>`<col data-ship-col="${column.key}" style="width:${widths[column.key]}px">`).join('')}</colgroup>`;
}
/* Genişliği colgroup üzerinden uygular. Sürükleme sırasında tablo yeniden
   ÇİZİLMEZ: binlerce hücreyi her fare hareketinde yeniden kurmak sürüklemeyi
   takılgan yapar, ayrıca odaktaki giriş alanı kaybolurdu. */
function applyShipCompareWidths(){
  const table=document.querySelector('.shipCompare');
  if(!table) return;
  const widths=shipCompareWidths();
  let total=0;
  for(const column of SHIP_COMPARE_COLUMNS){
    total+=widths[column.key];
    const col=table.querySelector(`col[data-ship-col="${column.key}"]`);
    if(col) col.style.width=widths[column.key]+'px';
  }
  table.style.minWidth=total+'px';
}
function attachShipCompareResize(){
  const table=document.querySelector('.shipCompare');
  if(!table) return;
  SHIP_COMPARE_COLUMNS.forEach((column,index)=>{
    const th=table.querySelectorAll('thead th')[index];
    if(!th||th.querySelector('.colResizer')) return;
    const grip=document.createElement('div');
    grip.className='colResizer';
    grip.title=appLang==='en'?'Drag to resize · double-click to reset':'Sürükleyip genişliği ayarla · sıfırlamak için çift tıkla';
    th.appendChild(grip);
    grip.addEventListener('mousedown',event=>{
      event.preventDefault(); event.stopPropagation();
      const startX=event.clientX, startPx=shipCompareWidths()[column.key];
      const onMove=move=>{
        shipCompareWidths()[column.key]=Math.max(column.min,startPx+(move.clientX-startX));
        applyShipCompareWidths();
      };
      const onUp=()=>{
        saveShipCompareWidths();
        document.removeEventListener('mousemove',onMove);
        document.removeEventListener('mouseup',onUp);
      };
      document.addEventListener('mousemove',onMove);
      document.addEventListener('mouseup',onUp);
    });
    grip.addEventListener('dblclick',event=>{
      event.preventDefault(); event.stopPropagation();
      shipCompareWidths()[column.key]=column.def;
      applyShipCompareWidths(); saveShipCompareWidths();
    });
  });
}
function syncShipSelectionUi(){
  document.querySelectorAll('.shipCompareChk').forEach(box=>{
    box.checked=shipSelected.has(box.dataset.shipid);
  });
  document.querySelectorAll('.shipRowChk').forEach(box=>{
    box.checked=shipSelected.has(box.dataset.shipid);
  });
  const all=document.querySelector('[data-ship-chk-all]');
  if(all){
    const selectable=shipRows.filter(row=>row._canEdit!==false);
    const chosen=selectable.filter(row=>shipSelected.has(row._shipId)).length;
    all.checked=selectable.length>0&&chosen===selectable.length;
    all.indeterminate=chosen>0&&chosen<selectable.length;
  }
  document.querySelectorAll('#shipTable thead input[type="checkbox"]').forEach(box=>{
    if(box.dataset.shipid==null&&!box.hasAttribute('data-ship-chk-all')){
      box.checked=shipRows.length>0&&shipRows.every(row=>shipSelected.has(row._shipId));
    }
  });
  updateShipSelectionActions();
  const count=document.getElementById('shipCount');
  if(count&&shipSelected.size) count.dataset.shipSelected=String(shipSelected.size);
}
function bindShipCompareSelection(host){
  host.querySelectorAll('.shipCompareChk').forEach(box=>{
    box.addEventListener('change',()=>{
      if(box.checked) shipSelected.add(box.dataset.shipid); else shipSelected.delete(box.dataset.shipid);
      syncShipSelectionUi();
    });
  });
  const all=host.querySelector('[data-ship-chk-all]');
  if(all) all.addEventListener('change',()=>{
    shipRows.forEach(row=>{
      if(row._canEdit===false) return;
      if(all.checked) shipSelected.add(row._shipId); else shipSelected.delete(row._shipId);
    });
    syncShipSelectionUi();
  });
}
function resetShipCompareWidths(){
  const widths=shipCompareWidths();
  SHIP_COMPARE_COLUMNS.forEach(column=>{ widths[column.key]=column.def; });
  applyShipCompareWidths(); saveShipCompareWidths();
  showToast(appLang==='en'?'Column widths reset.':'Sütun genişlikleri sıfırlandı.');
}
function shipCompareHeadCells(){
  const tr=appLang!=='en';
  /* Ad ve statik rol yalnız başlıkta yazılır; satırda tekrarlanmaz.
     İlk iki sütun FİYAT, son üçü AVANTAJ sütunudur. */
  const columns=[
    {key:'fob', name:tr?'Overseas FOB':'Overseas FOB', role:tr?'Kaynak':'Source'},
    {key:'tr', name:tr?'Domestic Landed':'Domestic Landed', role:tr?'Taban':'Baseline'},
    {key:'gemi', name:'SEA Landed'},
    {key:'gemiUcak', name:'SEA+AIR Landed'},
    {key:'ucak', name:'AIR Landed'},
  ];
  return columns.map(column=>`<th class="shipColPrice" data-ship-col="${escapeHtml(column.key)}">
    <span>${escapeHtml(column.name)}</span>${column.role?`<i class="shipBadge ${column.key==='fob'?'isSource':'isBase'}">${escapeHtml(column.role)}</i>`:''}
  </th>`).join('');
}
/* Kopyalanabilir çıktı: Excel ve Outlook text/html'i olduğu gibi alır, bu
   yüzden tabloyu satır içi stille yeniden kurarız (dış CSS gitmez). Görsel
   mutlak URL'e çevrilir; aksi hâlde e-postada kırık görünür. */
/* Kopyalanacak küme: işaretli satır varsa yalnız onlar, yoksa tümü. */
function shipCopyRows(){
  const chosen=shipRows.filter(row=>shipSelected.has(row._shipId));
  return chosen.length?chosen:shipRows;
}

/* Üst Shipping Comparison tablosunun Excel-ready clipboard modeli.
   DOM scrape edilmez: görünümü besleyen aynı shipRows + hesaplama state'i kullanılır.
   Her model tam olarak bir satırdır; görsel ve çok satırlı UI metinleri clipboard'a
   taşınmaz. */
function shipComparisonClipboardColumns(){
  const tr=appLang!=='en';
  return [
    {key:'orderCode',label:'Order Code'},
    {key:'styleName',label:'Style Name'},
    {key:'colour',label:tr?'Renk':'Colour'},
    {key:'colorCode',label:tr?'Renk Kodu':'Colour Code'},
    {key:'season',label:tr?'Sezon':'Season'},
    {key:'country',label:tr?'Ülke':'Country'},
    {key:'supplier',label:tr?'Üretici':'Supplier'},
    {key:'quantity',label:tr?'Adet':'Quantity'},
    {key:'category',label:tr?'Klasman':'Category'},
    {key:'opd',label:'OPD'},
    {key:'exFactory',label:'Ex-Factory'},
    {key:'retailDate',label:'Retail Date'},
    {key:'fob',label:'Overseas FOB'},
    {key:'domesticFob',label:'Domestic FOB'},
    {key:'domesticLanded',label:'Domestic Landed'},
    {key:'seaLanded',label:'SEA Landed'},
    {key:'seaSavingPct',label:'SEA Saving %'},
    {key:'seaEta',label:'SEA ETA'},
    {key:'seaTransit',label:tr?'SEA Transit Gün':'SEA Transit Days'},
    {key:'seaAirLanded',label:'SEA+AIR Landed'},
    {key:'seaAirSavingPct',label:'SEA+AIR Saving %'},
    {key:'seaAirEta',label:'SEA+AIR ETA'},
    {key:'seaAirTransit',label:tr?'SEA+AIR Transit Gün':'SEA+AIR Transit Days'},
    {key:'airLanded',label:'AIR Landed'},
    {key:'airSavingPct',label:'AIR Saving %'},
    {key:'airEta',label:'AIR ETA'},
    {key:'airTransit',label:tr?'AIR Transit Gün':'AIR Transit Days'},
    {key:'cheapest',label:tr?'En Ucuz':'Cheapest'},
    {key:'earliest',label:tr?'En Erken':'Earliest'},
  ];
}
function shipClipboardScalar(value){
  if(value==null||value==='') return '';
  if(typeof value==='number') return Number.isFinite(value)?String(value):'';
  if(value instanceof Date) return isNaN(value)?'':toISODate(value);
  return String(value).replace(/[\t\r\n]+/g,' ').trim();
}
function shipComparisonClipboardRows(){
  return shipCopyRows().map(source=>{
    // Copy daima kullanıcının o anda gördüğü hesapla aynı sonucu versin.
    const row=computeShipFormulas(source);
    const state=shipDecisionState(row);
    const byKey=Object.fromEntries(state.options.map(option=>[option.key,option]));
    const sea=byKey.gemi||{}, seaAir=byKey.gemiUcak||{}, air=byKey.ucak||{}, domestic=byKey.tr||{}, fob=byKey.fob||{};
    const cheapest=state.options.filter(option=>option.decision!==false&&option.unit!=null&&state.cheapest!=null&&option.unit===state.cheapest).map(option=>option.name).join(' / ');
    const earliest=state.options.filter(option=>option.date&&state.earliest&&option.date===state.earliest).map(option=>option.name).join(' / ');
    const pct=value=>value==null||value===''||!Number.isFinite(Number(value))?'':`${(Number(value)*100).toFixed(1)}%`;
    return {
      orderCode:row.orderCode, styleName:row.styleName, colour:row.colour, colorCode:row.colorCode,
      season:row.season, country:row.country, supplier:row.supplier, quantity:toNum(row.quantity), category:row.category,
      opd:row.opd?toISODate(coerceDateLoose(row.opd)):'', exFactory:row.exFactory?toISODate(coerceDateLoose(row.exFactory)):'', retailDate:row.retailDate?toISODate(coerceDateLoose(row.retailDate)):'',
      fob:fob.unit, domesticFob:toNum(row.trFiyatUsd), domesticLanded:domestic.unit,
      seaLanded:sea.unit, seaSavingPct:pct(sea.pct), seaEta:sea.date||'', seaTransit:sea.transit,
      seaAirLanded:seaAir.unit, seaAirSavingPct:pct(seaAir.pct), seaAirEta:seaAir.date||'', seaAirTransit:seaAir.transit,
      airLanded:air.unit, airSavingPct:pct(air.pct), airEta:air.date||'', airTransit:air.transit,
      cheapest, earliest,
    };
  });
}
function shipComparisonClipboardMatrix(){
  const columns=shipComparisonClipboardColumns(), rows=shipComparisonClipboardRows();
  return [columns.map(column=>column.label), ...rows.map(row=>columns.map(column=>shipClipboardScalar(row[column.key])))];
}
function shipComparisonFlatPlain(){
  return shipComparisonClipboardMatrix().map(row=>row.join('\t')).join('\n');
}
function shipComparisonFlatHtml(){
  const matrix=shipComparisonClipboardMatrix();
  const border='border:1px solid #d0d5dd;padding:4px 6px;font-family:Arial,sans-serif;font-size:11px;white-space:nowrap;';
  const head=(matrix[0]||[]).map(value=>`<th style="${border}background:#f2f4f7;text-align:left">${escapeHtml(value)}</th>`).join('');
  const body=matrix.slice(1).map(row=>`<tr>${row.map(value=>`<td style="${border}">${escapeHtml(value)}</td>`).join('')}</tr>`).join('');
  return `<table style="border-collapse:collapse"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table>`;
}
async function copyShipComparisonFlat(button){
  if(!shipRows.length){ showToast(appLang==='en'?'Nothing to copy.':'Kopyalanacak satır yok.'); return; }
  const count=shipCopyRows().length, partial=shipSelected.size>0;
  const ok=await copyRichToClipboard(shipComparisonFlatHtml(),shipComparisonFlatPlain());
  if(!ok){ showToast(appLang==='en'?'Copy failed.':'Kopyalanamadı.'); return; }
  showToast(appLang==='en'
    ?`${count} ${partial?'selected ':''}comparison row(s) copied.`
    :`${count} ${partial?'seçili ':''}karşılaştırma satırı kopyalandı.`);
}
function shipCopyTableHtml(){
  const tr=appLang!=='en';
  const heads=[tr?'Görsel':'Image',tr?'Ürün':'Product',tr?'Tarihler':'Dates',
    'Overseas FOB','Domestic Landed','SEA Landed','SEA+AIR Landed','AIR Landed'];
  const border='border:1px solid #d0d5dd;padding:4px 6px;font-family:Arial,sans-serif;font-size:11px;';
  const rows=shipCopyRows().map(row=>{
    const options=shipDecisionOptions(row);
    const ref=shipRowImageRef(row);
    const image=ref?`<img src="${location.origin}${CP_IMAGE_API}/${encodeURIComponent(ref)}" width="52" height="52" style="object-fit:contain">`:'';
    const qty=toNum(row.quantity);
    const product=[escapeHtml(row.styleName||row.orderCode||''),
      escapeHtml([row.orderCode,row.colour].filter(Boolean).join(' · ')),
      escapeHtml([row.season,row.country,row.supplier].filter(Boolean).join(' · ')),
      (qty!=null?qty.toLocaleString(tr?'tr-TR':'en-GB'):'')+' '+(tr?'adet':'pcs')].filter(v=>String(v).trim()).join('<br>');
    const dates=[['OPD',row.opd],['Ex-Fac.',row.exFactory],['Retail',row.retailDate]]
      .map(([k,v])=>`${k}: ${v?fmtDate(v):'—'}`).join('<br>');
    const cells=options.map(option=>{
      if(option.priceOnly) return `<td style="${border}text-align:right">${escapeHtml(shipMoney(option.unit))}</td>`;
      const parts=[`<b>${escapeHtml(shipPct(option.pct)||'—')}</b>`, escapeHtml(shipMoney(option.unit))];
      if(option.date) parts.push(escapeHtml(fmtDate(option.date)));
      parts.push(`${Number(option.transit)||0}${tr?'g':'d'}`);
      return `<td style="${border}text-align:right">${parts.join('<br>')}</td>`;
    }).join('');
    return `<tr><td style="${border}">${image}</td><td style="${border}">${product}</td><td style="${border}">${dates}</td>${cells}</tr>`;
  }).join('');
  const head=heads.map(h=>`<th style="${border}background:#f2f4f7;text-align:left">${escapeHtml(h)}</th>`).join('');
  return `<table style="border-collapse:collapse"><thead><tr>${head}</tr></thead><tbody>${rows}</tbody></table>`;
}
function shipCopyTablePlain(){
  const tr=appLang!=='en';
  const heads=[tr?'Görsel':'Image',tr?'Ürün':'Product',tr?'Tarihler':'Dates','Overseas FOB','Domestic Landed','SEA Landed','SEA+AIR Landed','AIR Landed'];
  const lines=[heads.join('\t')];
  for(const row of shipCopyRows()){
    const options=shipDecisionOptions(row);
    const qty=toNum(row.quantity);
    const cells=options.map(option=>option.priceOnly?shipMoney(option.unit)
      :[shipPct(option.pct)||'—',shipMoney(option.unit),option.date?fmtDate(option.date):'',`${Number(option.transit)||0}${tr?'g':'d'}`].filter(Boolean).join(' '));
    lines.push(['',
      [row.styleName,row.orderCode,row.colour,row.season,row.country,row.supplier,qty!=null?qty:''].filter(v=>String(v||'').trim()).join(' · '),
      [['OPD',row.opd],['Ex-Fac.',row.exFactory],['Retail',row.retailDate]].map(([k,v])=>`${k}: ${v?fmtDate(v):'—'}`).join(' '),
      ...cells].join('\t'));
  }
  return lines.join('\n');
}
async function copyShipComparison(button){
  if(!shipRows.length){ showToast(appLang==='en'?'Nothing to copy.':'Kopyalanacak satır yok.'); return; }
  const count=shipCopyRows().length, partial=shipSelected.size>0;
  const ok=await copyRichToClipboard(shipCopyTableHtml(),shipCopyTablePlain());
  if(!ok){ showToast(appLang==='en'?'Copy failed.':'Kopyalanamadı.'); return; }
  // Kaç satırın kopyalandığı söylenmeli: kullanıcı seçim yaptığını sanıp
  // tabloyu bütün kopyalamış olabilir.
  showToast(appLang==='en'
    ?`${count} ${partial?'selected ':''}row(s) copied — paste into Excel or an e-mail.`
    :`${count} ${partial?'seçili ':''}satır kopyalandı — Excel'e veya e-postaya yapıştırabilirsiniz.`);
}
function renderShipDecision(){
  const host=document.getElementById('shipDecision');
  if(!host) return;
  if(!shipRows.length){ host.hidden=true; host.innerHTML=''; updateShipHiddenRowsUi(); return; }
  host.hidden=false;
  const visibleRows=shipVisibleRows();
  host.innerHTML=`<div class="tablewrap shipCompareWrap"><table class="shipCompare">
    ${shipCompareColgroup()}
    <thead><tr>
      <th class="shipColChk"><input type="checkbox" data-ship-chk-all aria-label="${appLang==='en'?'Select all':'Tümünü seç'}"></th>
      <th class="shipColImage">${appLang==='en'?'Image':'Görsel'}</th>
      <th class="shipColProduct">${appLang==='en'?'Product':'Ürün'}</th>
      <th class="shipColDates">${appLang==='en'?'Dates':'Tarihler'}</th>
      ${shipCompareHeadCells()}
    </tr></thead>
    <tbody>${visibleRows.map(row=>`<tr class="shipRowCards" data-shipid="${escapeHtml(String(row._shipId))}" draggable="true">${shipModelCard(row)}${shipCompareCards(row)}</tr>`).join('')}</tbody>
  </table></div>`;

  // Shipping de ortak contextual PLM image contract'ına katılır. Filtre/gizli
  // satır durumu renderShipDecision içinde zaten korunur; sync sonrası yalnız
  // bu görünüm yeniden çizilir.
  registerModelAssetScopeHost(host,{contextType:'shipping-comparison',label:appLang==='en'?'Shipping Comparison':'Nakliye Kıyaslama',identities:visibleRows.map((row,index)=>({plmId:row.plm||'',styleName:row.styleName||'',colourCode:row.colorCode||'',colour:row.colour||'',rowId:String(row._shipId??index),hasImage:null})),repaint:renderShipDecision});
  bindDetailModelThumbs(host);
  applyShipCompareWidths();
  attachShipCompareResize();
  bindShipCompareSelection(host);
  syncShipSelectionUi();
  applyShipTableVisibility();
  updateShipHiddenRowsUi();
  host.querySelectorAll('.shipCardInput').forEach(inp=>{
    const collapseFieldEditors=()=>{
      inp.closest('.shipCard')?.classList.remove('isEditingPrice');
      inp.closest('.shipCellDates')?.classList.remove('isEditingExFac');
    };
    const commit=()=>{
      // Kart formülleri yazarken canlı önizlenir; change/blur aşamasında aynı
      // commit yolu tabloyu ve kalıcı kaydı birlikte günceller.
      if(commitShipEditor(inp,{rerender:true})) return;
      collapseFieldEditors();
      if(inp.classList.contains('isInvalid')) renderShipDecision();
    };
    inp.addEventListener('input',()=>previewShipCardInput(inp));
    inp.addEventListener('change',commit);
    inp.addEventListener('blur',commit);
    inp.addEventListener('keydown',event=>{
      if(event.key==='Enter'){ event.preventDefault(); inp.blur(); }
      else if(event.key==='Escape'){
        // İptal kısmi değeri KAYDETMEMELİ: girişi son çizimdeki değere geri al,
        // sonra normal blur/commit yoluna gir — değer değişmediği için kayıt olmaz.
        event.preventDefault();
        inp.value=inp.defaultValue;
        collapseFieldEditors();
        inp.blur();
      }
    });
  });
  // Sea+AIR / Air: giriş varsayılan gizli, fiyata çift tıklayınca açılır.
  host.querySelectorAll('.shipCard.isPriceEditable [data-ship-unit]').forEach(el=>{
    el.addEventListener('dblclick',()=>{
      const card=el.closest('.shipCard');
      if(!card) return;
      card.classList.add('isEditingPrice');
      const editor=card.querySelector('.shipCardInput');
      editor?.focus(); editor?.select?.();
    });
  });
  // Ex-Factory: kalıcı görünür giriş etiketi kaldırıldı, tarihin kendisine
  // çift tıklamak düzenleyiciyi açar.
  host.querySelectorAll('[data-ship-exfac]').forEach(el=>{
    el.addEventListener('dblclick',()=>{
      const cell=el.closest('.shipCellDates');
      if(!cell) return;
      cell.classList.add('isEditingExFac');
      const editor=cell.querySelector('.shipCardInput[data-key="exFactory"]');
      editor?.focus(); editor?.select?.();
    });
  });
  // Satır sürükleme: yalnız satırın kendisinden başlar, giriş/düğme/etiket
  // üzerinden başlayan bir sürükleme reddedilir (seçim kutusu dâhil).
  host.querySelectorAll('tr.shipRowCards').forEach(rowEl=>{
    rowEl.addEventListener('dragstart',event=>{
      if(event.target.closest('input,button,select,textarea,label')){ event.preventDefault(); return; }
      event.dataTransfer.effectAllowed='move';
      try{ event.dataTransfer.setData('text/plain',rowEl.dataset.shipid); }catch(_){}
      rowEl.classList.add('isDragging');
    });
    rowEl.addEventListener('dragend',()=>{
      rowEl.classList.remove('isDragging');
      host.querySelectorAll('.isDragOver').forEach(el=>el.classList.remove('isDragOver'));
    });
    rowEl.addEventListener('dragover',event=>{
      const dragging=host.querySelector('tr.shipRowCards.isDragging');
      if(!dragging||dragging===rowEl) return;
      event.preventDefault();
      event.dataTransfer.dropEffect='move';
      rowEl.classList.add('isDragOver');
    });
    rowEl.addEventListener('dragleave',()=>rowEl.classList.remove('isDragOver'));
    rowEl.addEventListener('drop',event=>{
      event.preventDefault();
      rowEl.classList.remove('isDragOver');
      const draggedId=event.dataTransfer.getData('text/plain');
      if(!draggedId||draggedId===rowEl.dataset.shipid) return;
      const rect=rowEl.getBoundingClientRect();
      const after=(event.clientY-rect.top)>rect.height/2;
      shipMoveRow(draggedId,rowEl.dataset.shipid,after);
    });
    // Sağ tık: Düzenle / Gizle / Kopyala — mevcut satır menüsü kabuğu (row-context-menu.js)
    // yeniden kullanılır, ikinci bir menü bileşeni kurulmaz.
    rowEl.addEventListener('contextmenu',event=>{
      if(!window.BLRowMenu?.render) return;
      event.preventDefault();
      const shipId=rowEl.dataset.shipid;
      const row=shipRows.find(r=>String(r._shipId)===String(shipId));
      const tr=appLang!=='en';
      const label=(row&&(row.styleName||row.orderCode))||(tr?'bu satır':'this row');
      window.BLRowMenu.render([
        {label:tr?'Düzenle':'Edit', run:()=>shipEnterRowEditMode(shipId)},
        {label:tr?'Gizle':'Hide', run:()=>shipHideRow(shipId)},
        {separator:true},
        {label:tr?'Kopyala':'Copy', run:()=>void shipCopyRowsForIds([shipId])},
      ],event.clientX,event.clientY,label);
    });
  });
}

/* Nakliye boşken satır işlemleri şeridi gizlenir; düz metin yerine CP Tracker'a
   yönlendiren ortak boş durum kartı çizilir. */
function renderShipEmptyState(empty,isEmpty){
  document.getElementById('view-shipping')?.classList.toggle('isShipEmpty',isEmpty);
  if(!isEmpty||!empty||!window.BLUI||typeof window.BLUI.renderState!=='function')return;
  const en=appLang==='en';
  window.BLUI.renderState(empty,{kind:'empty',icon:'ship',
    title:en?'No rows in the shipping comparison yet':'Nakliye kıyasında henüz satır yok',
    detail:en?'Tick rows in CP Tracker and use “Send to shipping comparison” to compare freight options here.':'CP Tracker’da satırları işaretleyip “Nakliye kıyasına aktar” ile buraya gönder; navlun seçeneklerini burada karşılaştır.',
    actionLabel:en?'Go to CP Tracker':'CP Tracker’a git',actionPrimary:true,actionOnce:false,
    onAction:()=>document.querySelector('nav.tabs button[data-tab="cp"]')?.click()});
}
function renderShipTable(){
  applyFormulaColumns('ship');
  const empty = document.getElementById('shipEmpty'), content = document.getElementById('shipContent');
  renderShipEmptyState(empty,!shipRows.length);
  if(!shipRows.length){ empty.style.display='block'; content.style.display='none'; document.getElementById('shipCount').textContent=''; updateShipSelectionActions(); return; }
  empty.style.display='none'; content.style.display='block';
  document.getElementById('shipCount').textContent = `${shipRows.length} satır`;
  updateShipSelectionActions();
  shipRows.forEach(computeShipFormulas);
  const cols = visibleCols('ship');
  const table = document.getElementById('shipTable');
  buildColgroup(table, 'ship', true);
  const thead = table.querySelector('thead');
  thead.innerHTML = '<tr><th style="padding:8px;background:var(--navy-deep);color:#fff;"><input type="checkbox" id="shipChkAll"></th>' +
    cols.map(c=>{
      const bg = SHIP_HEADER_COLORS[c.k] || '#00B0F0';
      return `<th data-k="${c.k}" style="padding:6px 8px;background:${bg};color:#000;text-align:left;font-weight:700;font-size:10.5px;">${escapeHtml(c.label)}</th>`;
    }).join('') + '</tr>';
  thead.querySelectorAll('th[data-k]').forEach(th=>{
    const key = th.dataset.k;
    attachResize(th, key, 'ship', table);
    attachDrag(th, key, 'ship', renderShipTable);
  });
  const body = document.getElementById('shipTableBody');
  body.innerHTML = shipRows.map(row=>{
    const editable = c => row._canEdit!==false && (c.type==='manual' || c.type==='manual-num' || c.type==='manual-date' || c.type==='auto' || c.type==='auto-num' || c.type==='auto-date');
    const tds = cols.map(c=>{
      if(!editable(c)){
        const lock=row._canEdit===false&&c.type!=='formula'&&c.type!=='formula-date'?'<span class="viewOnlyLock" aria-hidden="true">🔒</span> ':'';
        return `<td class="${row._canEdit===false?'viewOnlyCell':''}" style="padding:4px 8px;color:var(--muted);font-family:var(--mono);white-space:nowrap;">${lock}${escapeHtml(shipCellDisplay(c,row))}</td>`;
      }
      const isDate = c.type.endsWith('date');
      const isNum = c.type.endsWith('num');
      const val = row[c.k]==null?'':row[c.k];
      const inputType = isDate?'date':'text';
      const dispVal = isDate ? (val||'') : (c.k==='kur'?shipRateDisplay(val):val);
      const fxTitle=c.k==='kur'
        ? (row._kurManual
          ? (appLang==='en'?'Manually edited FX rate':'Elle güncellenmiş kur')
          : (row._kurResolvedMonth ? `${appLang==='en'?'FX month':'Kur ayı'}: ${row._kurResolvedMonth}${row._kurExact?'':` (${appLang==='en'?'nearest available':'en yakın mevcut'})`}` : (appLang==='en'?'Editable; Update FX uses Ex-Factory month':'Düzenlenebilir; Kur Güncelle Ex-Factory ayını kullanır')))
        : '';
      return `<td style="padding:2px 4px;"><input type="${inputType}" ${isNum?'inputmode="decimal"':''} class="shipEditCell" data-shipid="${row._shipId}" data-key="${c.k}" value="${escapeHtml(String(dispVal))}" ${fxTitle?`title="${escapeHtml(fxTitle)}"`:''} style="width:100%;border:1px solid transparent;background:transparent;font-size:11.5px;padding:3px 5px;border-radius:var(--r-xs);color:var(--table-ink);"></td>`;
    }).join('');
    return `<tr data-shipid="${row._shipId}" class="${row._canEdit===false?'rowViewOnly':''}"><td style="padding:4px 8px;"><input type="checkbox" class="shipRowChk" data-shipid="${row._shipId}" ${shipSelected.has(row._shipId)?'checked':''}></td>${tds}</tr>`;
  }).join('');

  body.querySelectorAll('.shipRowChk').forEach(chk=>{
    chk.addEventListener('change', ()=>{
      if(chk.checked) shipSelected.add(chk.dataset.shipid); else shipSelected.delete(chk.dataset.shipid);
      syncShipSelectionUi();
      updateSelectionFooterCount(table,shipRows,shipSelected,row=>row._shipId);
      updateShipSelectionActions();
    });
  });
  const chkAll = document.getElementById('shipChkAll');
  if(chkAll) chkAll.addEventListener('change', ()=>{
    shipRows.forEach(r=>{ if(chkAll.checked) shipSelected.add(r._shipId); else shipSelected.delete(r._shipId); });
    syncShipSelectionUi();
    updateShipSelectionActions();
    renderShipTable();
  });
  body.querySelectorAll('.shipEditCell').forEach(inp=>{
    inp.addEventListener('change', ()=> commitShipEditor(inp, {rerender:true}));
  });
  renderQuantityTotalsFooter(table,shipRows,cols,{withCheck:true,selectedSet:shipSelected,getId:row=>row._shipId,getValue:(row,c)=>row[c.k]});
  renderShipDecision();
}

function commitShipEditor(inp, options={}){
  const rerender = options.rerender !== false;
  if(!inp || !inp.dataset) return false;
  const row=shipRowByEditor(inp); if(!row) return false;
  if(row._canEdit===false){showToast(appLang==='en'?'You have view-only access for this order.':'Bu sipariş için yalnız görüntüleme yetkiniz var.');return false;}
  const key=inp.dataset.key;
  const col=SHIP_COLS.find(item=>item.k===key); if(!col) return false;
  const parsed=shipParseEditorValue(inp,col);
  if(!parsed.ok){
    inp.classList.add('isInvalid');
    showToast(appLang==='en'?'Enter a valid numeric value.':'Geçerli bir sayısal değer girin.');
    return false;
  }
  inp.classList.remove('isInvalid');
  const val=parsed.value;
  const prev = row[key];
  if(editableValuesEqual(prev,val)) return false;
  row[key] = val;
  const patch={[key]:val};
  if(key==='kur'){
    row._shipFxToken=(Number(row._shipFxToken)||0)+1; // bekleyen otomatik isteği iptal eder
    row._kurManual=true; row._kurUpdatedAt=new Date().toISOString();
    patch._kurManual=true; patch._kurUpdatedAt=row._kurUpdatedAt;
  }
  computeShipFormulas(row);
  patchShipRow(row._shipId, patch);
  if(typeof pushUndo==='function') pushUndo({kind:'ship', shipId:row._shipId, fields:[{key, prev, next:val}]});
  if(rerender) renderShipTable();
  if(key==='exFactory') void updateShipFxByExFactory([row],{notify:false,history:true,rerender:true});
  return true;
}

let _shipSyncTimers = {};
let _shipSyncPending = {};
function enqueueShipMutation(url,opts){
  const run=shipMutationQueue.then(()=>fetchJSON(url,{...opts,expectedRevision:shipRevision})).then(data=>{shipRevision=Number(data._revision)||shipRevision;return data;});
  shipMutationQueue=run.catch(()=>{});return run;
}
function patchShipRow(shipId, patch){
  _shipSyncPending[shipId]={...(_shipSyncPending[shipId]||{}),...(patch||{})};
  clearTimeout(_shipSyncTimers[shipId]);
  _shipSyncTimers[shipId] = setTimeout(()=>{
    const merged=_shipSyncPending[shipId]||{};
    delete _shipSyncPending[shipId]; delete _shipSyncTimers[shipId];
    enqueueShipMutation(`/api/shipping-comparison/${shipId}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(merged)})
      .catch(err=>{console.warn('Nakliye satırı kaydedilemedi:',err.message);showToast(err.message);void loadShipRows();});
  }, 500);
}

async function loadShipRows(){
  if(typeof window.BLCanAccessArea==='function'&&!window.BLCanAccessArea('shipping')) return;
  try{
    const data = await fetchJSON('/api/shipping-comparison');
    shipRows = data.rows || [];
    shipRevision=Number(data._revision)||0;
    renderShipTable();
  }catch(err){ console.warn('Nakliye verisi alınamadı:', err.message); }
}

document.getElementById('navToShipping').addEventListener('click', async ()=>{
  const selectedRows=selectedCpRowsForAction();
  if(!selectedRows || !selectedRows.length) return;
  if(window.BLFX) await BLFX.load();
  const newRows = selectedRows.map(mapCPRowToShip).filter(Boolean);
  newRows.forEach(row=>{
    const fx=shipFxInfoForExFactory(row.exFactory);
    if(Number.isFinite(fx.rate)){
      row.kur=fx.rate; row._kurRequestedMonth=fx.requestedMonth; row._kurResolvedMonth=fx.resolvedMonth;
      row._kurExact=fx.exact; row._kurManual=false; row._kurUpdatedAt=new Date().toISOString();
      computeShipFormulas(row);
    }
  });
  if(!newRows.length) return;
  try{
    const saved=await enqueueShipMutation('/api/shipping-comparison', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({rows:newRows})});
    shipRows=saved.rows||shipRows;
    showToast(`${newRows.length} satır Nakliye Kıyaslama tablosuna eklendi.`);
    state.cpSelected.clear();
    updateShippingBtnVisibility();
    renderCP();
    await loadShipRows();
    switchTab('shipping');
  }catch(err){ alert('Aktarılamadı: '+err.message); }
});

document.getElementById('shipUpdateFxBtn')?.addEventListener('click', async ()=>{
  commitActiveTableEditor({refresh:false});
  const rows=shipRows.filter(r=>shipSelected.has(r._shipId));
  if(!rows.length){ showToast(appLang==='en'?'Select rows to update FX.':'Kur güncellemek için önce satır seç.'); return; }
  if(rows.some(r=>r._canEdit===false)){showToast(appLang==='en'?'The selection contains view-only orders. Remove them before updating FX.':'Seçimde yalnız görüntülenebilen siparişler var. Kur güncellemeden önce seçimden çıkarın.');return;}
  const btn=document.getElementById('shipUpdateFxBtn');
  const old=btn.innerHTML; btn.disabled=true;
  btn.innerHTML=`<svg class="ic"><use href="#i-refresh"/></svg><span>${appLang==='en'?'Updating…':'Güncelleniyor…'}</span>`;
  try{ await updateShipFxByExFactory(rows,{notify:true,history:true,rerender:true}); }
  catch(err){ showToast((appLang==='en'?'FX update failed: ':'Kur güncellenemedi: ')+err.message); }
  finally{ btn.innerHTML=old; updateShipSelectionActions(); applyStaticI18n(); }
});

document.getElementById('shipDeleteBtn').addEventListener('click', async ()=>{
  if(!shipSelected.size){ showToast('Önce silinecek satırları işaretle.'); return; }
  const selectedRows=shipRows.filter(r=>shipSelected.has(r._shipId));
  if(selectedRows.some(r=>r._canEdit===false)){showToast(appLang==='en'?'The selection contains view-only orders. Remove them before deleting.':'Seçimde yalnız görüntülenebilen siparişler var. Silmeden önce seçimden çıkarın.');return;}
  if(!confirm(`${shipSelected.size} satır silinecek. Emin misin?`)) return;
  try{
    const saved=await enqueueShipMutation('/api/shipping-comparison/delete', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({ids:[...shipSelected]})});
    shipRows=saved.rows||shipRows;
    shipSelected.clear();
    await loadShipRows();
    renderShipDecision();
  }catch(err){ alert('Silinemedi: '+err.message); }
});

setupColBtn('shipColsBtn','shipColPanel','ship', renderShipTable);
loadShipRows();

/* ===================================================================
   NAVLUN HESAPLAMA (v5.76)

   Kaynak: "GEMİ+UÇAK VE UÇAK NAVLUN MALİYET BULMA" Exceli. O dosyada bir
   sipariş için koli ölçüleri ve ağırlık girilip charchable weight bulunuyor,
   sonra tablonun başındaki birim navlun ücretleriyle çarpılıp Landed fiyat
   çıkarılıyordu. Bu ekranda Landed Gemi+Uçak ve Landed Uçak sütunları o güne
   kadar ELLE giriliyordu; hesap artık burada yapılır ve sonuç doğrudan ilgili
   sütuna yazılır.

   Matematik public/freight-calc.js içinde; burası yalnız arayüz.
   Birim ücretler sunucuda ortak ayar olarak durur (/api/freight-rates), bu
   yüzden bir kez güncellenince herkesin hesabı yeni ücretle çalışır.
   =================================================================== */
const FREIGHT_INPUT_KEYS = ['kgPerPiece','qtyTotal','qtyPerCarton','cartonL','cartonH','cartonW','stylePrice'];

function freightSettings(){
  const raw = state.overrides && state.overrides.freightRates;
  return BLFreight.normalizeSettings(raw);
}
// Navlun kartındaki her sayı en fazla iki ondalık basamakla gösterilir.
// digits yalnız daha KISA gösterim için kullanılabilir (koli sayısı: 0);
// ikiden fazla basamak istenirse yine ikiye kırpılır.
function freightNumberText(value, digits){
  if(value==null || !Number.isFinite(Number(value))) return '—';
  const places = Math.min(2, Math.max(0, Number.isFinite(Number(digits)) ? Number(digits) : 2));
  return Number(value).toLocaleString(appLang==='en'?'en-GB':'tr-TR',{minimumFractionDigits:places,maximumFractionDigits:places});
}
function freightMoneyText(value, digits){
  if(value==null || !Number.isFinite(Number(value))) return '—';
  return '$'+freightNumberText(value, digits==null?2:digits);
}
// Satırdan gelen ön dolgu: Adet ve FOB zaten CP'den geliyor, kullanıcı tekrar
// yazmasın. Daha önce kaydedilmiş girdiler varsa onlar öne geçer.
function freightInputsForRow(row, settings){
  const saved = (row && row._freightInput && typeof row._freightInput==='object') ? row._freightInput : {};
  const out = {};
  FREIGHT_INPUT_KEYS.forEach(key => { out[key] = saved[key]==null ? '' : String(saved[key]); });
  if(out.qtyTotal==='' && row && row.quantity!=null && row.quantity!=='') out.qtyTotal=String(row.quantity);
  if(out.stylePrice==='' && row && row.fob!=null && row.fob!=='') out.stylePrice=String(row.fob);
  // Koli ölçüsü her hesapta elle yazılmasın: kayıtlı değer yoksa varsayılan
  // ölçü (58 × 38 × 30) ön dolu gelir, üzerine yazılabilir.
  const carton = (settings && settings.carton) || BLFreight.DEFAULT_CARTON;
  ['cartonL','cartonH','cartonW'].forEach(key=>{ if(out[key]==='') out[key]=String(carton[key]); });
  return out;
}
async function persistFreightSettings(value){
  const clean = BLFreight.normalizeSettings(value);
  if(window.SERVER_BACKED){
    const res = await fetch('/api/freight-rates',{method:'PUT',headers:{'Content-Type':'application/json','If-Match':String((state.storeRevisions&&state.storeRevisions.freightRates)||0)},body:JSON.stringify({freight:clean})});
    const data = await res.json().catch(()=>({}));
    if(!res.ok) throw new Error(data.error||res.statusText);
    state.storeRevisions={...(state.storeRevisions||{}),freightRates:Number(data.revision)||0};
    state.overrides.freightRates = BLFreight.normalizeSettings(data.freight||clean);
  } else state.overrides.freightRates = clean;
  return state.overrides.freightRates;
}

function openFreightModal(rows){
  document.getElementById('_freightModal')?.remove();
  const en = appLang==='en';
  const canEditRates = typeof window.BLHasPermission!=='function' || window.BLHasPermission('manageBusinessRules');
  const list = (Array.isArray(rows)?rows:(rows?[rows]:[])).filter(Boolean);
  const multi = list.length>1;
  let settings = freightSettings();
  // Her satırın kendi girdi kümesi var: adet ve fiyat satırdan gelir, koli
  // ölçüleri ortak varsayılandan başlar. Serbest hesapta tek boş kümedir.
  let entries = (list.length?list:[null]).map(row=>({
    row,
    key: row ? String(row._shipId) : 'free',
    label: row
      ? [row.orderCode,row.styleName,row.colour].map(v=>String(v==null?'':v).trim()).filter(Boolean).join(' · ')
      : (en?'Standalone calculation':'Serbest hesap'),
    inputs: freightInputsForRow(row, settings),
  }));
  let activeKey = entries[0].key;

  const modal = document.createElement('div');
  modal.id='_freightModal'; modal.className='warnOverlay';
  const who = multi
    ? (en?`${list.length} orders — each calculated with its own quantity and price`:`${list.length} sipariş — her biri kendi adedi ve fiyatıyla hesaplanır`)
    : (entries[0].row ? entries[0].label : (en?'Standalone calculation — no row is updated':'Serbest hesap — hiçbir satır güncellenmez'));

  modal.innerHTML = `<div class="modalCard freightCard" role="dialog" aria-modal="true" aria-labelledby="_freightTitle">
    <div class="freightHead">
      <div>
        <div class="modalTitle" id="_freightTitle">${escapeHtml(en?'Freight Calculation':'Navlun Hesaplama')}</div>
        <p>${escapeHtml(who)}</p>
      </div>
      <button type="button" class="pricingRuleIconBtn _freightClose" data-overlay-close title="${escapeHtml(en?'Close':'Kapat')}"><svg class="ic"><use href="#i-x"/></svg></button>
    </div>
    <div class="freightScroll">
      <section class="freightSection">
        <div class="freightSectionHead">
          <b>${escapeHtml(en?'Freight rates (per kg)':'Navlun ücretleri (kg başına)')}</b>
          <span>${escapeHtml(en?'Shared for everyone. Editing a rate updates the result immediately; Save keeps it for the next calculation.':'Herkes için ortaktır. Ücreti değiştirmek sonucu anında günceller; Kaydet bir sonraki hesap için saklar.')}</span>
        </div>
        <div id="_freightRateList" class="freightRateList"></div>
        <div class="freightRateFoot">
          <label class="freightFactor"><span>${escapeHtml(en?'Volumetric factor (CBM × …)':'Hacimsel katsayı (CBM × …)')}</span><input id="_freightFactor" type="text" inputmode="decimal" ${canEditRates?'':'disabled'}></label>
          <label class="freightFactor"><span>${escapeHtml(en?'Extra Costs Multiplier (FOB × …)':'Ekstra Masraf Çarpanı (FOB × …)')}</span><input id="_freightLandedMult" type="text" inputmode="decimal" ${canEditRates?'':'disabled'}></label>
          <span style="flex:1"></span>
          <button type="button" class="tbtn" id="_freightRateAdd" ${canEditRates?'':'disabled'}><svg class="ic"><use href="#i-copy-plus"/></svg>${escapeHtml(en?'Add rate':'Ücret ekle')}</button>
          <button type="button" class="tbtn" id="_freightRateSave" ${canEditRates?'':'disabled'}><svg class="ic"><use href="#i-device-floppy"/></svg>${escapeHtml(en?'Save settings':'Ayarları kaydet')}</button>
        </div>
        ${canEditRates?'':`<div class="freightNotice">${escapeHtml(en?'You can calculate with the current rates, but changing them needs the business-rules permission.':'Mevcut ücretlerle hesap yapabilirsin; ücretleri değiştirmek için iş kuralları yetkisi gerekir.')}</div>`}
      </section>

      <section class="freightSection">
        <div class="freightSectionHead">
          <b>${escapeHtml(en?'Packing list values':'Çeki listesi değerleri')}</b>
          <span>${escapeHtml(multi
            ? (en?'Pick an order to edit its values. Carton size can be applied to every order at once.':'Değerlerini düzenlemek için sipariş seç. Koli ölçüsü tek seferde hepsine uygulanabilir.')
            : (en?'These are the fields highlighted yellow in the source workbook.':'Kaynak Excel’de sarı ile işaretli, doldurulması gereken alanlar.'))}</span>
        </div>
        ${multi?`<div class="freightRowTabs" id="_freightRowTabs"></div>`:''}
        <div class="freightInputGrid" id="_freightInputGrid"></div>
        ${multi?`<div class="freightApplyAll"><button type="button" class="tbtn" id="_freightCartonAll">${escapeHtml(en?'Apply carton size and kg/piece to all orders':'Koli ölçüsü ve kg/adet değerini tüm siparişlere uygula')}</button></div>`:''}
      </section>

      <section class="freightSection">
        <div class="freightSectionHead"><b>${escapeHtml(en?'Chargeable weight':'Charchable weight')}</b><span id="_freightDerivedFor"></span></div>
        <div class="freightDerived" id="_freightDerived"></div>
      </section>

      <section class="freightSection">
        <div class="freightSectionHead"><b>${escapeHtml(en?'Result':'Sonuç')}</b></div>
        <div class="freightResults" id="_freightResults"></div>
      </section>
    </div>
    <div class="freightFoot">
      <span id="_freightStatus"></span>
      <button type="button" class="tbtn _freightClose">${escapeHtml(en?'Close':'Kapat')}</button>
      ${list.length?`<button type="button" class="navActionBtn" id="_freightSaveInputs"><svg class="ic"><use href="#i-device-floppy"/></svg>${escapeHtml(en?'Save inputs':'Girdileri kaydet')}</button>`:''}
    </div>
  </div>`;
  document.body.appendChild(modal);
  modal.__refreshCanonicalRecipients=()=>{prepareEmailFillFromShared();if(typeof refreshAll==='function')refreshAll();};
  modal.addEventListener('click',event=>{const manage=event.target.closest('[data-manage-email-groups]');if(manage){event.preventDefault();window.BLEmailGroups?.open?.();}});

  const status = modal.querySelector('#_freightStatus');
  const rateList = modal.querySelector('#_freightRateList');
  const factorInput = modal.querySelector('#_freightFactor');
  const landedMultInput = modal.querySelector('#_freightLandedMult');
  const grid = modal.querySelector('#_freightInputGrid');
  const tabs = modal.querySelector('#_freightRowTabs');

  const entryOf = key => entries.find(item=>item.key===key) || entries[0];
  const canWrite = entry => Boolean(entry && entry.row && entry.row._canEdit!==false);

  function readInputs(){
    const entry = entryOf(activeKey);
    grid.querySelectorAll('[data-freight-input]').forEach(el=>{ entry.inputs[el.dataset.freightInput]=el.value; });
    return entry;
  }
  function readSettings(){
    const rates=[...rateList.querySelectorAll('[data-rate-index]')].map((rowEl,index)=>({
      id: settings.rates[Number(rowEl.dataset.rateIndex)]?.id || `rate-${index+1}`,
      label: rowEl.querySelector('[data-rate-label]').value,
      mode: rowEl.querySelector('[data-rate-mode]').value,
      rate: BLFreight.num(rowEl.querySelector('[data-rate-value]').value),
    }));
    settings = BLFreight.normalizeSettings({
      rates,
      volumetricFactor: BLFreight.num(factorInput.value),
      landedMultiplier: BLFreight.num(landedMultInput.value),
      carton: settings.carton,
    });
    return settings;
  }
  function renderRates(){
    factorInput.value = String(settings.volumetricFactor);
    landedMultInput.value = String(settings.landedMultiplier);
    rateList.innerHTML = settings.rates.map((rate,index)=>`
      <div class="freightRateRow" data-rate-index="${index}">
        <input type="text" data-rate-label value="${escapeHtml(rate.label)}" ${canEditRates?'':'disabled'} placeholder="${escapeHtml(en?'Route name':'Rota adı')}">
        <select data-rate-mode ${canEditRates?'':'disabled'}>
          <option value="seaAir" ${rate.mode==='seaAir'?'selected':''}>${escapeHtml(en?'Sea+Air':'Gemi+Uçak')}</option>
          <option value="air" ${rate.mode==='air'?'selected':''}>${escapeHtml(en?'Air':'Uçak')}</option>
        </select>
        <div class="freightRateValue"><i>$</i><input type="text" inputmode="decimal" data-rate-value value="${escapeHtml(String(rate.rate))}" ${canEditRates?'':'disabled'}></div>
        <button type="button" class="pricingRuleIconBtn" data-rate-remove="${index}" title="${escapeHtml(en?'Remove':'Kaldır')}" ${canEditRates&&settings.rates.length>1?'':'disabled'}><svg class="ic"><use href="#i-trash"/></svg></button>
      </div>`).join('');
    rateList.querySelectorAll('[data-rate-remove]').forEach(btn=>btn.addEventListener('click',()=>{
      readSettings(); settings.rates.splice(Number(btn.dataset.rateRemove),1);
      settings = BLFreight.normalizeSettings(settings); renderRates(); recalc();
    }));
    rateList.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',recalc));
  }

  // Koli ölçüleri tek satırda üç dar kutu: üç ayrı geniş alan yer kaplıyordu ve
  // birbirine ait oldukları görünmüyordu.
  const CARTON_KEYS = ['cartonL','cartonW','cartonH'];
  function renderGrid(){
    const entry = entryOf(activeKey);
    const fields = BLFreight.INPUT_FIELDS.filter(field=>!CARTON_KEYS.includes(field.key));
    grid.innerHTML = fields.map(field=>`
      <label class="freightField">
        <span>${escapeHtml(en?field.en:field.tr)}</span>
        <input type="text" inputmode="decimal" data-freight-input="${escapeHtml(field.key)}" value="${escapeHtml(entry.inputs[field.key]||'')}">
        ${field.hintTr?`<small>${escapeHtml(en?field.hintEn:field.hintTr)}</small>`:''}
      </label>`).join('') + `
      <label class="freightField freightCartonField">
        <span>${escapeHtml(en?'Carton L × W × H (cm)':'Koli En × Boy × Yükseklik (cm)')}</span>
        <div class="freightCartonRow">${CARTON_KEYS.map((key,index)=>`
          ${index?'<i>×</i>':''}<input type="text" inputmode="decimal" data-freight-input="${key}" value="${escapeHtml(entry.inputs[key]||'')}" aria-label="${escapeHtml(key)}">`).join('')}</div>
      </label>`;
    grid.querySelectorAll('[data-freight-input]').forEach(el=>el.addEventListener('input',recalc));
  }
  function renderTabs(){
    if(!tabs) return;
    const config = settings;
    tabs.innerHTML = entries.map(entry=>{
      const done = BLFreight.calculate(entry.inputs, config).complete;
      return `<button type="button" class="freightRowTab${entry.key===activeKey?' isActive':''}${done?' isReady':''}" data-freight-row="${escapeHtml(entry.key)}">${escapeHtml(entry.label||'—')}</button>`;
    }).join('');
    tabs.querySelectorAll('[data-freight-row]').forEach(btn=>btn.addEventListener('click',()=>{
      readInputs(); activeKey = btn.dataset.freightRow; renderGrid(); recalc();
    }));
  }

  function recalc(){
    const config = readSettings();
    const entry = readInputs();
    const result = BLFreight.calculate(entry.inputs, config);
    renderTabs();

    const forLabel = modal.querySelector('#_freightDerivedFor');
    if(forLabel) forLabel.textContent = multi ? entry.label : '';
    const derived = modal.querySelector('#_freightDerived');
    const wins = key => result.chargeableSource===key ? ' freightWins' : '';
    derived.innerHTML = `
      <div class="freightStat"><span>${escapeHtml(en?'Total cartons':'Toplam koli')}</span><b>${freightNumberText(result.cartonCount,0)}</b></div>
      <div class="freightStat"><span>CBM</span><b>${freightNumberText(result.cbm,2)}</b></div>
      <div class="freightStat${wins('gross')}"><span>${escapeHtml(en?'Gross weight (kg)':'Brüt kilogram')}</span><b>${freightNumberText(result.grossWeight,2)}</b></div>
      <div class="freightStat${wins('volumetric')}"><span>${escapeHtml(en?`Volumetric (CBM × ${result.volumetricFactor})`:`Hacimsel (CBM × ${result.volumetricFactor})`)}</span><b>${freightNumberText(result.volumetricWeight,2)}</b></div>
      <div class="freightStat freightStatMain"><span>${escapeHtml(en?'Chargeable weight (kg)':'Charchable weight')}</span><b>${freightNumberText(result.chargeableWeight,2)}</b></div>`;

    const host = modal.querySelector('#_freightResults');
    if(multi) return renderMultiResults(host, config);
    if(!result.complete){
      host.innerHTML = `<div class="freightEmpty">${escapeHtml(en?'Fill every field above to see the freight cost.':'Navlun maliyetini görmek için yukarıdaki alanların tümünü doldur.')}</div>`;
      return;
    }
    host.innerHTML = `<table class="freightTable"><thead><tr>
        <th>${escapeHtml(en?'Route':'Rota')}</th>
        <th>${escapeHtml(en?'Rate':'Birim')}</th>
        <th>${escapeHtml(en?'Freight total':'Navlun toplam')}</th>
        <th>${escapeHtml(en?'Per piece':'Birim navlun')}</th>
        <th>${escapeHtml(en?'Landed':'Landed')}</th>
        <th></th>
      </tr></thead><tbody>${result.results.map((item,index)=>`
        <tr>
          <td><b>${escapeHtml(item.label)}</b><small>${escapeHtml(item.mode==='air'?(en?'Air':'Uçak'):(en?'Sea+Air':'Gemi+Uçak'))}</small></td>
          <td>${freightMoneyText(item.rate,2)}</td>
          <td>${freightMoneyText(item.total,2)}</td>
          <td>${freightMoneyText(item.perPiece,2)}</td>
          <td class="freightLanded">${freightMoneyText(item.landed,2)}</td>
          <td>${entry.row?`<button type="button" class="tbtn" data-freight-apply="${index}" ${canWrite(entry)&&item.landed!=null?'':'disabled'}>${escapeHtml(en?'Apply':'Uygula')}</button>`:''}</td>
        </tr>`).join('')}</tbody></table>
      ${applyNotice()}`;
    host.querySelectorAll('[data-freight-apply]').forEach(btn=>btn.addEventListener('click',()=>{
      applyResult(entry, result.results[Number(btn.dataset.freightApply)]);
    }));
  }

  // Çoklu seçimde her satır KENDİ adedi ve fiyatıyla ayrı hesaplanır; alttaki
  // toplam satırı yalnız özet içindir, uygulanan değer her zaman satırın kendi
  // sonucudur.
  function renderMultiResults(host, config){
    const many = BLFreight.calculateMany(entries.map(entry=>({key:entry.key,label:entry.label,input:entry.inputs})), config);
    const ready = many.rows.filter(item=>item.result.complete);
    if(!ready.length){
      host.innerHTML = `<div class="freightEmpty">${escapeHtml(en?'Fill the packing list values for at least one order.':'En az bir sipariş için çeki listesi değerlerini doldur.')}</div>`;
      return;
    }
    host.innerHTML = `<table class="freightTable freightMultiTable"><thead><tr>
        <th>${escapeHtml(en?'Order':'Sipariş')}</th>
        <th>${escapeHtml(en?'Qty':'Adet')}</th>
        <th>${escapeHtml(en?'Chargeable':'Charchable')}</th>
        ${config.rates.map(rate=>`<th>${escapeHtml(rate.label)}</th>`).join('')}
      </tr></thead><tbody>${many.rows.map(item=>`
        <tr${item.result.complete?'':' class="freightRowPending"'}>
          <td><b>${escapeHtml(item.label||'—')}</b>${item.result.complete?'':`<small>${escapeHtml(en?'incomplete':'eksik')}</small>`}</td>
          <td>${freightNumberText(item.result.qtyTotal,0)}</td>
          <td>${freightNumberText(item.result.chargeableWeight,2)}</td>
          ${item.result.results.map(entry=>`<td class="freightLanded">${freightMoneyText(entry.landed,2)}</td>`).join('')}
        </tr>`).join('')}
        <tr class="freightTotalRow">
          <td><b>${escapeHtml(en?'Total / weighted':'Toplam / ağırlıklı')}</b></td>
          <td>${freightNumberText(many.totals[0]&&many.totals[0].qtyTotal,0)}</td>
          <td>—</td>
          ${many.totals.map(total=>`<td class="freightLanded">${freightMoneyText(total.landed,2)}</td>`).join('')}
        </tr>
      </tbody></table>
      <div class="freightApplyAll">${config.rates.map((rate,index)=>`
        <button type="button" class="tbtn" data-freight-apply-all="${index}">${escapeHtml((en?'Apply ':'Uygula: ')+rate.label)}</button>`).join('')}</div>
      ${applyNotice()}
      ${many.incompleteRows?`<div class="freightNotice">${escapeHtml(en?`${many.incompleteRows} order(s) are still missing values and will be skipped.`:`${many.incompleteRows} siparişin değerleri eksik, atlanacak.`)}</div>`:''}`;
    host.querySelectorAll('[data-freight-apply-all]').forEach(btn=>btn.addEventListener('click',()=>{
      const index=Number(btn.dataset.freightApplyAll);
      let applied=0;
      many.rows.forEach(item=>{
        const entry=entryOf(item.key);
        if(!item.result.complete || !canWrite(entry)) return;
        applyResult(entry, item.result.results[index], {quiet:true});
        applied++;
      });
      renderShipTable();
      status.textContent = en?`Applied to ${applied} order(s).`:`${applied} siparişe uygulandı.`;
      showToast(en?`Landed price updated on ${applied} order(s).`:`${applied} siparişin Landed fiyatı güncellendi.`);
    }));
  }
  function applyNotice(){
    return `<div class="freightNotice">${escapeHtml(en
      ? 'Apply writes the Landed value into the row: Air rates go to “YD Fiyat (USD) Landed Uçak”, Sea+Air rates to “YD Fiyat (USD) Landed Gemi+Uçak”.'
      : 'Uygula, Landed değerini satıra yazar: Uçak ücretleri “YD Fiyat (USD) Landed Uçak”, Gemi+Uçak ücretleri “YD Fiyat (USD) Landed Gemi+Uçak” sütununa gider.')}</div>`;
  }

  function storedInputs(entry){
    const out={};
    FREIGHT_INPUT_KEYS.forEach(key=>{ const n=BLFreight.num(entry.inputs[key]); if(n!=null) out[key]=n; });
    return out;
  }
  function saveInputs(entry, extra){
    if(!canWrite(entry)) return;
    const patch = {_freightInput: storedInputs(entry), ...(extra||{})};
    Object.assign(entry.row, patch);
    patchShipRow(entry.row._shipId, patch);
  }
  function applyResult(entry, item, options){
    if(!canWrite(entry) || !item || item.landed==null) return;
    const key = item.mode==='air' ? 'ydFiyatUsdLandedUcak' : 'ydFiyatUsdLandedGemiUcak';
    const prev = entry.row[key];
    // Modalda 2 basamak gösteriliyor; satıra da 2 basamak yazılır ki
    // kullanıcının gördüğü sayı ile hücreye düşen sayı ayrışmasın.
    const next = Number(item.landed.toFixed(2));
    saveInputs(entry, {[key]: next, _freightAppliedRate: {id:item.id, label:item.label, mode:item.mode, rate:item.rate, at:new Date().toISOString()}});
    computeShipFormulas(entry.row);
    if(typeof pushUndo==='function') pushUndo({kind:'ship', shipId:entry.row._shipId, fields:[{key, prev, next}]});
    if(options&&options.quiet) return;
    renderShipTable();
    status.textContent = en ? `Applied: ${item.label} → ${freightMoneyText(next,2)}` : `Uygulandı: ${item.label} → ${freightMoneyText(next,2)}`;
    showToast(en?`Landed price updated from ${item.label}.`:`Landed fiyat ${item.label} ücretiyle güncellendi.`);
  }

  modal.querySelector('#_freightCartonAll')?.addEventListener('click',()=>{
    const source = readInputs();
    entries.forEach(entry=>{
      if(entry===source) return;
      [...CARTON_KEYS,'qtyPerCarton','kgPerPiece'].forEach(key=>{ entry.inputs[key]=source.inputs[key]; });
    });
    recalc();
    showToast(en?'Carton values copied to every order.':'Koli değerleri tüm siparişlere kopyalandı.');
  });
  modal.querySelector('#_freightRateAdd')?.addEventListener('click',()=>{
    readSettings();
    settings.rates.push({id:`rate-${Date.now()}`, mode:'seaAir', label:en?'New route':'Yeni rota', rate:1});
    settings = BLFreight.normalizeSettings(settings); renderRates(); recalc();
  });
  modal.querySelector('#_freightRateSave')?.addEventListener('click',async e=>{
    const btn=e.currentTarget; const config=readSettings();
    if(config.rates.some(rate=>!(rate.rate>0))){ status.textContent = en?'Every rate must be greater than zero.':'Her navlun ücreti sıfırdan büyük olmalı.'; return; }
    // Kaydetme anındaki koli ölçüsü bir sonraki hesabın varsayılanı olur.
    const active = readInputs();
    config.carton = {
      cartonL: BLFreight.num(active.inputs.cartonL) || settings.carton.cartonL,
      cartonH: BLFreight.num(active.inputs.cartonH) || settings.carton.cartonH,
      cartonW: BLFreight.num(active.inputs.cartonW) || settings.carton.cartonW,
    };
    btn.disabled=true; status.textContent = en?'Saving…':'Kaydediliyor…';
    try{
      settings = await persistFreightSettings(config);
      renderRates(); recalc();
      status.textContent=''; showToast(en?'Freight settings saved.':'Navlun ayarları kaydedildi.');
    }catch(err){ status.textContent=err.message; }
    finally{ btn.disabled=false; }
  });
  modal.querySelector('#_freightSaveInputs')?.addEventListener('click',()=>{
    readInputs();
    let saved=0;
    entries.forEach(entry=>{ if(canWrite(entry)){ saveInputs(entry); saved++; } });
    showToast(en?`Packing list values saved on ${saved} row(s).`:`Çeki listesi değerleri ${saved} satıra kaydedildi.`);
  });
  const close=()=>modal.remove();
  modal.querySelectorAll('._freightClose').forEach(btn=>btn.addEventListener('click',close));
  modal.addEventListener('click',e=>{ if(e.target===modal) close(); });
  modal.addEventListener('keydown',e=>{ if(e.key==='Escape'){ e.preventDefault(); close(); } });

  renderRates(); renderGrid(); recalc();
  setTimeout(()=>modal.querySelector('[data-freight-input]')?.focus(),0);
}

document.getElementById('shipFreightBtn')?.addEventListener('click',()=>{
  if(typeof commitActiveTableEditor==='function') commitActiveTableEditor({refresh:false});
  // Seçim yoksa serbest hesap açılır: hızlı bir kontrol için tabloya dokunmadan
  // da kullanılabilsin. Birden fazla satır seçiliyse her satır ayrı hesaplanır.
  openFreightModal(shipRows.filter(r=>shipSelected.has(r._shipId)));
});


// Orijinal Excel şablonundaki sütun başlıklarını (A-AT) birebir korur.
const SHIP_EXCEL_HEADERS = [
  ['onay','HAKAN BEY UÇAK YÜKLEME ONAYI'], ['status','STATUS'], ['talepTipi','TALEP TİPİ'],
  ['buyerGroup','BUYER GROUP'], ['buyer','BUYER'], ['category','CATEGORY'], ['line','LİNE'],
  ['retailDate','RETAIL DATE'], ['opd','OPD'], ['exFactory','EX-FACTORY'], ['leadTime','LEAD TIME'],
  ['specialCode','SPECIAL CODE'], ['styleName','STYLE NAME'], ['productMainCategory','Product Main Catategory'],
  ['fit','FIT'], ['colour','COLOUR '], ['colorCode','COLOR CODE'], ['quantity','QUANTITY'],
  ['country','COUNTRY'], ['supplier','SUPPLIER'], ['fob','FOB'], ['suppFob','Supp.FOB'], ['kur','KUR'],
  ['trFiyatTl','TR FİYAT (TL)'], ['trFiyatUsd','TR FİYAT (USD)'], ['trFiyatFobUsdLanded','TR FİYAT FOB USD LANDED (1,05)'],
  ['ydFiyatUsd','YD Fiyat (USD)'], ['ydFiyatUsdLandedGemi','YD Fiyat (USD) LANDED\nGemi'],
  ['ydFiyatUsdLandedGemiUcak','YD Fiyat (USD) LANDED\nGemi+Uçak'], ['ydFiyatUsdLandedUcak','YD Fiyat (USD) LANDED  Uçak'],
  ['gemiAvantaj','GEMİ YD-TR LANDED AVANTAJ (USD)'], ['gemiUcakAvantaj','GEMİ+UÇAK YD-TR LANDED AVANTAJ (USD)'],
  ['ucakAvantaj','UÇAK YD-TR LANDED AVANTAJ (USD)'], ['retailTrWithVessel','RETAIL TR WITH VESSEL'],
  ['gemiUcakAntrepoTeslim','GEMI+UÇAK VASITA TAHMİNİ ANTREPO TESLİM'], ['ucakAntrepoTeslim','UÇAK VASITA TAHMİNİ ANTREPO TESLİM'],
  ['nihaiVasitaKarar','NİHAİ VASITA PBL KARAR'], ['retailTarihPblTalep','RETAIL TARIH PBL TALEP'],
  ['retailAyPblTalep','RETAIL AY PBL TALEP'], ['modelButceIstenenGun','MODEL BUTCE ISTENEN GÜN'],
  ['gecikmeSonrasiAntrepo','GECİKME SONRASI ANTREPO TARİHİ'], ['siparisGecilenGrup','SİPARİŞ GEÇİLEN GRUP'],
  ['ucakNavlunKimOdeyecek','UÇAK NAVLUN BEDELİNİ KİM ÖDEYECEK? BUYING KARAR'],
  ['ucakYuklemeSebebi','UÇAK veye Uçak+ Gemi YÜKLEME SEBEBİ?'],
  ['acilIhtiyacVarMi','Geleceği dönemde mağazada bu ürüne acil ihtiyaç olacak mı? alternatifi var mı?'],
  ['hizliGemiDegerlendirildiMi','Hızlı gemi, gemi-uçak seçenekleri değerlendirildi mi?'],
  ['orderCode','Order Code (referans)'], // orijinal şablonda yok, izlenebilirlik için eklendi
];
const SHIP_EXCEL_DATE_KEYS = new Set(['retailDate','opd','exFactory','retailTrWithVessel','gemiUcakAntrepoTeslim','ucakAntrepoTeslim','retailTarihPblTalep','gecikmeSonrasiAntrepo']);
document.getElementById('shipExportBtn').addEventListener('click', ()=>{
  if(!shipRows.length){ showToast('Aktarılacak satır yok.'); return; }
  shipRows.forEach(computeShipFormulas);
  const bd = _XLS_BORDERS;
  const ws = {};
  const put=(r,c,cell)=>{ ws[XLSX.utils.encode_cell({r,c})]=cell; };
  // TÜM sütunlar (görünürlük tercihi ne olursa olsun) — SHIP_EXCEL_HEADERS tam listedir.
  // Başlık renkleri uygulamadaki Nakliye Kıyas tablosuyla birebir aynı paletten alınır.
  SHIP_EXCEL_HEADERS.forEach(([key,label],ci)=>{
    const headerHex = (SHIP_HEADER_COLORS[key] || '#F2F4F7').replace('#','').toUpperCase();
    const isDarkHeader = headerHex === 'FF0000';
    put(0,ci,{v:label,t:'s',s:{
      border:bd,
      font:{sz:10,bold:true,color:{rgb:isDarkHeader?'FFFFFFFF':'FF000000'}},
      fill:{patternType:'solid',fgColor:{rgb:'FF'+headerHex}},
      alignment:{horizontal:'center',vertical:'center',wrapText:true}
    }});
  });
  shipRows.forEach((row,ri)=>{
    SHIP_EXCEL_HEADERS.forEach(([key],ci)=>{
      let v = row[key];
      const s = {border:bd, font:{sz:10}, alignment:{vertical:'center'}};
      let cell;
      if(v==null || v===''){ cell={v:'',t:'s',s}; }
      else if(key==='orderCode'||key==='colorCode'){ cell={v:key==='orderCode'?String(v).replace(/\.(?=\d{3}(?:\D|$))/g,''):String(v),t:'s',s:{...s,numFmt:'@',alignment:{horizontal:'left',vertical:'center'}}}; }
      else if(SHIP_EXCEL_DATE_KEYS.has(key)){
        const d = coerceDateLoose(v);
        cell = isNaN(d) ? {v:String(v),t:'s',s} : {v:d,t:'d',s:{...s,numFmt:'dd.mm.yy',alignment:{horizontal:'right',vertical:'center'}}};
      }
      else if(typeof v==='number' && Number.isFinite(v)){
        cell={v,t:'n',s:{...s,alignment:{horizontal:'right',vertical:'center'},numFmt:Number.isInteger(v)?'#,##0':'#,##0.00'}};
      }
      else cell={v:String(v),t:'s',s};
      put(ri+1,ci,cell);
    });
  });
  ws['!ref']=XLSX.utils.encode_range({s:{r:0,c:0},e:{r:shipRows.length,c:SHIP_EXCEL_HEADERS.length-1}});
  ws['!cols']=SHIP_EXCEL_HEADERS.map(()=>({wch:14}));
  ws['!rows']=[{hpx:28}];
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Nakliye Kıyaslama');
  const d = new Date(); const p=x=>String(x).padStart(2,'0');
  XLSX.writeFile(wb, `Nakliye_Tipine_Gore_Maliyet_Kiyaslamasi_${d.getFullYear()}${p(d.getMonth()+1)}${p(d.getDate())}.xlsx`);
  showToast(`Nakliye kıyaslaması Excel'e aktarıldı (${shipRows.length} satır, tüm sütunlar).`);
});

// ================= BİÇİMLİ EXCEL DIŞA AKTARIM (xlsx-js-style) =================
// Ekranda görünen tabloyu, hücre dolgu/yazı renkleri, hizalama, sayı formatı ve
// sütun genişlikleriyle birebir Excel'e yazar. İşaretli satır varsa yalnızca onları alır.
function _xlsHexColor(cssColor){
  if(!cssColor) return null;
  const m = String(cssColor).match(/rgba?\(([^)]+)\)/);
  if(!m) return null;
  const p = m[1].split(',').map(x=>parseFloat(x));
  if(p.length>=4 && p[3]===0) return null; // tamamen şeffaf
  const hx = n=>Math.max(0,Math.min(255,Math.round(n))).toString(16).padStart(2,'0').toUpperCase();
  return 'FF'+hx(p[0])+hx(p[1])+hx(p[2]);
}
const _XLS_BORDER = {style:'thin', color:{rgb:'FFD0D5DD'}};
const _XLS_BORDERS = {top:_XLS_BORDER,bottom:_XLS_BORDER,left:_XLS_BORDER,right:_XLS_BORDER};
// Kanonik aydınlık paletin (#RRGGBB) Excel ARGB karşılığı. Boş değer "dolgu yok"
// demektir; fallback üretmez.
function _xlsArgbFromHex(hex){
  const raw=String(hex||'').replace(/^#/,'').trim().toUpperCase();
  if(/^[0-9A-F]{8}$/.test(raw))return raw;
  if(/^[0-9A-F]{6}$/.test(raw))return 'FF'+raw;
  return null;
}
function _xlsCellFromTd(td,options){
  options=options||{};
  // Hücre metni: rozet varsa rozetten, input/select varsa değerinden, yoksa düz metinden.
  let src = td, text;
  const badge = td.querySelector('.badge');
  const ctl = td.querySelector('select,input');
  if(badge){ src = badge; text = badge.textContent.trim(); }
  else if(ctl){
    text = ctl.tagName==='SELECT' ? (ctl.selectedOptions[0]?.textContent.trim() ?? ctl.value) : String(ctl.value??'').trim();
    src = ctl.classList.contains('selApproved') || ctl.classList.contains('selNA') ? ctl : td;
  }
  else text = td.textContent.replace(/\s+/g,' ').trim();
  const cs = getComputedStyle(src);
  const tdCs = src===td ? cs : getComputedStyle(td);
  const alignRight = tdCs.textAlign==='right' || td.classList.contains('num') || td.classList.contains('money');
  /* Aydınlık dışa aktarım paleti (bkz. exportSemanticPalette) verildiyse renkler
     ekranın HESAPLANMIŞ CSS'inden OKUNMAZ. Eski davranışta koyu/kurşun temadaki
     koyu dolgu ve açık yazı rengi Excel'e olduğu gibi yazılıyor, beyaz sayfada
     okunamayan hücreler oluşuyordu. CP bunu geçici tema değiştirip yeniden
     çizerek örtmeye çalışıyordu; Orders'ta o örtü hiç yoktu. */
  const palette = options.palette || null;
  const fill = palette
    ? _xlsArgbFromHex(palette.bg)
    : (_xlsHexColor(cs.backgroundColor) || (src!==td ? _xlsHexColor(tdCs.backgroundColor) : null));
  const fg = palette
    ? (_xlsArgbFromHex(palette.color) || _xlsArgbFromHex(EXPORT_LIGHT_BODY_FG))
    : _xlsHexColor(cs.color);
  const bold = palette ? !!palette.bold : parseInt(cs.fontWeight,10) >= 600;
  const s = {border:_XLS_BORDERS, alignment:{vertical:'center', horizontal: alignRight?'right':'left'}, font:{sz:10, bold, color: fg?{rgb:fg}:undefined}};
  if(fill) s.fill = {fgColor:{rgb:fill}};
  // Sipariş numarası ve PLM ID Excel'de sayı değil kimliktir; binlik ayırıcı uygulanmaz.
  if(options.forceIdentifierText){
    const clean=String(text||'').replace(/\.(?=\d{3}(?:\D|$))/g,'');
    return {v:clean,t:'s',s:{...s,numFmt:'@',alignment:{vertical:'center',horizontal:'left'}}};
  }
  // Sayı algılama: para ($) veya tr biçimli sayı. Supp. FOB, FOB ile birebir
  // aynı dolar biçimini kullanır; girişte $ görünmese de Excel'e para olarak gider.
  let cell;
  const fieldKey=String(options.fieldKey||td.dataset.key||ctl?.dataset.key||'').trim();
  const forceDollarCurrency=fieldKey==='FOB ($)'||fieldKey==='FOB'||fieldKey==='Supp. FOB'||fieldKey==='Supp.FOB';
  const money = forceDollarCurrency || /^\$\s?-?[\d.,]+$/.test(text);
  const numish = /^-?\d{1,3}(\.\d{3})*(,\d+)?$/.test(text) || /^-?\d+([.,]\d+)?$/.test(text);
  if(text!=='' && (money || (alignRight && numish))){
    const n = parseFloat(text.replace(/[$\s]/g,'').replace(/\.(?=\d{3}(\D|$))/g,'').replace(',', '.'));
    if(Number.isFinite(n)){
      cell = {v:n, t:'n', s:{...s, numFmt: money ? '"$"#,##0.00' : (Number.isInteger(n)?'#,##0':'#,##0.00')}};
    }
  }
  if(!cell) cell = {v:text, t:'s', s};
  return cell;
}
function _excelJsArgb(value,fallback='FF000000'){
  const raw=String(value||'').replace(/^#/,'').trim().toUpperCase();
  if(/^[0-9A-F]{8}$/.test(raw))return raw;
  if(/^[0-9A-F]{6}$/.test(raw))return 'FF'+raw;
  return fallback;
}
function _applySheetJsStyleToExcelJs(cell,style){
  const s=style||{};
  const font=s.font||{};
  cell.font={
    name:'Calibri',size:Number(font.sz)||10,bold:!!font.bold,italic:!!font.italic,
    color:{argb:_excelJsArgb(font.color&&font.color.rgb,'FF101828')}
  };
  const fillRgb=s.fill&&s.fill.fgColor&&s.fill.fgColor.rgb;
  if(fillRgb)cell.fill={type:'pattern',pattern:'solid',fgColor:{argb:_excelJsArgb(fillRgb,'FFFFFFFF')}};
  const a=s.alignment||{};
  const vertical=a.vertical==='center'?'middle':(a.vertical||'middle');
  cell.alignment={
    horizontal:a.horizontal||'left',vertical,
    wrapText:!!a.wrapText,indent:Number(a.indent)||0
  };
  const edge=()=>({style:'thin',color:{argb:'FFD0D5DD'}});
  cell.border={top:edge(),bottom:edge(),left:edge(),right:edge()};
  if(s.numFmt)cell.numFmt=s.numFmt;
}
function _setExcelJsCellFromSheetSpec(cell,spec){
  const source=spec||{v:'',t:'s',s:{}};
  if(source.f){
    cell.value={formula:String(source.f),result:source.v==null?'':source.v};
  }else if(source.t==='d'){
    // ExcelJS'e Date verilirse dönüşümü UTC üzerinden yapar ve UTC+X saat
    // dilimlerinde tarih bir gün geriye kayar. Hazır seri numarası veriyoruz.
    const d=source.v instanceof Date?source.v:coerceDateLoose(source.v);
    if(d instanceof Date&&!isNaN(d)&&window.BLExcelDates&&BLExcelDates.writeExcelJsSerial(cell,d)){
      _applySheetJsStyleToExcelJs(cell,source.s||{});
      if(!(source.s&&source.s.numFmt))cell.numFmt=BLExcelDates.DATE_FORMAT;
      return;
    }
    cell.value=(d instanceof Date&&!isNaN(d))?d:'';
  }else if(source.t==='n'){
    const n=Number(source.v);cell.value=Number.isFinite(n)?n:null;
  }else if(source.t==='b')cell.value=!!source.v;
  else cell.value=source.v==null?'':String(source.v);
  _applySheetJsStyleToExcelJs(cell,source.s||{});
}
/* Dışa aktarımdaki model görselleri EKRANDAN değil kanonik kimlikten çözülür.
   Eski davranış entry.src olarak ekrandaki <img>'in currentSrc'sini kullanıyordu;
   lazy yükleme yüzünden viewport'a hiç girmemiş satırlarda bu değer placeholder
   SVG'siydi ve o satırların görseli Excel'e ya hiç ya da yanlış gidiyordu.
   Artık panonun zaten çalışan yolu (_copyImageDataUrlFor → BLModelImageCache)
   kullanılır; sonuç dizisi entries ile AYNI SIRADADIR, yani bir görsel asla
   başka bir modelin satırına düşmez. Aynı model görselini paylaşan satırlar
   baytları bir kez hazırlar. */
async function _prepareExcelJsImages(entries){
  const list=entries||[];
  const keyOf=entry=>{const identity=entry&&entry.identity;return identity?identity.key:String((entry&&entry.src)||'');};
  // Benzersiz görseller SINIRLI EŞZAMANLILIKLA hazırlanır: her görsel ağdan
  // çekilip canvas'ta yeniden kodlandığı için yüzlerce satırı aynı anda
  // başlatmak tarayıcıyı kilitliyordu. Aynı model görselini paylaşan satırlar
  // işi bir kez yapar.
  const unique=[],seen=new Set();
  list.forEach(entry=>{const key=keyOf(entry);if(key&&!seen.has(key)){seen.add(key);unique.push(entry);}});
  const prepared=await blMapWithConcurrency(unique,_COPY_IMAGE_CONCURRENCY,async entry=>{
    const identity=entry.identity;
    let source=identity?identity.source:entry.src;
    if(identity){
      const dataUrl=await _copyImageDataUrlFor({modelId:identity.modelId,colourCode:identity.colourCode,source:identity.source,fallbackSource:identity.source});
      if(!/^data:image\//i.test(dataUrl)||/^data:image\/svg\+xml/i.test(dataUrl))return null;
      source=dataUrl;
    }
    return await kolPrepareExcelImage(source);
  });
  const byKey=new Map();
  unique.forEach((entry,index)=>byKey.set(keyOf(entry),prepared[index]||null));
  // Sonuç entries ile AYNI SIRADADIR; tek bir görselin hatası ne diğerlerini
  // ne de dışa aktarımı iptal eder.
  return list.map(entry=>byKey.get(keyOf(entry))||null);
}
function beginFullTableLayout(table){
  if(!table)return()=>{};
  const already=table.classList.contains('blForceFullRender');
  if(!already){table.classList.add('blForceFullRender');void table.offsetHeight;}
  return()=>{if(!already)table.classList.remove('blForceFullRender');};
}
async function exportStyledDomTable(tableSel, opts){
  opts=opts||{};
  flushPendingTableRenders();
  const table=document.querySelector(tableSel);
  if(!table){showToast('Tablo bulunamadı.');return;}
  if(window.BLPerf)await window.BLPerf.ensureLibrary('exceljs');
  if(typeof ExcelJS==='undefined')throw new Error(appLang==='en'?'Excel engine could not be loaded.':'Excel motoru yüklenemedi.');

  const releaseFullLayout=beginFullTableLayout(table);
  try{

  const idAttr=opts.idAttr||'data-id';
  const candidateRows=[...table.querySelectorAll('tbody tr')].filter(tr=>tr.style.display!=='none'&&!tr.classList.contains('cpLogisticDetailRow'));
  const requestedSet=opts.selectedSet&&opts.selectedSet.size?opts.selectedSet:null;
  const hasVisibleSelection=!!(requestedSet&&candidateRows.some(tr=>{
    const id=tr.getAttribute(idAttr)??tr.dataset.id;
    return id!=null&&(requestedSet.has(Number(id))||requestedSet.has(String(id))||requestedSet.has(id));
  }));
  const selSet=hasVisibleSelection?requestedSet:null;
  const isIdentifierHeader=label=>{
    const key=String(label||'').toLocaleUpperCase('tr-TR').replace(/İ/g,'I').replace(/Ş/g,'S').replace(/Ç/g,'C').replace(/Ö/g,'O').replace(/Ü/g,'U').replace(/Ğ/g,'G').replace(/[^A-Z0-9]+/g,' ').trim();
    return ['PLM ID','ORDER CODE','ORDER','SIPARIS','SIPARIS KODU','C CODE','COLOUR CODE','COLOR CODE','RENK KOD','RENK KODU'].includes(key);
  };
  const wb=new ExcelJS.Workbook();
  wb.creator='Buyer Log';wb.created=new Date();
  const sheetName=String(opts.sheetName||'Sayfa1').slice(0,31);
  const ws=wb.addWorksheet(sheetName);
  const headRows=[...table.querySelectorAll('thead tr')];
  const leafHeaders=[],columnWidths=[];
  let excelRow=1,maxCol=0;

  headRows.forEach((trh,headerIndex)=>{
    let col=1;
    [...trh.children].forEach(th=>{
      if(th.classList.contains('chkTh')||(th.cellIndex===0&&th.querySelector('.chkFilterBtn')))return;
      const span=th.colSpan||1;
      const label=(th.querySelector('.thLabel')?.childNodes[0]?.textContent??th.textContent).replace(/[▲▼▾]/g,'').replace(/\s+/g,' ').trim();
      // Başlık paleti de temadan okunmaz: koyu temada dışa aktarılan kitapta
      // koyu lacivert dolgu + açık yazı çıkıyordu. Kanonik aydınlık başlık.
      const fill=_xlsArgbFromHex(EXPORT_LIGHT_HEADER_BG),fg=_xlsArgbFromHex(EXPORT_LIGHT_HEADER_FG);
      const cell=ws.getCell(excelRow,col);
      cell.value=label;
      _applySheetJsStyleToExcelJs(cell,{font:{sz:10,bold:true,color:{rgb:fg}},fill:{fgColor:{rgb:fill}},alignment:{horizontal:'center',vertical:'center',wrapText:true}});
      if(span>1){
        ws.mergeCells(excelRow,col,excelRow,col+span-1);
        for(let c=col+1;c<col+span;c++)_applySheetJsStyleToExcelJs(ws.getCell(excelRow,c),{font:{sz:10,bold:true,color:{rgb:fg}},fill:{fgColor:{rgb:fill}},alignment:{horizontal:'center',vertical:'center'}});
      }
      if(headerIndex===headRows.length-1){
        leafHeaders[col-1]=label;
        columnWidths[col-1]=Math.max(9,Math.round(th.getBoundingClientRect().width/7)||12);
      }
      col+=span;maxCol=Math.max(maxCol,col-1);
    });
    ws.getRow(excelRow).height=22*72/96;
    excelRow++;
  });

  /* Renk ve görsel artık kayıttan gelir; hücre METNİ ekrandan okunmaya devam
     eder (rozet/select/input içeren bileşik hücrelerde görünen iş değeri
     budur). Kayıt bulunamayan tablolar (ör. Nakliye Kıyaslama) eski hesaplanmış
     stil yoluyla çalışmaya devam eder. */
  const recordById=new Map(),columnByKey=new Map();
  if(opts.tableKey&&Array.isArray(opts.records)){
    opts.records.forEach(row=>{if(row&&row._id!=null)recordById.set(String(row._id),row);});
    visibleCols(opts.tableKey).forEach(column=>columnByKey.set(column.k,column));
  }
  const imageEntries=[];
  let exported=0,imagesRequested=0;
  for(const tr of candidateRows){
    if(selSet){
      const id=tr.getAttribute(idAttr)??tr.dataset.id;
      if(id==null||(!selSet.has(Number(id))&&!selSet.has(String(id))&&!selSet.has(id)))continue;
    }
    const rowId=tr.getAttribute(idAttr)??tr.dataset.id;
    const record=rowId==null?null:(recordById.get(String(rowId))||null);
    const cf=record&&typeof opts.computeFn==='function'?opts.computeFn(record):null;
    let col=1;
    for(const td of [...tr.children]){
      if(td.classList.contains('chkCell'))continue;
      const fieldKey=td.dataset.key||leafHeaders[col-1];
      const column=columnByKey.get(String(td.dataset.key||''))||null;
      const palette=record?exportSemanticPalette(column,record,cf):null;
      const thumb=td.querySelector('img.kolThumb');
      // Görsel hücresi kayıttan tanınır: satırın ekranda çizilmiş/yüklenmiş
      // olması gerekmez.
      const identity=record&&column&&column.type==='cpImage'?cpOrdersRowImageIdentity(record):null;
      const domSrc=thumb&&thumb.dataset.hasImage==='1'?String(thumb.dataset.src||thumb.currentSrc||thumb.src||''):'';
      const domImage=!identity&&domSrc&&!/^data:image\/svg\+xml/i.test(domSrc)?domSrc:'';
      if(identity||domImage||(column&&column.type==='cpImage')||thumb){
        const base=_xlsCellFromTd(td,{forceIdentifierText:false,fieldKey,palette});
        base.v='';base.t='s';
        _setExcelJsCellFromSheetSpec(ws.getCell(excelRow,col),base);
        const tdRect=td.getBoundingClientRect(),trRect=tr.getBoundingClientRect();
        if(identity||domImage){
          imagesRequested++;
          imageEntries.push({row:excelRow,col:col-1,identity,src:domImage,cellWidth:tdRect.width||0,cellHeight:trRect.height||0});
        }
      }else{
        const spec=_xlsCellFromTd(td,{forceIdentifierText:isIdentifierHeader(leafHeaders[col-1]),fieldKey,palette});
        _setExcelJsCellFromSheetSpec(ws.getCell(excelRow,col),spec);
      }
      col++;maxCol=Math.max(maxCol,col-1);
    }
    ws.getRow(excelRow).height=Math.max(18,Math.ceil(tr.getBoundingClientRect().height||19))*72/96;
    excelRow++;exported++;
  }
  if(!exported){showToast('Aktarılacak satır yok.');return;}

  for(let i=1;i<=maxCol;i++)ws.getColumn(i).width=columnWidths[i-1]||12;
  if(headRows.length)ws.views=[{state:'frozen',ySplit:headRows.length,topLeftCell:`A${headRows.length+1}`}];
  ws.autoFilter={from:{row:headRows.length,column:1},to:{row:Math.max(headRows.length,excelRow-1),column:maxCol}};

  // Kitap SERİLEŞTİRİLMEDEN ÖNCE bütün görseller çözülür; writeBuffer yalnız bu
  // bekleme bittikten sonra çağrılır.
  const prepared=await _prepareExcelJsImages(imageEntries);
  const mediaIds=new Map();
  let imagesEmbedded=0;
  imageEntries.forEach((entry,index)=>{
    const image=prepared[index];if(!image)return;
    try{
      const column=ws.getColumn(entry.col+1),row=ws.getRow(entry.row);
      if(Number(entry.cellWidth)>0)column.width=Math.max(3,(Number(entry.cellWidth)-5)/7);
      if(Number(entry.cellHeight)>0)row.height=Number(entry.cellHeight)*72/96;
      const cellWidth=kolExcelColumnWidthPx(column.width||8),cellHeight=(Number(row.height)||24)*96/72;
      // Aynı model görselini paylaşan satırlar tek medya kaydını kullanır; ankraj
      // yine SATIR BAŞINA yazılır, yani her satır kendi görselini taşır.
      const mediaKey=entry.identity?entry.identity.key:String(entry.src||index);
      let imageId=mediaIds.get(mediaKey);
      if(imageId===undefined){imageId=wb.addImage({base64:image.dataUrl,extension:image.extension||'png'});mediaIds.set(mediaKey,imageId);}
      ws.addImage(imageId,kolExcelImageTwoCellPlacement(image,entry.row,cellWidth,cellHeight,entry.col+1,2));
      imagesEmbedded++;
    }catch(err){console.warn('Excel image could not be embedded:',err);}
  });
  if(window.BLExcelDates)window.BLExcelDates.normalizeExcelJsWorkbookDateColumns(wb);
  const buffer=await wb.xlsx.writeBuffer();
  const d=new Date(),pad=x=>String(x).padStart(2,'0');
  const filename=`${opts.fileBase||'Tablo'}_${d.getFullYear()}${pad(d.getMonth()+1)}${pad(d.getDate())}.xlsx`;
  kolDownloadBuffer(buffer,filename,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  // Görsel sonucu TEK bir özet olarak bildirilir; görsel başına bildirim yok.
  const missing=Math.max(0,imagesRequested-imagesEmbedded);
  const imageNote=imagesRequested
    ? ` · ${imagesEmbedded}/${imagesRequested} model görseli eklendi${missing?` (${missing} görsel alınamadı)`:''}`
    : '';
  showToast(`${exported} satır Excel'e aktarıldı${hasVisibleSelection?' (yalnızca işaretliler)':' (mevcut filtre)'}${imageNote}.`);
  }finally{
    releaseFullLayout();
  }
}

/* CP Export eskiden Excel'i aydınlık üretebilmek için temayı geçici olarak
   "light" yapıp tabloyu İKİ KEZ yeniden çiziyordu; renkler ekranın hesaplanmış
   CSS'inden okunduğu için başka yolu yoktu. Orders'ta bu örtü hiç olmadığından
   koyu tema renkleri doğrudan kitaba yazılıyordu. Renkler artık kanonik
   aydınlık paletten geldiği için (bkz. exportSemanticPalette) tema değişimi,
   perde ve yeniden çizim gereksizdir: CP ve Orders aynı yolu kullanır ve
   ekrandaki tema/kaydırma/filtre durumu hiç bozulmaz. */
async function exportCpTableWithLightTheme(){
  return await exportActiveTableStyled();
}
// Aktif sekmedeki tabloyu dışa aktarır (CP / Orders / Nakliye).
async function exportActiveTableStyled(){
  const tab = document.body.dataset.activeTab;
  const cfg = {
    cp:      {sel:'#cpTable',   set:state.cpSelected,   name:'CP_Tracker', tableKey:'cp', rowsFn:()=>filteredCP(), computeFn:computeFlags},
    orders:  {sel:'#ordersTable',set:state.ordersSelected,name:'Orders', tableKey:'orders', rowsFn:()=>filteredOrders(), computeFn:computeFlags},
    shipping:{sel:'#shipTable', set:(typeof shipSelected!=='undefined'?shipSelected:new Set()), name:'Nakliye_Kiyaslama', idAttr:'data-shipid'},
  }[tab];
  if(!cfg){ showToast('Bu sayfada dışa aktarılacak tablo yok.'); return; }
  return await exportStyledDomTable(cfg.sel, {
    selectedSet:cfg.set, fileBase:cfg.name, sheetName:cfg.name.replace(/_/g,' ').slice(0,30), idAttr:cfg.idAttr,
    tableKey:cfg.tableKey, records:cfg.rowsFn?cfg.rowsFn():null, computeFn:cfg.computeFn||null,
  });
}

// ================= TEMA — AYDINLIK / GRİ / KARANLIK =================
const THEMES = { light:{label:'Aydınlık', labelEn:'Light', icon:'#i-moon'}, grey:{label:'Kurşun', labelEn:'Slate', icon:'#i-contrast'}, dark:{label:'Karanlık', labelEn:'Dark', icon:'#i-sun'} };
// Tema adı tek yerden okunur: hem panel hem ray düğmesinin ipucu bunu kullanır.
// Antrasit teması kaldırıldı. Taşıma kodu da v5.00'de silindi; tanınmayan bir
// tema adı gelirse applyTheme sistem temasına düşer.
function themeLabel(key){ const th=THEMES[key]; if(!th) return key; return (appLang==='en'&&th.labelEn)?th.labelEn:th.label; }
function themeCycleTitle(){ const names=THEME_CYCLE.map(themeLabel).join(' → '); return (appLang==='en'?'Theme: ':'Tema: ')+names; }
const THEME_CYCLE = ['light','grey','dark'];
function systemTheme(){ return (window.matchMedia && matchMedia('(prefers-color-scheme: dark)').matches) ? 'dark' : 'light'; }
let _themeSwitchRelease=null;
function beginFastThemeSwitch(){
  const root=document.documentElement,body=document.body;
  if(!body||document.readyState==='loading')return null;
  if(typeof _themeSwitchRelease==='function')_themeSwitchRelease(true);
  const cs=getComputedStyle(body);
  const curtain=document.createElement('div');
  curtain.id='_fastThemeCurtain';
  curtain.style.backgroundColor=cs.backgroundColor||'#F6F7F9';
  curtain.style.color=cs.color||'#101828';
  body.appendChild(curtain);
  root.classList.add('blThemeSwitching');
  // Önce ağır tablo alt ağaçlarını render dışına al; ardından tema değişsin.
  void curtain.offsetWidth;
  let released=false;
  const release=immediate=>{
    if(released)return;released=true;
    const finish=()=>{
      root.classList.remove('blThemeSwitching');
      curtain.remove();
      if(_themeSwitchRelease===release)_themeSwitchRelease=null;
    };
    if(immediate){finish();return;}
    requestAnimationFrame(()=>requestAnimationFrame(finish));
  };
  _themeSwitchRelease=release;
  return release;
}
function applyTheme(name){
  const resolved = THEMES[name] ? name : systemTheme();
  const root = document.documentElement;
  const use=document.querySelector('#railThemeBtn use');
  try{void window.buyerLogDesktop?.workspace?.setTheme?.(resolved);}catch(_){}
  if(root.dataset.theme===resolved){
    if(use)use.setAttribute('href',THEMES[resolved].icon);
    try{BLStorage.setItem('lcw_theme',resolved);}catch(e){}
    return;
  }
  const release=beginFastThemeSwitch();
  root.dataset.theme = resolved;
  // colorScheme: gri tema açık tarafta olduğu için tarayıcı yerel kontrolleri aydınlık görünsün.
  root.style.colorScheme = (resolved==='dark') ? 'dark' : 'light';
  if(use) use.setAttribute('href', THEMES[resolved].icon);
  try{ BLStorage.setItem('lcw_theme', resolved); }catch(e){}
  syncThemeButtonTitle();
  if(release)release(false);
}
// Ray düğmesinin ipucu artık elle yazılmıyor; tema listesi değişirse metin de değişir.
function syncThemeButtonTitle(){
  const btn=document.getElementById('railThemeBtn'); if(!btn) return;
  const title=themeCycleTitle();
  btn.setAttribute('title',title);
  btn.setAttribute('aria-label',title);
  btn.setAttribute('data-i18n-title-tr','Tema: '+THEME_CYCLE.map(k=>THEMES[k]?THEMES[k].label:k).join(' → '));
  btn.setAttribute('data-i18n-title-en','Theme: '+THEME_CYCLE.map(k=>THEMES[k]?(THEMES[k].labelEn||THEMES[k].label):k).join(' → '));
}
function nextTheme(){
  const cur = document.documentElement.dataset.theme || 'light';
  const i = THEME_CYCLE.indexOf(cur);
  return THEME_CYCLE[(i<0?0:i+1) % THEME_CYCLE.length];
}
function renderThemePanel(){
  const panel = document.getElementById('themePanel'); if(!panel) return;
  const cur = document.documentElement.dataset.theme || 'light';
  panel.innerHTML = Object.entries(THEMES).map(([key,t])=>
    `<button class="themeOptBtn" data-theme="${key}"><span class="tik">${key===cur?'✓':''}</span><span>${escapeHtml(themeLabel(key))}</span></button>`
  ).join('');
  panel.querySelectorAll('.themeOptBtn').forEach(b=> b.addEventListener('click', ()=>{
    applyTheme(b.dataset.theme); renderThemePanel(); panel.style.display='none';
  }));
}
const UI_SCALE_PRESETS=[
  {key:'standard',tr:'Standard',en:'Standard'},
  {key:'large',tr:'Büyük',en:'Large'},
  {key:'xl',tr:'Çok Büyük',en:'XL'},
  {key:'compact',tr:'Kompakt',en:'Compact'},
];
function normalizeUiFontStep(value){const n=Number(value);return Number.isFinite(n)?Math.max(0,Math.min(3,Math.trunc(n))):0;}
function applyUiFontStep(value,{persist=true}={}){
  const step=normalizeUiFontStep(value),preset=UI_SCALE_PRESETS[step];
  document.documentElement.dataset.fontStep=String(step);
  document.documentElement.dataset.uiScale=preset.key;
  const btn=document.getElementById('railFontSizeBtn'),label=document.getElementById('railFontSizeLabel');
  const text=appLang==='en'?`Interface: ${preset.en}`:`Arayüz: ${preset.tr}`;
  if(label)label.textContent=text;
  if(btn)btn.title=appLang==='en'?`Interface size: ${preset.en} · click for next size`:`Arayüz boyutu: ${preset.tr} · sonraki boyut için tıkla`;
  if(persist)try{BLStorage.setItem('lcw_font_step',String(step));}catch(_){}
  requestAnimationFrame(()=>window.dispatchEvent(new Event('resize')));
  return step;
}
function cycleUiFontStep(){const cur=normalizeUiFontStep(document.documentElement.dataset.fontStep);applyUiFontStep((cur+1)%4);}
document.getElementById('railFontSizeBtn')?.addEventListener('click',cycleUiFontStep);
applyUiFontStep(document.documentElement.dataset.fontStep||0,{persist:false});

const _themeBtnEl = document.getElementById('themeBtn');
if(_themeBtnEl) _themeBtnEl.addEventListener('click', ()=>{
  const panel = document.getElementById('themePanel'); if(!panel) return;
  if(panel.style.display==='none'){ renderThemePanel(); panel.style.display='block'; }
  else panel.style.display='none';
});
document.addEventListener('click', e=>{
  const panel = document.getElementById('themePanel'); if(!panel) return;
  const wrap = document.getElementById('themeBtn')?.parentElement;
  if(panel.contains(e.target)) return;
  if(wrap && wrap.contains(e.target)) return;
  panel.style.display='none';
});
(function(){ try{ applyTheme(BLStorage.getItem('lcw_theme')||systemTheme()); }catch(e){ applyTheme('light'); } })();

(function premiumEnhancements(){
  document.documentElement.lang='tr';
  const themeBtn=document.getElementById('headerThemeBtn'); if(themeBtn) themeBtn.addEventListener('click',()=>applyTheme(nextTheme()));
  document.querySelectorAll('button[title]').forEach(b=>{if(!b.getAttribute('aria-label'))b.setAttribute('aria-label',b.title)});
  if(window.matchMedia) window.matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{try{if((BLStorage.getItem('lcw_theme')||'dark')==='__never_system__')applyTheme('system')}catch(e){}});
})();

