// ================= KOLEKSİYON (henüz sipariş olmamış konsept modeller) =================
// CP ile aynı görsel dilde ama lojistik/onay alanları olmadan; tüm hücreler elle
// düzenlenebilir. Sunucudaki ASAS/Antrepo verisinden bağımsızdır — tarayıcıda saklanır.
const KOL_STORAGE_KEY = 'lcw.koleksiyon.rows.v1';
let kolWorkspaceOwnerId=String(window.BL_USER_CONTEXT&&window.BL_USER_CONTEXT.id||'moderator');
let kolWorkspaceRevision=0;
let kolWorkspaceCanEdit=true;
let kolWorkspaceList=[];
let kolWorkspaceSharedMode=false;
let kolWorkspaceMode='single';
let kolWorkspaceSelectedOwnerIds=new Set([kolWorkspaceOwnerId]);
const KOL_SCOPE_PREF_KEY='lcw.koleksiyon.scope.v1';
let kolPermissionState=null;
let kolScopeOutsideClickBound=false;
let kolWorkspaceSaveTimer=null;
let kolWorkspaceSaving=false;
let kolWorkspacePending=false;
let kolWorkspaceSavePromise=null;
function kolWorkspaceLocalKey(ownerId){return `bl.collection.workspace.${String(ownerId||'anonymous').replace(/[^A-Za-z0-9_-]/g,'_')}.v1`;}
function kolWorkspacePendingKey(ownerId){return `bl.collection.pending.${String(ownerId||'anonymous').replace(/[^A-Za-z0-9_-]/g,'_')}.v1`;}
function kolPersistPendingWorkspace(status='pending'){
  if(!kolWorkspaceCanEdit||!kolWorkspaceOwnerId||kolWorkspaceOwnerId==='__multi__')return false;
  try{
    localStorage.setItem(kolWorkspacePendingKey(kolWorkspaceOwnerId),JSON.stringify({
      schemaVersion:1,ownerId:kolWorkspaceOwnerId,baseRevision:kolWorkspaceRevision,status,
      rows:kolRows.map(kolPersistableRow),manufacturers:kolManufacturers,customColumns:kolCustomCols,statusCatalog:kolStatusEntries(),nextId:kolNextId,
      updatedAt:new Date().toISOString(),
    }));
    return true;
  }catch(err){showToast((appLang==='en'?'Pending Collection change could not be secured on this device: ':'Bekleyen Koleksiyon değişikliği bu cihazda güvenli hale getirilemedi: ')+(err.message||err));return false;}
}
function kolReadPendingWorkspace(ownerId){try{return JSON.parse(localStorage.getItem(kolWorkspacePendingKey(ownerId))||'null');}catch(_){return null;}}
function kolClearPendingWorkspace(ownerId){try{localStorage.removeItem(kolWorkspacePendingKey(ownerId));}catch(_){}}
function kolHasDirtyWorkspace(){const change=kolCollectChanges();return Boolean(change&&!change.empty);}
function kolRestorePendingWorkspace(){
  const pending=kolReadPendingWorkspace(kolWorkspaceOwnerId);
  if(!pending||pending.ownerId!==kolWorkspaceOwnerId||!Array.isArray(pending.rows)||!kolWorkspaceCanEdit)return false;
  kolStatusCatalog=kolNormalizeStatusCatalog(pending.statusCatalog,pending.rows);
  kolRows=kolNormalizeModelGroups(pending.rows.map(migrateKolRow));
  kolManufacturers=Array.isArray(pending.manufacturers)?pending.manufacturers:kolManufacturers;
  kolCustomCols=kolNormalizeCustomCols(Array.isArray(pending.customColumns)?pending.customColumns:kolCustomCols);
  kolNextId=Math.max(Number(pending.nextId)||1,1+kolRows.reduce((m,r)=>Math.max(m,Number(r&&r.id)||0),0));
  refreshSubmfrList();loadKolColState({preserveCustom:true});renderKol();scheduleOverviewCollectionSummaryRender();
  if(!kolHasDirtyWorkspace()){kolClearPendingWorkspace(kolWorkspaceOwnerId);return false;}
  return true;
}
function kolRequireWorkspaceEdit(){if(kolWorkspaceCanEdit)return true;showToast(appLang==='en'?'This Collection page is view-only.':'Bu Koleksiyon sayfası yalnız görüntülenebilir.');return false;}
function kolPersistableRow(row){
  if(!row||typeof row!=='object')return row;
  if(!Object.prototype.hasOwnProperty.call(row,'_sharedCollectionImageUrl'))return {...row};
  const next={...row};delete next._sharedCollectionImageUrl;return next;
}
function kolWorkspacePayload(){return {rows:kolRows.map(kolPersistableRow),manufacturers:kolManufacturersForPersistence(),customColumns:kolCustomCols,statusCatalog:kolStatusEntries(),nextId:kolNextId,expectedRevision:kolWorkspaceRevision};}

/* ===================================================================
   v7.22 — YALNIZ DEĞİŞEN SATIRLAR GÖNDERİLİR.

   Eskiden her kayıt bütün sayfayı gönderiyordu (uç noktanın gövde sınırı
   100 MB) ve revizyon kontrolü bütün sayfa bazındaydı: A 1. satırı, B 900.
   satırı düzenlediğinde B'nin yazması reddediliyor, istemci güncel sürümü
   yükleyip B'nin girişini atıyordu — ölçülen gerçek veri kaybı.

   NEDEN MUTASYON NOKTALARI İŞARETLENMİYOR: "değişen satırı burada kaydet"
   yaklaşımı, Koleksiyon'daki onlarca düzenleme yolundan BİRİNİ atlamak
   demek olurdu ve atlanan yol sessizce hiç kaydedilmezdi — düzeltmeye
   çalıştığımız hatanın daha sinsi bir biçimi. Bunun yerine son başarılı
   kayıttaki TEMEL ANLIK GÖRÜNTÜ tutulur ve fark ondan alınır. Hangi yolla
   değiştiği önemli değildir; değiştiyse görülür.
   =================================================================== */
let kolBaseline=null; // { rows:Map(id→satır kopyası), structure:string, ownerId }
function kolRowKey(row){const id=row&&row.id;return id==null||id===''?'':String(id);}
function kolStructureSignature(){
  return JSON.stringify({columns:kolCustomCols||[],manufacturers:kolManufacturers||[],statusCatalog:kolStatusEntries(),order:kolRows.map(kolRowKey)});
}
function kolCaptureBaseline(){
  const rows=new Map();
  for(const row of kolRows){const key=kolRowKey(row);if(key)rows.set(key,kolPersistableRow(row));}
  kolBaseline={ownerId:kolWorkspaceOwnerId,rows,structure:kolStructureSignature()};
}
// Sığ karşılaştırma: satır başına JSON.stringify, 50.000 satırlık bir sayfada
// tek başına yüzlerce milisaniye sürüyordu (sunucu tarafında ölçüldü).
function kolRowEqual(a,b){
  if(a===b)return true;
  if(!a||!b)return false;
  const keysA=Object.keys(a).filter(k=>k!=='_rev'&&k!=='_sharedCollectionImageUrl'),keysB=Object.keys(b).filter(k=>k!=='_rev'&&k!=='_sharedCollectionImageUrl');
  if(keysA.length!==keysB.length)return false;
  for(const key of keysA){
    const left=a[key],right=b[key];
    if(left===right)continue;
    if(left==null&&right==null)continue;
    // Kayıt öncesi normalleştirme iç nesneleri (pricing, pricingSent,
    // variantOverrides…) yeniden oluşturur: referans değil içerik karşılaştırılır,
    // yoksa dokunulmamış bütün satırlar değişmiş sayılıp gönderiliyordu.
    if(left&&right&&typeof left==='object'&&typeof right==='object'&&kolValueEqual(left,right))continue;
    return false;
  }
  return true;
}
function kolValueEqual(a,b){
  if(a===b||(a==null&&b==null))return true;
  if((a&&typeof a==='object')||(b&&typeof b==='object')){
    try{return JSON.stringify(a)===JSON.stringify(b);}catch(_){}
  }
  return false;
}
function kolRowChangedFromBase(base,local){
  if(!base||!local)return base!==local;
  const keys=new Set([...Object.keys(base),...Object.keys(local)]);
  keys.delete('_rev');keys.delete('_sharedCollectionImageUrl');
  for(const key of keys){
    const hasBase=Object.prototype.hasOwnProperty.call(base,key);
    const hasLocal=Object.prototype.hasOwnProperty.call(local,key);
    if(hasBase!==hasLocal||!kolValueEqual(base[key],local[key]))return true;
  }
  return false;
}
function kolCloneConflictValue(value){
  if(!value||typeof value!=='object')return value;
  try{return JSON.parse(JSON.stringify(value));}catch(_){return value;}
}
// Üç yönlü birleştirme: uzak satırı temel alır, yalnız bu ekranda gerçekten
// değiştirilmiş alanları tekrar uygular. Böylece başka pencerenin farklı
// alanlardaki güncellemesi ezilmez; kullanıcının kendi girişi de kaybolmaz.
function kolMergeLocalRowDelta(base,local,remote){
  const next=migrateKolRow({...remote});
  const keys=new Set([...Object.keys(base||{}),...Object.keys(local||{})]);
  keys.delete('_rev');keys.delete('_sharedCollectionImageUrl');
  for(const key of keys){
    const hasBase=Object.prototype.hasOwnProperty.call(base||{},key);
    const hasLocal=Object.prototype.hasOwnProperty.call(local||{},key);
    if(hasBase===hasLocal&&kolValueEqual(base&&base[key],local&&local[key]))continue;
    if(!hasLocal){delete next[key];continue;}
    next[key]=kolCloneConflictValue(local[key]);
  }
  if(remote&&Object.prototype.hasOwnProperty.call(remote,'_rev'))next._rev=remote._rev;
  return next;
}
function kolIsOwnWorkspace(){
  const current=String(window.BL_USER_CONTEXT&&window.BL_USER_CONTEXT.id||'');
  return Boolean(current)&&String(kolWorkspaceOwnerId||'')===current;
}
function kolCollectChanges(){
  if(!kolBaseline||kolBaseline.ownerId!==kolWorkspaceOwnerId)return null; // temel yok: tam kayıt gerekir
  const upserts=[],deletes=[];
  const seen=new Set();
  for(const row of kolRows){
    const key=kolRowKey(row);
    if(!key)continue; // id'siz satır satır bazlı gönderilemez
    seen.add(key);
    const base=kolBaseline.rows.get(key);
    if(!base){upserts.push(kolPersistableRow(row));continue;}
    if(!kolRowEqual(base,row))upserts.push({...kolPersistableRow(row),_rev:base._rev});
  }
  for(const [key,base] of kolBaseline.rows){
    // SİLME satırın yokluğundan çıkarılmaz, açıkça bildirilir.
    if(!seen.has(key))deletes.push({id:base.id,_rev:base._rev});
  }
  const structureChanged=kolStructureSignature()!==kolBaseline.structure;
  if(!upserts.length&&!deletes.length&&!structureChanged)return {empty:true};
  const change={upserts,deletes,nextId:kolNextId};
  if(structureChanged){
    change.baseRevision=kolWorkspaceRevision;
    change.structure={manufacturers:kolManufacturersForPersistence(),customColumns:kolCustomCols,statusCatalog:kolStatusEntries(),order:kolRows.map(kolRowKey).filter(Boolean)};
  }
  return change;
}
// Kaydedilemeyen satırlar SESSİZCE geçilmez: kullanıcı hangi satırın
// kaydedilmediğini ve sunucudaki değerin ne olduğunu bilmelidir.
function kolReportConflicts(conflicts){
  const list=Array.isArray(conflicts)?conflicts.filter(item=>item&&item.id!=null):[];
  if(!list.length)return false;
  const own=kolIsOwnWorkspace();
  let rebased=false;
  for(const item of list){
    if(!item.current)continue;
    const key=String(item.id);
    const remote=migrateKolRow({...item.current});
    const base=kolBaseline&&kolBaseline.rows.get(key);
    const index=kolRowIndexById(item.id);
    const local=index>=0?kolRows[index]:null;
    // Kendi Koleksiyon'unda satır revizyonu değişmişse kullanıcıyı durdurma:
    // uzaktaki güncel satır üzerine yalnız yerel farkı taşı ve otomatik tekrar dene.
    if(own&&base&&local){
      kolRows[index]=kolMergeLocalRowDelta(base,local,remote);
      rebased=true;
    }
    if(kolBaseline)kolBaseline.rows.set(key,{...remote});
  }
  kolPersistPendingWorkspace(rebased?'rebased':'conflict');
  if(!rebased){
    const ids=list.map(item=>item.id).slice(0,5).join(', ');
    const more=list.length>5?` (+${list.length-5})`:'';
    showToast(appLang==='en'
      ?`${list.length} row(s) changed while you were editing and could not be saved: ${ids}${more}. Your local edit is still preserved.`
      :`${list.length} satır siz düzenlerken değişti ve kaydedilemedi: ${ids}${more}. Yerel girişiniz korunmaya devam ediyor.`);
  }
  return rebased;
}
function kolWorkspaceSetReadonly(){
  const root=document.getElementById('view-koleksiyon');if(root)root.dataset.workspaceReadonly=kolWorkspaceCanEdit?'0':'1';
  const badge=document.getElementById('kolWorkspaceAccess');if(badge){badge.textContent=kolWorkspaceMode==='multi'?(appLang==='en'?'Multi view':'Çoklu görünüm'):kolWorkspaceCanEdit?(appLang==='en'?'Edit':'Düzenleme'):(appLang==='en'?'View':'Görüntüleme');badge.classList.toggle('isView',!kolWorkspaceCanEdit);}
  // Satır seçimi gerektiren eylemler burada açılmaz; güncel seçim ve işlem
  // durumu `updateKolSendBtnState` tarafından belirlenir.
  const ids=['kolPlmImportBtn','kolPricingExcelColsBtn','kolCreateOcBtn','kolQuotationsBtn','kolSendPricingBtn','kolUndoBtn','kolRedoBtn','kolAddRowBtn','kolModelFilesBtn','kolManageStatusesBtn'];
  ids.forEach(id=>{const el=document.getElementById(id);if(!el)return;if(el.tagName==='LABEL')el.style.pointerEvents=kolWorkspaceCanEdit?'':'none';el.toggleAttribute('disabled',!kolWorkspaceCanEdit);el.setAttribute('aria-disabled',kolWorkspaceCanEdit?'false':'true');});
}
function kolApplyWorkspace(workspace,access){
  kolWorkspaceMode='single';kolWorkspaceSelectedOwnerIds=new Set([kolWorkspaceOwnerId]);
  kolWorkspaceRevision=Number(workspace&&workspace._revision)||0;kolWorkspaceCanEdit=Boolean(access&&access.canEdit);
  const rawRows=Array.isArray(workspace&&workspace.rows)?workspace.rows:[];
  kolStatusCatalog=kolNormalizeStatusCatalog(workspace&&workspace.statusCatalog,rawRows);
  kolRows=kolNormalizeModelGroups(rawRows.map(migrateKolRow));
  kolManufacturers=Array.isArray(workspace&&workspace.manufacturers)?workspace.manufacturers:[];
  const rawCustomCols=Array.isArray(workspace&&workspace.customColumns)?workspace.customColumns:[];
  const legacyAssortment=rawCustomCols.find(col=>turknorm(norm(col&&col.label))==='ASSORTMENT');
  if(legacyAssortment){
    kolRows.forEach(row=>{if(!norm(row.assortment)&&row[legacyAssortment.k]!=null)row.assortment=norm(row[legacyAssortment.k]);delete row[legacyAssortment.k];});
  }
  kolCustomCols=kolNormalizeCustomCols(rawCustomCols.filter(col=>!legacyAssortment||col.k!==legacyAssortment.k));
  kolNextId=Math.max(Number(workspace&&workspace.nextId)||1,1+kolRows.reduce((m,r)=>Math.max(m,Number(r&&r.id)||0),0));
  kolSelected.clear();kolUndoStack=[];kolRedoStack=[];refreshSubmfrList();loadKolColState({preserveCustom:true});kolWorkspaceSetReadonly();renderKol();
  kolCaptureBaseline();
  try{localStorage.setItem(kolWorkspaceLocalKey(kolWorkspaceOwnerId),JSON.stringify({rows:kolRows.map(kolPersistableRow),manufacturers:kolManufacturersForPersistence(),customColumns:kolCustomCols,statusCatalog:kolStatusEntries(),nextId:kolNextId,_revision:kolWorkspaceRevision}));}catch(_){}
  kolRestorePendingWorkspace();
  scheduleOverviewCollectionSummaryRender();
}
async function kolRebaseOwnWorkspace(ownerId){
  if(!kolIsOwnWorkspace()||String(ownerId)!==String(kolWorkspaceOwnerId)||!kolBaseline||kolBaseline.ownerId!==ownerId)return false;
  const originalBaseline=kolBaseline;
  const baseRows=originalBaseline.rows;
  let baseStructure={};
  try{baseStructure=JSON.parse(originalBaseline.structure||'{}')||{};}catch(_){}
  const localRows=kolRows.map(kolPersistableRow);
  const localById=new Map(localRows.map(row=>[kolRowKey(row),row]).filter(([key])=>key));
  const localStructure={
    columns:kolCustomCols||[],
    manufacturers:kolManufacturers||[],
    statusCatalog:kolStatusEntries(),
    order:localRows.map(kolRowKey).filter(Boolean),
  };
  kolPersistPendingWorkspace('rebasing');

  const res=await fetch(`/api/collection-workspaces/${encodeURIComponent(ownerId)}?rebase=${Date.now()}`,{cache:'no-store'});
  const data=await res.json().catch(()=>({}));
  if(!res.ok||kolWorkspaceOwnerId!==ownerId)return false;
  kolReportReplication(data.replication);
  const remote=data.workspace||{};
  const remoteRows=Array.isArray(remote.rows)?remote.rows.map(row=>migrateKolRow({...row})):[];
  const remoteStructure={
    columns:Array.isArray(remote.customColumns)?remote.customColumns:[],
    manufacturers:Array.isArray(remote.manufacturers)?remote.manufacturers:[],
    statusCatalog:Array.isArray(remote.statusCatalog)?remote.statusCatalog:[],
    order:remoteRows.map(kolRowKey).filter(Boolean),
  };

  const merged=[];
  const consumed=new Set();
  for(const remoteRow of remoteRows){
    const key=kolRowKey(remoteRow);
    const local=key?localById.get(key):null;
    const base=key?baseRows.get(key):null;
    if(local){
      merged.push(base?kolMergeLocalRowDelta(base,local,remoteRow):kolMergeLocalRowDelta({},local,remoteRow));
      consumed.add(key);
      continue;
    }
    if(base){
      // Yerelde silinmiş ama uzakta aynı satır sonradan değiştirilmişse sessizce
      // silmeyiz; uzak değişiklik korunur. Değişmemişse kullanıcının silmesi kalır.
      if(kolRowChangedFromBase(base,remoteRow))merged.push(remoteRow);
      consumed.add(key);
      continue;
    }
    merged.push(remoteRow);
  }
  for(const local of localRows){
    const key=kolRowKey(local);
    if(!key||consumed.has(key))continue;
    const base=baseRows.get(key);
    // Uzakta silinen dokunulmamış satır geri dirilmez; yerelde değiştirilmiş
    // veya yeni satır ise kullanıcının işi korunur.
    if(!base||kolRowChangedFromBase(base,local))merged.push(local);
  }

  const choose=(localValue,baseValue,remoteValue)=>kolValueEqual(localValue,baseValue)?remoteValue:localValue;
  kolCustomCols=kolNormalizeCustomCols(choose(localStructure.columns,baseStructure.columns||[],remoteStructure.columns));
  kolManufacturers=choose(localStructure.manufacturers,baseStructure.manufacturers||[],remoteStructure.manufacturers);
  kolStatusCatalog=kolNormalizeStatusCatalog(choose(localStructure.statusCatalog,baseStructure.statusCatalog||[],remoteStructure.statusCatalog),merged);

  const localOrderChanged=!kolValueEqual(localStructure.order,baseStructure.order||[]);
  const wanted=localOrderChanged?localStructure.order:remoteStructure.order;
  const byId=new Map(merged.map(row=>[kolRowKey(row),row]).filter(([key])=>key));
  const ordered=[];
  for(const id of wanted){const row=byId.get(String(id));if(row){ordered.push(row);byId.delete(String(id));}}
  for(const row of byId.values())ordered.push(row);
  kolRows=kolNormalizeModelGroups(ordered);

  kolWorkspaceRevision=Number(remote._revision)||kolWorkspaceRevision;
  const remoteBaselineRows=new Map();
  for(const row of remoteRows){const key=kolRowKey(row);if(key)remoteBaselineRows.set(key,{...row});}
  kolBaseline={ownerId,rows:remoteBaselineRows,structure:JSON.stringify(remoteStructure)};
  kolNextId=Math.max(Number(remote.nextId)||1,kolNextId,1+kolRows.reduce((max,row)=>Math.max(max,Number(row&&row.id)||0),0));
  kolSelected=new Set([...kolSelected].filter(id=>kolRowIndexById(id)>=0));
  refreshSubmfrList();loadKolColState({preserveCustom:true});renderKol();scheduleOverviewCollectionSummaryRender();
  try{localStorage.setItem(kolWorkspaceLocalKey(ownerId),JSON.stringify({rows:kolRows.map(kolPersistableRow),manufacturers:kolManufacturersForPersistence(),customColumns:kolCustomCols,statusCatalog:kolStatusEntries(),nextId:kolNextId,_revision:kolWorkspaceRevision}));}catch(_){}
  kolPersistPendingWorkspace('rebased');
  return true;
}
async function kolSaveWorkspaceNow(saveOptions){
  const options=saveOptions&&typeof saveOptions==='object'?saveOptions:{};
  const conflictRetry=Math.max(0,Number(options._conflictRetry)||0);
  clearTimeout(kolWorkspaceSaveTimer);kolWorkspaceSaveTimer=null;
  if(!kolWorkspaceCanEdit)return {ok:true,durable:true,skipped:true};
  if(kolWorkspaceSaving){kolWorkspacePending=true;const activeResult=await kolWorkspaceSavePromise;return kolWorkspacePending?kolSaveWorkspaceNow(options):activeResult;}
  const ownerId=kolWorkspaceOwnerId;
  const change=kolCollectChanges();
  if(change&&change.empty){kolWorkspacePending=false;return {ok:true,durable:true,unchanged:true};}
  const payload=JSON.parse(JSON.stringify(change||kolWorkspacePayload()));
  const rowMode=Boolean(change);
  if(rowMode&&options.atomic===true)payload.atomic=true;
  kolWorkspaceSaving=true;kolWorkspacePending=false;
  kolWorkspaceSavePromise=(async()=>{
    try{
      const res=await fetch(`/api/collection-workspaces/${encodeURIComponent(ownerId)}`,{
        method:rowMode?'PATCH':'PUT',
        headers:{'Content-Type':'application/json',...(window.BL_CLIENT_ID?{'X-Client-Id':window.BL_CLIENT_ID}:{})},
        body:JSON.stringify(payload),
      });
      const data=await res.json().catch(()=>({}));
      if(!res.ok){const err=new Error(data.error||res.statusText);err.code=data.code;err.currentRevision=data.currentRevision;err.conflicts=data.conflicts;throw err;}
      kolReportReplication(data.replication);
      if(kolWorkspaceOwnerId!==ownerId)return {ok:true,durable:true,ownerChanged:true};
      let ownConflictRebased=false;
      if(rowMode){
        kolWorkspaceRevision=Number(data.revision)||kolWorkspaceRevision;
        for(const item of Array.isArray(data.applied)?data.applied:[]){
          if(item.kind==='removed')continue;
          const index=kolRowIndexById(item.id);
          if(index>=0)kolRows[index]._rev=Number(item.rev)||kolRows[index]._rev;
        }
        if(!kolBaseline)kolCaptureBaseline();
        for(const item of Array.isArray(data.applied)?data.applied:[]){
          const key=String(item.id),sent=(payload.upserts||[]).find(row=>kolRowKey(row)===key);
          if(item.kind==='removed'){kolBaseline.rows.delete(key);continue;}
          if(sent)kolBaseline.rows.set(key,{...sent,_rev:Number(item.rev)||sent._rev});
        }
        if(payload.structure)kolBaseline.structure=JSON.stringify({columns:payload.structure.customColumns||[],manufacturers:payload.structure.manufacturers||[],statusCatalog:payload.structure.statusCatalog||[],order:payload.structure.order||[]});
        if(Array.isArray(data.conflicts)&&data.conflicts.length)ownConflictRebased=kolReportConflicts(data.conflicts);
      }else{
        kolWorkspaceRevision=Number(data.workspace&&data.workspace._revision)||kolWorkspaceRevision;
        const serverRows=new Map();for(const row of Array.isArray(data.workspace&&data.workspace.rows)?data.workspace.rows:[]){const key=kolRowKey(row);if(key)serverRows.set(key,{...row});}
        kolBaseline={ownerId:kolWorkspaceOwnerId,rows:serverRows,structure:JSON.stringify({columns:data.workspace&&data.workspace.customColumns||[],manufacturers:data.workspace&&data.workspace.manufacturers||[],statusCatalog:data.workspace&&data.workspace.statusCatalog||[],order:(data.workspace&&data.workspace.rows||[]).map(kolRowKey)})};
      }
      const dirty=kolHasDirtyWorkspace();
      if(dirty)kolPersistPendingWorkspace(Array.isArray(data.conflicts)&&data.conflicts.length?'conflict':'pending');
      else kolClearPendingWorkspace(ownerId);
      return {ok:true,durable:true,pending:dirty,retryOwnConflict:ownConflictRebased};
    }
    catch(err){
      const conflictCode=err.code==='REVISION_CONFLICT'||err.code==='STRUCTURE_REVISION_CONFLICT';
      const canRebase=conflictCode&&kolWorkspaceOwnerId===ownerId&&kolIsOwnWorkspace()&&options.atomic!==true&&conflictRetry<3&&kolBaseline;
      if(canRebase){
        kolPersistPendingWorkspace('rebasing');
        return {ok:false,pending:true,rebase:true,error:err};
      }
      if((conflictCode||err.code==='COLLECTION_ATOMIC_CONFLICT')&&kolWorkspaceOwnerId===ownerId){
        kolPersistPendingWorkspace('conflict');
        showToast(appLang==='en'?'The Collection changed while saving. Your local edit is safe on this device.':'Koleksiyon kayıt sırasında değişti. Yerel girişiniz bu cihazda güvende.');
      }else showToast((appLang==='en'?'Collection page could not be saved: ':'Koleksiyon sayfası kaydedilemedi: ')+(err.message||err));
      if(kolWorkspaceOwnerId===ownerId)kolPersistPendingWorkspace('save-failed');
      return {ok:false,pending:true,error:err};
    }
    finally{kolWorkspaceSaving=false;kolWorkspaceSavePromise=null;}
  })();
  const result=await kolWorkspaceSavePromise;
  if(result&&result.rebase&&conflictRetry<3){
    const rebased=await kolRebaseOwnWorkspace(ownerId).catch(()=>false);
    if(rebased){
      kolWorkspacePending=false;
      return kolSaveWorkspaceNow({...options,_conflictRetry:conflictRetry+1});
    }
  }
  if(result&&result.retryOwnConflict&&options.atomic!==true&&conflictRetry<3){
    kolWorkspacePending=false;
    return kolSaveWorkspaceNow({...options,_conflictRetry:conflictRetry+1});
  }
  if(kolWorkspacePending){kolWorkspacePending=false;return kolSaveWorkspaceNow(options);}
  return result;
}
function kolQueueWorkspaceSave(){if(!kolWorkspaceCanEdit)return;clearTimeout(kolWorkspaceSaveTimer);kolWorkspaceSaveTimer=setTimeout(()=>void kolSaveWorkspaceNow(),350);}
const kolReplicationNoticeByOwner=new Map();
function kolReportReplication(replication){
  if(!replication||typeof replication!=='object')return;
  const owner=String(replication.ownerId||kolWorkspaceOwnerId||'');
  const failed=replication.ok===false||replication.state==='conflict'||replication.state==='error';
  // Eşzamanlı düzenleme birleştirildi ama aynı alanda önce kaydedilen değer
  // korundu: kullanıcının değeri Senkron çakışmalarında bekler, sessiz kalmaz.
  const mergeConflicts=Number(replication.mergeConflicts)||0;
  if(!failed&&!mergeConflicts){if(owner)kolReplicationNoticeByOwner.delete(owner);return;}
  const signature=[replication.state,replication.code,replication.localRevision,replication.remoteRevision,replication.updatedAt,mergeConflicts].join('|');
  if(owner&&kolReplicationNoticeByOwner.get(owner)===signature)return;
  if(owner)kolReplicationNoticeByOwner.set(owner,signature);
  const detail=String(replication.message||'').trim();
  const message=!failed
    ?(appLang==='en'
      ?`Another user changed the same Collection fields at the same time; the value saved first was kept in ${mergeConflicts} field(s). Your values are waiting in Sync Conflicts.`
      :`Başka bir kullanıcı aynı Koleksiyon alanlarını eşzamanlı değiştirdi; ${mergeConflicts} alanda önce kaydedilen değer korundu. Sizin değerleriniz Senkron çakışmalarında bekliyor.`)
    :appLang==='en'
    ?`Saved locally, but Collection sharing needs attention.${detail?' '+detail:''}`
    :`Yerel kayıt tamamlandı; Koleksiyon paylaşımı ilgilenmenizi gerektiriyor.${detail?' '+detail:''}`;
  showToast(message);
}
async function kolLoadWorkspace(ownerId){
  const res=await fetch(`/api/collection-workspaces/${encodeURIComponent(ownerId)}`);const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||res.statusText);
  kolReportReplication(data.replication);
  kolWorkspaceOwnerId=ownerId;kolApplyWorkspace(data.workspace,data.access);const select=document.getElementById('kolWorkspaceSelect');if(select)select.value=ownerId;
}
function kolPersistScope(){
  try{BLStorage.setItem(KOL_SCOPE_PREF_KEY,JSON.stringify({ownerIds:[...kolWorkspaceSelectedOwnerIds]}));}catch(_){}
}
function kolApplyCombinedWorkspaces(items){
  kolWorkspaceMode='multi';kolWorkspaceOwnerId='__multi__';kolWorkspaceRevision=0;kolWorkspaceCanEdit=false;
  const manufacturers=new Set(),custom=new Map(),catalog=[],rowStatuses=[];let syntheticId=-1;
  kolRows=[];
  (items||[]).forEach(item=>{
    const owner=item&&item.owner||{},workspace=item&&item.workspace||{};
    (workspace.manufacturers||[]).forEach(name=>{if(norm(name))manufacturers.add(norm(name));});
    (workspace.customColumns||[]).forEach(col=>{if(col&&col.k&&!custom.has(col.k))custom.set(col.k,col);});
    (workspace.statusCatalog||[]).forEach(entry=>catalog.push(entry));
    (workspace.rows||[]).forEach(source=>{
      if(source&&source.durum)rowStatuses.push(source.durum);
      const row=migrateKolRow(JSON.parse(JSON.stringify(source||{})));
      row._collectionSourceId=row.id;row._collectionOwnerId=owner.id;row._collectionOwnerName=owner.displayName||owner.id;row.id=syntheticId--;
      kolRows.push(row);
    });
  });
  kolStatusCatalog=KOL_STATUS_API.normalize(catalog.length?catalog:null,{rowStatuses});
  kolRows=kolNormalizeModelGroups(kolRows);
  kolManufacturers=[...manufacturers].sort((a,b)=>a.localeCompare(b,'tr',{sensitivity:'base'}));
  kolCustomCols=kolNormalizeCustomCols([...custom.values()]);kolNextId=1;kolSelected.clear();kolUndoStack=[];kolRedoStack=[];
  refreshSubmfrList();loadKolColState({preserveCustom:true});kolWorkspaceSetReadonly();renderKol();renderKolScopeFilters();scheduleOverviewCollectionSummaryRender();
}
async function kolLoadWorkspaceBatch(ownerIds){
  const ids=[...new Set((ownerIds||[]).filter(id=>kolWorkspaceList.some(item=>item.ownerId===id)))];
  if(!ids.length)return;
  if(ids.length===1){kolWorkspaceSelectedOwnerIds=new Set(ids);kolPersistScope();await kolLoadWorkspace(ids[0]);renderKolScopeFilters();return;}
  const res=await fetch(`/api/collection-workspaces-batch?ownerIds=${encodeURIComponent(ids.join(','))}`);const data=await res.json().catch(()=>({}));
  if(!res.ok)throw new Error(data.error||res.statusText);
  for(const item of Array.isArray(data.workspaces)?data.workspaces:[])kolReportReplication(item&&item.replication);
  kolWorkspaceSelectedOwnerIds=new Set(ids);kolPersistScope();kolApplyCombinedWorkspaces(data.workspaces||[]);
  const select=document.getElementById('kolWorkspaceSelect');if(select)select.value='';
}
