  if(_submfrDrop&&!suggestionDropContainsScrollTarget(_submfrDrop,target))closeSubmfrDrop();
  if(_licensorDrop&&!suggestionDropContainsScrollTarget(_licensorDrop,target))closeLicensorDrop();
