function migrateKolRow(r){
  if(r.licensor===undefined && r.tasarimci!==undefined) r.licensor = r.tasarimci;
  // License boşsa Licensor artık bağımsız bir değer değildir. Eski satırlarda
  // kalmış değeri açılış/import/sync sırasında güvenle temizle; dolu License
  // kayıtlarına ve tarihçeye dokunma.
  if(!norm(r.lisans) && norm(r.licensor)){r.licensor='';r._licensorManual=false;r._licensorAuto=false;delete r._licensorAutoLicense;}
  if(r.colour===undefined && r.renkKumas!==undefined) r.colour = r.renkKumas;
  if(r.season===undefined && r.sezonHft!==undefined) r.season = r.sezonHft;
  delete r.tasarimci; delete r.renkKumas; delete r.sezonHft; delete r.paket; delete r.kalip; delete r.shoppingNo; delete r.nkKodu;
  ['plmId','productMainDefinition','specialCode','line','mbOrderType','colourCode','fabric','fabricSupplierS6','fabricPriceS6','fabricSupplierS7','fabricPriceS7','fit','buyingSampleManufacturer','quantity','assortment','country','exFactory','retail','inStore','inStoreWeek','inStoreMonth','previousFob','targetPrice','royalty','hologramCost','fob','opd','mag','mmyg','buyingGroup','buyer'].forEach(k=>{
    if(r[k]===undefined) r[k]='';
  });
  // Eski Koleksiyon kayıtlarında hafta alanı yoktu. Mevcut gerçek tarih varsa
  // haftayı tarihten türet; yalnız ay varsa yeni dönem kuralıyla hafta + pazartesi
  // tarihini doldur. Var olan In Store tarihini geriye dönük olarak değiştirme.
  if(!norm(r.inStoreWeek)&&norm(r.inStore))r.inStoreWeek=kolWeekCodeForDate(r.inStore);
  if(norm(r.inStoreMonth)){
    const schedule=kolScheduleFromMonthCode(r.inStoreMonth);
    if(schedule){if(!norm(r.inStoreWeek))r.inStoreWeek=schedule.inStoreWeek;if(!norm(r.inStore))r.inStore=schedule.inStore;}
  }
  if(r.buyingSampleApproved===undefined || r.buyingSampleApproved===null) r.buyingSampleApproved=false;
  // v2.08: Koleksiyon Supp. FOB alanı kaldırıldı; eski kayıtlardaki değer artık kullanılmaz.
  delete r.suppFob;
  if(r.delType===undefined || r.delType===null || !normalizeTransitDelType(r.delType)) r.delType='Gemi';
  if(!norm(r.durum)) r.durum = kolStatusDefaultName();
  if(!r.pricing) r.pricing = {}; // {üreticiAdı: "4.50"} — kullanıcı elle girdiği fiyat
  if(!r.pricingSent) r.pricingSent = {}; // {üreticiAdı: true} — fiyatlamaya gönderildi, henüz fiyat gelmedi
  // Kullanıcının onayladığı tek üretici. Fiyat ayrıca kopyalanmaz; seçili üreticinin
  // güncel fiyat hücresinden türetilir, böylece fiyat sonradan değişirse CONF. FOB da güncel kalır.
  if(r.confirmedManufacturer===undefined || r.confirmedManufacturer===null) r.confirmedManufacturer = '';
  // Landed karşılaştırması: TR fiyatı elle girilir; landed çarpanı ve kur otomatik
  // gelir ama elle değiştirilebilir. Ayrı sütun açmamak için hepsi kendi hücresinde.
  if(r.trPrice===undefined || r.trPrice===null) r.trPrice='';
  if(r.trLandedMult===undefined || r.trLandedMult===null) r.trLandedMult='';
  if(r.trFx===undefined || r.trFx===null) r.trFx='';
  if(r.ydLandedMult===undefined || r.ydLandedMult===null) r.ydLandedMult='';
  if(!r.endeksmatikData || typeof r.endeksmatikData!=='object' || Array.isArray(r.endeksmatikData)) r.endeksmatikData={};
  if(r.imgRef===undefined || r.imgRef===null) r.imgRef='';
  if(r.dropped===undefined || r.dropped===null) r.dropped=false;
  if(r.imgRef && !r.img) r.img=`/api/collection-images/${encodeURIComponent(r.imgRef)}`;
  return r;
}
// Keep the existing flat row store and add model-group metadata as a
