  const hasImage=img.dataset.hasImage==='1',dims=kolImgDims();
  const rowHeight=tr.classList.contains('kolModelGroupVariant')?kolVariantRowHeight(dims.row):dims.row;
  const imageMaxHeight=Math.max(20,Math.min(dims.h,rowHeight-6));
