async function copyKolSelectedRows(){
  commitActiveTableEditor({refresh:false});
  const rows=kolCollectionExportProjection(filteredKol()).filter(record=>kolCollectionProjectionSelected(record,kolSelected));
  if(!rows.length){ showToast(L('Kopyalamak için önce satır seç.')); return; }
  // Tema değiştirilmeden canlı tablodan kopyalanır; Koleksiyon tablosu işlem
  // öncesi/sonrası yeniden çizilmez.
  const built=await buildStyledCopyFromDom('#kolTable', kolSelected, 'data-id', { leafHeadersOnly:true });
  if(!built){ showToast(L('Kopyalamak için önce satır seç.')); return; }
  const html=built.html, plain=built.plain;
  const ok=await copyRichToClipboard(html,plain);
  const btn=document.getElementById('kolCopySelectedBtn');
  if(btn){
    const old=btn.innerHTML; btn.innerHTML=ok?`<svg class="ic"><use href="#i-copy"/></svg>${rows.length} ${L('satır kopyalandı')}`:`<svg class="ic"><use href="#i-x"/></svg>${L('Kopyalama başarısız')}`;
    setTimeout(()=>{ if(btn.isConnected) btn.innerHTML=old; },2200);
  }
  if(ok) showToast(`${rows.length} ${L('satır başlıklarıyla kopyalandı.')}`);
}
function kolClearDuplicateCommercialHistory(row){
  if(!row)return row;
  // Duplicate Model yalnız yeni kopyanın ticari geçmişini temizler. Kaynak satırın
  // pricing, onaylı üretici, Conf. FOB ve diğer alanlarına hiçbir zaman dokunulmaz.
  row.pricing={};
  row.pricingSent={};
  row.confirmedManufacturer='';
  row.fob='';
  delete row._pricingRuleId;
  delete row._sourceOrderCode;
  delete row._styleRowId;
  kolApplyRulePricing(row); // Royalty/Hologram kuraldan yeniden gelir; fiyat yoksa Target Price FOB için kullanılabilir.
  return row;
}
function kolBuildDuplicatePlan(rows,selectedIds,nextId){
  const chosen=selectedIds instanceof Set?selectedIds:new Set(selectedIds||[]);
  const next=[],newIds=[];
  let id=Math.max(1,Number(nextId)||1);
  (Array.isArray(rows)?rows:[]).forEach(source=>{
    // Seçili kaynak satırı da ayrık bir snapshot olarak yeniden eklenir. Böylece
    // kopyayı hazırlayan herhangi bir migrasyon/temizleme adımı kaynak nesnenin
    // pricing veya onay alanlarını referans yoluyla değiştiremez.
    const preserved=chosen.has(source.id)?JSON.parse(JSON.stringify(source)):source;
    next.push(preserved);
    if(!chosen.has(source.id))return;
    const copy=kolClearDuplicateCommercialHistory(migrateKolRow(JSON.parse(JSON.stringify(preserved))));
    copy.id=id++;
    copy.dropped=false;
    next.push(copy);
    newIds.push(copy.id);
  });
  return {rows:next,newIds,nextId:id};
}
function kolValidSelectedRows(){
  const selectedIds=new Set([...kolSelected].map(id=>String(id)));
  return kolRows.filter(row=>row&&selectedIds.has(String(row.id)));
}
function kolPruneSelection(){
  const valid=new Set(kolRows.map(row=>String(row&&row.id)));
  kolSelected.forEach(id=>{if(!valid.has(String(id)))kolSelected.delete(id);});
}
function kolSelectedRowsSnapshot(){
  kolPruneSelection();
  return new Set(kolValidSelectedRows().map(row=>row.id));
}
function kolSelectedActionLabel(action){
  const en=appLang==='en';
  return action==='delete' ? (en?'Delete selected models':'Seçilen modelleri sil') : (en?'Duplicate selected models':'Seçilen modelleri çoğalt');
}
function openKolSelectedActionConfirmation(action,snapshot){
  const rows=kolRows.filter(row=>snapshot.has(row.id));
  if(!rows.length)return Promise.resolve(false);
  const en=appLang==='en';
  document.getElementById('_kolSelectedActionConfirm')?.remove();
  const fields=[
    ['Model Name',row=>row.modelKod],
    ['PLM ID',row=>row.plmId],
    ['Colour',row=>row.colour||row.colourCode],
    ['Product Main Definition',row=>row.productMainDefinition],
    ['Category',row=>row.urunTipi],
    ['Buying Sample',row=>row.buyingSampleManufacturer],
    ['Season',row=>row.season],
  ];
  const modal=document.createElement('div');
  modal.id='_kolSelectedActionConfirm'; modal.className='warnOverlay'; modal.tabIndex=-1;
  modal.innerHTML=`<div class="modalCard verHistCard" role="dialog" aria-modal="true" aria-labelledby="_kolSelectedActionTitle">
    <div class="verHistHead"><div><div class="modalTitle" id="_kolSelectedActionTitle">${escapeHtml(kolSelectedActionLabel(action))}</div><p>${escapeHtml(en?`${rows.length} model(s) selected. Review the records before continuing.`:`${rows.length} model seçildi. Devam etmeden önce kayıtları kontrol edin.`)}</p></div><button type="button" class="pricingRuleIconBtn" data-cancel aria-label="${escapeHtml(en?'Cancel':'Vazgeç')}"><svg class="ic"><use href="#i-x"/></svg></button></div>
    <div class="plmImportTableWrap" style="max-height:48vh;overflow:auto"><table class="plmImportTable"><thead><tr>${fields.map(([label])=>`<th>${escapeHtml(label)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${fields.map(([,get])=>`<td>${escapeHtml(norm(get(row))||'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>
    <div class="verHistFoot"><span>${escapeHtml(`${rows.length} ${en?'record(s)':'kayıt'}`)}</span><button type="button" class="tbtn" data-cancel>${escapeHtml(en?'Cancel':'Vazgeç')}</button><button type="button" class="tbtn ${action==='delete'?'danger':'primary'}" data-confirm>${escapeHtml(action==='delete'?(en?`Delete ${rows.length} Models`:`${rows.length} modeli sil`):(en?`Duplicate ${rows.length} Models`:`${rows.length} modeli çoğalt`))}</button></div>
  </div>`;
  document.body.appendChild(modal);
  modal.__refreshCanonicalRecipients=()=>{prepareEmailFillFromShared();if(typeof refreshAll==='function')refreshAll();};
  modal.addEventListener('click',event=>{const manage=event.target.closest('[data-manage-email-groups]');if(manage){event.preventDefault();window.BLEmailGroups?.open?.();}});
  return new Promise(resolve=>{
    let settled=false;
    const finish=value=>{if(settled)return;settled=true;modal.remove();resolve(value);};
    modal.querySelectorAll('[data-cancel]').forEach(button=>button.addEventListener('click',()=>finish(false)));
    modal.querySelector('[data-confirm]')?.addEventListener('click',()=>finish(true));
    modal.addEventListener('click',event=>{if(event.target===modal)finish(false);});
    modal.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();finish(false);}});
    modal.focus();
  });
}
async function duplicateKolSelectedRows(){
  if(!kolRequireWorkspaceEdit()||kolSelectedActionState!=='idle')return;
  commitActiveTableEditor({refresh:false});
  const snapshot=kolSelectedRowsSnapshot();
  if(!snapshot.size){ showToast(L('Çoğaltmak için önce satır seç.')); return; }
  kolSelectedActionState='confirming'; updateKolSendBtnState();
  if(!await openKolSelectedActionConfirmation('duplicate',snapshot)){ kolSelectedActionState='idle'; updateKolSendBtnState(); return; }
  kolSelectedActionState='processing'; updateKolSendBtnState();
  try{
    kolPushUndo();
    const plan=kolBuildDuplicatePlan(kolRows,snapshot,kolNextId);
    kolRows=plan.rows;kolNextId=plan.nextId;
    // v6.42 — Duplicate sonrası hiçbir satır seçili kalmasın.
    kolSelected=new Set();
    saveKolRows(); renderKol();
    showToast(`${plan.newIds.length} ${L('satır çoğaltıldı.')} ${appLang==='en'?'The source model was preserved; pricing and approval history was not copied to the new row.':'Kaynak model korundu; fiyatlama ve onay geçmişi yeni satıra kopyalanmadı.'}`);
  }catch(err){ showToast((appLang==='en'?'Models could not be duplicated: ':'Modeller çoğaltılamadı: ')+(err?.message||String(err))); }
  finally{ kolSelectedActionState='completed'; updateKolSendBtnState(); kolSelectedActionState='idle'; updateKolSendBtnState(); }
}
