// Colour Code → QTX bridge (v6.55 — sağ tık menüsü + kalıcı kayıt).
// "Umbrella'da Bul": Umbrella'da arayıp bulur, dosyanın GERÇEK baytlarını
// yakalar ve Colour Code'a göre kalıcı olarak kaydeder (bkz. server/lib/qtx-store.js).
// "QTX İndir": daha önce kaydedilmiş dosyayı Umbrella'ya hiç gitmeden indirir.
// Colour Code TÜM modellerde ortak bir değer olduğu için kayıt bir kez
// yapılınca AYNI Colour Code'a sahip HER satırda (CP/Siparişler/Koleksiyon)
// görünür/indirilebilir olur — bu yüzden işaretleme tek bir Set üzerinden,
// tabloların hepsine birden uygulanır.
let qtxDownloadBusy=false;
const qtxSavedColourSet=new Set();
function qtxCellIdentity(tableId,cell){
  const tr=cell&&cell.closest&&cell.closest('tr[data-id]');if(!tr)return null;
  if(tableId==='kolTable'){
    const row=typeof kolRows!=='undefined'&&kolRows.find(item=>String(item&&item.id)===String(tr.dataset.id));
    return row?{source:'koleksiyon',colourCode:norm(row.colourCode)}:null;
  }
  const source=tableId==='ordersTable'?'orders':'cp',row=(state[source]?.rows||[]).find(item=>String(item&&item._id)===String(tr.dataset.id));
  return row?{source,colourCode:norm(row['C.Code'])}:null;
}
function qtxErrorMessage(error){
  const code=String(error&&error.code||'');
  if(code==='EDGE_EXISTING_PROFILE_DEBUG_DISABLED'||code==='EDGE_CONNECTION_NOT_READY')return appLang==='en'
    ?'The Buyer Log browser connection is not ready. Check Browser & Remote Debugging settings and try again.'
    :'Buyer Log tarayıcı bağlantısı hazır değil. Browser & Remote Debugging ayarlarını kontrol edip tekrar deneyin.';
  if(code==='UMBRELLA_LOGIN_REQUIRED')return appLang==='en'
    ?'Umbrella sign-in is required. Complete sign-in in the opened Edge tab, then try again.'
    :'Umbrella oturumu gerekli. Açılan Edge sekmesinde giriş işlemini tamamlayıp yeniden deneyin.';
  if(code==='UMBRELLA_ROS_NOT_FOUND'||code==='QTX_LIBRARY_NOT_FOUND')return appLang==='en'
    ?'ROS / QTX Library could not be opened. Keep the Umbrella home page open in the connected Edge profile and try again.'
    :'ROS / QTX Library açılamadı. Bağlı Edge profilinde Umbrella ana sayfasını açık tutup yeniden deneyin.';
  if(code==='QTX_NOT_FOUND')return appLang==='en'?'No QTX file matching this Colour Code was found.':'Bu Colour Code ile eşleşen QTX dosyası bulunamadı.';
  if(code==='QTX_BYTES_NOT_CAPTURED')return appLang==='en'?'The download started but its content could not be captured. This can be adjusted from Automations Terminal.':'İndirme başladı ama içeriği yakalanamadı. Bu, Otomasyon Terminali\'nden ayarlanabilir.';
  if(code==='QTX_ALREADY_RUNNING')return appLang==='en'?'Another QTX operation is already running.':'Başka bir QTX işlemi zaten çalışıyor.';
  if(code==='QTX_NOT_SAVED')return appLang==='en'?'No QTX file is saved for this Colour Code yet.':'Bu Colour Code için henüz kayıtlı bir QTX dosyası yok.';
  return String(error&&error.message||error||'');
}
async function ensureQtxEdgeConnection(){
  // QTX and PLM share the exact same canonical browser/CDP connection. Keeping
  // a second preflight here used to re-open the legacy Edge inspect page.
  return ensurePlmEdgeConnection();
}
// Kayıtlı Colour Code listesini sunucudan çeker ve görsel işaretlemeyi TÜM
// tablolara uygular. Uygulama açılışında ve her başarılı kayıttan sonra çağrılır.
async function loadQtxSavedList(){
  try{
    const data=await plmJsonRequest('/api/qtx/saved');
    qtxSavedColourSet.clear();
    (data&&data.colourCodes||[]).forEach(code=>qtxSavedColourSet.add(code));
    applyQtxSavedHighlight();
  }catch(_){/* sessizce geç — işaretleme olmadan da tablo çalışmaya devam eder */}
}
function qtxColourKey(value){return norm(value).replace(/\s+/g,' ').toLocaleUpperCase('tr-TR');}
// DOM'daki her Colour Code hücresini tarar; Set'te olanlara mavi+kalın sınıfı
// ekler, olmayanlardan çıkarır. Tam yeniden çizim gerektirmez.
function applyQtxSavedHighlight(){
  [['cpTable','C.Code'],['ordersTable','C.Code'],['kolTable','colourCode']].forEach(([tableId,key])=>{
    const table=document.getElementById(tableId);if(!table)return;
    table.querySelectorAll(`td[data-key="${key}"]`).forEach(cell=>{
      const saved=qtxSavedColourSet.has(qtxColourKey(cell.textContent));
      cell.classList.toggle('qtxSavedColourCell',saved);
    });
  });
}
async function fetchAndSaveQtxForColourCell(tableId,cell){
  const identity=qtxCellIdentity(tableId,cell);if(!identity)return;
  if(!identity.colourCode){showToast(appLang==='en'?'This row has no Colour Code.':'Bu satırda Colour Code bulunmuyor.');return;}
  if(qtxDownloadBusy){showToast(appLang==='en'?'Another QTX operation is already running.':'Başka bir QTX işlemi zaten çalışıyor.');return;}
  qtxDownloadBusy=true;cell.classList.add('qtxColourBridgeBusy');
  try{
    showToast((appLang==='en'?'Searching Umbrella by Colour Code: ':'Umbrella\'da Colour Code ile aranıyor: ')+identity.colourCode,{icon:false,duration:5000});
    if(!await ensureQtxEdgeConnection())return;
    const data=await plmJsonRequest('/api/qtx/fetch-and-save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(identity)});
    qtxSavedColourSet.add(qtxColourKey(identity.colourCode));applyQtxSavedHighlight();
    showToast(appLang==='en'
      ?`QTX saved: ${data.saved?.fileName||identity.colourCode}. It will now appear on every row with this Colour Code.`
      :`QTX kaydedildi: ${data.saved?.fileName||identity.colourCode}. Artık bu Colour Code'a sahip her satırda görünecek.`,{icon:false,duration:9000});
  }catch(error){showToast((appLang==='en'?'Could not fetch QTX: ':'QTX bulunamadı: ')+qtxErrorMessage(error),{icon:false,duration:12000});}
  finally{qtxDownloadBusy=false;cell.classList.remove('qtxColourBridgeBusy');}
}
async function downloadSavedQtxForColourCell(tableId,cell){
  const identity=qtxCellIdentity(tableId,cell);if(!identity||!identity.colourCode)return;
  const a=document.createElement('a');
  a.href=`/api/qtx/file/${encodeURIComponent(identity.colourCode)}`;a.style.display='none';
  document.body.appendChild(a);a.click();setTimeout(()=>a.remove(),1000);
}
function closeQtxContextMenu(){document.getElementById('_qtxContextMenu')?.remove();document.removeEventListener('click',closeQtxContextMenu,true);}
function openQtxContextMenu(event,tableId,cell){
  event.preventDefault();closeQtxContextMenu();
  const identity=qtxCellIdentity(tableId,cell);if(!identity)return;
  const hasSaved=qtxSavedColourSet.has(qtxColourKey(identity.colourCode));
  const menu=document.createElement('div');menu.id='_qtxContextMenu';menu.className='qtxContextMenu';
  menu.style.left=`${Math.min(event.clientX,window.innerWidth-210)}px`;menu.style.top=`${Math.min(event.clientY,window.innerHeight-90)}px`;
  menu.innerHTML=`
    <div class="qtxMenuHint">${escapeHtml(appLang==='en'?'Colour Code: ':'Colour Code: ')}${escapeHtml(identity.colourCode||'—')}</div>
    <button type="button" data-act="fetch"><svg class="ic"><use href="#i-search"/></svg>${escapeHtml(appLang==='en'?'Find on Umbrella':'Umbrella\'da Bul')}</button>
    <button type="button" data-act="download"${hasSaved?'':' disabled'}><svg class="ic"><use href="#i-download"/></svg>${escapeHtml(appLang==='en'?'Download QTX':'QTX İndir')}</button>`;
  document.body.appendChild(menu);
  menu.querySelector('[data-act="fetch"]').addEventListener('click',()=>{closeQtxContextMenu();void fetchAndSaveQtxForColourCell(tableId,cell);});
  menu.querySelector('[data-act="download"]')?.addEventListener('click',()=>{closeQtxContextMenu();void downloadSavedQtxForColourCell(tableId,cell);});
  setTimeout(()=>document.addEventListener('click',closeQtxContextMenu,true),0);
}
function bindQtxColourBridge(tableId){
  const table=document.getElementById(tableId);if(!table||table.dataset.qtxBridgeBound==='1')return;table.dataset.qtxBridgeBound='1';
  const wantedKey=tableId==='kolTable'?'colourCode':'C.Code';
  table.addEventListener('pointerover',event=>{const cell=event.target&&event.target.closest&&event.target.closest(`td[data-key="${wantedKey}"]`);if(!cell||!table.contains(cell))return;cell.title=appLang==='en'?'Right-click for Umbrella QTX options':'Umbrella QTX seçenekleri için sağ tıklayın';});
  table.addEventListener('contextmenu',event=>{const cell=event.target&&event.target.closest&&event.target.closest(`td[data-key="${wantedKey}"]`);if(!cell||!table.contains(cell))return;openQtxContextMenu(event,tableId,cell);},true);
}
['cpTable','ordersTable','kolTable'].forEach(bindQtxColourBridge);
void loadQtxSavedList();

function kolImportStyleRowId(ws,rowIndex,columnCount){
  for(let ci=0;ci<Math.max(1,Number(columnCount)||1);ci++){
    const cell=ws&&ws[XLSX.utils.encode_cell({r:rowIndex,c:ci})];
    const comments=Array.isArray(cell&&cell.c)?cell.c:[];
    for(const comment of comments){
      const text=[comment&&comment.t,comment&&comment.a,comment&&comment.r].filter(Boolean).map(value=>typeof value==='string'?value:JSON.stringify(value)).join(' ');
      const match=/BL_COLLECTION_ROW_ID\s*:\s*(\d+)/i.exec(text);
      if(match)return Number(match[1])||0;
    }
  }
  return 0;
}
async function importKolExcelFile(file){
  if(!kolRequireWorkspaceEdit())return;
  if(!file) return;
  if(typeof XLSX==='undefined'){ showToast('Excel kütüphanesi yüklenemedi.'); return; }
  const input=document.getElementById('kolImportFile'), label=document.getElementById('kolImportBtn');
  const labelText=label&&label.querySelector('span');
  const oldLabelText=labelText?labelText.textContent:'';
  if(label){ label.style.pointerEvents='none'; label.setAttribute('aria-busy','true'); }
  if(labelText) labelText.textContent=L('İçe aktarılıyor…');
  try{
    const buffer=await file.arrayBuffer();
    const wb=XLSX.read(buffer,{type:'array',cellDates:true,cellNF:true,cellComments:true});
    const sheetName=wb.SheetNames.find(n=>/koleksiyon|collection/i.test(n))||wb.SheetNames[0];
    const ws=wb.Sheets[sheetName];
    const matrix=XLSX.utils.sheet_to_json(ws,{header:1,raw:true,defval:''});
    if(!matrix.length) throw new Error('Excel sayfası boş.');
    const aliases=kolImportHeaderAliases();
    let best=null;
    for(let ri=0;ri<Math.min(30,matrix.length);ri++){
      const headers=(matrix[ri]||[]).map(v=>norm(v));
      const mapped=headers.map(h=>aliases[kolImportHeaderKey(h)]||null);
      const mfr=headers.map((h,ci)=>({h,ci})).filter(x=>!mapped[x.ci]&&/\(\s*\$\s*\)\s*$/i.test(x.h)&&!/^FOB/i.test(x.h));
      const score=mapped.filter(Boolean).length+mfr.length;
      if(!best||score>best.score) best={ri,headers,mapped,mfr,score};
    }
    if(!best||best.score<1) throw new Error('Koleksiyon sütun başlıkları tanınamadı.');
    const knownByKey={...Object.fromEntries(kolColDefs().filter(c=>!c.endeksmatik).map(c=>[c.k,c])),...kolStyleFieldMap()};
    const mfrDefs=best.mfr.map(x=>({ci:x.ci,name:norm(x.h.replace(/\(\s*\$\s*\)\s*$/i,''))})).filter(x=>x.name);
    mfrDefs.forEach(m=>{ if(!kolManufacturers.some(x=>turknorm(x.name)===turknorm(m.name))) kolManufacturers.push({name:m.name,email:''}); });
    const confirmedNameIndex=best.headers.findIndex(h=>kolImportHeaderKey(h)==='CONFMANUFACTURER'||kolImportHeaderKey(h)==='NIHAIURETICI');
    // Excel'de GERCEKTEN bulunan alanlar. Karsilastirma ve uzerine yazma yalniz bunlarla
    // yapilir; sayfada olmayan bir sutun mevcut kayitta asla silinmez.
    const touchedKeys=[];
    const addTouched=k=>{ if(k&&!kolImportIsProtectedKey(k)&&!touchedKeys.includes(k))touchedKeys.push(k); };
    best.mapped.forEach(key=>{ if(key&&key!=='exToRetail'&&key!=='royalty'&&key!=='hologramCost'&&key!=='fob') addTouched(key); });
    mfrDefs.forEach(m=>addTouched('pricing:'+m.name));
    const imported=[];
    for(let ri=best.ri+1;ri<matrix.length;ri++){
      const src=matrix[ri]||[]; const out={id:0,pricing:{},pricingSent:{},img:null,_styleRowId:kolImportStyleRowId(ws,ri,best.headers.length)}; let meaningful=false;
      best.mapped.forEach((key,ci)=>{
        if(!key||key==='exToRetail'||key==='royalty'||key==='hologramCost'||key==='fob') return;
        const col=knownByKey[key], raw=src[ci];
        if(raw==null||String(raw).trim()===''){ out[key]=''; return; }
        meaningful=true;
        if(col&&col.date) out[key]=toISODate(raw);
        else if(col&&col.boolean) out[key]=kolStyleBooleanValue(raw);
        else if(col&&col.qty){ const n=kolParseQuantityNum(raw); out[key]=Number.isFinite(n)?String(Math.trunc(n)):norm(raw); }
        else if(col&&col.number){ const n=kolImportNumber(raw); out[key]=Number.isFinite(n)?String(n):norm(raw); }
        else if(col&&col.percent){
          let n=kolImportNumber(raw); const cell=ws[XLSX.utils.encode_cell({r:ri,c:ci})];
          if(Number.isFinite(n)&&typeof raw==='number'&&cell&&String(cell.z||'').includes('%')) n*=100;
          out[key]=Number.isFinite(n)?kolFormatPercentDisplay(n):norm(raw);
        } else if(col&&col.hologram){ const n=kolImportNumber(raw); out[key]=Number.isFinite(n)?kolFormatHologramDisplay(String(n)):norm(raw); }
        else if(col&&col.money){ const n=kolImportNumber(raw); out[key]=Number.isFinite(n)?kolFormatMoneyDisplay(String(n)):norm(raw); }
        else if(col&&col.select) out[key]=kolImportSelectValue(col,raw);
        else out[key]=norm(raw);
      });
      mfrDefs.forEach(m=>{
        const raw=src[m.ci]; if(raw==null||String(raw).trim()==='') return;
        meaningful=true; const n=kolImportNumber(raw);
        out.pricing[m.name]=Number.isFinite(n)?kolFormatMoneyDisplay(String(n)):norm(raw);
      });
      if(confirmedNameIndex>=0){ out.confirmedManufacturer=norm(src[confirmedNameIndex]); addTouched('confirmedManufacturer'); }
      if(!meaningful) continue;
      imported.push(migrateKolRow(out));
    }
    if(!imported.length) throw new Error('İçe aktarılabilecek dolu satır bulunamadı.');
    if(touchedKeys.includes('urunTipi')){
      imported.forEach(row=>{
        if(!norm(row.urunTipi))return;
        const matched=kolImportCategoryCatalogMatch(row.urunTipi);
        if(matched)row.urunTipi=matched;
      });
    }

    const plan=kolBuildImportPlan(imported,touchedKeys,knownByKey);
    // Category dahil tüm serbest giriş alanları Excel'deki metin gibi kabul edilir.
    // ASAS kataloğunda eşleşen değerler yukarıda yalnız kanonik yazıma dönüştürülür.
    const approved=await showKolImportPlanModal(plan);
    if(!approved){
      showToast(L('İçe aktarım iptal edildi.'),{icon:false});
      return;
    }
    kolPushUndo();
    // Guncellemeler: yalnizca degisen alanlar mevcut kaydin uzerine yazilir. id, img ve
    // Excel'de bulunmayan hicbir alan ellenmez.
    plan.updates.forEach(u=>{ u.changes.forEach(c=>kolImportWriteField(u.target,c.key,c.to)); });
    // Yeni modeller: kimlik ancak burada uretilir, gorsel bos kalir.
    const created=plan.creates.map(row=>{ row.id=kolNextId++; row.img=null; delete row.imgRef; delete row.imgSize; delete row._styleRowId; return kolApplyNewModelDefaults(migrateKolRow(row)); });
    if(created.length) kolRows=[...created,...kolRows];
    kolSelected=new Set([...created.map(r=>r.id),...plan.updates.map(u=>u.target.id)]);
    saveKolManufacturers(); saveKolRows(); renderKol();
    const parts=[];
    if(plan.updates.length) parts.push(`${plan.updates.length} ${L('model güncellendi')}`);
    if(created.length) parts.push(`${created.length} ${L('yeni model eklendi')}`);
    showToast(parts.length?parts.join(' · '):L('Değişiklik uygulanmadı.'));
  }catch(err){ showToast(`${L('Excel içe aktarılamadı')}: ${err.message}`); }
  finally{
    if(input) input.value='';
    if(label){ label.style.pointerEvents=''; label.removeAttribute('aria-busy'); }
    if(labelText) labelText.textContent=oldLabelText;
  }
}
function addBlankKolRow(){
  if(!kolRequireWorkspaceEdit())return;
  commitActiveTableEditor({refresh:false});
  kolPushUndo();
  const row=kolApplyNewModelDefaults(migrateKolRow({
    id:kolNextId++,
    plmId:'',modelKod:'',lisans:'',urunTipi:'',country:'',delType:'Gemi',assortment:'',
    durum:kolStatusDefaultName(),not:'',img:null,pricing:{},pricingSent:{},
    confirmedManufacturer:''
  }));
  kolApplyRulePricing(row);
  kolRows.unshift(row);
  kolTransientTopRowId=row.id;
  kolSelected=new Set([row.id]);
  saveKolRows();
  renderKol();
  // Yeni satır doğrudan tabloda açılır; model adı hücresi hemen düzenlemeye hazırdır.
  setTimeout(()=>{
    const input=document.querySelector(`#kolTable input[data-id="${row.id}"][data-k="modelKod"]`);
    if(input){input.focus();input.select?.();}
  },0);
  showToast(appLang==='en'?'A blank model row was added.':'Boş bir model satırı eklendi.',{icon:false});
}
document.getElementById('kolCopySelectedBtn')?.addEventListener('click',copyKolSelectedRows);
document.getElementById('kolDuplicateBtn')?.addEventListener('click',duplicateKolSelectedRows);
document.getElementById('kolImportFile')?.addEventListener('change',e=>importKolExcelFile(e.target.files&&e.target.files[0]));
document.getElementById('kolAddRowBtn')?.addEventListener('click',addBlankKolRow);
function dropKolSelectedRows(){
  if(!kolRequireWorkspaceEdit())return;
  if(!kolSelected.size){ showToast(L('İptal etmek için önce model seç.')); return; }
  const selected=kolRows.filter(r=>kolSelected.has(r.id));
  const active=selected.filter(r=>!r.dropped);
  if(!active.length){ showToast(L('Seçili modeller zaten iptal edilmiş.')); return; }
  kolPushUndo();
  active.forEach(row=>{row.dropped=true;});
  saveKolRows(); renderKol();
  showToast(`${active.length} ${L('model iptal edildi.')}`);
}

/* ===================================================================
   KOLEKSİYON GERİ DÖNÜŞÜM KUTUSU (v5.97)

   Silinen modeller 30 gün saklanır ve geri çağrılabilir. Kayıt satırın
   TAMAMINI taşır (Pricing History bağlantısı, Confirmed Supplier/FOB ve
   diğer kullanıcı girişleri dahil): alan seçmek, ileride eklenen bir alanın
   sessizce kaybolması demekti.

   Geri yüklemede ÇAKIŞMA UYARISI: aynı PLM ID ile hâlâ bir model varsa
   kullanıcıya söylenir ve karar ona bırakılır. Engellemek yerine uyarmak
   doğru: aynı PLM ID meşru şekilde iki satırda bulunabilir (revizyon,
   çoğaltma) ve kullanıcı hangisinin doğru olduğunu bizden iyi bilir.
   =================================================================== */
async function kolBinApi(pathSuffix, options){
  const url=`/api/collection-recycle-bin/${encodeURIComponent(kolWorkspaceOwnerId)}${pathSuffix||''}`;
  const res=await fetch(url,{headers:{'Content-Type':'application/json'},...(options||{})});
  const data=await res.json().catch(()=>({}));
  if(!res.ok)throw new Error(data.error||res.statusText);
  return data;
}
// Silinen satırlar kutuya gönderilir. Bu adım tamamlanmadan canlı satır
// kaldırılmaz; geri alınabilir kopyası olmayan bir silmeye izin verilmez.
async function kolArchiveDeletedRows(rows,reason){
  const list=(Array.isArray(rows)?rows:[]).filter(Boolean);
  if(!list.length)return true;
  const entries=list.map(row=>({
    rowId:Number(row.id)||null,
    plmId:row.plmId||row['PLM ID']||'',
    modelName:row.modelName||row['Model Name']||'',
    season:row.season||row['Season']||'',
    reason,
    row,
  }));
  try{ await kolBinApi('',{method:'POST',body:JSON.stringify({entries,reason})}); return true; }
  catch(err){
    showToast((appLang==='en'?'Deleted models could not be moved to the recycle bin: ':'Silinen modeller geri dönüşüm kutusuna alınamadı: ')+(err.message||err));
    return false;
  }
}
function kolBinDaysLeft(entry){
  const deleted=Date.parse(entry&&entry.deletedAt);
  if(!Number.isFinite(deleted))return 30;
  return Math.max(0,30-Math.floor((Date.now()-deleted)/86400000));
}
async function openKolRecycleBin(){
  const en=appLang==='en';
  document.getElementById('_kolBinModal')?.remove();
  const modal=document.createElement('div');
  modal.id='_kolBinModal'; modal.className='warnOverlay';
  modal.innerHTML=`<div class="modalCard kolBinCard" role="dialog" aria-modal="true" aria-labelledby="_kolBinTitle">
    <div class="kolBinHead">
      <div>
        <div class="modalTitle" id="_kolBinTitle">${escapeHtml(en?'Recycle bin':'Geri dönüşüm kutusu')}</div>
        <p>${escapeHtml(en?'Deleted models are kept for 30 days and can be restored with all their data.':'Silinen modeller 30 gün saklanır ve tüm verileriyle geri çağrılabilir.')}</p>
      </div>
      <button type="button" class="pricingRuleIconBtn" data-overlay-close aria-label="${escapeHtml(en?'Close':'Kapat')}"><svg class="ic"><use href="#i-x"/></svg></button>
    </div>
    <div class="kolBinBody" id="_kolBinBody"><div class="kolBinEmpty">${escapeHtml(en?'Loading…':'Yükleniyor…')}</div></div>
    <div class="kolBinFoot">
      <span id="_kolBinStatus"></span>
      <button type="button" class="tbtn" data-overlay-close>${escapeHtml(en?'Close':'Kapat')}</button>
      <button type="button" class="navActionBtn" id="_kolBinRestore" disabled><svg class="ic"><use href="#i-arrow-back-up"/></svg>${escapeHtml(en?'Restore selected':'Seçilenleri geri yükle')}</button>
    </div>
  </div>`;
  document.body.appendChild(modal);
  modal.__refreshCanonicalRecipients=()=>{prepareEmailFillFromShared();if(typeof refreshAll==='function')refreshAll();};
  modal.addEventListener('click',event=>{const manage=event.target.closest('[data-manage-email-groups]');if(manage){event.preventDefault();window.BLEmailGroups?.open?.();}});
  const body=modal.querySelector('#_kolBinBody'), status=modal.querySelector('#_kolBinStatus'), restoreBtn=modal.querySelector('#_kolBinRestore');
  const close=()=>modal.remove();
  modal.querySelectorAll('[data-overlay-close]').forEach(btn=>btn.addEventListener('click',close));
  modal.addEventListener('click',e=>{ if(e.target===modal) close(); });
  modal.addEventListener('keydown',e=>{ if(e.key==='Escape'){ e.preventDefault(); close(); } });

  let entries=[];
  const selected=new Set();
  function syncRestoreBtn(){ restoreBtn.disabled=selected.size===0||!kolWorkspaceCanEdit; }
  function render(){
    if(!entries.length){
      body.innerHTML=`<div class="kolBinEmpty">${escapeHtml(en?'The recycle bin is empty.':'Geri dönüşüm kutusu boş.')}</div>`;
      syncRestoreBtn(); return;
    }
    // Aynı PLM ID ile hâlâ bir model varsa çakışma burada işaretlenir.
    const livePlm=new Map();
    kolRows.forEach(row=>{ const id=String(row&&row.plmId||'').trim(); if(id)livePlm.set(id,(livePlm.get(id)||0)+1); });
    body.innerHTML=`<table class="kolBinTable"><thead><tr>
        <th></th>
        <th>${escapeHtml(en?'Model':'Model')}</th>
        <th>PLM ID</th>
        <th>${escapeHtml(en?'Season':'Sezon')}</th>
        <th>${escapeHtml(en?'Deleted':'Silinme')}</th>
        <th>${escapeHtml(en?'Days left':'Kalan gün')}</th>
      </tr></thead><tbody>${entries.map(entry=>{
        const conflict=entry.plmId&&livePlm.has(String(entry.plmId).trim());
        const days=kolBinDaysLeft(entry);
        return `<tr${conflict?' class="kolBinConflict"':''}>
          <td><input type="checkbox" data-bin-id="${escapeHtml(entry.entryId)}" ${selected.has(entry.entryId)?'checked':''}></td>
          <td><b>${escapeHtml(entry.modelName||'—')}</b>${conflict?`<small class="kolBinWarn">${escapeHtml(en?'A model with this PLM ID already exists':'Bu PLM ID ile hâlâ bir model var')}</small>`:''}</td>
          <td>${escapeHtml(entry.plmId||'—')}</td>
          <td>${escapeHtml(entry.season||'—')}</td>
          <td>${escapeHtml(fmtTsForTitle(entry.deletedAt)||entry.deletedAt||'—')}${entry.deletedByName?`<small>${escapeHtml(entry.deletedByName)}</small>`:''}</td>
          <td class="kolBinDays${days<=3?' isSoon':''}">${days}</td>
        </tr>`;
      }).join('')}</tbody></table>`;
    body.querySelectorAll('[data-bin-id]').forEach(box=>box.addEventListener('change',()=>{
      if(box.checked)selected.add(box.dataset.binId); else selected.delete(box.dataset.binId);
      syncRestoreBtn();
    }));
    syncRestoreBtn();
  }
  async function load(){
    try{ const data=await kolBinApi(''); entries=Array.isArray(data.entries)?data.entries:[]; render(); }
    catch(err){ body.innerHTML=`<div class="kolBinEmpty">${escapeHtml(err.message||String(err))}</div>`; }
  }
  restoreBtn.addEventListener('click',async()=>{
    if(!kolRequireWorkspaceEdit())return;
    const picked=entries.filter(entry=>selected.has(entry.entryId));
    if(!picked.length)return;
    const livePlm=new Set(kolRows.map(row=>String(row&&row.plmId||'').trim()).filter(Boolean));
    const clashing=picked.filter(entry=>entry.plmId&&livePlm.has(String(entry.plmId).trim()));
    if(clashing.length){
      // Engellemek yerine uyar: aynı PLM ID meşru şekilde iki satırda bulunabilir.
      const names=clashing.map(entry=>`${entry.modelName||'—'} (${entry.plmId})`).join(', ');
      const message=en
        ?`${clashing.length} model already exist with the same PLM ID: ${names}\n\nRestoring creates a second row with that PLM ID. Continue?`
        :`${clashing.length} model aynı PLM ID ile hâlâ mevcut: ${names}\n\nGeri yüklemek o PLM ID'den ikinci bir satır oluşturur. Devam edilsin mi?`;
      if(!window.confirm(message))return;
    }
    restoreBtn.disabled=true; status.textContent=en?'Restoring…':'Geri yükleniyor…';
    try{
      const data=await kolBinApi('/restore',{method:'POST',body:JSON.stringify({entryIds:picked.map(entry=>entry.entryId)})});
      const restored=Array.isArray(data.restored)?data.restored:[];
      kolPushUndo();
      // Satır kimliği çakışmasın diye her geri yüklenen satıra YENİ kimlik verilir;
      // eski kimlik silindikten sonra başka bir satıra verilmiş olabilir.
      const added=restored.map(entry=>{
        const row=migrateKolRow({...(entry.row||{})});
        row.id=kolNextId++;
        return row;
      });
      if(added.length)kolRows=[...added,...kolRows];
      kolSelected=new Set(added.map(row=>row.id));
      saveKolRows(); renderKol();
      entries=Array.isArray(data.bin&&data.bin.entries)?data.bin.entries:[];
      selected.clear(); render();
      status.textContent='';
      showToast(en?`${added.length} model restored.`:`${added.length} model geri yüklendi.`);
    }catch(err){ status.textContent=err.message||String(err); }
    finally{ syncRestoreBtn(); }
  });
  load();
}
document.getElementById('kolRecycleBinBtn')?.addEventListener('click',openKolRecycleBin);

document.getElementById('kolDropSelectedBtn')?.addEventListener('click',dropKolSelectedRows);
document.getElementById('kolDelRowBtn')?.addEventListener('click',deleteKolSelectedRows);
async function deleteKolSelectedRows(){
  if(!kolRequireWorkspaceEdit()||kolSelectedActionState!=='idle')return;
  const snapshot=kolSelectedRowsSnapshot();
  if(!snapshot.size){ showToast('Silmek için önce satır seç.'); return; }
  kolSelectedActionState='confirming'; updateKolSendBtnState();
  if(!await openKolSelectedActionConfirmation('delete',snapshot)){ kolSelectedActionState='idle'; updateKolSendBtnState(); return; }
  kolSelectedActionState='processing'; updateKolSendBtnState();
  try{
    // Silmeden ÖNCE kutuya al: silme tamamlandıktan sonra satır elde kalmazdı.
    const removedRows=kolRows.filter(row=>snapshot.has(row.id));
    if(!removedRows.length)return;
    const archived=await kolArchiveDeletedRows(removedRows,'manual');
    if(!archived)throw new Error(appLang==='en'?'A recoverable copy could not be created.':'Geri alınabilir kopya oluşturulamadı.');
    kolPushUndo();
    const removedRefs=removedRows.map(r=>r.imgRef).filter(Boolean);
    const removedIds=new Set(removedRows.map(r=>r.id));
    if(kolTransientTopRowId!=null&&removedIds.has(Number(kolTransientTopRowId)))releaseKolTransientTopRow();
    kolRows=kolRows.filter(r=>!removedIds.has(r.id));
    // Onay penceresi açıkken oluşabilecek yeni seçimleri koru; yalnız gerçekten
    // silinen ID'leri seçim kaynağından çıkar.
    kolSelected.forEach(id=>{if(removedIds.has(Number(id))||removedIds.has(id))kolSelected.delete(id);});
    saveKolRows(); renderKol();
    // Yardımcı model dosyalarını ancak satırın tam kopyası geri dönüşüm
    // deposuna ve silinmiş durum yerel kalıcı kuyruğa yazıldıktan sonra temizle.
    // Bu temizlik başarısız olsa bile iş kaydı geri alınabilir durumdadır.
    let purged=null;
    try{purged=await kolPurgeStoredModelFiles(removedRows);}
    catch(fileErr){showToast((appLang==='en'?'Models were deleted safely, but stored files could not be cleaned: ':'Modeller güvenle silindi ancak kayıtlı dosyalar temizlenemedi: ')+(fileErr?.message||String(fileErr)));}
    void kolDeleteUnusedImageRefs(removedRefs);
    const fileCount=Number(purged?.deletedFiles)||0;
    showToast(appLang==='en'?`${removedRows.length} model(s) deleted${fileCount?` together with ${fileCount} stored file(s)`:''}.`:`${removedRows.length} model silindi${fileCount?`; ${fileCount} kayıtlı dosya da bilgisayardan kaldırıldı`:''}.`);
  }catch(err){
    showToast((appLang==='en'?'Models were not deleted because a recoverable copy could not be secured: ':'Geri alınabilir kopya güvenceye alınamadığı için modeller silinmedi: ')+(err?.message||String(err)));
  }finally{
    kolSelectedActionState='completed'; updateKolSendBtnState(); kolSelectedActionState='idle'; updateKolSendBtnState();
  }
}
['kolSearch'].forEach(id=>{
  const el = document.getElementById(id); if(!el) return;
  const renderSearch=el.tagName==='INPUT' ? renderKolDebounced : renderKol;
  el.addEventListener(el.tagName==='INPUT' ? 'input' : 'change', ()=>{releaseKolTransientTopRow();renderSearch();});
  bindTableSearchClipboardPaste(el);
});
// Excel'e aktarılacak satırları belirler: işaretli satır varsa yalnızca onlar, yoksa
// o an filtrelenmiş/görünen tüm satırlar (uygulama genelindeki tutarlı davranış).
function kolRawExportSelection(){
  const filtered=filteredKol();
  const selected=filtered.filter(r=>kolSelected.has(r.id));
  return {rows:selected.length?selected:filtered,selectedOnly:selected.length>0};
}
function kolExportSelection(){
  const logical=filteredKol(),projected=kolCollectionExportProjection(logical);
  const hasLogicalSelection=logical.some(row=>kolSelected.has(row.id)||kolSelected.has(Number(row.id))||kolSelected.has(String(row.id)));
  const selected=hasLogicalSelection?projected.filter(record=>kolCollectionProjectionSelected(record,kolSelected)):[];
  return {rows:hasLogicalSelection?selected:projected,selectedOnly:hasLogicalSelection};
}
function kolExportRows(){ return kolExportSelection().rows; }
function kolColHeaders(){
  const mfrCols = kolManufacturers.map(m=>m.name);
  const base=kolOrderedCols();
  return { base, mfr: mfrCols, all: [...base.map(c=>c.label), ...mfrCols.map(m=>m+' ($)')] };
}
function kolExportSingleLineText(value){
  if(window.BLTableExport?.normalizeCell)return window.BLTableExport.normalizeCell(value);
  return String(value==null?'':value).replace(/[\r\n\u000B\u000C\u0085\u2028\u2029\t]+/g,' ').replace(/ {2,}/g,' ').trim();
}
// ---- Biçimli (görselsiz) hızlı dışa aktarım: xlsx-js-style, CP ile aynı görsel dil ----
function buildKolStyledSheet(rows){
  const bd = _XLS_BORDERS;
  const sourceRows=(rows||[]).map(kolCollectionProjectionSource);
  const mfrCols = kolManufacturers.map(m=>m.name);
  const exportCols = kolOrderedCols();
  exportCols.forEach(c=>{c._blSchema=columnSchemaFor(c,sourceRows);});
  // Görsel sütunu ekranda gizliyse dışa aktarımda da yer almaz; ofsetler kayar.
  const withImg = !kolPictureHidden;
  const imgOff = withImg ? 1 : 0;
  const headers = [...(withImg?['Görsel Notu']:[]), ...exportCols.map(c=>c.label), ...mfrCols.map(m=>m+' ($)'), ...(mfrCols.length?['Conf. Manufacturer','Conf. FOB']:[])];
  const ws = {}; const put=(r,c,cell)=>{ ws[XLSX.utils.encode_cell({r,c})]=cell; };
  headers.forEach((h,ci)=> put(0,ci,{v:h,t:'s',s:{border:bd,font:{sz:10,bold:true,color:{rgb:'FF475467'}},fill:{fgColor:{rgb:'FFF2F4F7'}},alignment:{horizontal:'center',vertical:'center',wrapText:true}}}));
  rows.forEach((record,ri)=>{
    const r=kolCollectionProjectionSource(record),summary=kolCollectionProjectionSummary(record);
    if(withImg) put(ri+1,0,{v:r.img?'Uygulamada görsel mevcut':'Görsel yok',t:'s',s:{border:bd,font:{sz:9,italic:true,color:{rgb:'FF98A2B3'}}}});
    exportCols.forEach((c,ci)=>{
      const summaryEntry=summary?.get?.(c.k);
      if(summaryEntry){
        put(ri+1,ci+imgOff,{v:kolExportSingleLineText(summaryEntry.display),t:'s',s:{border:bd,font:{sz:10,bold:c.k==='modelKod'},alignment:{vertical:'middle',wrapText:true}}});
        return;
      }
      const raw = c.exToRetail ? kolExToRetailDays(r) : kolEffectiveValue(r,c.k);
      const schema=columnSchemaFor(c,sourceRows);
      const s = {border:bd, font:{sz:10, bold:c.k==='modelKod'}};
      let cell;
      if(c.endeksmatik){
        // v6.42 — Ekranda hücre fiyat + index olmak üzere İKİ satır gösterirken
        // ("YD $.. · TR $.." ve "YD %.. · TR %.."), bu yol yalnız fiyat satırını
        // (endeksmatikCompactText) yazıyordu; index satırı Excel'e hiç gitmiyordu.
        // endeksmatikExcelText ikisini birden verir — Kopyala yolunda zaten
        // bu kullanılıyordu, buradaki eksiklik ikisini tutarsız kılıyordu.
        const textValue=kolExportSingleLineText(endeksmatikExcelText(r));
        cell={v:textValue,t:'s',s:{...s,alignment:{horizontal:'left',vertical:'center',wrapText:true}}};
        put(ri+1,ci+imgOff,cell);return;
      }
      // Landed sütunları hesaplanmış sayıdır; Excel'de para biçiminde yazılır.
      if(c.trLanded || c.ydLanded){
        const k=kolLandedCalc(r);
        const value=c.trLanded?k.trLanded:k.ydLanded;
        cell = value==null ? {v:'',t:'s',s} : {v:value,t:'n',s:{...s,numFmt:'"$"#,##0.00',alignment:{horizontal:'right'}}};
        put(ri+1, ci+imgOff, cell);
        return;
      }
      if(c.k==='colourCode'){
        cell={v:kolExportSingleLineText(raw),t:'s',s:{...s,numFmt:'@',alignment:{horizontal:'left',vertical:'center'}}};
      } else if(c.exToRetail){
        cell = raw==='' ? {v:'',t:'s',s} : {v:Number(raw),t:'n',s:{...s,numFmt:'#,##0" g."',alignment:{horizontal:'right'},font:{sz:10,color:{rgb:'FF98A2B3'}}}};
      } else if(c.date && raw){
        const d = coerceDateLoose(raw);
        cell = !d ? {v:kolExportSingleLineText(raw),t:'s',s} : {v:d,t:'d',s:{...s,numFmt:'dd.mm.yy',alignment:{horizontal:'right'}}};
      } else if(c.qty && raw!==''&&raw!=null && Number.isFinite(kolParseQuantityNum(raw))){
        cell = {v:kolParseQuantityNum(raw),t:'n',s:{...s,numFmt:'#,##0',alignment:{horizontal:'right'}}};
      } else if(c.percent && raw!==''&&raw!=null && Number.isFinite(kolParseMoneyNum(raw))){
        cell = {v:kolParseMoneyNum(raw)/100,t:'n',s:{...s,numFmt:'0.00%',alignment:{horizontal:'right'}}};
      } else if(c.hologram && raw!==''&&raw!=null && Number.isFinite(kolParseMoneyNum(raw))){
        cell = {v:kolParseMoneyNum(raw),t:'n',s:{...s,numFmt:'#,##0.######',alignment:{horizontal:'right'}}};
      } else if(c.money && raw!==''&&raw!=null && Number.isFinite(kolParseMoneyNum(raw))){
        cell = {v:kolParseMoneyNum(raw),t:'n',s:{...s,numFmt:'"$"#,##0.00',alignment:{horizontal:'right'}}};
      } else if(c.custom && schema){
        const value=schema.exportValue(raw);
        cell=value instanceof Date?{v:value,t:'d',s:{...s,numFmt:'dd.mm.yy',alignment:{horizontal:'right'}}}:typeof value==='number'?{v:value,t:'n',s:{...s,numFmt:Number.isInteger(value)?'#,##0':'#,##0.00',alignment:{horizontal:'right'}}}:{v:kolExportSingleLineText(value),t:'s',s};
      } else if(c.status||c.k==='durum'){
        const argb=kolStatusExcelArgb(raw),fontArgb=kolStatusExcelTextArgb(raw);
        cell = {v:kolExportSingleLineText(raw),t:'s',s:{...s,fill:{fgColor:{rgb:argb}},font:{sz:10,bold:true,color:{rgb:fontArgb}}}};
      } else {
        cell = {v:kolExportSingleLineText(raw),t:'s',s};
      }
      put(ri+1, ci+imgOff, cell);
    });
    const effectivePricing=kolEffectivePricing(r),validPrices = mfrCols.map(m=>kolParseMoneyNum(effectivePricing && effectivePricing[m])).filter(n=>Number.isFinite(n) && n>0);
    mfrCols.forEach((m,mi)=>{
      const v = effectivePricing && effectivePricing[m];
      const ci = imgOff + exportCols.length + mi;
      const n = kolParseMoneyNum(v);
      if(v==='0' || v==='0,00'){
        put(ri+1,ci,{v:0,t:'n',s:{border:bd,font:{sz:10},numFmt:'"$"#,##0.00',alignment:{horizontal:'right'}}});
      } else if(v!=='' && v!=null && Number.isFinite(n)){
        let fill;
        if(n>0 && validPrices.length){
          const min=Math.min(...validPrices), max=Math.max(...validPrices);
          const t = max===min ? 0 : (n-min)/(max-min);
          const hue = 150 - t*150;
          fill = {fgColor:{rgb: hslToArgb(hue,55,88)}};
        }
        put(ri+1,ci,{v:n,t:'n',s:{border:bd,font:{sz:10},numFmt:'"$"#,##0.00',alignment:{horizontal:'right'}, ...(fill?{fill}:{})}});
      }
      else if(v!=='' && v!=null){
        // "Fiyatlamada" gibi metin bir değer — sayı değil, olduğu gibi yazılır.
        put(ri+1,ci,{v:kolExportSingleLineText(v),t:'s',s:{border:bd,font:{sz:10,italic:true}}});
      }
      else put(ri+1,ci,{v:'',t:'s',s:{border:bd}});
    });
    if(mfrCols.length){
      const confirmed = kolConfirmedPricing(r);
      const bi = imgOff + exportCols.length + mfrCols.length;
      const confirmedFill = confirmed ? {fgColor:{rgb:'FFE4F3EB'}} : undefined;
      put(ri+1,bi,{v:confirmed?kolExportSingleLineText(confirmed.name):'',t:'s',s:{border:bd,font:{sz:10,bold:true,color:{rgb:'FF177A4C'}}, ...(confirmedFill?{fill:confirmedFill}:{})}});
      put(ri+1,bi+1,{v:confirmed?confirmed.price:'',t: confirmed?'n':'s',s:{border:bd,font:{sz:10,bold:true,color:{rgb:'FF177A4C'}},numFmt:confirmed?'"$"#,##0.00':undefined,alignment:{horizontal:'right'}, ...(confirmedFill?{fill:confirmedFill}:{})}});
    }
  });
  ws['!ref']=XLSX.utils.encode_range({s:{r:0,c:0},e:{r:rows.length,c:headers.length-1}});
  ws['!cols']=[...(withImg?[{wch:kolExcelImageMetrics().colChars}]:[]), ...exportCols.map(c=>({wch:Math.max(11,Math.round(kolColWidth(c)/7))})), ...mfrCols.map(()=>({wch:14})), ...(mfrCols.length?[{wch:22},{wch:14}]:[])];
  ws['!rows']=[{hpx:26}];
  return ws;
}


// ---- Görsel gömülü dışa aktarım: ExcelJS (ayrı kütüphane; xlsx-js-style resim desteklemiyor) ----
// Mailto gövdesi yalnızca düz metin kabul eder (HTML tablo desteklenmez) — bu yüzden
// sabit genişlikli, hizalı bir düz-metin tablosu üretilir. Sütunlar e-posta talebiyle
// birebir aynı sırada: Category / Style Name / License / Colour / Fit / Fabric /
// Quantity / Ex-Factory / Target FOB / Notes.
function kolPlainTextTable(rows){
  const cols = [
    ['CATEGORY','urunTipi',14], ['STYLE NAME','modelKod',16], ['LICENSE','lisans',12],
    ['COLOUR','colour',12], ['FIT','fit',10], ['FABRIC','fabric',12],
    ['QUANTITY','quantity',9], ['EX-FACTORY','exFactory',11], ['TARGET FOB','targetPrice',11], ['NOTES','not',18],
  ];
  const pad = (s,w) => { s=String(s==null?'':s); return s.length>=w ? s.slice(0,w-1)+'…' : s+' '.repeat(w-s.length); };
  const header = cols.map(([label,,w])=>pad(label,w)).join(' | ');
  const sep = cols.map(([,,w])=>'-'.repeat(w)).join('-+-');
  const lines = rows.map(r => cols.map(([,key,w])=>{
    let v = kolEffectiveValue(r,key);
    if(key==='targetPrice' && v!=='' && v!=null) v = '$'+v;
    return pad(v,w);
  }).join(' | '));
  return [header, sep, ...lines].join('\r\n');
}
// Fiyatlama talebi Excel'i: Export with Pictures ile aynı ExcelJS görsel/biçim motorunu kullanır.
// Görsel sütunu sabittir; diğer sütunlar kalıcı Pricing Excel Columns seçimine göre eklenir.
// v1.84: çalışma kitabı artık yalnız indirilmez; düzenlenebilir .eml taslağına gerçek ek olarak
// bağlanır ve aynı tablonun görsel önizlemesi e-posta metninin hemen altına gömülür.
function kolSafePricingFileName(value){
  return String(value||'Uretici').replace(/[\\/:*?"<>|]/g,'_').replace(/\s+/g,' ').trim() || 'Uretici';
}
function kolArrayBufferToBase64(buffer){
  const bytes=new Uint8Array(buffer); let binary=''; const chunk=0x8000;
  for(let i=0;i<bytes.length;i+=chunk) binary+=String.fromCharCode(...bytes.subarray(i,i+chunk));
  return btoa(binary);
}
function kolDownloadBuffer(buffer,name,mime='application/octet-stream'){
  const blob=new Blob([buffer],{type:mime});
  const url=URL.createObjectURL(blob), a=document.createElement('a');
  a.href=url; a.download=name; document.body.appendChild(a); a.click(); a.remove();
  setTimeout(()=>URL.revokeObjectURL(url),30000);
}
function kolPricingMailDate(d=new Date()){
  const p=x=>String(x).padStart(2,'0');
  return `${p(d.getDate())}.${p(d.getMonth()+1)}.${String(d.getFullYear()).slice(-2)}`;
}
function kolPricingPreviewValue(r,c){
  const raw=c.exToRetail?kolExToRetailDays(r):kolEffectiveValue(r,c.k);
  if(raw==null || raw==='') return '';
  if(c.date) return fmtDate(raw);
  if(c.qty){ const n=kolParseQuantityNum(raw); return Number.isFinite(n)?n.toLocaleString('tr-TR'):String(raw); }
  if(c.percent){ const n=kolParseMoneyNum(raw); return Number.isFinite(n)?`%${n.toLocaleString('tr-TR',{maximumFractionDigits:3})}`:String(raw); }
  if(c.hologram){ const n=kolParseMoneyNum(raw); return Number.isFinite(n)?n.toLocaleString('tr-TR',{maximumFractionDigits:6}):String(raw); }
  if(c.money){ const n=kolParseMoneyNum(raw); return Number.isFinite(n)?`$${n.toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})}`:String(raw); }
  return String(raw);
}
function kolCanvasTextLines(ctx,text,maxWidth,maxLines){
  const words=String(text??'').replace(/\s+/g,' ').trim().split(' ').filter(Boolean);
  if(!words.length) return [''];
  const lines=[]; let line='';
  for(const word of words){
    const trial=line?`${line} ${word}`:word;
    if(ctx.measureText(trial).width<=maxWidth || !line) line=trial;
    else { lines.push(line); line=word; if(lines.length>=maxLines-1) break; }
  }
  if(line && lines.length<maxLines) lines.push(line);
  const consumed=lines.join(' ').split(' ').filter(Boolean).length;
  if(consumed<words.length && lines.length){
    let last=lines[lines.length-1];
    while(last && ctx.measureText(last+'…').width>maxWidth) last=last.slice(0,-1);
    lines[lines.length-1]=(last||'')+'…';
  }
  return lines;
}
function kolLoadPricingImage(src){
  return new Promise(resolve=>{
    if(!src){ resolve(null); return; }
    const img=new Image(); let settled=false;
    const done=value=>{ if(settled) return; settled=true; clearTimeout(timer); resolve(value); };
    const timer=setTimeout(()=>done(null),4000);
    img.onload=()=>done(img); img.onerror=()=>done(null); img.src=src;
  });
}
async function kolBuildPricingPreviewImages(rows){
  const exportCols=kolPricingExcelCols();
  const defs=[{label:'Görsel',width:108,image:true},...exportCols.map(c=>({label:L(c.label),width:Math.max(90,Math.min(185,Math.round((kolColWidth(c)||110)*0.9))),col:c}))];
  const rawWidth=defs.reduce((sum,d)=>sum+d.width,0);
  const maxWidth=1900, scale=Math.min(1,maxWidth/rawWidth), width=Math.max(720,Math.round(rawWidth*scale));
  const headerH=Math.round(44*scale), rowH=Math.max(58,Math.round(86*scale));
  const maxRowsPerImage=Math.max(12,Math.min(38,Math.floor((5600-headerH)/rowH)));
  const loadedImages=await Promise.all(rows.map(r=>kolLoadPricingImage(r.img)));
  const previews=[];
  for(let offset=0;offset<rows.length;offset+=maxRowsPerImage){
    const chunkRows=rows.slice(offset,offset+maxRowsPerImage), chunkImgs=loadedImages.slice(offset,offset+maxRowsPerImage);
    const height=headerH+chunkRows.length*rowH;
    const dpr=1, canvas=document.createElement('canvas');
    canvas.width=Math.ceil(width*dpr); canvas.height=Math.ceil(height*dpr);
    const ctx=canvas.getContext('2d');
    if(!ctx) throw new Error('E-posta tablo görseli oluşturulamadı.');
    ctx.scale(dpr,dpr);
    ctx.fillStyle='#FFFFFF'; ctx.fillRect(0,0,width,height);
    ctx.textBaseline='middle'; ctx.lineWidth=1;
    let x=0;
    defs.forEach(d=>{
      const w=d.width*scale;
      ctx.fillStyle='#F2F4F7'; ctx.fillRect(x,0,w,headerH);
      ctx.strokeStyle='#D0D5DD'; ctx.strokeRect(x,0,w,headerH);
      ctx.fillStyle='#475467'; ctx.font=`600 ${Math.max(10,Math.round(12*scale))}px Arial, sans-serif`;
      const lines=kolCanvasTextLines(ctx,d.label,Math.max(20,w-12),2), lh=Math.max(12,Math.round(14*scale));
      lines.forEach((line,i)=>ctx.fillText(line,x+6,headerH/2+(i-(lines.length-1)/2)*lh));
      x+=w;
    });
    chunkRows.forEach((r,ri)=>{
      const y=headerH+ri*rowH; let cx=0;
      defs.forEach((d,di)=>{
        const w=d.width*scale;
        ctx.fillStyle=ri%2?'#FCFCFD':'#FFFFFF'; ctx.fillRect(cx,y,w,rowH);
        ctx.strokeStyle='#D0D5DD'; ctx.strokeRect(cx,y,w,rowH);
        if(d.image){
          const img=chunkImgs[ri];
          if(img){
            const pad=Math.max(4,Math.round(6*scale)), aw=w-pad*2, ah=rowH-pad*2;
            const ratio=Math.min(aw/img.naturalWidth,ah/img.naturalHeight);
            const iw=img.naturalWidth*ratio, ih=img.naturalHeight*ratio;
            ctx.drawImage(img,cx+(w-iw)/2,y+(rowH-ih)/2,iw,ih);
          }
        }else{
          const value=kolPricingPreviewValue(r,d.col);
          ctx.fillStyle='#101828';
          ctx.font=`${d.col.k==='modelKod'?'600':'400'} ${Math.max(9,Math.round(11*scale))}px Arial, sans-serif`;
          const lines=kolCanvasTextLines(ctx,value,Math.max(20,w-12),4), lh=Math.max(11,Math.round(14*scale));
          lines.forEach((line,i)=>ctx.fillText(line,cx+6,y+rowH/2+(i-(lines.length-1)/2)*lh));
        }
        cx+=w;
      });
    });
    const cid=`pricing-preview-${offset/maxRowsPerImage+1}-${Date.now()}@buyerlog`;
    const dataUrl=canvas.toDataURL('image/jpeg',0.78);
    previews.push({cid,filename:`Pricing_Preview_${String(previews.length+1).padStart(2,'0')}.jpg`,mimeType:'image/jpeg',base64:dataUrl.split(',')[1]});
  }
  return previews;
}
/* ===================================================================
   E-POSTA KONU VE TASLAK AYARLARI
   Her E-mail Subjects satırı tek bir taslak ve ek/tablo ayarıdır.
   Depolama: localStorage 'lcw.mailTemplates.v1'
     { pricing:{ items:[{id,name,body}], activeId }, general:{...} }
   Gövde düz metin olarak saklanır; HTML sürüm paragraflara bölünerek üretilir.
   =================================================================== */
/* ===================================================================
   PREPAIRE E-MAIL — CP'deki seçili siparişler için üretici ve konu seçerek
   taslak e-posta hazırlar. Send to Pricing ve diğer konular aynı pencerededir.
   =================================================================== */
// Üretici seçim penceresi — Koleksiyon akışıyla aynı veri kaynağı.
function prepareEmailOpenFromCp(){
  const en=appLang==='en';
  // Seçim kontrolü aktif sekmeye göre yapılır; CP ve Siparişler'de de çalışır.
  const rows=selectedCpRowsForAction();
  if(rows===null)return;
  if(!rows.length){
    showToast(en?'Select at least one order first.':'Önce en az bir sipariş seç.');return;
  }
  const names=[...new Set(rows.map(r=>norm(r['Sub-Manufacturer'])||norm(r['Manufacturer'])).filter(Boolean))];
  let added=false;
  names.forEach(n=>{
    if(!kolManufacturers.some(m=>m&&String(m.name).toLocaleLowerCase('tr-TR')===n.toLocaleLowerCase('tr-TR'))){
      kolManufacturers.push({name:n,email:''});added=true;
    }
  });
  if(added)saveKolManufacturers();
  let tempId=-1;
  const tempRows=rows.map(r=>{
    const k=cpRowToKolRow(r),manufacturer=norm(r['Sub-Manufacturer'])||norm(r['Manufacturer'])||'';
    return {...r,...k,id:tempId--,manufacturer,buyingSampleManufacturer:manufacturer,_cpSourceRow:r};
  });
  renderKolMfrModal({
    rows:tempRows,count:tempRows.length,btnId:'cpProdStatusBtn',persist:false,preselect:names,
    defaultTopicKind:'general',
    title:en?'Prepare E-Mail':'E-Posta Hazırla',
    subtitle:en?`${tempRows.length} selected order(s) · choose manufacturer and subject`:`${tempRows.length} seçili sipariş · üretici ve e-posta başlığı seç`
  });
}
// Üretici e-postalarını hatırla (fiyatlama tarafındaki liste ile ortak kullanılır)
const PREPARE_EMAIL_MAIL_KEY = 'lcw.prodstatus.mails.v1'; // eski kayıt anahtarı korunur
function prepareEmailLookupEmail(name){
  /* Central e-mail directory is the single source of truth. Workflow-local
     address stores are intentionally ignored so Settings > E-Mail Groups is
     the only place where manufacturer recipients are maintained. */
  try{return String(window.BLEmailDirectory?.emailFor(name)||'').trim();}catch(_){return '';}
}

