function mailTopicDefaultSubjectColumnKeys(kind,sourceKind){
  if(kind==='pricing')return sourceKind==='cp'?['Season']:['season'];
  return [];
}
function mailTopicSubjectColumnKeys(kind,id,sourceKind){
  const item=mailTopicFindItem(kind,id),valid=new Set(mailTopicSourceColumns(sourceKind).map(c=>c.k));
  const hasStored=Boolean(item?.subjectColumns&&Object.prototype.hasOwnProperty.call(item.subjectColumns,sourceKind));
  const stored=hasStored&&Array.isArray(item.subjectColumns[sourceKind])?item.subjectColumns[sourceKind]:mailTopicDefaultSubjectColumnKeys(kind,sourceKind);
  const clean=[];
  stored.forEach(key=>{key=String(key||'');if(valid.has(key)&&!clean.includes(key))clean.push(key);});
  return clean;
}
function mailTopicSubjectIncludesManufacturer(kind,id,sourceKind){
  const item=mailTopicFindItem(kind,id);
  const stored=item?.subjectManufacturer?.[sourceKind];
  return typeof stored==='boolean'?stored:true;
}
function mailTopicSetSubjectOptions(kind,id,sourceKind,{manufacturer,keys}={}){
  const item=mailTopicFindItem(kind,id);if(!item)return false;
  const valid=new Set(mailTopicSourceColumns(sourceKind).map(c=>c.k)),clean=[];
  (keys||[]).forEach(key=>{key=String(key||'');if(valid.has(key)&&!clean.includes(key))clean.push(key);});
  if(!item.subjectColumns||typeof item.subjectColumns!=='object')item.subjectColumns={};
  if(!item.subjectManufacturer||typeof item.subjectManufacturer!=='object')item.subjectManufacturer={};
  item.subjectColumns[sourceKind]=clean;
  item.subjectManufacturer[sourceKind]=Boolean(manufacturer);
  mailTplSave();return true;
}
function mailTopicSelectedSubjectColumns(kind,id,sourceKind){
  const selected=new Set(mailTopicSubjectColumnKeys(kind,id,sourceKind));
  return mailTopicSourceColumns(sourceKind).filter(c=>selected.has(c.k)).map(c=>({...c,sourceKind}));
}
function mailTopicIsProtected(kind,id){
  return id===`${kind}-default` || id===MAIL_QUOTATION_REMINDER_ID;
}
function mailTopicDelete(kind,id){
  if(mailTopicIsProtected(kind,id))return false;
  const st=mailTplLoad(),branch=st[kind];if(!branch)return false;
  const before=(branch.items||[]).length;
  branch.items=(branch.items||[]).filter(item=>item.id!==id);
  if(branch.items.length===before||!branch.items.length)return false;
  if(branch.activeId===id)branch.activeId=branch.items[0].id;
  mailTplSave();return true;
}
