    const host = document.getElementById('kolMfrList');
    if(host){
      host.innerHTML = listHtml();
      if(q) [...host.querySelectorAll('.mfrNavItem')].forEach(el=>{
        const i = Number(el.dataset.mfrItem), m = kolManufacturers[i];
        const hay = `${m?.name||''} ${m?.email||''}`.toLocaleLowerCase('tr-TR');
        if(!hay.includes(q)) el.style.display='none';
      });
    }
