    if(confirmBtn){ confirmBtn.disabled=pricingStoredLoading; confirmBtn.title=pricingStoredLoading?(appLang==='en'?'Uploaded model files are loading.':'Yüklenmiş model dosyaları yükleniyor.'):''; }
