    const editBtn=e.target.closest('[data-mfr-edit]');
    if(editBtn){
      e.preventDefault(); e.stopPropagation();
      const i=Number(editBtn.dataset.mfrEdit);
      if(editingMfrIndex===i) commitInlineMfrEdit(i); else startInlineMfrEdit(i);
      return;
    }
    const pickBtn=e.target.closest('[data-mfr-pick]');
    if(!pickBtn) return;
