  mfrSearch.addEventListener('input', refreshAll);
  // Kalemle açılan yerinde editör: Ctrl/Cmd+Enter kaydeder, Esc vazgeçer.
  function bindInlineEditor(){
    if(editingMfrIndex<0) return;
    const i=editingMfrIndex;
    const editor=modal.querySelector(`[data-mfr-editor="${i}"]`);
    if(!editor) return;
    editor.addEventListener('keydown',e=>{
      if(e.key==='Escape'){ e.preventDefault(); cancelInlineMfrEdit(); return; }
      if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){ e.preventDefault(); commitInlineMfrEdit(i); }
    });
  }
  async function loadStoredPricingFiles(){
    if(!pricingStoredEnabled() || storedPricingFilesLoaded || pricingStoredLoading) return;
    pricingStoredLoading=true; refreshAll();
    try{
      const metas=await kolListStoredModelFiles(prepareEmailStoredModelRows(getRows()));
      for(const meta of metas){
        const candidate={id:`stored-${meta.id}`,storedId:meta.id,stored:true,modelKey:meta.modelKey,modelLabel:meta.modelLabel||'',plmSource:meta.plmSource||'',plmLanguage:meta.plmLanguage||'',plmId:meta.plmId||''};
        const identity=pricingAttachmentIdentity(candidate);
        const duplicate=pricingModelFiles.some(entry=>pricingAttachmentIdentity(entry)===identity);
        if(duplicate) continue;
        try{
          const file=await kolStoredMetaToFile(meta);
          pricingModelFiles.push({...candidate,file});
        }catch(err){ console.warn('Stored model file could not be loaded:',meta.filename,err); }
      }
    }catch(err){ showToast(err?.message||String(err)); }
    finally{
      storedPricingFilesLoaded=true;
      pricingStoredLoading=false;
      if(!topicAddsTps()){pricingModelFiles=pricingModelFiles.filter(x=>!x.stored);storedPricingFilesLoaded=false;}
      refreshAll();
    }
  }
  function syncStoredFilesForTopic(){
    if(!pricingStoredEnabled()){
      const hadStored=pricingModelFiles.some(x=>x.stored);
      pricingModelFiles=pricingModelFiles.filter(x=>!x.stored);
      storedPricingFilesLoaded=false;
      if(hadStored)refreshAll();
      return;
    }
    loadStoredPricingFiles();
  }
  function bindPricingFiles(){
    const input=document.getElementById('kolPricingFilesInput');
    const box=document.getElementById('pricingAttachBox');
    const addFiles=list=>{
      [...(list||[])].forEach(file=>{
        if(!file||!file.name) return;
        const duplicate=pricingModelFiles.some(x=>x.file.name===file.name&&x.file.size===file.size&&x.file.lastModified===file.lastModified);
        if(!duplicate) pricingModelFiles.push({id:`pf-${Date.now()}-${++pricingFileSeq}`,file,modelLabel:pricingMatchFileToRow(file,getRows())});
      });
      refreshAll();
    };
    input?.addEventListener('change',()=>addFiles(input.files));
    document.getElementById('kolPricingFilesClear')?.addEventListener('click',()=>{ pricingModelFiles=[]; refreshAll(); });
    document.querySelectorAll('[data-pricing-file-remove]').forEach(btn=>btn.addEventListener('click',()=>{
      pricingModelFiles=pricingModelFiles.filter(x=>x.id!==btn.dataset.pricingFileRemove); refreshAll();
    }));
    if(box){
      box.addEventListener('dragover',e=>{ e.preventDefault(); box.classList.add('isDrag'); });
      box.addEventListener('dragleave',()=>box.classList.remove('isDrag'));
      box.addEventListener('drop',e=>{ e.preventDefault(); box.classList.remove('isDrag'); addFiles(e.dataTransfer?.files); });
    }
  }
