  const mailSubjectEditorOptions=extra=>({
    ...(extra||{}),
    getRows,
    getManufacturerName:()=>{
      const pickedNames=[...(_mfrPicked||[])].sort((a,b)=>a-b).map(i=>kolManufacturers[i]?.name).filter(Boolean);
      if(pickedNames.length)return pickedNames.join(' / ');
      const names=[],seen=new Set();
      getRows().forEach(row=>{const value=prepareEmailSubjectSegment(prepareEmailRowManufacturer(row));const key=value.toLocaleLowerCase('tr-TR');if(value&&!seen.has(key)){seen.add(key);names.push(value);}});
      return names.join(' / ');
    },
    getSubjectPreviewContexts:subjectKind=>{
      const rows=getRows(),pickedNames=[...(_mfrPicked||[])].sort((a,b)=>a-b).map(i=>kolManufacturers[i]?.name).filter(Boolean);
      const names=[],seen=new Set();
      (pickedNames.length?pickedNames:rows.map(prepareEmailRowManufacturer)).forEach(name=>{const value=prepareEmailSubjectSegment(name);const key=value.toLocaleLowerCase('tr-TR');if(value&&!seen.has(key)){seen.add(key);names.push(value);}});
      if(!names.length)return [{rows,manufacturerName:''}];
      return names.map(name=>{
        const own=rows.filter(row=>prepareEmailRowManufacturer(row).toLocaleLowerCase('tr-TR')===name.toLocaleLowerCase('tr-TR'));
        return {rows:subjectKind==='pricing'?rows:(own.length?own:rows),manufacturerName:name};
      });
    }
  });
