      branch.items.push(item);branch.activeId=item.id;mailTplSave();selectedTopic=mailTopicActiveDescriptor('general');refreshAll();
      openMailTopicEditor('general',item.id,topicSourceKind,()=>{selectedTopic=mailTopicActiveDescriptor('general');refreshAll();syncStoredFilesForTopic();},mailSubjectEditorOptions({focusName:true}));return;
