      const item=mailTopicFindItem(kind,id);if(!item)return;
      if(!confirm(appLang==='en'?`Delete the subject “${item.name}”?`:`“${item.name}” başlığı silinsin mi?`))return;
      if(!mailTopicDelete(kind,id))return;
      const remaining=mailTopicCatalog();
      if(selectedTopic.kind===kind&&selectedTopic.id===id){const next=remaining[0];if(next){mailTopicSelect(next.kind,next.id);selectedTopic=mailTopicActiveDescriptor(next.kind);}}
      refreshAll();showToast(appLang==='en'?'Subject deleted.':'Başlık silindi.');return;
